// Per-frame spring magnification for each dock icon:
const dist = Math.abs(mouseX - centerX);
const influence = dist < 95 ? 0.5 * (1 + Math.cos(Math.PI * dist / 95)) : 0;
const targetSize = 34 + influence * 22;
// Integrate with spring(stiffness: 240, damping: 18)

