// React Bits ClickSpark core radial needle math:
const e = 1 - Math.pow(1 - t, 3);
const dist = e * radius;
const len = sparkSize * (1 - e);
ctx.beginPath();
ctx.moveTo(x + Math.cos(angle) * dist, y + Math.sin(angle) * dist);
ctx.lineTo(x + Math.cos(angle) * (dist + len), y + Math.sin(angle) * (dist + len));
ctx.stroke();

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

float hash(float n) { return fract(sin(n) * 43758.5453); }
float noise1(float x) {
  float i = floor(x), f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

void main() {
  vec2 aspect = vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  vec2 origin = vec2(0.5 + (u_mouse.x - 0.5) * 0.25, 0.78 + (u_mouse.y - 0.5) * 0.16);
  vec2 d = (v_uv - origin) * aspect;
  float ang = atan(d.y, d.x);
  float dist = length(d);

  float r1 = noise1(ang * 7.0 + u_time * 0.35);
  float r2 = noise1(ang * 15.0 - u_time * 0.52 + 4.1);
  float r3 = noise1(ang * 27.0 + u_time * 0.22 + 9.3);
  float rays = pow(r1 * 0.55 + r2 * 0.3 + r3 * 0.15, 1.55);
  float atten = exp(-dist * 1.45);
  float core = exp(-dist * 4.8);

  vec3 bg = vec3(0.05, 0.04, 0.08);
  vec3 c1 = vec3(1.0, 0.72, 0.36);
  vec3 c2 = vec3(0.76, 0.36, 0.96);
  vec3 c3 = vec3(0.32, 0.64, 1.0);
  vec3 rayCol = mix(c1, c2, 0.5 + 0.5 * sin(ang * 2.0 + u_time * 0.4));
  rayCol = mix(rayCol, c3, 0.3 * sin(ang * 3.5 - u_time * 0.3) + 0.3);

  vec3 col = bg + rayCol * rays * atten * 1.45 + vec3(1.0, 0.93, 0.84) * core * 0.95;
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

void main() {
  vec2 uv = (v_uv - 0.5) * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  vec2 m = (u_mouse - 0.5) * 0.6;
  vec2 p = uv * 2.4;
  float t = u_time * 0.45;
  for (int i = 1; i <= 5; i++) {
    float fi = float(i);
    p.x += 0.36 / fi * sin(fi * 2.3 * p.y + t + m.x * 2.0) + 0.08 * cos(t * 0.7);
    p.y += 0.36 / fi * cos(fi * 2.1 * p.x - t * 0.8 + m.y * 2.0);
  }
  float stripe = sin(p.x * 3.8 + p.y * 2.6);
  float sharp = smoothstep(-0.2, 0.85, stripe);
  float spec = pow(max(0.0, stripe), 6.0);

  vec3 dark = vec3(0.07, 0.08, 0.11);
  vec3 silver = vec3(0.84, 0.87, 0.92);
  vec3 irid = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + p.x * 1.4 + t);
  vec3 col = mix(dark, silver, sharp * 0.82);
  col += irid * pow(1.0 - abs(stripe), 4.0) * 0.28;
  col += vec3(1.0) * spec * 0.55;
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

vec2 rot(vec2 p, float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c) * p; }

float neuro(vec2 uv, float t) {
  vec2 p = uv * 3.1;
  vec2 n = vec2(0.0);
  float res = 0.0;
  float scale = 1.0;
  for (int i = 0; i < 6; i++) {
    p = rot(p, 0.52);
    n = rot(n, 0.52);
    vec2 q = p * scale + t + n;
    res += dot(sin(q), vec2(0.5)) / scale;
    n -= cos(q);
    scale *= 1.24;
  }
  return res;
}

void main() {
  vec2 uv = (v_uv - 0.5) * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  vec2 m = (u_mouse - 0.5) * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  float md = length(uv - m);
  uv += (uv - m) * exp(-md * 3.5) * 0.16;

  float v = neuro(uv, u_time * 0.55);
  float ridge = smoothstep(0.02, 0.55, abs(v));
  float glow = pow(max(0.0, 1.0 - ridge), 3.2);
  float pulse = 0.65 + 0.35 * sin(u_time * 1.4 - length(uv) * 3.0);

  vec3 bg = vec3(0.03, 0.05, 0.10);
  vec3 mid = vec3(0.16, 0.52, 0.96);
  vec3 hi = vec3(0.84, 0.95, 1.0);
  vec3 col = bg + mid * glow * 1.35 * pulse + hi * pow(glow, 3.0) * 0.95;
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

void main() {
  vec2 uv = v_uv * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  float cells = 8.0;
  vec2 gv = fract(uv * cells) - 0.5;
  vec2 id = floor(uv * cells);

  vec3 col = vec3(0.965, 0.962, 0.945);
  vec3 pal[4];
  pal[0] = vec3(0.91, 0.28, 0.22);
  pal[1] = vec3(0.14, 0.45, 0.88);
  pal[2] = vec3(0.94, 0.68, 0.14);
  pal[3] = vec3(0.10, 0.11, 0.14);

  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 offs = vec2(float(x), float(y));
      vec2 cid = id + offs;
      float h = hash21(cid);
      float ang = u_time * (1.2 + h * 1.1) + h * 6.2831;
      float rad = 0.20 + 0.10 * sin(u_time * 0.8 + h * 12.0);
      vec2 pos = offs + vec2(cos(ang), sin(ang)) * rad;
      float d = length(gv - pos);
      float dotR = 0.14 + 0.05 * h;
      float mask = smoothstep(dotR + 0.025, dotR - 0.025, d);
      int ci = int(floor(h * 4.0));
      vec3 dc = ci == 0 ? pal[0] : (ci == 1 ? pal[1] : (ci == 2 ? pal[2] : pal[3]));
      col = mix(col, dc, mask);
    }
  }
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

void main() {
  vec2 aspect = vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  vec2 uv = (v_uv - 0.5) * aspect;
  float t = u_time * 0.65;

  vec2 b[6];
  b[0] = vec2(sin(t * 0.9) * 0.34, cos(t * 1.1) * 0.22);
  b[1] = vec2(cos(t * 0.7 + 1.4) * 0.30, sin(t * 0.8 + 0.6) * 0.26);
  b[2] = vec2(sin(t * 1.2 + 2.5) * 0.22, cos(t * 0.6 + 2.1) * 0.28);
  b[3] = vec2(cos(t * 1.0 + 4.0) * 0.36, sin(t * 1.3 + 1.2) * 0.18);
  b[4] = vec2(sin(t * 0.5 + 5.2) * 0.18, cos(t * 0.9 + 3.4) * 0.16);
  b[5] = (u_mouse - 0.5) * aspect;

  vec3 c[6];
  c[0] = vec3(1.0, 0.32, 0.52);
  c[1] = vec3(0.55, 0.28, 1.0);
  c[2] = vec3(1.0, 0.58, 0.24);
  c[3] = vec3(0.24, 0.64, 1.0);
  c[4] = vec3(0.95, 0.28, 0.82);
  c[5] = vec3(1.0, 0.82, 0.92);

  float field = 0.0;
  vec3 acc = vec3(0.0);
  for (int i = 0; i < 6; i++) {
    float r = i == 5 ? 0.015 : 0.022;
    float d = dot(uv - b[i], uv - b[i]) + 0.0025;
    float w = r / d;
    field += w;
    acc += c[i] * w;
  }
  vec3 blobCol = acc / max(field, 0.001);
  float edge = smoothstep(0.95, 1.25, field);
  float gloss = smoothstep(1.9, 3.4, field);
  vec3 bg = vec3(0.06, 0.05, 0.09);
  vec3 col = mix(bg, blobCol * (0.85 + 0.35 * gloss), edge);
  col += blobCol * smoothstep(0.35, 1.1, field) * (1.0 - edge) * 0.35;
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

vec2 hash22(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

void main() {
  vec2 uv = v_uv * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0) * 4.5;
  vec2 i_st = floor(uv), f_st = fract(uv);
  float m1 = 8.0, m2 = 8.0;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 nb = vec2(float(x), float(y));
      vec2 pt = hash22(i_st + nb);
      pt = 0.5 + 0.42 * sin(u_time * 0.65 + 6.2831 * pt);
      float d = length(nb + pt - f_st);
      if (d < m1) { m2 = m1; m1 = d; }
      else if (d < m2) { m2 = d; }
    }
  }
  float edge = m2 - m1;
  float caustic = pow(1.0 - smoothstep(0.0, 0.28, edge), 2.4);
  float inner = smoothstep(0.0, 0.85, m1);

  vec3 deep = vec3(0.03, 0.11, 0.18);
  vec3 teal = vec3(0.06, 0.48, 0.58);
  vec3 foam = vec3(0.68, 0.96, 0.95);
  vec3 col = mix(deep, teal, inner * 0.72) + foam * caustic * 0.88;
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

void main() {
  vec2 uv = (v_uv - 0.5) * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  vec2 m = (u_mouse - 0.5) * 0.7;
  vec2 p = uv * 2.2;
  float t = u_time * 0.35;
  for (int i = 1; i <= 4; i++) {
    float fi = float(i);
    p.x += 0.42 / fi * sin(fi * 2.2 * p.y + t + m.x);
    p.y += 0.42 / fi * cos(fi * 2.0 * p.x - t * 0.9 + m.y);
  }
  float band = 0.5 + 0.5 * sin(p.x * 2.4 + p.y * 1.6);
  float band2 = 0.5 + 0.5 * cos(p.y * 2.8 - p.x * 1.3 + t);

  vec3 c1 = vec3(0.05, 0.14, 0.16);
  vec3 c2 = vec3(0.09, 0.46, 0.39);
  vec3 c3 = vec3(0.18, 0.24, 0.58);
  vec3 c4 = vec3(0.95, 0.78, 0.44);

  vec3 col = mix(c1, c2, smoothstep(0.15, 0.85, band));
  col = mix(col, c3, smoothstep(0.25, 0.85, band2) * 0.75);
  col += c4 * pow(band * band2, 3.0) * 0.72;
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.05; a *= 0.5; }
  return v;
}

void main() {
  vec2 uv = (v_uv - 0.5) * vec2(u_resolution.x / max(u_resolution.y, 1.0), 1.0);
  float a = atan(uv.y, uv.x);
  float r = length(uv);
  vec2 q = vec2(cos(a + u_time * 0.25), sin(a + u_time * 0.25)) * 2.2 + uv * 3.0;
  float turb = fbm(q + vec2(u_time * 0.2, -u_time * 0.15));
