  float w3=0.25+0.06*sin(uv.x*6.0+t*0.9+3.0);
  col=mix(col,vec3(0.82,0.88,0.96),smoothstep(w1+0.008,w1-0.008,uv.y));
  col=mix(col,vec3(0.16,0.58,0.89),smoothstep(w2+0.008,w2-0.008,uv.y));
  col=mix(col,vec3(0.08,0.09,0.12),smoothstep(w3+0.008,w3-0.008,uv.y));
  gl_FragColor=vec4(col,1.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image folds up like a pleated paper toward one side while the incoming one unfolds out of the other, both in 3D with lit and shadowed pleats
// Tags: fold, 3d, slide, stripes

// @range(1, 12, 1) Number of pleats in each image (a pleat is a pair of panels, one lit and one in the shade)
uniform int pleats; // = 4
// @param Direction in which the images move, snapped to its main axis (left, right, up or down): the outgoing image folds up toward it, the incoming one unfolds from the opposite side
uniform vec2 direction; // = vec2(-1.0, 0.0)
// @range(0, 1) Contrast between the lit and the shaded panels
uniform float shading; // = 0.7
// @range(0, 3) Amount of perspective: the valleys between the pleats recede
uniform float perspective; // = 1.5
// @color Color seen around the folded images, where the valleys recede
uniform vec4 backColor; // = vec4(0.0, 0.0, 0.0, 1.0)

const float LIGHT_SIDE = 0.55;
const float LIGHT_FRONT = 0.835;
const float EDGE = 0.0015;

// brightness of a panel folded by angle (c, s) = (cos, sin), facing the light (sign 1) or away (-1)
float panelLight(float c, float s, float facing) {
  float lambert = (c * LIGHT_FRONT + facing * s * LIGHT_SIDE) / LIGHT_FRONT;
  return mix(1.0, clamp(lambert, 0.08, 1.25), shading);
}

// f: position along the image (0 at its anchored side), c: cos of the fold angle, len: its length, b: position across it (frame heights)
vec4 pleated(float f, float c, float len, float b, float bLen, bool incoming, bool flipA, bool vertical) {
  float m = 2.0 * float(pleats > 1 ? pleats : 1);
  float s = sqrt(max(1.0 - c * c, 0.0));
  float u = f * m;
  // f = 1 is the end of the last panel, not the start of one more
  float panel = min(floor(u), m - 1.0);
  float fu = u - panel;
  // the ridges (odd boundaries) stay in the frame's plane, the valleys (even ones) recede
  float tri = 1.0 - abs(mod(u, 2.0) - 1.0);
  float panelLen = len / m;
  float z = panelLen * s * (1.0 - tri);
  float scale = 1.0 / (1.0 + perspective * z);
  float bb = (b - 0.5 * bLen) / scale / bLen + 0.5;
  // soft top and bottom edges while folded (sharp when flat, to keep the first and last frames exact)
  float edge = EDGE * min(1.0, 20.0 * s * c) + 1e-6;
  float cover = clamp(min(bb, 1.0 - bb) * bLen * scale / edge, 0.0, 1.0);
  float a = flipA ? 1.0 - f : f;
  vec2 st = clamp(vertical ? vec2(bb, a) : vec2(a, bb), 0.0, 1.0);
  vec4 img = incoming ? getToColor(st) : getFromColor(st);
  float facing = mod(panel, 2.0) < 0.5 ? 1.0 : -1.0;
  float toEdge = min(fu, 1.0 - fu) * panelLen * c;
  float k = 0.5 + 0.5 * clamp(toEdge / EDGE, 0.0, 1.0);
  float light = mix(panelLight(c, s, -facing), panelLight(c, s, facing), k);
  float valley = 1.0 - tri;
  light *= 1.0 - 0.4 * shading * s * valley * valley;
  return mix(backColor, vec4(img.rgb * light, img.a), cover);
}

vec4 transition(vec2 uv) {
  bool vertical = abs(direction.y) > abs(direction.x);
  bool positive = vertical ? direction.y > 0.0 : direction.x > 0.0;
  // a: along the motion, 0 on the side the outgoing image folds up toward; b: across it
  float a = vertical ? uv.y : uv.x;
  if (positive) a = 1.0 - a;
  float b = vertical ? uv.x : uv.y;
  float len = vertical ? 1.0 : ratio;
  float bLen = vertical ? ratio : 1.0;

  float p = progress;
  float e = p * p * (3.0 - 2.0 * p);
  e = mix(p, e, 0.8);
  float cFrom = 1.0 - e;
  float cTo = e;
  if (a < cFrom || cTo <= 0.0) {
    return pleated(a / cFrom, cFrom, len, b * bLen, bLen, false, positive, vertical);
  }
  return pleated(1.0 - (1.0 - a) / cTo, cTo, len, b * bLen, bLen, true, positive, vertical);
}

// Author: gre
// License: MIT
// Description: A black hole opens in the outgoing picture and shears it into a glowing disk of its own colors; the camera swings down to the edge of the disk, whose far side is seen bent up over the dark shadow, with the incoming picture as the sky warped all around; the disk is swallowed, the hole evaporates and the sky straightens out
// Tags: space, black-hole, lens, 3d, distort
// Preview: 0.58

// @range(0, 1.45) How far the camera swings down towards the plane of the disk
uniform float tilt; // = 1.36
// @range(0.03, 0.14) Radius of the hole, in frame heights
uniform float holeSize; // = 0.085
// @range(0, 1.5) Heat of the inner disk
uniform float glow; // = 0.8
// @color Color of the hole
uniform vec4 hole; // = vec4(0.0, 0.0, 0.0, 1.0)

const int STEPS = 40;
const float H = 0.17;
const float DIST = 1.6;

float heating() {
  return smoothstep(0.06, 0.4, progress);
}

vec2 mirrored(vec2 u) {
  return 1.0 - abs(1.0 - mod(u, 2.0));
}

float hash(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + 1.0), f.x), f.y);
}

vec2 turn(vec2 v, float a) {
  return vec2(v.x * cos(a) - v.y * sin(a), v.x * sin(a) + v.y * cos(a));
}

vec4 pm(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 material(vec2 d, float r, vec2 asp) {
  float hot = heating();
  vec2 w = turn(d, -2.2 * hot * progress * pow(max(r, 0.06), -1.1));
  vec2 b = 2.0 * w / asp;
  b *= b;
  // a soft cap keeps the disk within the picture, which would repeat past its edges
  w /= pow(1.0 + hot * dot(b, b), 0.25);
  return pm(getFromColor(mirrored(w / asp + 0.5)));
}

float diskCover(float r, float rs, float rOut) {
  return smoothstep(2.4 * rs - 1e-4, 3.1 * rs + 1e-4, r + step(rs, 0.0)) * (1.0 - smoothstep(0.82 * rOut, rOut, r)) * smoothstep(0.001, 0.02, rOut);
}

vec4 disk(vec2 d, float rs, float rOut, float st, vec2 asp) {
  float hot = heating();
  float r = length(d);
  float inner = 2.6 * rs;
  // the shear packs the picture along the radius
  vec2 e = 0.0035 * hot * d / max(r, 1e-4);
  vec4 c = 0.25 * (material(d - 1.5 * e, r - 1.5 * length(e), asp) + material(d - 0.5 * e, r - 0.5 * length(e), asp)
    + material(d + 0.5 * e, r + 0.5 * length(e), asp) + material(d + 1.5 * e, r + 1.5 * length(e), asp));
  vec2 s = turn(d / max(r, 1e-4), -2.0 * progress * pow(max(r, 0.06), -1.1));
  float lanes = noise(vec2(r * 46.0, 7.0)) * 0.6 + 0.4 * noise(vec2(r * 95.0, 3.0));
  lanes *= 0.75 + 0.5 * noise(s * 4.0 + 8.0 + r * 9.0);
  c.rgb *= mix(1.0, 0.45 + 1.3 * lanes, hot * 0.6);
  // Doppler beaming: the side turning towards the camera is brighter
  float beam = 1.0 + 0.55 * st * hot * d.x / max(r, 0.05);
  float heat = hot * glow * exp(-max(r - inner, 0.0) * 5.5);
  c.rgb = c.rgb * beam + heat * (c.rgb + 0.25 * c.a) * vec3(1.9, 1.1, 0.5) * beam * (0.4 + lanes);
  return c;
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  float lean = tilt * smoothstep(0.04, 0.55, p);
  float rs = holeSize * min(1.0, 0.35 + 0.65 * ratio) * smoothstep(0.02, 0.4, p) * (1.0 - smoothstep(0.62, 1.0, p));
  float hot = heating();
  float rOut = max(1e-3, 2.3 * pow(1.0 - smoothstep(0.12, 0.92, p), 1.1) - 0.12 * smoothstep(0.6, 0.95, p) + 6.0 * (1.0 - smoothstep(0.0, 0.16, p)));
  float ct = cos(lean);
  float st = sin(lean);
  float roll = 0.22 * smoothstep(0.1, 0.5, p) * (1.0 - smoothstep(0.65, 1.0, p));
  vec2 s = turn((uv - 0.5) * asp, roll);
  // the disk lies in z = 0 and the camera swings down towards its plane
  vec3 ex = vec3(1.0, 0.0, 0.0);
  vec3 ey = vec3(0.0, ct, st);
  vec3 ez = vec3(0.0, -st, ct);
  // a ray stays in the plane of the hole and its own direction
  float sl = max(length(s), 1e-4);
  vec3 et = (ex * s.x + ey * s.y) / sl;
  float u = 1.0 / DIST;
  float v = u * DIST / sl;
  float invB2 = u * u * (1.0 - rs * u) + v * v;
  // angle at which the ray crosses the disk, as a direction
  vec2 cr = normalize(vec2(-et.z, ez.z));

  float escaped = 0.0;
  // z = 1 once the ray has crossed the disk
  vec3 hitA = vec3(0.0);
  vec3 hitB = vec3(0.0);
  vec3 dir = -ez;
  float cH = cos(H);
  float sH = sin(H);
  for (int i = 0; i < STEPS; i++) {
    vec2 f = vec2(cos(float(i) * H), sin(float(i) * H));
    // u = 1 / r follows u'' = -u + 1.5 rs u^2: the first part is an exact rotation
    v += 0.75 * H * rs * u * u;
    float un = u * cH + v * sH;
    float vn = v * cH - u * sH;
    vec2 g = vec2(f.x * cr.x + f.y * cr.y, f.x * cr.y - f.y * cr.x);
    if (g.x < 0.0) g = -g;
    float uc = u * g.x + v * g.y;
    if (g.y > 0.0 && g.y <= sH && uc > 0.0) {
      vec2 at = vec2(f.x * g.x - f.y * g.y, f.y * g.x + f.x * g.y) / uc;
      vec3 hit = vec3(ez.x * at.x + et.x * at.y, ez.y * at.x + et.y * at.y, 1.0);
      if (hitA.z < 0.5) hitA = hit;
      else if (hitB.z < 0.5) hitB = hit;
    }
    if (un <= 0.0) {
      vec2 e = normalize(vec2(-v, u));
      dir = ez * (f.x * e.x - f.y * e.y) + et * (f.y * e.x + f.x * e.y);
      escaped = 1.0;
      break;
    }
    u = un;
    v = vn + 0.75 * H * rs * u * u;
    if (u * rs > 1.0) break;
  }

  vec3 cd = vec3(dot(dir, ex), dot(dir, ey), -dot(dir, ez));
  float far = 0.55 * length(asp) / DIST;
  float z1 = 1.0 / sqrt(1.0 + far * far);
  float q = max(1.0 - cd.z / z1, 0.0);
  // levels off past the corners, so that light bent backwards still lands on the picture
  float rho = cd.z > z1 ? length(cd.xy) / cd.z : far + 1.0 / sqrt(1.0 - z1 * z1) * q / (1.0 + 12.0 * q);
  vec2 sk = turn(normalize(cd.xy + 1e-6) * rho * DIST, -roll);
  vec4 sky = pm(getToColor(mirrored(sk / asp + 0.5)));
  float shade = smoothstep(0.1, 0.4, p) * (1.0 - smoothstep(0.6, 0.95, p));
  sky.rgb *= 1.0 - 0.28 * shade;
  // light that winds round the hole is a blur of the whole sky
  vec4 blur = pm(0.5 * (getToColor(vec2(0.3, 0.6)) + getToColor(vec2(0.7, 0.4))));
  sky = mix(vec4(0.35 * blur.rgb, blur.a), sky, smoothstep(-0.4, 0.5, cd.z));
  // b is conserved along the ray, and critical at sqrt(6.75) rs
  float b = 1.0 / sqrt(max(invB2, 1e-6));
  float bc = 2.598 * rs;
  float ring = glow * hot * exp(-max(b - bc, 0.0) / (0.004 + 0.25 * rs)) * smoothstep(0.0, 0.02, rs);
  sky.rgb += ring * vec3(0.75, 0.5, 0.28) * sky.a;
  float clear = escaped * smoothstep(bc - 0.0015, bc + 0.0015, b + step(rs, 0.0));
  vec4 acc = mix(pm(hole), sky, clear);
  float kA = hitA.z * diskCover(length(hitA.xy), rs, rOut);
  float kB = hitB.z * diskCover(length(hitB.xy), rs, rOut);
  if (kB > 0.0) acc = mix(acc, disk(hitB.xy, rs, rOut, st, asp), kB);
  if (kA > 0.0) acc = mix(acc, disk(hitA.xy, rs, rOut, st, asp), kA);
  return acc.a > 0.0 ? vec4(min(acc.rgb / acc.a, 1.0), acc.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A camera aperture opens its turning blades to reveal the incoming image
// Tags: shape, wipe, iris, rotate

#define PI 3.141592653589793

// @range(3, 12) Number of blades
uniform int blades; // = 6
// @range(-180, 180) How much the blades turn while opening, in degrees
uniform float rotation; // = 60.0
// @range(0, 1) How dark the blades are shaded along their edges
uniform float shadow; // = 0.5

const float AA = 0.006;

vec4 transition (vec2 uv) {
  // Square pixels, normalized so the frame's corners are at distance 1
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0) / (0.5 * length(vec2(ratio, 1.0)));
  float n = clamp(float(blades), 3.0, 12.0);
  float sector = 2.0 * PI / n;
  float turn = radians(rotation) * progress;
  // Each blade's straight edge is at distance r from the center: the opening is the polygon they enclose
  float r = mix(-AA, 1.0 + AA, progress);
  float dist = -1e3;
  float seam = 0.0;
  for (int i = 0; i < 12; i++) {
    if (float(i) < n) {
      float angle = turn + float(i) * sector;
      float d = dot(q, vec2(cos(angle), sin(angle))) - r;
      float next = dot(q, vec2(cos(angle + sector), sin(angle + sector))) - r;
      dist = max(dist, d);
      float s = 1.0 - smoothstep(0.0, 0.12, -d);
      seam = max(seam, (1.0 - smoothstep(0.0, AA, d)) * s * s * smoothstep(0.0, AA, next));
    }
  }
  float rim = 1.0 - smoothstep(0.0, 0.08, dist);
  float shade = shadow * max(rim * rim, seam) * smoothstep(0.0, 0.1, progress);
  vec4 from = getFromColor(uv);
  from.rgb *= 1.0 - shade;
  return mix(from, getToColor(uv), 1.0 - smoothstep(0.0, AA, dist));
}

// Author: gre
// License: MIT
// Description: A notched arrowhead window onto the incoming image flies in from the edge behind it (or appears at the center), then swells until it fills the frame
// Tags: shape, wipe, arrow, chevron, directional

// @param Direction the arrow points and flies toward
uniform vec2 direction; // = vec2(1.0, 0.0)
// @range(0, 0.9) Depth of the notch at the back of the arrowhead (0 for a plain triangle)
uniform float notch; // = 0.4
// @range(20, 160) Opening angle of the arrowhead's tip, in degrees
uniform float width; // = 80.0
// @range(1, 3, 1) Number of nested chevrons flying in a row
uniform int count; // = 1
// @param Grow the arrow from the center of the frame instead of flying it in
uniform bool origin; // = false
// @range(0, 0.1) Softness of the arrow's edges
uniform float smoothness; // = 0.004

// Signed distance (in frame heights) to an arrowhead whose tip is at x = tip and whose notch
// reaches back to x = back, in the arrow's frame (x along the direction, y = |across|)
float arrow(vec2 q, float tip, float back, vec2 tipN, vec2 notchN) {
  float front = dot(vec2(q.x - tip, q.y), tipN);
  float rear = dot(vec2(back - q.x, -q.y), notchN);
  return max(front, rear);
}

vec4 transition(vec2 uv) {
  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  vec2 across = vec2(-dir.y, dir.x);
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  vec2 q = vec2(dot(p, dir), abs(dot(p, across)));

  float s = max(smoothness, 0.001);
  float n = clamp(notch, 0.0, 0.9);
  float h = radians(0.5 * clamp(width, 20.0, 160.0));
  float cot = cos(h) / sin(h);
  vec2 tipN = vec2(sin(h), cos(h));
  float notchLen = length(vec2(1.0, n * cot));
  vec2 notchN = vec2(1.0, n * cot) / notchLen;
  // how far the tip must pass a point for the soft edge to clear it
  float tipPad = s / sin(h);

  vec2 c1 = vec2(0.5 * ratio, 0.5);
  vec2 c2 = vec2(0.5 * ratio, -0.5);
  vec2 k1 = vec2(abs(dot(c1, dir)), abs(dot(c1, across)));
  vec2 k2 = vec2(abs(dot(c2, dir)), abs(dot(c2, across)));
  float e = max(k1.x, k2.x);
  float r = 0.5 / max(abs(dir.x) / ratio, abs(dir.y));
  // To cover the frame, the tip must be ahead of every corner, and the notch behind every
  // corner and behind the back edge's middle (with room for the soft edge)
  float tipMin = max(k1.x + k1.y * cot, k2.x + k2.y * cot) + tipPad;
  float notchMax = min(min(n * cot * k1.y - k1.x, n * cot * k2.y - k2.x), -r) - s * notchLen;

  // The arrow (length 1 from tip to barbs) turns around the middle of its axis: its tip is
  // half its body ahead of that point, its notch half its body behind
  float body = 0.5 * (1.0 - n);
  // The scale at which the arrow centered on the frame covers it
  float cover = max(tipMin, -notchMax) / body;

  float t = progress;
  float o; // middle of the arrow
  float l; // size of the arrow
  if (origin) {
    o = 0.0;
    l = cover * t * (0.4 + 0.6 * t);
  } else {
    float l0 = 0.92 * min(1.0, ratio) / max(1.0, 2.0 * tan(h));
    float o0 = -e - 2.0 * tipPad - body * l0;
    float u = 1.0 - clamp(t / 0.65, 0.0, 1.0);
    float fly = 1.0 - u * u * u;
    // the swell speeds up and still moves at the end, so the last corners do not linger
    float grow = clamp((t - 0.3) / 0.7, 0.0, 1.0);
    o = mix(o0, 0.0, fly);
    l = mix(l0, cover, grow * grow * (2.0 - grow));
  }

  float gap = (1.0 - n) * 1.35;
  float d = arrow(q, o + body * l, o - body * l, tipN, notchN);
  for (int i = 1; i < 3; i++) {
    if (i < count) {
      float back = o - float(i) * gap * l;
      d = min(d, arrow(q, back + body * l, back - body * l, tipN, notchN));
    }
  }
  // the soft edge slides from outside the arrow to inside it, so nothing shows at the start
  float m = 1.0 - smoothstep(-s, s, d + 2.0 * s * (1.0 - t));

  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The image turns into text-mode characters, denser where it is brighter, the characters scramble into those of the incoming image, then resolve back into it
// Tags: text, pattern, retro, digital

// @range(0.01, 0.1) Height of a character, in frame heights
uniform float cellSize; // = 0.04
// @param Color the characters with the image (otherwise, with the ink color)
uniform bool colored; // = true
// @color Color of the characters when they are not colored with the image
uniform vec4 ink; // = vec4(0.3, 1.0, 0.45, 1.0)
// @color Color behind the characters
uniform vec4 background; // = vec4(0.0, 0.0, 0.0, 1.0)

// width of a character cell, in cell heights
const float ASPECT = 0.6;
const float STROKE = 0.05;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float segment(vec2 q, vec2 a, vec2 b) {
  vec2 pa = q - a;
  vec2 ba = b - a;
  return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}

// distance to the strokes of the character of density g, 0 (" ") to 9 ("@"), q in cell heights from its center
float glyph(float g, vec2 q) {
  if (g < 0.5) return 1.0; // " "
  if (g < 1.5) return length(q - vec2(0.0, -0.27)) - 0.035; // "."
  if (g < 2.5) return min(length(q - vec2(0.0, -0.25)), length(q - vec2(0.0, 0.1))) - 0.035; // ":"
  if (g < 3.5) return segment(q, vec2(-0.17, 0.0), vec2(0.17, 0.0)) - STROKE; // "-"
  if (g < 4.5) { // "="
    return min(segment(q, vec2(-0.18, 0.1), vec2(0.18, 0.1)), segment(q, vec2(-0.18, -0.1), vec2(0.18, -0.1))) - STROKE;
  }
  if (g < 5.5) { // "+"
    return min(segment(q, vec2(-0.19, 0.0), vec2(0.19, 0.0)), segment(q, vec2(0.0, -0.19), vec2(0.0, 0.19))) - STROKE;
  }
  if (g < 6.5) { // "*"
    float d = segment(q, vec2(0.0, -0.2), vec2(0.0, 0.2));
    d = min(d, segment(q, vec2(-0.18, -0.11), vec2(0.18, 0.11)));
    d = min(d, segment(q, vec2(-0.18, 0.11), vec2(0.18, -0.11)));
    return d - STROKE;
  }
  if (g < 7.5) { // "#"
    float d = min(segment(q, vec2(-0.06, -0.3), vec2(-0.1, 0.3)), segment(q, vec2(0.12, -0.3), vec2(0.08, 0.3)));
    d = min(d, min(segment(q, vec2(-0.24, 0.11), vec2(0.24, 0.11)), segment(q, vec2(-0.24, -0.11), vec2(0.24, -0.11))));
    return d - STROKE;
  }
  if (g < 8.5) { // "%"
    float d = segment(q, vec2(-0.2, -0.3), vec2(0.2, 0.3));
    d = min(d, abs(length(q - vec2(-0.13, 0.19)) - 0.08));
    d = min(d, abs(length(q - vec2(0.13, -0.19)) - 0.08));
    return d - STROKE;
  }
  // "@": a ring around a small "a"
  float d = abs(length(q) - 0.25);
  d = min(d, abs(length(q - vec2(-0.02, 0.0)) - 0.1));
  d = min(d, segment(q, vec2(0.08, 0.1), vec2(0.08, -0.12)));
  return d - 0.8 * STROKE;
}

float density(vec4 c) {
  return floor(pow(clamp(dot(c.rgb, vec3(0.299, 0.587, 0.114)) * c.a, 0.0, 1.0), 0.75) * 9.99);
}

vec4 cellColor(vec2 center, vec2 dims, bool incoming) {
  vec4 c = vec4(0.0);
  for (int i = 0; i < 4; i++) {
    vec2 o = (vec2(mod(float(i), 2.0), floor(float(i) / 2.0)) - 0.5) * 0.5 * dims;
    vec2 st = clamp((center + o) / vec2(ratio, 1.0) + 0.5, 0.0, 1.0);
    c += incoming ? getToColor(st) : getFromColor(st);
  }
  return c * 0.25;
}

vec4 transition(vec2 uv) {
  float p = progress;
  float h = cellSize;
  vec2 fp = (uv - 0.5) * vec2(ratio, 1.0);
  vec2 dims = vec2(ASPECT * h, h);
  vec2 cell = floor(fp / dims);
  vec2 center = (cell + 0.5) * dims;
  vec2 q = (fp - center) / h;

  float r = hash12(cell + 100.0);
  float at = 0.4 + 0.2 * r;
  bool incoming = p > at;
  vec4 c = cellColor(center, dims, incoming);
  float g = density(c);
  float scramble = 1.0 - smoothstep(0.02, 0.045, abs(p - at));
  if (hash12(cell + floor(p * 40.0) * vec2(17.0, 31.0)) < scramble) {
    g = 1.0 + floor(9.0 * hash12(cell * 1.7 + floor(p * 40.0) * vec2(5.0, 11.0)));
  }

  float cover = 1.0 - smoothstep(-0.02, 0.02, glyph(g, q));
  vec3 tint = colored ? mix(c.rgb, c.rgb / max(max(c.r, max(c.g, c.b)), 0.05), 0.7) : ink.rgb;
  float alpha = colored ? c.a : ink.a * c.a;
  vec3 behind = colored ? mix(background.rgb, c.rgb, 0.3) : background.rgb;
  vec4 back = vec4(behind, background.a * c.a);
  vec4 text = mix(back, vec4(clamp(tint, 0.0, 1.0), alpha), cover);

  float into = 0.05 + 0.22 * hash12(cell + 200.0);
  float outof = 0.95 - 0.22 * hash12(cell + 300.0);
  float show = smoothstep(into, into + 0.08, p) * (1.0 - smoothstep(outof - 0.08, outof, p));
  vec4 image = p < 0.5 ? getFromColor(uv) : getToColor(uv);
  return mix(image, text, show);
}

// Author: gre
// License: MIT
// Description: Alternating bands wipe in from opposite sides together and interleave like fingers, while both images stay still
// Tags: wipe, stripes, interleave, horizontal

// @range(2, 40, 1) Number of bands
uniform int bands; // = 8
// @param Cut the frame into columns that wipe up and down instead of rows that wipe sideways
uniform bool vertical; // = false
// @range(0, 0.2) Softness of the bands' leading edges
uniform float smoothness; // = 0.02
// @range(0, 0.8) Delay between the first and the last band, so they cascade from the top (or the left)
uniform float stagger; // = 0.1

const float AA = 0.0015;

// how far band i has wiped in (0..1) at position a along the bands (0..l), alternate bands
// entering from opposite ends
float bandMask(float i, float n, float a, float l, float s) {
  float k = vertical ? i : n - 1.0 - i;
  float g = clamp(stagger, 0.0, 0.95);
  float t = clamp((progress - g * k / max(n - 1.0, 1.0)) / (1.0 - g), 0.0, 1.0);
  t = mix(t, t * t * (3.0 - 2.0 * t), 0.5);
  float x = mod(i, 2.0) > 0.5 ? l - a : a;
  // the edge starts fully before the band and ends fully past it
  float c = mix(-s, l + s, t);
  return 1.0 - smoothstep(c - s, c + s, x);
}

vec4 transition(vec2 uv) {
  float n = float(bands < 1 ? 1 : bands);
  // along: position along the bands, in frame heights; across: position across them (0..1)
  float along = vertical ? uv.y : uv.x * ratio;
  float across = vertical ? uv.x : uv.y;
  float l = vertical ? 1.0 : ratio;
  float aaAcross = vertical ? AA / ratio : AA;
  float s = max(smoothness, AA);

  float f = across * n;
  float i = clamp(floor(f), 0.0, n - 1.0);
  float m = bandMask(i, n, along, l, s);

  // near a cut between two bands, blend with the neighbor band over a pixel or so so the cut
  // does not alias (at the frame's borders the neighbor is the band itself)
  float fr = f - i;
  float edge = min(fr, 1.0 - fr) / n;
  if (edge < aaAcross) {
    float j = clamp(fr < 0.5 ? i - 1.0 : i + 1.0, 0.0, n - 1.0);
    m = mix(bandMask(j, n, along, l, s), m, 0.5 + 0.5 * smoothstep(0.0, aaAcross, edge));
  }

  if (m <= 0.0) return getFromColor(uv);
  if (m >= 1.0) return getToColor(uv);
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image is a thin film of liquid on glass that pulls itself apart like water on a waxed surface: dry holes open and grow with glossy rolled rims, meet in a web of ridges, the ridges break into round beads that magnify the picture, and the beads dry up over the incoming image
// Tags: liquid, water, surface-tension, refraction, organic

// @range(2, 6) Number of rows of holes across the frame
uniform float holes; // = 2.5
// @range(0.01, 0.06) Radius of the rims and beads, in frame heights (at most a seventh of the space between holes)
uniform float rim; // = 0.026
// @range(0, 1) Strength of the reflections and of the magnification in the liquid
uniform float gloss; // = 0.7

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec3 hash3(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xxy + p3.yzz) * p3.zyx);
}

// the liquid at x (frame heights): x = signed distance into the liquid (negative where dry), y = height
vec2 liquid(vec2 x, float p) {
  float cs = 1.0 / max(holes, 1.0);
  // the rims and beads stay small next to the holes, so the beads keep round when holes are many
  float w = clamp(rim, 0.001, 0.15 * cs);
  vec2 cell = floor(x / cs);
  float d1 = 1e3, d2 = 1e3;
  vec2 c1 = vec2(0.0), c2 = vec2(1.0, 0.0);
  float s1 = 0.0, s2 = 0.0;
  float hRim = 0.0;
  for (int j = -2; j <= 2; j++) {
    for (int i = -2; i <= 2; i++) {
      vec2 n = cell + vec2(float(i), float(j));
      vec3 h = hash3(n + 17.0);
      vec2 c = (n + 0.5 + 0.75 * (h.xy - 0.5)) * cs;
      float age = p - 0.28 * h.z;
      if (age <= 0.0) continue;
      float d = length(x - c) - 2.3 * cs * age - 0.6 * smoothstep(0.6, 1.0, p);
      // the rolled rim in front of the hole, which gathers as the hole opens instead of popping in at full size
      float wh = w * smoothstep(0.0, 0.06, age);
      hRim = max(hRim, sqrt(max(wh * wh - (d - wh) * (d - wh), 0.0)));
      if (d < d1) { d2 = d1; c2 = c1; s2 = s1; d1 = d; c1 = c; s1 = h.x; }
      else if (d < d2) { d2 = d; c2 = c; s2 = h.x; }
    }
  }
  hRim *= step(0.0, d1);
  if (d2 > 1e2) return vec2(d1, hRim);
  float e = 0.5 * (d2 - d1);
  float meet = clamp(1.0 - 0.5 * (d1 + d2) / (2.0 * w), 0.0, 1.0);
  vec2 axis = normalize(c2 - c1);
  // the same way for both holes, so the beads line up across the ridge
  axis *= axis.x < 0.0 ? -1.0 : 1.0;
  float along = dot(x - 0.5 * (c1 + c2), vec2(-axis.y, axis.x));
  float lambda = 6.5 * w;
  float k = along / lambda + s1 + s2;
  float db = length(vec2(e, (fract(k) - 0.5) * lambda));
  float beading = smoothstep(0.4, 0.62, p);
  float dry = 1.0 - smoothstep(0.62, 0.97, p);
  float wr = w * sqrt(meet) * (1.0 - beading);
  float rb = 1.55 * w * smoothstep(0.0, 1.0, beading) * dry;
  float hRidge = sqrt(max(wr * wr - e * e, 0.0));
  float hBead = sqrt(max(rb * rb - db * db, 0.0));
  float inside = max(d1, max(wr > 0.0 ? wr - e : -1.0, rb > 0.0 ? rb - db : -1.0));
  return vec2(inside, max(hRim, max(hRidge, hBead)));
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 x = uv * asp;
  vec2 L = liquid(x, p);
  float px = 0.0015;
  float cover = clamp(L.x / px + 0.5, 0.0, 1.0);
  vec4 to = getToColor(uv);
  to.rgb *= 1.0 - 0.18 * gloss * (1.0 - smoothstep(0.8, 0.98, p)) * (1.0 - smoothstep(0.0, 0.012, -L.x)) * step(L.x, 0.0);
  if (cover <= 0.0) return to;

  float eps = 0.002;
  vec2 g = vec2(liquid(x + vec2(eps, 0.0), p).y - L.y, liquid(x + vec2(0.0, eps), p).y - L.y) / eps;
  g = clamp(g, -6.0, 6.0);
  vec3 n = normalize(vec3(-g, 1.0));
  vec2 off = g * L.y * 0.5 * gloss;
  vec4 img = getFromColor(fold((x + off) / asp));
  vec3 light = normalize(vec3(-0.45, 0.55, 0.7));
  vec3 hv = normalize(light + vec3(0.0, 0.0, 1.0));
  float diffuse = dot(n, light) - light.z;
  float spec = max(pow(max(dot(n, hv), 0.0), 60.0) - pow(hv.z, 60.0), 0.0);
  float side = pow(1.0 - n.z, 3.0);
  vec3 c = img.rgb * (1.0 + 0.45 * gloss * diffuse) * (1.0 - 0.5 * gloss * side) + gloss * spec;
  c *= 1.0 - 0.35 * gloss * (1.0 - smoothstep(0.0, 0.004, L.x));
  vec4 wet = vec4(c, img.a);
  return mix(to, wet, cover);
}

// Author: gre
// License: MIT
// Description: The outgoing image is drawn out into flat rays of its own colors that zigzag in and out from the center like a jagged star; the star turns and keeps growing, the colors of the incoming image open along every ray, and the zigzags straighten out into it
// Tags: rays, zigzag, star, flat-color, geometric
// Preview: 0.5

// @range(6, 24, 1) Rays around the center
uniform float rays; // = 12.0
// @range(-1, 1) Turns made by the star
uniform float turns; // = 0.25

const float TAU = 6.28318530718;

float stair(float s, float m) {
  float f = 2.0 * fract(s) - 1.0;
  return floor(s) + 0.5 + 0.5 * sign(f) * pow(abs(f), m);
}

vec4 transition(vec2 uv) {
  vec2 asp = vec2(ratio, 1.0);
  float count = max(floor(rays + 0.5), 1.0);
  float k = smoothstep(0.0, 0.4, progress) * (1.0 - smoothstep(0.6, 1.0, progress));
  float m = 1.0 / max(1.0 - k, 0.03);
  // once flat, colors average a small area so that single pixels don't flicker
  float soft = 16.0 * pow(k, 8.0);
  float spin = TAU * turns * progress;
  vec4 sum = vec4(0.0);
  for (int i = 0; i < 16; i++) {
    vec2 o = (vec2(mod(float(i), 4.0), floor(float(i) / 4.0)) - 1.5) / 1200.0;
    vec2 p = (uv - 0.5) * asp + o * k;
    float lr = log(max(length(p), 1e-3) / 0.4) / 0.7 - 1.1 * progress;
    float odd = mod(floor(lr), 2.0);
    // tangents to nested circles, every other ring leaning back so that the rays join into zigzags
    float a = atan(p.y, p.x) + (1.0 - 2.0 * odd) * (acos(exp(-0.7 * fract(lr))) - 1.0519 * odd);
    float b = (a - spin) / TAU * count;
    float g = smoothstep(0.0, 0.3, progress - 0.25 - 0.2 * fract(mod(floor(b), count) * 0.618));
    bool late = fract(b) < g * 1.02 - 0.01;
    a = stair(b, m) / count * TAU + spin;
    vec2 q = vec2(cos(a), sin(a)) * (0.4 - 0.12 * progress);
    q = mix(p, q, k) / asp + 0.5 + soft * o;
    q = 1.0 - abs(1.0 - mod(q, 2.0));
    vec4 c = late ? getToColor(q) : getFromColor(q);
    sum += vec4(c.rgb * c.a, c.a);
  }
  return vec4(sum.rgb / max(sum.a, 1e-5), sum.a / 16.0);
}

// Author: gre
// License: MIT
// Description: The incoming image flows over the outgoing one like one fluid sliding over another, its front rolling up into a row of curling spirals that wind the two images into each other, tighten as they sweep across the frame and drift sideways, then leave it
// Tags: fluid, wave, swirl, organic, directional, wipe

// @param Direction the front travels toward
uniform vec2 direction; // = vec2(0.0, -1.0)
// @range(0.2, 1.2) Distance between the curls, in frame heights
uniform float spacing; // = 0.55
// @range(0, 12) How many radians the curls wind up while crossing the frame
uniform float winding; // = 9.0
// @range(-1, 1) How far the curls drift sideways while crossing, in frame heights
uniform float drift; // = 0.35

// radius of a curl, relative to the distance between the curls
const float SIZE = 0.47;
// how far the curls are already wound when they enter the frame, in radians
const float START = 1.5;
// how far before the frame the eyes of the curls start, in curl radii
const float ENTER = 0.5;
// share of the transition the curls take to start winding
const float RAMP = 0.15;
// width of the lit lip on the incoming side and of the shadow on the outgoing side, in frame heights
const float LIP = 0.02;
const float SHADOW = 0.035;
// half width of the antialiased interface, in frame heights
const float AA = 0.0015;

// folds coordinates back into the frame, so a curl reaching past the edge never smears its border pixels
vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  float t = progress;

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(0.0, -1.0);
  // across the front, so that (side, -dir) keeps the orientation of the frame
  vec2 side = vec2(-dir.y, dir.x);
  vec2 aspect = vec2(ratio, 1.0);
  vec2 p = (uv - 0.5) * aspect;
  // half extent of the frame along the travel, in frame heights
  float E = 0.5 * (abs(dir.x) * ratio + abs(dir.y));
  float S = max(spacing, 0.01);
  float R = SIZE * S;

  // the front sweeps from just before the frame, its curls not wound yet, to fully past it, curls included
  float e = mix(t, t * t * (3.0 - 2.0 * t), 0.3);
  float front = mix(-E - max(ENTER * R, SHADOW + AA), E + R + 0.02, e);
  float slide = drift * t;
  // u across the front, v behind it (on the incoming side)
  float u = dot(p, side) - slide;
  float v = front - dot(p, dir);
  // the curl of this column, centered on the front
  float cu = floor(u / S + 0.5) * S;
  vec2 q = vec2(u - cu, v);
  float r = length(q);
  // away from the front, the images are untouched
  if (v < -max(R, SHADOW)) return getFromColor(uv);
  if (v > max(R, LIP)) return getToColor(uv);

  // each curl winds both images into a spiral: still at its rim, turning most at its eye, tighter as it travels
  float x = clamp(r / R, 0.0, 1.0);
  float s = 1.0 - x * x * (3.0 - 2.0 * x);
  float fall = s * s;
  // the curls start winding as they enter the frame
  float turns = (START + winding * t) * smoothstep(0.0, RAMP, t);
  float a = turns * fall;
  float c = cos(a);
  float sn = sin(a);
  vec2 w = vec2(c * q.x + sn * q.y, c * q.y - sn * q.x);

  vec2 src = mirror(uv + ((w.x - q.x) * side - (w.y - q.y) * dir) / aspect);
  vec4 outgoing = getFromColor(src);
  vec4 incoming = getToColor(src);

  // the interface is where the unwound point crosses the front; its distance on screen comes from the gradient of w.y
  float dfall = -12.0 * s * x * (1.0 - x) / R;
  vec2 grad = vec2(-sn, c) - w.x * turns * dfall * (r > 0.0 ? q / r : vec2(0.0));
  float phi = w.y / max(length(grad), 0.1);
  float m = smoothstep(-AA, AA, phi);

  // a lit lip on the incoming side and a soft shadow on the outgoing side, along the whole interface
  float lip = 1.0 - smoothstep(0.0, LIP, phi);
  float shadow = 1.0 - smoothstep(0.0, SHADOW, -phi);
  incoming.rgb += (1.0 - incoming.rgb) * 0.25 * lip;
  outgoing.rgb *= 1.0 - 0.3 * shadow * shadow;

  // mixed premultiplied, so transparent images do not bleed their color
  vec4 col = mix(vec4(outgoing.rgb * outgoing.a, outgoing.a), vec4(incoming.rgb * incoming.a, incoming.a), m);
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image is eaten like a cookie: bites are snapped out of its edges one after another, each deeper than the last and leaving a scalloped tooth-marked hole with a dark bitten rim, a jolt and falling crumbs, until a last big bite takes the rest and leaves the incoming image
// Tags: bite, eat, cookie, crumbs, playful

// @range(1, 9, 1) Number of bites before the last one
uniform int bites; // = 6
// @range(0, 1) How hard each bite jolts the image
uniform float jolt; // = 0.6
// @range(0, 1) Darkness of the bitten rims and of the shadow the image casts into the holes
uniform float shading; // = 0.6

const float START = 0.04;
const float LAST = 0.74;
const float SNAP = 0.06;
const float CRUMB_LIFE = 0.26;

float hash(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

float hash2(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash2(i), hash2(i + vec2(1.0, 0.0)), f.x),
             mix(hash2(i + vec2(0.0, 1.0)), hash2(i + vec2(1.0, 1.0)), f.x), f.y);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

float scale() {
  return min(ratio, 1.0);
}

float biteCount() {
  return clamp(float(bites), 1.0, 9.0);
}

float biteStart(float k) {
  return START + k * (LAST - START) / biteCount();
}

float biteRadius(float k) {
  return (0.28 + 0.22 * k / biteCount()) * scale();
}

vec2 biteDir(float k) {
  float a = 2.39996 * k + 0.6;
  return vec2(cos(a), sin(a));
}

// placed so the bite always cuts the frame edge, reaching deeper inside for later bites
vec2 biteCenter(float k) {
  vec2 d = biteDir(k);
  vec2 h = vec2(0.5 * ratio, 0.5);
  float e = min(h.x / max(abs(d.x), 1e-4), h.y / max(abs(d.y), 1e-4));
  float r = biteRadius(k);
  return h + d * (e + r - r * (0.55 + 0.6 * k / biteCount()));
