float growth(float t0) {
  float t = 1.0 - clamp((progress - t0) / SNAP, 0.0, 1.0);
  return 0.92 * (1.0 - t * t * t) + 0.08 * clamp((progress - t0) / (LAST - t0), 0.0, 1.0);
