  float crumbShade = 1.0;
  float ca = 0.0;
  for (int k = 0; k < 9; k++) {
    float fk = float(k);
    if (fk >= biteCount()) break;
    float t0 = biteStart(fk);
    if (progress < t0) break;
    float g = growth(t0);
    vec2 c = biteCenter(fk);
    float r = biteRadius(fk);
