        continue;
      }
      vec2 src = home + q;
      // the frame cuts the wall's edge bricks: their part outside it is never drawn
      vec4 b = getFromColor(falling > 0.0 ? vec2(src.x / ratio, src.y) : uv);
      vec2 inFrame = clamp(min(src, vec2(ratio, 1.0) - src) * grow / EDGE + 1.0, 0.0, 1.0);
      vec2 l = q / vec2(bw, bh) + 0.5;
      float lit = min(s * 8.0, 1.0);
      float joint = 1.0 - smoothstep(0.0, 0.004 + 0.004 * lit, e);
      b.rgb *= 1.0 - 0.45 * k * joint * appear;
      b.rgb *= 1.0 + 0.25 * k * lit * (l.y - l.x);
      b.rgb *= 1.0 - 0.35 * k * falling * min(s * 4.0, 1.0) * (1.0 - l.y);
      if (falling > 0.0) {
        float a = mix(1.0, clamp(e * grow / EDGE + 0.5, 0.0, 1.0), moving) * inFrame.x * inFrame.y;
        // the brick that has grown most is nearest to the eye
        if (grow > fallGrow) {
          float nc = a + fallCov * (1.0 - a);
          if (nc > 0.0) fall = mix(fall, b, a / nc);
          fallCov = nc;
          fallGrow = grow;
        } else {
          float w = a * (1.0 - fallCov);
          fallCov += w;
          if (w > 0.0) fall = mix(fall, b, w / fallCov);
        }
      } else {
        wall = b;
        wallCov = 1.0;
      }
    }
  }
  vec4 c = getToColor(uv);
  c.rgb *= 1.0 - 0.55 * k * ao;
  c = mix(c, wall, wallCov);
  c.rgb *= 1.0 - 0.45 * k * shadow;
  return mix(c, fall, fallCov);
}

// Author: gre
// License: MIT
// Description: A few broad brush strokes sweep across the frame in turn, back and forth, painting in the incoming image with streaky bristle edges and dry, ragged ends
// Tags: wipe, paint, brush, organic

// @range(1, 8, 1) Number of brush strokes needed to cover the frame
uniform float strokes; // = 4.0
// @range(-45, 45) Angle of the strokes, in degrees
uniform float angle; // = -7.0
// @range(0, 1) How rough the bristles make the edges and ends of the strokes
uniform float roughness; // = 0.6
// @range(0, 1) How much the strokes wave along their way
uniform float waviness; // = 0.5

const float PI = 3.141592653589793;

float hash (vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float vnoise (vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// bristle streaks: fine across the stroke (t), long along it (u)
float bristles (float t, float u, float seed) {
  return 0.6 * vnoise(vec2(t * 26.0 + seed, u * 1.3 + seed)) + 0.4 * vnoise(vec2(t * 8.0 - seed, u * 0.7));
}

// one stroke: k its index, t the position across it (-1..1 is its core), u along it
// returns (coverage, wet streak shading)
vec2 stroke (float k, float t, float u, float U, float n, float h) {
  float dir = mod(k, 2.0) < 0.5 ? 1.0 : -1.0;
  float x = u * dir;
  float dur = min(1.0, 1.8 / (n + 0.8));
  float start = n > 1.0 ? k * (1.0 - dur) / (n - 1.0) : 0.0;
  float s = clamp((progress - start) / dur, 0.0, 1.0);
  s = mix(s, s * s * (3.0 - 2.0 * s), 0.7);
  float r = roughness;
  float lag = (0.15 + 0.6 * r) * h; // how far the longest bristles run ahead of the shortest
  float dry = (0.1 + 0.9 * r) * h; // length of the streaky, dry trail behind the head of the stroke
  // at the end even the shortest bristles, at the rounded corners, are past the far edge with their dry trail
  float head = mix(-U, U + lag + 0.3 * h + 1.15 * dry + 0.01, s);
  float b = bristles(t, k * 3.7, k * 17.0);
  float front = head - lag * (1.0 - b) - 0.3 * h * t * t;
  float streak = bristles(t * 1.7, x * 2.0 / h, k * 5.0 + 9.0);
  float along = clamp(((front - x) / (dry + 0.001) - 0.1 - 0.8 * streak) * 6.0, 0.0, 1.0);
  float fringe = 0.1 + 0.7 * r;
  float e = (abs(t) - 1.0) / fringe; // < 0 in the core of the stroke
  float reach = 0.5 + 0.5 * vnoise(vec2(x * 2.5 / h, k * 7.0 + (t > 0.0 ? 3.0 : 0.0)));
  float hair = clamp(bristles(t * 1.4, x * 3.0 / h, k * 11.0 + 3.0) * 2.0 - 0.5, 0.0, 1.0);
  float side = clamp((reach * hair - e) * 12.0 + 1.0, 0.0, 1.0);
  float cover = along * side;
  float wet = (1.0 - clamp((progress - start - dur) / 0.25, 0.0, 1.0)) * min(1.0, (1.0 - progress) * 6.0);
  return vec2(cover, cover * wet * (bristles(t * 2.0, x * 2.0 / h, k) - 0.5));
}

vec4 transition (vec2 uv) {
  float a = angle * PI / 180.0;
  float c = cos(a);
  float sn = sin(a);
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  float u = c * q.x + sn * q.y; // along the strokes
  float v = -sn * q.x + c * q.y; // across them
  float U = 0.5 * (abs(c) * ratio + abs(sn));
  float V = 0.5 * (abs(sn) * ratio + abs(c));
  float n = max(1.0, floor(strokes + 0.5));
  float h = 2.0 * V / n;
  // waves shared by the neighbouring strokes so that they always tile the frame
  float A = 0.12 * waviness * h;
  float w = v + A * sin(u * 5.0 / U + v * 2.0 / h + 1.3) + 0.5 * A * sin(u * 11.0 / U - v * 3.0 / h);
  float y = (V + 1.5 * A - w) / (2.0 * V + 3.0 * A) * n;
  float hh = (2.0 * V + 3.0 * A) / n;
  float k = clamp(floor(y), 0.0, n - 1.0);
  float cover = 0.0;
  float shade = 0.0;
  for (int i = -1; i <= 1; i++) {
    float j = k + float(i);
    if (j >= 0.0 && j <= n - 1.0) {
      vec2 s = stroke(j, (y - j - 0.5) * 2.0, u, U, n, hh);
      cover = max(cover, s.x);
      shade = mix(shade, s.y, s.x);
    }
  }
  vec4 from = getFromColor(uv);
  vec4 to = getToColor(uv);
  to.rgb = min(to.rgb * (1.0 + 0.2 * shade), 1.0);
  return mix(from, to, cover);
}

// Author: gre
// License: MIT
// Description: The outgoing image turns into a patchwork of small and large squares where concentric circles, squares and diamonds in flat colors of both images keep pulsing outwards, one inside another, from the middle of the frame to its corners; the last pulse of each square opens onto the incoming image
// Tags: geometric, rings, squares, grid, pattern, colorful

// @range(2, 8, 1) Number of large squares along the shorter side of the frame
uniform float count; // = 4.0
// @range(0, 1) Share of the large squares that are split into four small ones
uniform float split; // = 0.45
// @range(0, 1) How far the pulses lag from the middle of the frame to its corners
uniform float spread; // = 0.5

float hash12(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

// 1 in the corners of the cell, whatever the shape
float metric(vec2 q, float kind) {
  q = abs(q);
  if (kind < 0.45) return length(q) / 1.4143;
  if (kind < 0.75) return max(q.x, q.y);
  return 0.5 * (q.x + q.y);
}

vec4 premultiplied(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

// averaged over a small patch, so a ring does not flicker with the grain of a video
vec4 flatColor(vec2 c, vec2 e, bool incoming) {
  vec4 s = vec4(0.0);
  for (int i = 0; i < 4; i++) {
    vec2 st = c + e * vec2(i < 2 ? -1.0 : 1.0, i == 1 || i == 3 ? 1.0 : -1.0);
    s += 0.25 * premultiplied(incoming ? getToColor(st) : getFromColor(st));
  }
  return s;
}

vec4 transition(vec2 uv) {
  float n = max(floor(count + 0.5), 1.0);
  vec2 res = floor(n * vec2(max(ratio, 1.0), max(1.0 / ratio, 1.0)) + 0.5);
  vec2 g = uv * res;
  vec2 cell = floor(g);
  float salt = 1.0;
  if (hash12(cell + 3.0) < split) {
    salt = 2.0;
    res *= 2.0;
    g = uv * res;
    cell = floor(g);
  }
  float seed = hash12(cell + 7.0 * salt);
  float kind = hash12(cell + 31.0 * salt);
  vec2 q = 2.0 * (g - cell) - 1.0;
  vec2 c = (cell + 0.5) / res;
  vec2 asp = vec2(ratio, 1.0);
  float away = length((c - 0.5) * asp) / (0.5 * length(asp));
  float delay = 0.45 * spread * clamp(1.25 * mix(away, seed, 0.3) - 0.25, 0.0, 1.0);
  float life = 1.0 - 0.45 * spread;
  float d = metric(q, kind);
  // circles and diamonds have a gentler metric than squares
  float aa = 0.0028 * res.y * (kind < 0.45 || kind >= 0.75 ? 0.7071 : 1.0);
  vec2 off = 0.3 / res;
  vec4 col = premultiplied(getFromColor(uv));
  for (int i = 0; i < 5; i++) {
    float s = clamp(((progress - delay) / life - 0.13 * float(i)) / 0.48, 0.0, 1.0);
    s = i < 4 ? s * (1.6 - 0.6 * s) : s * (0.55 + 0.45 * s * s);
    float r = s * (1.0 + 2.0 * aa) - aa;
    float m = 1.0 - smoothstep(r - aa, r + aa, d);
    // the frame left around the last pulse fades out before it gets thin
    if (i == 4) m = max(m, smoothstep(0.7, 0.96, s));
    if (m > 0.0) {
      vec4 l;
      if (i == 4) {
        l = premultiplied(getToColor(uv));
      } else {
        vec2 o = i == 0 ? vec2(0.0) : i == 1 ? vec2(1.0) : i == 2 ? vec2(-1.0, 1.0) : vec2(-1.0);
        l = flatColor(c + off * o, 0.06 / res, i == 0 || i == 2);
      }
      col = mix(col, l, m);
    }
  }
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: liubailin2020@gmail.com
// License: MIT
// Description: The outgoing image burns away in noisy, glowing patches
// Tags: burn, fire, noise

// @color Color of the burning edges
uniform vec3 burnColor; // = vec3(1.0, 0.5, 0.0)

float random (in vec2 st) {
    return fract(sin(dot(st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}

// Based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise (in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

#define OCTAVES 4
float fbm (in vec2 st) {
    float value = 0.0;
    float amplitude = .5;
    for (int i = 0; i < OCTAVES; i++) {
        value += amplitude * noise(st);
        st *= 2.;
        amplitude *= .5;
    }
    return value;
}

vec4 transition (vec2 uv) {
    vec4 from = getFromColor(uv);
    vec4 to = getToColor(uv);
    float n = fbm(uv * 4.);
    float e = progress * 1.05 - 0.05;
    float l = smoothstep(e, e + 0.05, n);
    float edge = (1.0 - l) * l * 5.0;
    return mix(to, from, l) + vec4(burnColor, 0.0) * edge;
}

// Author: gre
// License: MIT
// Description: The outgoing picture becomes a butterfly: its two halves round off into wings that start beating, folding toward the viewer on the center line, and the butterfly flutters away up and to the right, growing smaller as it bobs along, until it leaves the frame and its shadow fades off the incoming picture
// Tags: 3d, fold, fly, nature, shadow

// @range(2, 8) Wing beats during the flight
uniform float beats; // = 5.0

const float PI = 3.1415927;

float ellipse(vec2 p, vec2 c, vec2 r, float a) {
  p -= c;
  p = mat2(cos(a), -sin(a), sin(a), cos(a)) * p;
  return (length(p / r) - 1.0) * min(r.x, r.y);
}

// signed distance of the wing, from the picture's half (hw wide) to a wing shape hw wide and h tall
float wing(vec2 v, float hw, float h, float m) {
  // the box reaches past the hinge so the two halves meet without a seam
  vec2 b = abs(v) - vec2(hw, 0.5);
  float rect = length(max(b, 0.0)) + min(max(b.x, b.y), 0.0);
  vec2 w = v / vec2(hw, h);
  float fore = ellipse(w, vec2(0.5, 0.15), vec2(0.56, 0.33), 0.45);
  float hind = ellipse(w, vec2(0.36, -0.2), vec2(0.4, 0.28), -0.6);
  float body = ellipse(w, vec2(0.0, -0.04), vec2(0.06, 0.4), 0.0);
  return mix(rect, min(min(fore, hind), body) * min(hw, h), m);
}

// returns the picture uv in xy, coverage in z, wing tilt in w
vec4 butterfly(vec2 p, float t, float blur) {
  // no ease-out: the butterfly keeps speeding up until it leaves the frame, just before the end
  float fly = clamp((t - 0.08) / 0.92, 0.0, 1.0);
  float S = mix(1.0, 0.15, smoothstep(0.0, 0.8, fly));
  vec2 c = vec2(0.5 * ratio + 0.2, 0.66) * fly * fly + vec2(0.0, 0.24 * sin(PI * beats * t) * fly * (1.0 - fly));
  float tilt = -0.35 * fly;
  vec2 q = mat2(cos(tilt), sin(tilt), -sin(tilt), cos(tilt)) * (p - c) / S;
  float amp = 1.15 * smoothstep(0.0, 0.25, t) * (1.0 - smoothstep(0.9, 1.0, t));
  float th = amp * (0.5 - 0.5 * cos(2.0 * PI * beats * t));
  float sn = sin(th), cs = cos(th);
  float hw = 0.5 * ratio;
  // narrow frames get a shorter butterfly, so its wings keep their shape
  float h = min(1.0, 1.15 * hw);
  // the camera distance follows the wing size, so a folded tip never reaches the camera on wide frames
  float f = 2.5 * max(hw, h);
  float X = abs(q.x);
  float d = X * f / (cs * f + X * sn);
  float y = q.y * (f - d * sn) / f;
  float m = smoothstep(0.0, 0.12, t);
  float sd = wing(vec2(d, y), hw, h, m);
  float px = (0.003 + blur) / S * smoothstep(0.0, 0.04, t) + 1e-4;
  float cov = clamp(-sd / px + 1.0 - smoothstep(0.0, 0.04, t) * 0.5, 0.0, 1.0);
  // the body is drawn flat, in front of the beating wings
  float bd = ellipse(q, vec2(0.0, -0.02), vec2(0.025 * hw, 0.38 * h), 0.0);
  float body = m * (1.0 - smoothstep(-px, px, bd));
  return vec4(vec2(sign(q.x) * d / ratio + 0.5, y + 0.5), cov, max(0.45 * sn, body));
