      float rim = 1.0 - smoothstep(0.0, 0.008, cardDist(q, size));
      face.rgb = mix(min(face.rgb * light, vec3(face.a)), vec3(face.a), 0.45 * air * rim);
      col = mix(col, face, m);
    }
  }
  return col;
}

