    float body = smoothstep(cov, cov + 0.1, d);
    // density met on the way to the sun: Beer's law self-shadowing
    float ds = fbm(q + sun * 0.12);
    float lit = exp(-6.0 * max(ds - cov, 0.0));
    // thin edges glow when the sun shines through them
    float rim = (1.0 - smoothstep(0.0, 0.1, d - cov)) * 0.35;
    vec3 cl = mix(shade.rgb, vec3(1.0, 0.98, 0.94), clamp(lit + rim, 0.0, 1.0));
    col.rgb = mix(col.rgb, cl * sky, body * life);
  }
  float white = smoothstep(0.38, 0.5, p) * (1.0 - smoothstep(0.5, 0.62, p));
  col.rgb = mix(col.rgb, vec3(0.96, 0.97, 1.0) * (0.92 + 0.08 * up), white);
  return col;
}

// Author: gre
// License: MIT
// Description: The outgoing image darkens into a grid of flickering code characters tinted by its colors, then glowing streams of characters fall down the columns at their own speeds, each with a bright head and a fading tail, leaving the incoming image behind
// Tags: text, digital, rain, reveal

// @range(0.02, 0.1) Height of a character, in frame heights
uniform float cellSize; // = 0.045
// @range(0.05, 1) Average length of the streams' fading tails, in frame heights
uniform float trail; // = 0.5
// @range(0, 1) How much the characters of the outgoing image take its colors, instead of the glow color
uniform float tint; // = 0.5
// @color Color of the falling streams and their glow
uniform vec4 glow; // = vec4(0.2, 1.0, 0.4, 1.0)

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec4 hash42(vec2 p) {
  vec4 p4 = fract(vec4(p.xyxy) * vec4(0.1031, 0.1030, 0.0973, 0.1099));
  p4 += dot(p4, p4.wzxy + 33.33);
  return fract((p4.xxyz + p4.yzzw) * p4.zywx);
}

vec4 band(vec4 d) {
  return 1.0 - smoothstep(0.3, 0.6, d);
}

// coverage of the character of this cell at this time, drawn on a 5x7 dot grid in a 6x8 cell
// (local: 0..1 in the cell, from its top left), made of strokes picked by hashes
float glyph(vec2 cell, float t, vec2 local) {
  vec2 b = local * vec2(6.0, 8.0) - 0.5;
  float x = b.x;
  float y = b.y;
  float d = 0.667 * y;
  // how far outside the spans 0..4, 0..6, 0..3 and 3..6, in dots
  float x04 = abs(x - 2.0) - 2.0;
  float y06 = abs(y - 3.0) - 3.0;
  float y03 = abs(y - 1.5) - 1.5;
  float y36 = abs(y - 4.5) - 1.5;
  vec2 seed = cell + t * vec2(37.0, 61.0);
  // strokes: three bars and a diagonal, the halves of the side verticals,
  // the halves of the middle vertical, the other diagonal and a short bar
  vec4 sa = band(abs(vec4(y, y - 3.0, y - 6.0, x - d))) * band(vec4(x04, x04, x04, y06));
  vec4 sb = band(abs(vec4(x, x, x - 4.0, x - 4.0))) * band(vec4(y03, y36, y03, y36));
  vec4 sc = band(abs(vec4(x - 2.0, x - 2.0, x + d - 4.0, y - 1.0))) * band(vec4(y03, y36, y06, abs(x - 2.0) - 1.0));
  float on = dot(step(0.68, hash42(seed)), sa);
  on += dot(step(0.68, hash42(seed + 41.0)), sb);
  on += dot(step(0.68, hash42(seed + 83.0)), sc);
  return min(on, 1.0);
}

vec4 transition(vec2 uv) {
  float h = max(cellSize, 0.005);
  vec2 dims = vec2(0.75 * h, h);
  vec2 fp = vec2(uv.x * ratio, 1.0 - uv.y);
  // (shifted by odd fractions of a cell, so that pixel centers don't fall on its lines at usual sizes)
  vec2 grid = fp / dims + vec2(0.389, 0.278);
  vec2 cell = floor(grid);
  vec2 local = grid - cell;
  float rc = hash12(cell + vec2(97.0, 131.0));

  float r1 = hash12(vec2(cell.x, 11.0));
  float r2 = hash12(vec2(cell.x, 23.0));
  float r3 = hash12(vec2(cell.x, 37.0));
  float T = mix(progress, progress * progress * (3.0 - 2.0 * progress), 0.5);
  float len = max(trail, 0.01) * (0.5 + r3);
  float u = clamp((T - 0.03 - 0.5 * r1) / (0.3 + 0.12 * r2), 0.0, 1.0);
  float head = mix(-0.2, 1.0 + h + len, u * (0.7 + 0.3 * u));
  float dy = head - (cell.y - 0.278) * h;

  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);

  vec2 cuv = clamp(vec2((cell.x + 0.111) * dims.x / ratio, 1.0 - (cell.y + 0.222) * h), 0.0, 1.0);
  vec4 ca = getFromColor(cuv);
  float lum = dot(ca.rgb, vec3(0.299, 0.587, 0.114));
  vec3 hue = ca.rgb / max(max(ca.r, max(ca.g, ca.b)), 0.05);
  vec3 ink = mix(glow.rgb * glow.a, hue, tint) * (0.1 + 0.6 * lum);
  float near = smoothstep(-0.15, 0.0, dy);
  float dim = max(smoothstep(0.0, 0.3, T), near);
  float g = max(smoothstep(0.0, 0.2, T - 0.12 * rc), near);
  float passed = step(0.0, dy);
  float slow = mod(floor(T * 12.0 + rc * 7.0), 32.0);
  float fast = 32.0 + mod(floor(T * 40.0 + rc * 13.0), 32.0);
  float chr = glyph(cell, mix(slow, fast, passed), local);
  vec3 code = a.rgb * (1.0 - 0.8 * dim) + ink * chr * g;

  float fade = clamp(1.0 - dy / len, 0.0, 1.0);
  float shade = 1.0 - smoothstep(0.3 * len, len, dy);
  float hot = 1.0 - smoothstep(h, 3.0 * h, dy);
  vec3 col = mix(glow.rgb * 1.2, vec3(1.0), 0.8 * hot) * glow.a;
  vec3 stream = b.rgb * (1.0 - 0.8 * shade) + col * chr * (fade * (2.0 - fade) + hot * fade);

  float yy = (head - fp.y) / (1.5 * h);
  float halo = 1.6 * u * (1.0 - u) * exp(-yy * yy) * (1.0 - smoothstep(0.25, 0.5, abs(local.x - 0.5)));
  vec3 rgb = mix(code, stream, passed) + glow.rgb * glow.a * halo;
  return vec4(clamp(rgb, 0.0, 1.0), mix(a.a, mix(b.a, a.a, shade), passed));
}

// Author: gre
// License: MIT
// Description: The incoming image settles onto the outgoing one like a spun coin coming to rest: it starts standing on its edge, then leans over while its lifted side whirls around faster and faster with a sweeping shadow, rocking on its corners in a quickening rattle, until it drops flat and still over the frame
// Tags: 3d, spin, wobble, shadow

// @range(1, 6) Number of whirls of the lifted side
uniform float whirls; // = 4.5
// @range(0, 1.5) In-plane turn of the image when it stands up, undone as it settles
uniform float twist; // = 0.6
// @range(0, 1) Shading of the coin and darkness of its shadow
uniform float shading; // = 0.7

const float PI = 3.141592653589793;
// far camera and a smaller standing card keep the raised edge from looming over the frame
const float D = 6.0;
const float START_SCALE = 0.72;
const float AA = 0.0015;

vec3 rotAxis(vec3 v, vec3 a, float t) {
  return v * cos(t) + cross(a, v) * sin(t) + a * dot(a, v) * (1.0 - cos(t));
}

float nonZero(float x) {
  return x < 0.0 ? min(x, -1e-5) : max(x, 1e-5);
}

vec4 transition(vec2 uv) {
  float s = 1.0 - progress;
  float tilt = 0.5 * PI * pow(s, 1.2);
  // whirl rate grows like 1/sqrt(s + K), capped so the last frames do not strobe
  const float K = 0.04;
  float phi = 2.0 * PI * whirls * (sqrt(1.0 + K) - sqrt(s + K)) / (sqrt(1.0 + K) - sqrt(K)) - 0.4;
  float psi = twist * s * s;

  vec3 axis = vec3(-sin(phi), cos(phi), 0.0);
  vec3 e1 = rotAxis(vec3(cos(psi), sin(psi), 0.0), axis, tilt);
  vec3 e2 = rotAxis(vec3(-sin(psi), cos(psi), 0.0), axis, tilt);
  vec3 n = cross(e1, e2);
  float sc = mix(1.0, START_SCALE, 1.0 - cos(tilt));
  vec2 hs = vec2(0.5 * ratio, 0.5) * sc;
  // the lowest corner touches the table, so the center rides up and down as it rocks over the corners
  float h = abs(hs.x * e1.z) + abs(hs.y * e2.z);
  vec3 C = vec3(0.0, 0.0, -h);

  vec2 p = vec2((uv.x - 0.5) * ratio, uv.y - 0.5);
  vec3 d = vec3(p, D);
  float dn = nonZero(dot(d, n));
  float t = (D - h) * n.z / dn;
  vec3 g = vec3(0.0, 0.0, -D) + d * t - C;
  vec2 q = vec2(dot(g, e1), dot(g, e2));
  vec2 eq = abs(q) - hs;
  // edge distance in screen units through the projection's analytic Jacobian, crisp even edge-on
  vec2 g1 = t * (e1.xy - dot(d, e1) / dn * n.xy);
  vec2 g2 = t * (e2.xy - dot(d, e2) / dn * n.xy);
  vec2 ex = eq / clamp(vec2(length(g1), length(g2)), 1e-3, 40.0);
  float m = 1.0 - smoothstep(0.0, AA, max(ex.x, ex.y));
  m *= smoothstep(0.001, 0.02, abs(n.z));

  vec3 L = normalize(vec3(-0.4, 0.5, -1.0));
  vec3 P = vec3(p, 0.0);
  float ln = dot(L, n);
  float ts = dot(C - P, n) / nonZero(ln);
  vec3 gs = P + L * ts - C;
  vec2 es = abs(vec2(dot(gs, e1), dot(gs, e2))) - hs;
  float soft = 0.01 + 0.15 * clamp(ts, 0.0, 2.0);
  float shadow = (1.0 - smoothstep(-soft, soft, max(es.x, es.y))) * smoothstep(0.0, 0.15, h) * smoothstep(0.0, 0.06, progress) * smoothstep(0.0, 0.02, ts);
  // a card edge-on to the light casts a hairline that would alias
  shadow *= smoothstep(0.03, 0.15, abs(ln));

  vec4 bg = getFromColor(uv);
  bg.rgb *= 1.0 - 0.6 * shading * shadow;

  vec4 img = getToColor(clamp(vec2(q.x / ratio, q.y) / sc + 0.5, 0.0, 1.0));
  float lit = L.z - dot(n, L);
  float spec = pow(max(-dot(n, normalize(L + vec3(0.0, 0.0, -1.0))), 0.0), 30.0) * sin(tilt);
  vec2 rim = 1.0 - smoothstep(0.0, 0.025 * hs.y, -eq);
  img.rgb = img.rgb * (1.0 + shading * max(1.2 * lit, -0.45)) + shading * (0.3 * spec + 0.25 * sin(tilt) * max(rim.x, rim.y));
  return mix(bg, img, m);
}

// Author: haiyoucuv
// License: MIT
// Description: A crossfade in which the colors of one image displace the other
// Tags: displace, distort, blend

vec4 transition (vec2 uv) {

  vec4 coordTo = getToColor(uv);
  vec4 coordFrom = getFromColor(uv);

  return mix(
    getFromColor(mix(uv, coordTo.rg, progress)),
    getToColor(mix(coordFrom.rg, uv, progress)),
    progress
  );

}

// License: MIT
// Author: P-Seebauer
// Description: Pixels switch to the incoming image in order of how close their colors are
// Tags: blend, color
// ported by gre from https://gist.github.com/P-Seebauer/2a5fa2f77c883dd661f9

uniform float power; // = 5.0

vec4 transition(vec2 p) {
  vec4 fTex = getFromColor(p);
  vec4 tTex = getToColor(p);
  float m = step(distance(fTex, tTex), progress);
  return mix(
    mix(fTex, tTex, m),
    tTex,
    pow(progress, power)
  );
}

// Author: gre
// License: MIT
// Description: Solid color panels, slightly staggered, sweep across and cover the frame, then sweep off the far side and reveal the incoming image
// Tags: wipe, panels, color, slanted, motion-graphics
// Preview: 0.75

// @param Direction the panels sweep toward
uniform vec2 direction; // = vec2(1.0, 0.0)
// @range(1, 3, 1) Number of panels
uniform int panels; // = 3
// @color Color of the first panel
uniform vec4 color1; // = vec4(0.98, 0.76, 0.22, 1.0)
// @color Color of the second panel
uniform vec4 color2; // = vec4(0.93, 0.33, 0.36, 1.0)
// @color Color of the third panel
uniform vec4 color3; // = vec4(0.16, 0.2, 0.42, 1.0)
// @range(0, 1) Delay between the panels, relative to the sweep of one panel (at 0, they move as one and only the last shows)
uniform float stagger; // = 0.35
// @range(-1, 1) Slant of the panels' edges
uniform float skew; // = 0.25

// the frame is fully covered from cut - hold to cut + hold, where the image switches
const float cut = 0.46;
const float hold = 0.01;
const float aa = 0.0015;

float ease(float t) {
  float s = clamp(t, 0.0, 1.0);
  float u = 1.0 - s * s * (3.0 - 2.0 * s);
  return 1.0 - u * u * u;
}

float cover(float x, float back, float front) {
  return smoothstep(back - aa, back + aa, x) * (1.0 - smoothstep(front - aa, front + aa, x));
}

vec4 transition(vec2 uv) {
  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float k = clamp(skew, -1.0, 1.0);
  vec2 a = (dir + k * vec2(-dir.y, dir.x)) / sqrt(1.0 + k * k);
  float x = dot(p, a);
  float e = 0.5 * (abs(a.x) * ratio + abs(a.y));
  float start = -e - 2.0 * aa;
  float span = 2.0 * (e + 2.0 * aa);

  int n = panels < 1 ? 1 : panels > 3 ? 3 : panels;
  float m = float(n - 1);
  float st = clamp(stagger, 0.0, 1.0);
  vec2 d = vec2(cut - hold, 1.0 - cut - hold) / (1.0 + m * st);

  // the first panel enters first and leaves last; both images are sampled so no texture read sits in a divergent branch
  float front0 = start + span * ease(progress / d.x);
  float back0 = start + span * ease((progress - 1.0 + d.y) / d.y);
  vec4 c = mix(getToColor(uv), getFromColor(uv), step(0.5 * (front0 + back0), x));
  c = mix(c, color1, cover(x, back0, front0));

  for (int i = 1; i < 3; i++) {
    if (i < n) {
      vec2 t = float(i) * st * d;
      float front = start + span * ease((progress - t.x) / d.x);
      float back = start + span * ease((progress - 1.0 + d.y + t.y) / d.y);
      c = mix(c, i == 1 ? color2 : color3, cover(x, back, front));
    }
  }
  return c.a > 0.0 ? c : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A crossfade in which each color channel changes at a different time
// Tags: fade, color

// Usage: fromStep and toStep must be in [0.0, 1.0] range 
// and all(fromStep) must be < all(toStep)

// @range(0, 1) When each channel (r, g, b, a) starts changing
uniform vec4 fromStep; // = vec4(0.0, 0.2, 0.4, 0.0)
// @range(0, 1) When each channel (r, g, b, a) finishes changing
uniform vec4 toStep; // = vec4(0.6, 0.8, 1.0, 1.0)

vec4 transition (vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  return mix(a, b, smoothstep(fromStep, toStep, vec4(progress)));
}

// Author: Yoni Maltsman @friendlyspinach
// License: MIT
// Description: Each color channel of the outgoing image is shifted and wraps around into psychedelic bands, while crossfading to the incoming image
// Tags: color, glitch, psychedelic, fade

// @range(-2, 2) Shift of the red channel over the transition
uniform float r_strength; // = 1.0
// @range(-2, 2) Shift of the green channel over the transition
uniform float g_strength; // = 1.0
// @range(-2, 2) Shift of the blue channel over the transition
uniform float b_strength; // = 1.0

vec4 transition (vec2 uv) {
  vec4 from = getFromColor(uv);
  vec4 to = getToColor(uv);
  vec3 c = from.rgb + vec3(r_strength, g_strength, b_strength)*progress;
  // The wrap flips bright (or, with negative strengths, dark) channels at once: fade it in over the first frames
  from.rgb = mix(from.rgb, mod(c, 1.0), smoothstep(0.0, 0.1, progress));
  return mix(from, to, progress);
}

// Author: gre
// License: MIT
// Description: The frame is cut into interleaved strips that slide in opposite directions, each pushing the outgoing image out and the incoming one in
// Tags: slide, stripes, push, horizontal

// @range(2, 40, 1) Number of strips
uniform int strips; // = 10
// @param Cut the frame into columns that slide up and down instead
uniform bool vertical; // = false

vec4 transition (vec2 uv) {
  // a: the axis along which the strips slide, b: the axis across them
  float a = vertical ? uv.y : uv.x;
  float b = vertical ? uv.x : uv.y;
  float dir = mod(floor(b * float(strips)), 2.0) < 0.5 ? 1.0 : -1.0;
  // ease in and out, but keep moving from the first frame
  float t = mix(progress, progress * progress * (3.0 - 2.0 * progress), 0.6);
  float fa = a - dir * t;
  if (fa >= 0.0 && fa <= 1.0) {
    return getFromColor(vertical ? vec2(b, fa) : vec2(fa, b));
  }
  float ta = fa + dir;
  return getToColor(vertical ? vec2(b, ta) : vec2(ta, b));
}

// Author: gre
// License: MIT
// Description: The frame splits into slanted comic-book panels with gutters and ink borders; one after another in reading order, each panel lifts off the page with a zoom kick and a drop shadow and punches over to the incoming image, then the gutters close up over the full incoming image
// Tags: comic, panels, grid, zoom

// @range(0, 0.1) Width of the gutters between the panels, as a part of the frame's height
uniform float gutter; // = 0.03
// @color Color of the gutters and of the page's margin
uniform vec4 gutterColor; // = vec4(1.0, 1.0, 1.0, 1.0)
// @color Color of the ink borders around the panels
uniform vec4 borderColor; // = vec4(0.0, 0.0, 0.0, 1.0)
// @range(0, 100, 1) Changes the layout of the panels
uniform float seed; // = 0.0

const float PI = 3.141592653589793;
const float INK = 0.005;
const float EDGE = 0.0012;
const float PUNCH = 0.3;
// the first panel's punch starts at START, the last one ends at END
const float START = 0.05;
const float END = 0.97;
const float SPIKES = 11.0;

float hash(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

float cols(float r) {
  float h = hash(vec2(r * 7.0 + 3.0, seed * 1.37 + 11.0));
  float n = h < 0.15 ? 1.0 : (h < 0.6 ? 2.0 : 3.0);
  // the middle row is never a single panel, a narrow frame takes at most 2 panels per row
  if (r == 1.0) n = max(n, 2.0);
  if (ratio < 0.8) n = min(n, 2.0);
  return n;
}

// signed distance of p (x from 0 to ratio, y from 0 at the top to 1) below the gutter k between the rows
// (0 is the top of the frame, 3 its bottom)
float rowDist(float k, vec2 p) {
  if (k < 0.5) return p.y;
  if (k > 2.5) return p.y - 1.0;
  float y = (k + (hash(vec2(k * 5.0 + 1.0, seed * 1.37)) - 0.5) * 0.35) / 3.0;
  float s = (hash(vec2(k * 9.0 + 4.0, seed * 1.37 + 5.0)) - 0.5) * 0.24;
  return (p.y - y - s * (p.x / ratio - 0.5)) / sqrt(1.0 + s * s / (ratio * ratio));
}

// signed distance of p right of the gutter j of row r, which has n panels (0 is the left of the frame, n its right)
float colDist(float r, float j, float n, vec2 p) {
  if (j < 0.5) return p.x;
  if (j > n - 0.5) return p.x - ratio;
  float x = (j + (hash(vec2(r * 3.0 + j * 13.0, seed * 1.37 + 2.0)) - 0.5) * 0.45) / n;
  float s = (hash(vec2(r * 11.0 + j * 5.0, seed * 1.37 + 7.0)) - 0.5) * 0.5;
  return (p.x - ratio * (x + s * (p.y - 0.5))) / sqrt(1.0 + ratio * ratio * s * s);
}

// signed distance to the edges of panel c of row r, positive inside
float panelDist(float r, float c, float n, vec2 p) {
  return min(min(rowDist(r, p), -rowDist(r + 1.0, p)), min(colDist(r, c, n, p), -colDist(r, c + 1.0, n, p)));
}

// a point inside panel c of row r, as far from its top as from its bottom and from its left as from its right
vec2 panelCenter(float r, float c, float n) {
  // the sums of the distances to the opposite edges are linear: find where they are 0
  float y0 = rowDist(r, vec2(0.5 * ratio, 0.0)) + rowDist(r + 1.0, vec2(0.5 * ratio, 0.0));
  float y1 = rowDist(r, vec2(0.5 * ratio, 1.0)) + rowDist(r + 1.0, vec2(0.5 * ratio, 1.0));
  float y = y0 / (y0 - y1);
  float x0 = colDist(r, c, n, vec2(0.0, y)) + colDist(r, c + 1.0, n, vec2(0.0, y));
  float x1 = colDist(r, c, n, vec2(1.0, y)) + colDist(r, c + 1.0, n, vec2(1.0, y));
  return vec2(x0 / (x0 - x1), y);
}

float panelTime(float k, float total) {
  float t0 = START + (END - START - PUNCH) * k / max(total - 1.0, 1.0);
  return clamp((progress - t0) / PUNCH, 0.0, 1.0);
}

float lift(float t) {
  float u = 1.0 - (1.0 - t) * (1.0 - t);
  return sin(PI * u);
}

vec4 panelImage(vec2 p, vec2 center, float t) {
  float k = lift(t);
  vec2 q = center + (p - center) / (1.0 + 0.1 * k);
  vec2 uv = vec2(q.x / ratio, 1.0 - q.y);
  if (t <= 0.0) return getFromColor(uv);
  if (t >= 1.0) return getToColor(uv);
  vec2 v = p - center;
  float a = (atan(v.y, v.x + 1e-6) + PI) / (2.0 * PI) * SPIKES + center.x * 7.0;
  float i = floor(a);
  // (the spike index wraps around so that the star has no seam where the angle wraps)
  float spike = (1.0 - abs(2.0 * (a - i) - 1.0)) * (0.5 + 0.5 * hash(vec2(mod(i, SPIKES), center.y * 13.0 + seed)));
  // large enough to cover the widest panel, a whole row of a wide frame
  float burst = 1.5 * max(1.0, ratio / 1.8) * smoothstep(0.06, 0.42, t);
  float d = length(v) - burst * (0.62 + 0.38 * spike);
  float w = 1.4 * INK;
  vec4 c = mix(getToColor(uv), borderColor, smoothstep(-w - EDGE, -w + EDGE, d));
  return mix(c, getFromColor(uv), smoothstep(-EDGE, EDGE, d));
}

// the panel drawn over color: its gutter edge at g from its edges, its ink border inside it
vec4 drawPanel(vec4 color, vec4 img, float d, float g, float ink, float fade) {
  vec4 c = mix(borderColor, img, mix(1.0, smoothstep(g + ink - EDGE, g + ink + EDGE, d), fade));
  return mix(color, c, mix(1.0, smoothstep(g - EDGE, g + EDGE, d), fade));
}

vec4 transition(vec2 uv) {
  vec2 p = vec2(uv.x * ratio, 1.0 - uv.y);

  float open = smoothstep(0.0, 0.14, progress) * (1.0 - smoothstep(0.8, 1.0, progress));
  float g = 0.5 * gutter * open;
  float ink = INK * open;
  // the edges come in gently instead of popping in at half coverage
  float fade = clamp(open * 6.0, 0.0, 1.0);

  float n0 = cols(0.0);
  float n1 = cols(1.0);
  float n2 = cols(2.0);
  float total = n0 + n1 + n2;

  float r = rowDist(1.0, p) < 0.0 ? 0.0 : (rowDist(2.0, p) < 0.0 ? 1.0 : 2.0);
  float n = r == 0.0 ? n0 : (r == 1.0 ? n1 : n2);
  float c = colDist(r, 1.0, n, p) < 0.0 ? 0.0 : (colDist(r, 2.0, n, p) < 0.0 || n < 2.5 ? 1.0 : 2.0);
  c = min(c, n - 1.0);
  float first = r == 0.0 ? 0.0 : (r == 1.0 ? n0 : n0 + n1);
  float t = panelTime(first + c, total);

  vec4 color = gutterColor;
  if (t <= 0.0 || t >= 1.0) {
    color = drawPanel(color, panelImage(p, panelCenter(r, c, n), t), panelDist(r, c, n, p), g, ink, fade);
  }

  // the panels lifted off the page, the later ones on top: at most 4 of them punch at once
  float spacing = (END - START - PUNCH) / max(total - 1.0, 1.0);
  // (with a margin, so that a panel at the very end of its punch is not missed to rounding)
  float kFirst = floor((progress - START - PUNCH) / spacing - 0.01) + 1.0;
  for (int i = 0; i < 4; i++) {
    float pk = kFirst + float(i);
    if (pk < 0.0 || pk > total - 0.5) continue;
    float pt = panelTime(pk, total);
    if (pt <= 0.0 || pt >= 1.0) continue;
    float pr = pk < n0 ? 0.0 : (pk < n0 + n1 ? 1.0 : 2.0);
    float pn = pr == 0.0 ? n0 : (pr == 1.0 ? n1 : n2);
    float pc = pk - (pr == 0.0 ? 0.0 : (pr == 1.0 ? n0 : n0 + n1));
    float k = lift(pt);
    vec2 center = panelCenter(pr, pc, pn);
    float s = 1.0 + 0.08 * k;
    vec2 sq = center + (p - vec2(0.012, 0.018) * k - center) / s;
    float sd = panelDist(pr, pc, pn, sq) - g;
    color.rgb *= 1.0 - 0.4 * k * fade * smoothstep(-0.02, 0.01, sd);
    vec2 q = center + (p - center) / s;
    color = drawPanel(color, panelImage(q, center, pt), panelDist(pr, pc, pn, q), g, ink, 1.0);
  }
  return color;
}

// Author: gre
// License: MIT
// Description: Warm breath fogs the cold glass in front of the picture: an uneven milky haze blooms out from the middle, water beads swell in it and act as tiny lenses holding sharp upside-down views, a few grow heavy and run down leaving clear trails, then the fog evaporates from the edges inward, the beads last, off the incoming picture
// Tags: glass, fog, water, droplets, breath, organic, dissolve
// Preview: 0.6

// @range(4, 20) Number of large beads across the frame height
uniform float droplets; // = 8.0
// @range(0, 1) Whiteness of the fog at its thickest
uniform float milk; // = 0.7

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yxz + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + 1.0), f.x), f.y);
}

float fbm(vec2 p) {
  return 0.5 * noise(p) + 0.3 * noise(p * 2.1 + 3.7) + 0.2 * noise(p * 4.3 - 1.9);
}

// premultiplied, mirrored past the frame (min keeps uv exact inside it)
vec4 scene(vec2 uv, float m) {
  uv = mod(uv, 2.0);
  uv = min(uv, 2.0 - uv);
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  return mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
}

float front() {
  float e = clamp(progress / 0.3, 0.0, 1.0);
  return mix(-0.4, 1.6, 1.0 - (1.0 - e) * (1.0 - e));
}

// breath distance of a bead centre, without the costly noise: radial plus per-bead jitter
float reach(vec2 q, float jitter) {
  return length((q - vec2(0.06, -0.04)) * vec2(0.85, 1.0)) / (0.5 * length(vec2(ratio, 1.0))) + 0.35 * (jitter - 0.5);
}

// beads condense behind the fog front and evaporate from the edges inward, area shrinking steadily
float beadSize(float rr, float lag) {
  float end = 0.8 + 0.2 * clamp(1.0 - rr, 0.0, 1.0);
  return smoothstep(0.0, 0.3, front() - lag - rr) * sqrt(clamp((end - progress) / 0.3, 0.0, 1.0));
}

// spherical cap: x = height in cell units, yz = surface slope, w = height change per frame height
vec4 bead(vec2 g, vec2 ctr, float r, float cell) {
  float rs = max(r, 1e-3);
  vec2 d = (g - ctr) * vec2(1.0, 1.08);
  float w = max(1.0 - dot(d, d) / (rs * rs), 0.0);
  float sw = sqrt(w);
  vec2 slope = -d * sw / (rs * (w + 0.01)) * min(r * 1000.0, 1.0);
  // -1 off the bead keeps the smooth max from inflating empty glass
  return vec4(w > 0.0 ? r * sw : -1.0, slope, length(slope) / cell);
}

// polynomial smooth max, so touching beads merge with a neck instead of stacking
vec4 merge(vec4 a, vec4 b) {
  float k = 0.03;
  float h = clamp(0.5 + 0.5 * (b.x - a.x) / k, 0.0, 1.0);
  vec4 c = mix(a, b, h);
  c.x += k * h * (1.0 - h);
  return c;
}

vec4 beads(vec4 acc, vec2 q, float cell, float fill, float lag, float grow, float salt) {
  vec2 g = q / cell;
  vec2 base = floor(g);
  for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
      vec2 c = base + vec2(float(i), float(j)) + salt;
      float h = hash(c);
      vec2 ctr = c - salt + 0.2 + 0.6 * vec2(hash(c + 17.0), hash(c + 31.0));
      float size = beadSize(reach(ctr * cell, hash(c + 71.0)), lag) * grow;
      float r = (0.16 + 0.34 * h * h) * size * step(1.0 - fill, hash(c + 53.0));
      acc = merge(acc, bead(g, ctr, r, cell));
    }
  return acc;
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  float n = fbm(q * 3.0 + 2.0);
  // distance from the breath's middle, ragged by noise, ~1 at the corners
  float rr = length((q - vec2(0.06, -0.04)) * vec2(0.85, 1.0)) / (0.5 * length(vec2(ratio, 1.0))) + 0.35 * (n - 0.5);
  float fr = front();
  float back = 1.6 - 2.7 * clamp((p - 0.42) / 0.58, 0.0, 1.0);
  float fog = smoothstep(0.0, 0.3, fr - rr) * smoothstep(0.0, 0.3, back - rr);
  float m = smoothstep(0.34, 0.5, p);

  float cell = 1.0 / droplets;
  float grow = smoothstep(0.08, 0.45, p);
  vec4 water = beads(vec4(-1.0, 0.0, 0.0, 0.0), q, cell, 0.6, 0.2, grow, 0.0);
  water = beads(water, q, cell * 0.4, 0.5, 0.05, 1.0, 71.0);

  float cw = 2.3 * cell;
  float col = floor(q.x / cw);
  float hk = hash(vec2(col, 7.0));
  float t0 = 0.24 + 0.16 * hash(vec2(col, 13.0));
  float slide = smoothstep(t0, t0 + 0.55, p);
  float y0 = 0.45 - 0.6 * hash(vec2(col, 29.0));
  float yr = y0 - 1.4 * slide;
  float xr = (col + 0.5) * cw + 0.25 * cell * sin(q.y * 9.0 + hk * 6.0);
  float xh = (col + 0.5) * cw + 0.25 * cell * sin(yr * 9.0 + hk * 6.0);
  float rRun = 0.36 * grow * beadSize(reach(vec2(xh, yr), hk), 0.2) * step(0.35, hk);
  float trail = (1.0 - smoothstep(0.15, 0.3, abs(q.x - xr) / cell)) * step(yr, q.y) * (1.0 - smoothstep(y0 - 0.02, y0 + 0.02, q.y)) * smoothstep(0.0, 0.1, rRun);
  // the runner sweeps up every droplet in its path
  water = merge(mix(water, vec4(-1.0, 0.0, 0.0, 0.0), trail), bead(q / cell, vec2(xh, yr) / cell, rRun, cell));
  float dens = fog * (0.6 + 0.9 * fbm(q * 2.2 + 9.0)) * (0.8 + 0.4 * fbm(q * 8.0 - 4.0)) * (1.0 - trail);
  // beads absorb the mist around them
  dens *= 1.0 - 0.5 * smoothstep(0.0, 0.05, water.x);
  dens = clamp(dens, 0.0, 1.0);

  float rad = 0.035 * dens;
  vec4 c = vec4(0.0);
  for (int k = 0; k < 12; k++) {
    float fk = float(k);
    float a = fk * 2.39996;
    c += scene(uv + rad * sqrt((fk + 0.5) / 12.0) * vec2(cos(a) / ratio, sin(a)), m);
  }
  c /= 12.0;
  vec3 rgb = c.a > 0.0 ? c.rgb / c.a : vec3(0.0);
  vec3 haze = mix(vec3(dot(rgb, vec3(0.299, 0.587, 0.114))), vec3(1.0), 0.65) * vec3(0.95, 0.97, 1.0);
  rgb = mix(rgb, haze, clamp(milk * dens, 0.0, 1.0));

  float T = 0.03;
  // AA capped below T so vanishing beads (r -> 0, steep slopes) fade out completely
  float aa = clamp(water.w * 0.0015, 1e-4, 0.4 * T);
  float inside = smoothstep(-aa, aa, water.x - T);
  // a bead is a plano-convex lens: it shows an inverted, shrunken view of the scene behind it
  vec2 slope = water.yz * 1.3;
  vec3 nrm = normalize(vec3(-slope, 1.0));
  vec4 lc = scene(uv - nrm.xy * vec2(0.35 / ratio, 0.35), m);
  vec3 drop = lc.a > 0.0 ? lc.rgb / lc.a : vec3(0.0);
  float steep = 1.0 - nrm.z;
  vec3 L = normalize(vec3(-0.45, 0.6, 0.66));
  float spec = pow(max(dot(nrm, normalize(L + vec3(0.0, 0.0, 1.0))), 0.0), 80.0);
  float caustic = smoothstep(0.1, 0.4, steep) * max(dot(slope, -L.xy), 0.0) / max(length(slope), 1e-3);
  drop = drop * (1.0 - 0.8 * smoothstep(0.45, 0.8, steep)) + 0.3 * caustic * (1.0 - smoothstep(0.5, 0.75, steep));
  drop += 0.9 * spec + 0.12 * smoothstep(0.75, 0.9, steep);
  rgb *= 1.0 - 0.25 * smoothstep(0.5 * T, T, water.x) * (1.0 - inside);

  float aOut = mix(c.a, lc.a, inside);
  return vec4(mix(rgb, drop, inside), aOut);
}

// Author: gre
// License: MIT
// Description: The outgoing image is a thick solid block: a round core is scored in its middle and punched straight back through it, showing the bore's shaded walls, and drops away behind; then a wider ring is punched out around the hole, then another, until the outer frame is punched back and falls, leaving the incoming image
// Tags: 3d, punch, core, rings, depth, shadow, physical

// @range(0.05, 0.8) Thickness of the block, in frame heights
uniform float thickness; // = 0.35
// @range(0, 1) How much the bore walls and the punched pieces darken
uniform float shading; // = 0.7

const int N = 4;
const float EYE = 2.2;
const float SCORE = 0.25;
const float FALL = 0.6;
const vec3 L = vec3(-0.45, 0.65, 0.61);

const float BEAT = 1.0 / (float(N) + FALL);

float localU(int k) {
  return (progress - float(k) * BEAT) / BEAT;
}

// the last piece is the outer frame; the rings stay inside the shorter side so the frame is one piece
float outerR(int k, float hmin) {
  return k >= N - 1 ? 1e3 : hmin * (0.3 + 0.28 * float(k));
}

float lit(vec3 n) {
  return mix(1.0, (0.3 + 0.7 * max(dot(n, L), 0.0)) / (0.3 + 0.7 * L.z), shading);
}

// exit (x) and entry (y) depths where the ray q(d) = b + a d crosses the circle of radius r
vec2 crossings(vec2 a, vec2 b, float r) {
  float A = dot(a, a);
  float B = dot(a, b);
  float C = dot(b, b) - r * r;
  float disc = B * B - A * C;
  if (A < 1e-9 || disc < 0.0) return vec2(-1.0);
  float sq = sqrt(disc);
  // each root in its cancellation-free form
  float far = B > 0.0 ? -C / (B + sq) : (sq - B) / A;
  float near = B < 0.0 ? C / (sq - B) : -(B + sq) / A;
  return vec2(far, near);
}

vec3 rotX(vec3 v, float c, float s) {
  return vec3(v.x, c * v.y - s * v.z, s * v.y + c * v.z);
}

float score(vec2 q, float hmin) {
  float g = 1.0;
  for (int k = 0; k < N - 1; k++) {
    float u = localU(k);
    float sc = smoothstep(0.0, SCORE, u) * (1.0 - smoothstep(SCORE, SCORE + 0.25, u));
    g *= 1.0 - 0.7 * sc * (1.0 - smoothstep(0.0015, 0.004, abs(length(q) - outerR(k, hmin))));
  }
  return g;
}

// the nearest surface of piece k on the ray through p: (ray parameter or 1e4, light, point of the picture)
vec4 hitPiece(int k, vec2 p, float T, float hmin) {
  float u = localU(k);
  float t = clamp((u - SCORE) / (1.0 - SCORE), 0.0, 1.0);
  bool frame = k == N - 1;
  // the frame starts to topple while it is still being pushed back
  float w0 = frame ? 0.6 : 1.0;
  float w = clamp((u - w0) / (1.0 + FALL - w0), 0.0, 1.0);
  if (w >= 1.0) return vec4(1e4);
  float s = T * (1.0 - (1.0 - t) * (1.0 - t) * (1.0 - t)) + 0.3 * w;
  // enough to carry even the top of the toppled frame below the picture
  float drop = (1.3 + 1.2 * T) * w * w;
  // the rings tumble about their centre, the frame topples back over its bottom edge
  float tilt = frame ? -1.2 * w * w : -1.4 * w;
  vec3 pv = frame ? vec3(0.0, -0.5, -T) : vec3(0.0, 0.0, -0.5 * T);
  float c = cos(tilt), sn = sin(tilt);
  vec3 ol = rotX(vec3(0.0, drop, EYE + s) - pv, c, -sn) + pv;
  vec3 dl = rotX(vec3(p, -EYE), c, -sn);
  float rin = k == 0 ? 0.0 : outerR(k - 1, hmin);
  float rout = outerR(k, hmin);
  float sink = 1.0 - (frame ? 0.2 : 0.5) * shading * smoothstep(0.0, T, s);
  vec2 hw = vec2(0.5 * ratio, 0.5);
  vec4 best = vec4(1e4);

  if (abs(dl.z) > 1e-6) {
    // the front face, or the back one once the piece has turned it toward the eye
    bool front = dl.z < 0.0;
    float r = ((front ? 0.0 : -T) - ol.z) / dl.z;
    vec2 q = ol.xy + r * dl.xy;
    float rq = length(q);
    bool onFace = frame ? abs(q.x) <= hw.x && abs(q.y) <= hw.y : rq <= rout;
    if (r > 0.0 && rq >= rin && onFace) {
      float l = front ? sink * (t > 0.0 ? 1.0 : score(q, hmin)) : 0.6 * sink;
      best = vec4(r, lit(rotX(vec3(0.0, 0.0, front ? 1.0 : -1.0), c, sn)) * l, q);
    }
  }
  if (k > 0) {
    float r = crossings(dl.xy, ol.xy, rin).x;
    float z = ol.z + r * dl.z;
    if (r > 0.0 && z <= 0.0 && z >= -T && r < best.x) {
      vec2 q = ol.xy + r * dl.xy;
      float rim = 1.0 - smoothstep(0.0, 0.012, -z);
      float l = lit(rotX(vec3(-q / rin, 0.0), c, sn)) * (1.0 - 0.6 * shading * -z / T) + 0.3 * shading * rim;
      best = vec4(r, l * sink, q);
    }
  }
  if (!frame) {
    float r = crossings(dl.xy, ol.xy, rout).y;
    float z = ol.z + r * dl.z;
    if (r > 0.0 && z <= 0.0 && z >= -T && r < best.x) {
      vec2 q = ol.xy + r * dl.xy;
      best = vec4(r, lit(rotX(vec3(q / rout, 0.0), c, sn)) * sink, q);
    }
  } else {
    // the frame's outer sides, each seen only from outside
    for (int i = 0; i < 4; i++) {
      vec2 n = i == 0 ? vec2(0.0, 1.0) : i == 1 ? vec2(0.0, -1.0) : i == 2 ? vec2(1.0, 0.0) : vec2(-1.0, 0.0);
      float dn = dot(dl.xy, n);
      if (dn >= 0.0) continue;
      float r = (dot(hw, abs(n)) - dot(ol.xy, n)) / dn;
      vec3 x = ol + r * dl;
      vec2 off = abs(x.xy) - hw;
      if (r > 0.0 && x.z <= 0.0 && x.z >= -T && dot(off, abs(n.yx)) <= 0.0 && r < best.x) {
        vec2 q = x.xy - n * 0.001;
        best = vec4(r, lit(rotX(vec3(n, 0.0), c, sn)) * (1.0 - 0.4 * shading * -x.z / T) * sink, q);
      }
    }
  }
  return best;
}

vec4 scene(vec2 p, vec4 back, float T, float hmin) {
  vec4 best = vec4(1e4);
  for (int k = 0; k < N; k++) {
    vec4 h = hitPiece(k, p, T, hmin);
    if (h.x < best.x) best = h;
  }
  if (best.x > 1e3) return back;
  vec4 c = getFromColor(best.zw / vec2(ratio, 1.0) + 0.5);
  return vec4(c.rgb * min(best.y, 1.15), c.a);
}

vec4 transition(vec2 uv) {
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float T = max(thickness, 0.01);
  float hmin = 0.5 * min(ratio, 1.0);
  vec4 back = getToColor(uv);
  // 2x2 supersampling for the edges, collapsing to one point at both ends
  float j = 0.0012 * sin(3.14159265 * progress);
  return 0.25 * (scene(p + vec2(-j, -j), back, T, hmin) + scene(p + vec2(j, -j), back, T, hmin)
    + scene(p + vec2(-j, j), back, T, hmin) + scene(p + vec2(j, j), back, T, hmin));
}

// Author: gre
// License: MIT
// Description: The incoming image appears as a small card in the middle of the frame, then its corners are pinned out to the corners of the frame one after another, each snapping into place with a springy overshoot that skews the card in perspective, until it lies flat over the whole frame
// Tags: corner, pin, quad, perspective, snap, motion-graphics

// @range(0.05, 0.5) Size of the card before its corners are pulled out, relative to the frame
uniform float start; // = 0.2
// @range(0, 2) Overshoot of each corner as it snaps into place
uniform float overshoot; // = 1.2
// @range(0, 1) Darkness of the shadow the card casts on the outgoing image
uniform float shadow; // = 0.5

float cross2(vec2 a, vec2 b) { return a.x * b.y - a.y * b.x; }

// back-out ease: exactly 1 at x = 1, overshooting before it
float snap(float x) {
  x -= 1.0;
  float c = 1.70158 * overshoot;
  return 1.0 + (c + 1.0) * x * x * x + c * x * x;
}

vec2 corner(vec2 target, float x, float grow) {
  return mix(0.5 + (target - 0.5) * start * grow, target, snap(x));
}

// signed distance to the edge e0 -> e1 of the counterclockwise card, positive inside
float edge(vec2 p, vec2 e0, vec2 e1) {
  return cross2(e1 - e0, p - e0) / max(length(e1 - e0), 1e-6);
}

// an edge loses its softness as both its corners land, so it meets the frame border without a seam
float cover(float dist, float x0, float x1) {
  return clamp(dist / (0.002 * sqrt(1.0 - min(x0, x1)) + 1e-6) + 0.5, 0.0, 1.0);
}

vec4 transition(vec2 uv) {
  float t = progress;
  vec2 asp = vec2(ratio, 1.0);
  float appear = smoothstep(0.0, 0.12, t);
  // kept above 0 so the quad never collapses to a point
  float grow = max(appear, 1e-3);
  float xa = clamp((t - 0.10) / 0.32, 0.0, 1.0), xb = clamp((t - 0.28) / 0.32, 0.0, 1.0);
  float xc = clamp((t - 0.46) / 0.32, 0.0, 1.0), xd = clamp((t - 0.64) / 0.32, 0.0, 1.0);
  vec2 a = corner(vec2(0.0, 1.0), xa, grow) * asp;
  vec2 b = corner(vec2(1.0, 1.0), xb, grow) * asp;
  vec2 c = corner(vec2(1.0, 0.0), xc, grow) * asp;
  vec2 d = corner(vec2(0.0, 0.0), xd, grow) * asp;
  vec2 p = uv * asp;

  // inverse of the projective map sending the unit square to d (0,0), c (1,0), b (1,1), a (0,1)
  vec2 s = d - c + b - a, e1 = c - b, e2 = a - b;
  float den = cross2(e1, e2);
  float g = cross2(s, e2) / den, h = cross2(e1, s) / den;
  vec3 cu = vec3(c - d + g * c, g), cv = vec3(a - d + h * a, h), c1 = vec3(d, 1.0);
  vec3 hp = vec3(p, 1.0);
  float w = dot(cross(cu, cv), hp);
  // past the card's horizon w crosses 0: keep it finite there, the card does not cover it
  w = w < 0.0 ? min(w, -1e-6) : max(w, 1e-6);
  vec2 q = vec2(dot(cross(cv, c1), hp), dot(cross(c1, cu), hp)) / w;

  float inside = min(min(cover(edge(p, d, c), xd, xc), cover(edge(p, c, b), xc, xb)),
                     min(cover(edge(p, b, a), xb, xa), cover(edge(p, a, d), xa, xd)));
  inside *= smoothstep(0.0, 0.02, t);

  float lift = 1.0 - smoothstep(0.3, 1.0, xd);
  vec2 ps = p - vec2(0.012, -0.02) * lift * grow;
  float blur = 0.025 * grow;
  float sd = min(min(edge(ps, d, c), edge(ps, c, b)), min(edge(ps, b, a), edge(ps, a, d)));
  float sh = shadow * lift * appear * smoothstep(-blur, blur, sd);

  vec4 from = getFromColor(uv);
  from.rgb *= 1.0 - sh;
  return mix(from, getToColor(clamp(q, 0.0, 1.0)), inside);
}

// Author: gre
// License: MIT
// Description: The picture is cut into upright slats hung on the throws of one crankshaft: as it turns, each slat circles up and back while the slat of the incoming picture on the opposite throw circles down and forward into its place, the turn rolling across the frame from left to right
// Tags: mechanical, 3d, stripes, crank

// @range(3, 16) Number of slats across a 16:9 frame, fewer in narrower frames
uniform float slats; // = 6.0
// @range(0.1, 1) How far the slats swing back, as a fraction of the frame height
uniform float depth; // = 0.5

const float PI = 3.14159265;
// slats are a bit taller than the frame so that its border is never antialiased;
// a throw of half their height lets the two slats of a column pass without overlapping
const float MARGIN = 0.01;
const float THROW = 0.5 + MARGIN;
// slats overlap their neighbours, so that receding ones leave narrower gaps
const float OVER = 0.12;
const float PERSP = 0.6;
const float AA = 0.003;
// layers closer than this in depth blend, so overlapping slats never swap in a single frame
const float TIE = 0.01;

float slatCount() {
  return clamp(floor(slats * sqrt(ratio * 0.5625) + 0.5), 2.0, 16.0);
}

float crankAngle(float i, float n) {
  float c = clamp(progress * 1.6 - 0.6 * i / (n - 1.0), 0.0, 1.0);
  return PI * c * c * (3.0 - 2.0 * c);
}

float depthOf(float a) {
  return max(depth, 0.05) * (1.0 - cos(a));
}

// (signed distance to the slat's outline on screen, depth, x on the slat plane, y on the slat plane)
vec4 slatAt(vec2 P, float fi, float k, float n, float w) {
  float a = crankAngle(fi, n) + PI * k;
  float z = depthOf(a);
  float s = 1.0 / (1.0 + PERSP * z);
  vec2 Q = P / s - vec2(0.0, THROW * sin(a));
  vec2 d = abs(Q - vec2((fi + 0.5) * w - 0.5 * ratio, 0.0)) - vec2((0.5 + OVER) * w, 0.5 + MARGIN);
  return vec4(max(d.x, d.y) * s, z, Q);
}

float shadowAt(vec2 P, float zr, float n, float w) {
  float sh = 0.0;
  for (int i = 0; i < 16; i++) {
    float fi = float(i);
    if (fi >= n) break;
    for (int k = 0; k < 2; k++) {
      float gap = zr - depthOf(crankAngle(fi, n) + PI * float(k));
      if (gap < 1e-3) continue;
      vec4 c = slatAt(P - vec2(0.04, -0.07) * gap, fi, float(k), n, w);
      sh = max(sh, (1.0 - smoothstep(-0.01, 0.02 + 0.08 * gap, c.x)) * min(gap / max(depth, 0.05), 1.0));
    }
  }
  return sh;
}

vec4 transition(vec2 uv) {
  vec2 P = (uv - 0.5) * vec2(ratio, 1.0);
  float n = slatCount();
  float w = ratio / n;
  vec4 c1 = vec4(0.0), c2 = vec4(0.0);
  float z1 = 1e3, z2 = 1e3, a1 = 0.0, a2 = 0.0;
  for (int i = 0; i < 16; i++) {
    float fi = float(i);
    if (fi >= n) break;
    for (int k = 0; k < 2; k++) {
      vec4 sl = slatAt(P, fi, float(k), n, w);
      float cov = clamp(0.5 - sl.x / AA, 0.0, 1.0);
      if (cov <= 0.0) continue;
      float z = sl.y;
      vec2 q = 1.0 - abs(1.0 - abs(sl.zw / vec2(ratio, 1.0) + 0.5));
      vec4 col = k == 0 ? getFromColor(q) : getToColor(q);
      col.rgb *= 1.0 - 0.45 * z / (2.0 * max(depth, 0.05)) - 0.25 * (1.0 - smoothstep(0.0, 0.01, -sl.x)) * sin(crankAngle(fi, n));
