  vec4 img = getFromColor(clamp(leftward ? vec2(1.0 - src.x, src.y) : src, 0.0, 1.0));

  float steep = clamp(-dhs * drain * 1.5, 0.0, 1.0);
  float lit = clamp(slope * 2.5 + 0.6, 0.0, 1.0);
