  vec2 p = vec2(x, 1.0 - z / M);
  vec4 c = inc ? getToColor(p) : getFromColor(p);
  c.rgb *= max(lit, 0.0) * (0.55 + 0.45 * abs(ca));
  float aa = 400.0 / copies;
  float edge = clamp((0.5 - abs(v)) * aa + 1.0, 0.0, 1.0) * clamp((0.5 - abs(x - 0.5)) * 400.0 * ratio + 1.0, 0.0, 1.0);
