  if (wOut > 0.0) c += wOut * getFromColor(mirror(uv - shift * eOut));
  return c;
}

// Author: Woohyun Kim
// License: MIT
// Description: Both images fade through black with their edges glowing
// Tags: edges, fade

uniform float edge_thickness; // = 0.001
uniform float edge_brightness; // = 8.0

vec3 detectEdgeColor(vec3[9] c) {
  /* adjacent texel array for texel c[4]
    036
    147
    258
  */
  vec3 dx = 2.0 * abs(c[7]-c[1]) + abs(c[2] - c[6]) + abs(c[8] - c[0]);
	vec3 dy = 2.0 * abs(c[3]-c[5]) + abs(c[6] - c[8]) + abs(c[0] - c[2]);
  float delta = length(0.25 * (dx + dy) * 0.5);
	return clamp(edge_brightness * delta, 0.0, 1.0) * c[4];
}

vec4 getFromEdgeColor(vec2 uv) {
	vec3 c[9];
	float alpha = 0.0;
	for (int i=0; i < 3; ++i) for (int j=0; j < 3; ++j)
	{
	  vec4 color = getFromColor(uv + edge_thickness * vec2(i-1,j-1));
    c[3*i + j] = color.rgb;
    if (i == 1 && j == 1) alpha = color.a;
	}
	return vec4(detectEdgeColor(c), alpha);
}

vec4 getToEdgeColor(vec2 uv) {
	vec3 c[9];
	float alpha = 0.0;
	for (int i=0; i < 3; ++i) for (int j=0; j < 3; ++j)
	{
	  vec4 color = getToColor(uv + edge_thickness * vec2(i-1,j-1));
    c[3*i + j] = color.rgb;
    if (i == 1 && j == 1) alpha = color.a;
	}
	return vec4(detectEdgeColor(c), alpha);
}

vec4 transition (vec2 uv) {
  vec4 start = mix(getFromColor(uv), getFromEdgeColor(uv), clamp(2.0 * progress, 0.0, 1.0));
  vec4 end = mix(getToEdgeColor(uv), getToColor(uv), clamp(2.0 * (progress - 0.5), 0.0, 1.0));
  return mix(
    start,
    end,
    progress
  );
}

// Author: gre
// License: MIT
// Description: The incoming image rises from the bottom of the frame in vertical bars that bounce up and down like an audio equalizer, lit in segments and each topped by a floating peak cap that falls back slowly, their average level climbing until they fill the frame
// Tags: wipe, bars, music, vertical, retro

// @range(4, 48, 1) Number of bars across the frame
uniform int bars; // = 16
// @range(0, 0.6) How far the bars bounce above and below their average level, in frame heights
uniform float bounce; // = 0.3
// @range(0, 64, 1) Number of lit segments in a bar the height of the frame (0 for solid bars)
uniform int segments; // = 24
// @color Color of the peak caps (its alpha is their opacity)
uniform vec4 capColor; // = vec4(1.0, 1.0, 1.0, 1.0)

const float PI = 3.141592653589793;
const float AA = 0.0015;
const float CAP = 0.012;
const float CAP_GAP = 0.008;

float hash11(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

// level of bar i (0 at the bottom of the frame, 1 at the top) at progress t: an eased average
// level climbing from below the frame to above it, plus a bounce that is zero at both ends.
// k holds the bar's own speeds and phases, lead how far it runs ahead of the others
float level(float i, vec4 k, float lead, float t, float amp) {
  t = clamp(t, 0.0, 1.0);
  float env = sin(PI * t);
  float ramp = t * t * (3.0 - 2.0 * t);
  float base = mix(-0.03, 1.04, mix(t, ramp, 0.3));
  float w = 2.0 * PI * t;
  float osc = 0.5 * sin(w * k.x + k.y) + 0.3 * sin(w * k.z + k.w) + 0.2 * sin(w * 2.2 - 0.55 * i);
  return base + amp * env * (osc + lead);
}

vec4 transition(vec2 uv) {
  float n = float(bars < 1 ? 1 : bars);
  float amp = max(bounce, 0.0);
  float x = uv.x * n;
  float i = min(floor(x), n - 1.0);
  float fx = x - i;
  float aaX = AA * n / ratio;

  vec4 k = vec4(
    3.0 + 1.5 * hash11(i + 3.0), 2.0 * PI * hash11(i),
    5.5 + 2.0 * hash11(i + 7.0), 2.0 * PI * hash11(i + 11.0)
  );
  float lead = 0.35 * (hash11(i + 19.0) - 0.5);
  float h = level(i, k, lead, progress, amp);
  // the peak cap: the highest recent level, held a moment then falling back faster and faster
  float peak = h;
  for (int j = 1; j < 12; j++) {
    float dt = float(j) * 0.012;
    float fall = max(dt - 0.03, 0.0);
    peak = max(peak, level(i, k, lead, progress - dt, amp) - 60.0 * fall * fall);
  }
  float capY = peak + CAP_GAP;

  // a gap thinner than the antialiasing fades out instead of blurring the sides of the bar
  float open = 1.0 - smoothstep(0.72, 0.97, progress);
  float gap = 0.09 * open;
  float side = min(fx, 1.0 - fx);
  float inGap = clamp((gap - side) / (2.0 * aaX) + 0.5, 0.0, 1.0) * min(gap / aaX, 1.0);
  float barX = 1.0 - inGap;

  vec4 b = getToColor(uv);
  float fill;
  float lit;
  if (segments > 0) {
    float segs = float(segments);
    float above = h * segs - floor(uv.y * segs);
    fill = clamp(above, 0.0, 1.0);
    lit = 1.0 - clamp(above - 1.0, 0.0, 1.0);
    float seam = abs(fract(uv.y * segs) - 0.5) * 2.0;
    float aaS = AA * segs * 2.0;
    b.rgb *= 1.0 - 0.38 * open * smoothstep(0.78 - aaS, 0.78 + aaS, seam);
  } else {
    fill = 1.0 - smoothstep(h - AA, h + AA, uv.y);
    lit = 1.0 - smoothstep(0.0, 0.04, h - uv.y);
  }
  b.rgb += 0.2 * open * lit * (1.0 - b.rgb);
  float across = 2.0 * fx - 1.0;
  b.rgb *= 1.0 - 0.15 * open * across * across;
  float m = barX * fill;

  vec4 a = getFromColor(uv);
  float beside = (1.0 - smoothstep(0.0, gap, gap - side)) * (1.0 - smoothstep(h - 0.01, h + 0.01, uv.y));
  float under = barX * smoothstep(capY - 0.025, capY, uv.y) * (1.0 - smoothstep(capY - AA, capY + AA, uv.y));
  a.rgb *= 1.0 - open * (0.35 * inGap * beside + 0.4 * under);

  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);

  float cap = barX * smoothstep(capY - AA, capY + AA, uv.y) * (1.0 - smoothstep(capY + CAP - AA, capY + CAP + AA, uv.y));
  cap *= capColor.a * smoothstep(0.0, 0.05, progress) * (1.0 - smoothstep(0.95, 1.0, progress));
  c = mix(c, vec4(capColor.rgb, 1.0), cap);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image settles into a wall of flat squares, each rectangle filled with the largest squares that fit and the rest with smaller and smaller ones; as the corners glide, rows of tiny squares swell out of nothing, squares of the incoming image's colors open inside them, the smallest first, and they clear up into it
// Tags: squares, blocks, flat-color, geometric, math
// Preview: 0.6

// @range(0, 1) How far the corners of the rectangles glide
uniform float glide; // = 1.0
// @range(0, 1) How vivid the flat colors are
uniform float vividness; // = 0.6

vec4 vivid(vec4 c, float k) {
  float g = dot(c.rgb, vec3(0.333));
  return vec4(clamp(g + (c.rgb - g) * (1.0 + vividness * k), 0.0, 1.0), c.a);
}

// turns flat as k goes to 1; what stands out among the reads keeps its color vivid and steady while it moves
vec4 paint(vec2 uv, vec2 c, vec2 r, float k, bool incoming) {
  vec4 acc = vec4(0.0);
  float total = 0.0;
  r *= smoothstep(0.6, 1.0, k);
  for (int i = 0; i < 8; i++) {
    vec2 o = fract(vec2(0.754878, 0.569840) * (float(i) + 0.5)) - 0.5;
    vec2 q = mix(uv, c + o * r, k);
    vec4 t = incoming ? getToColor(q) : getFromColor(q);
    float w = 0.15 + max(t.r, max(t.g, t.b)) - min(t.r, min(t.g, t.b));
    acc += vec4(t.rgb * t.a, t.a) * w;
    total += w;
  }
  return vivid(vec4(acc.rgb / max(acc.a, 1e-5), acc.a / total), k);
}

vec4 squareAt(vec2 uv) {
  vec2 a = vec2(ratio, 1.0);
  bool tall = ratio < 1.0;
  vec2 L = tall ? a.yx : a;
  vec2 P = tall ? (uv * a).yx : uv * a;
  float t = mix(0.5, progress, glide);
  float x0 = L.x * (0.5 + 0.2 * sin(3.0 * t - 0.5));
  float side = step(x0, P.x);
  vec2 org = vec2(side * x0, 0.0);
  L.x = mix(x0, L.x - x0, side);
  vec2 C = L * (0.5 + 0.36 * vec2(sin(4.2 * t - 2.4 + 2.4 * side), cos(3.3 * t - 2.6 + 2.0 * side)));
  P -= org;
  vec2 s = step(C, P);
  vec2 wh = mix(C, L - C, s);
  vec2 p = abs(mix(P, L - P, s));
  vec2 o = vec2(0.0);
  float size = 0.0;
  for (int i = 0; i < 12; i++) {
    bool wide = wh.x > wh.y;
    float m = max(min(wh.x, wh.y), 1e-3);
    float n = floor((wide ? wh.x : wh.y) / m + 1e-4);
    float k = floor((wide ? p.x - o.x : p.y - o.y) / m);
    vec2 dir = wide ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    size = m;
    o += dir * min(k, n) * m;
    if (k < n) break;
    wh -= dir * n * m;
    if (min(wh.x, wh.y) < 0.004) break;
  }
  vec2 c = o + 0.5 * size;
  vec2 loc = abs(p - c) / size;
  c = mix(c, L - c, s) + org;
  if (tall) c = c.yx;
  float big = clamp(1.0 + log2(size / 0.5) / 5.0, 0.0, 1.0);
  float open = smoothstep(0.0, 0.2, progress - 0.26 - 0.28 * big);
  bool fresh = max(loc.x, loc.y) < 0.52 * open;
  float k = fresh ? 1.0 - smoothstep(0.68, 0.98, progress) : smoothstep(0.02, 0.32, progress);
  vec4 col = paint(uv, c / a, 0.85 * size / a, k, fresh);
  return vec4(col.rgb * col.a, col.a);
}

vec4 transition(vec2 uv) {
  vec2 e = 0.0011 / vec2(ratio, 1.0) * smoothstep(0.0, 0.1, min(progress, 1.0 - progress));
  vec4 s = squareAt(uv + e * vec2(0.5, 1.0)) + squareAt(uv + e * vec2(-1.0, 0.5)) + squareAt(uv - e * vec2(0.5, 1.0)) + squareAt(uv - e * vec2(-1.0, 0.5));
  return vec4(s.rgb / max(s.a, 1e-5), 0.25 * s.a);
}

// Author: gre
// License: MIT
// Description: Curved eyelids close from the top and bottom over the outgoing image, which blurs and dims, then open on the incoming image as it comes back into focus, as if the viewer blinked
// Tags: blink, eye, blur, shape

// @range(0, 1) How much the image blurs and dims while the eyes are closed
uniform float blur; // = 0.5
// @range(0.01, 0.3) Width of the soft shadow along the rim of the eyelids
uniform float softness; // = 0.12
// @range(1, 2, 1) Number of blinks: 1, or 2 for a quick double blink (the cut happens on the first one)
uniform int blinks; // = 1
// @color Color of the eyelids
uniform vec4 color; // = vec4(0.03, 0.02, 0.02, 1.0)

const int TAPS = 16;
// how much the eyelids curve: the opening is widest at the center and the corners close first
const float CURVE = 0.25;
// where the eyelids meet, below the middle: the upper lid travels further than the lower one
const float MEET = 0.44;

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// a blink fully closed at c (held for 2 * hold): the lids close over wc before it
// and open over wo after it, slower, like a real blink
float lidBlink(float t, float c, float wc, float wo, float hold) {
  return 1.0 - smoothstep(hold, t < c ? wc : wo, abs(t - c));
}

vec4 image(vec2 uv, bool incoming) {
  vec4 c = incoming ? getToColor(uv) : getFromColor(uv);
  return vec4(c.rgb * c.a, c.a);
}

vec4 transition(vec2 uv) {
  bool two = blinks > 1;
  float cut = two ? 0.3 : 0.42;
  float closed = two
    ? max(lidBlink(progress, cut, 0.26, 0.26, 0.015), lidBlink(progress, 0.7, 0.14, 0.24, 0.01))
    : lidBlink(progress, cut, 0.36, 0.5, 0.02);
  bool incoming = progress >= cut;

  // the rim of each eyelid is an arc; fully open, even its corners clear the frame by the widest shadow
  float soft = clamp(softness, 0.001, 0.3);
  float x = 2.0 * uv.x - 1.0;
  float rim = (1.0 - closed) * (1.31 + CURVE) - CURVE * x * x;
  float y = uv.y - MEET;
  float d = rim - max(y / (1.0 - MEET), -y / MEET);
  float s = 1.0 - smoothstep(0.0, soft, d);
  float lid = s * s;
  if (lid >= 1.0) return color;

  float f = progress < cut ? progress / cut : (1.0 - progress) / (1.0 - cut);
  f = clamp(f, 0.0, 1.0);
  f = max(f * (2.0 - f), closed) * blur;

  vec4 c;
  if (f <= 0.0) {
    c = incoming ? getToColor(uv) : getFromColor(uv);
  } else {
    float r = 0.025 * f;
    c = vec4(0.0);
    for (int i = 0; i < TAPS; i++) {
      float k = float(i) + 0.5;
      float a = 2.39996 * k;
      vec2 o = sqrt(k / float(TAPS)) * vec2(cos(a), sin(a)) * r;
      c += image(mirror(uv + o * vec2(1.0 / ratio, 1.0)), incoming);
    }
    c /= float(TAPS);
    c = c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
    c.rgb *= 1.0 - 0.35 * f;
  }
  return mix(c, color, lid);
}

// Author: gre
// License: MIT
// Description: The frame is seen through a pane of irregular cut-glass facets, each one showing its own shifted, zoomed and tilted view of the image, with bright beveled edges and thin dark seams; the facets turn to the incoming image one by one, then the glass flattens out and clears
// Tags: glass, refraction, facets, voronoi, distortion

// @range(2, 20) Number of facets across the height of the frame
uniform float facets; // = 5.0
// @range(0, 0.3) How far each facet shifts its view of the image at the peak
uniform float refraction; // = 0.1
// @range(0, 1) Strength of the highlights and shadows along the beveled edges, and of the glint as each facet turns
uniform float bevel; // = 0.6
// @color Color of the light caught by the bevels
uniform vec4 highlight; // = vec4(1.0, 0.98, 0.92, 1.0)
// @param Random seed: another value gives other facets, turning in another order
uniform float seed; // = 0.0

const float AA = 0.0015;

vec2 hash22(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xx + p3.yz) * p3.zy);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  float h = 1.0 - abs(2.0 * progress - 1.0);
  float amount = h * h * (3.0 - 2.0 * h);

  float n = max(facets, 1.0);
  vec2 aspect = vec2(ratio, 1.0);
  // measured in square pixels, so the facets are not stretched
  vec2 p = uv * aspect * n;
  vec2 i = floor(p);
  vec2 f = p - i;
  vec2 offset = vec2(17.31, 41.97) * seed;
  float bw = 0.18 * amount;

  vec2 mg = vec2(0.0);
  vec2 mr = vec2(0.0);
  float md = 8.0;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 g = vec2(float(x), float(y));
      vec2 r = g + 0.1 + 0.8 * hash22(i + g + offset) - f;
      float d = dot(r, r);
      if (d < md) {
        md = d;
        mr = r;
        mg = g;
      }
    }
  }

  // distance to the nearest facet edge, and the direction toward the edges, blended
  // between neighboring edges near the corners so the bevel lighting turns smoothly
  float edge = 8.0;
  vec2 normal = vec2(0.0);
  for (int y = -2; y <= 2; y++) {
    for (int x = -2; x <= 2; x++) {
      vec2 g = mg + vec2(float(x), float(y));
      vec2 r = g + 0.1 + 0.8 * hash22(i + g + offset) - f;
      vec2 dr = r - mr;
      if (dot(dr, dr) > 0.00001) {
        vec2 dn = normalize(dr);
        float e = dot(0.5 * (mr + r), dn);
        edge = min(edge, e);
        float w = max(1.0 - e / bw, 0.0);
        normal += dn * w * w;
      }
    }
  }
  float nl = length(normal);
  normal = nl > 0.0 ? normal / nl : vec2(0.0);

  vec2 id = i + mg + offset;
  vec2 h1 = hash22(id + 31.7);
  vec2 h2 = hash22(id + 59.3);
  vec2 h3 = hash22(id + 97.1);
  float angle = 6.2831853 * h1.x;
  vec2 dir = vec2(cos(angle), sin(angle));
  vec2 shift = dir * (0.4 + 0.6 * h1.y) * refraction;
  float zoom = (h2.x - 0.5) * 6.0 * refraction;
  float tilt = (h2.y - 0.5) * 2.0 * refraction;

  vec2 q = -mr / n;
  vec2 view = -q * zoom + vec2(-q.y, q.x) * sin(tilt) + q * (cos(tilt) - 1.0);

  float bv = 1.0 - smoothstep(0.0, bw, edge);
  bv *= bv;
  vec2 bend = normal * bv * 0.4 * refraction;

  float start = 0.15 + 0.5 * h3.x;
  float m = smoothstep(start, start + 0.2, progress);
  vec2 d = amount * (view + bend);
  vec2 s = amount * shift;
  vec4 ca = getFromColor(mirror(uv + (s + d) / aspect));
  vec4 cb = getToColor(mirror(uv + (d - s) / aspect));
  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(ca.rgb * ca.a, ca.a), vec4(cb.rgb * cb.a, cb.a), m);

  vec2 light = normalize(vec2(-0.6, 0.8));
  vec2 slope = dir * (0.4 + 0.6 * h1.y);
  float facetLight = 0.12 * amount * dot(slope, light);
  float lit = dot(normal, light);
  float k = clamp(bevel, 0.0, 1.0);
  float glow = k * bv * max(lit, 0.0) * 1.1 * amount;
  float shade = k * bv * max(-lit, 0.0) * 0.6 * amount;
  float turn = sin(3.14159265 * m);
  glow += k * 0.15 * amount * turn * turn;
  float seam = 0.6 * amount * (1.0 - smoothstep(0.0, 2.0 * AA, edge / n - 0.5 * AA));

  c.rgb *= (1.0 + facetLight) * (1.0 - shade) * (1.0 - seam);
  c.rgb += highlight.rgb * highlight.a * glow * c.a;
  return c.a > 0.0 ? vec4(clamp(c.rgb / c.a, 0.0, 1.0), c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A linear crossfade between the two images
// Tags: fade, blend

vec4 transition (vec2 uv) {
  return mix(
    getFromColor(uv),
    getToColor(uv),
    progress
  );
}

// Author: gre
// License: MIT
// Description: A fade through a solid color, black by default
// Tags: fade, color
// @color Color to fade through
uniform vec4 color; // = vec4(0.0, 0.0, 0.0, 1.0)
// @range(0, 1) How long the color shows in the middle
uniform float colorPhase; // = 0.4 ; // if 0.0, there is no black phase, if 0.9, the black phase is very important
vec4 transition (vec2 uv) {
  return mix(
    mix(color, getFromColor(uv), smoothstep(1.0-colorPhase, 0.0, progress)),
    mix(color, getToColor(uv), smoothstep(    colorPhase, 1.0, progress)),
    progress);
}

// Author: gre
// License: MIT
// Description: A crossfade through grayscale
// Tags: fade, grayscale, color

// @range(0, 1) How long the grayscale phase lasts
uniform float intensity; // = 0.3; // if 0.0, the image directly turn grayscale, if 0.9, the grayscale transition phase is very important

vec3 grayscale (vec3 color) {
  return vec3(0.2126*color.r + 0.7152*color.g + 0.0722*color.b);
}

vec4 transition (vec2 uv) {
  vec4 fc = getFromColor(uv);
  vec4 tc = getToColor(uv);
  return mix(
    mix(vec4(grayscale(fc.rgb), fc.a), fc, smoothstep(1.0-intensity, 0.0, progress)),
    mix(vec4(grayscale(tc.rgb), tc.a), tc, smoothstep(    intensity, 1.0, progress)),
    progress);
}

// Author: gre
// License: MIT
// Description: The viewer faints: the outgoing image splits into two swaying copies of itself and blurs while the edges of the view darken and close in, in two heartbeat throbs, down to a last pinpoint of light; the incoming image comes back blurred and doubled through a narrow tunnel, which widens again in throbs as the two copies drift together and lock
// Tags: eye, vignette, blur, fade

// @range(0, 0.15) How far apart the two copies drift at the peak, in frame heights
uniform float separation; // = 0.07
// @range(0, 1) How out of focus the view gets
uniform float blur; // = 0.6
// @color Color the view fades to
uniform vec4 color; // = vec4(0.0, 0.0, 0.0, 1.0)

const int TAPS = 8;

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 image(vec2 uv, bool incoming) {
  vec4 c = incoming ? getToColor(mirror(uv)) : getFromColor(mirror(uv));
  return vec4(c.rgb * c.a, c.a);
}

// a small blur disc around uv (premultiplied), golden-angle taps
vec4 soft(vec2 uv, float r, bool incoming) {
  vec4 s = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    float k = float(i) + 0.5;
    float a = 2.39996 * k;
    s += image(uv + sqrt(k / float(TAPS)) * vec2(cos(a) / ratio, sin(a)) * r, incoming);
  }
  return s / float(TAPS);
}

vec4 transition(vec2 uv) {
  float p = progress;
  bool incoming = p >= 0.5;
  // how far gone the viewer is: 0 at both ends, 1 at the cut
  float a = incoming ? 2.0 - 2.0 * p : 2.0 * p;
  float g = incoming ? a * sqrt(a) : a;
  // the view closes in steps, two heartbeat throbs: fast, pause, fast
  float closing = g - sin(12.566371 * g) / 12.566371;
  float sway = sin(9.0 * p + 1.3);
  vec2 off = separation * smoothstep(0.0, 0.5, a) * vec2(1.0, 0.25 * sway) * vec2(1.0 / ratio, 1.0);
  float r = 0.03 * blur * a;
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
