    if (m > 0.0) {
      xb += hb * flow(xb, 0.5 * d, cell, e0, e1, e2);
      vec4 c = getToColor(fold(xb, s));
      b += w * vec4(c.rgb * c.a, c.a);
    }
  }
  vec4 c = mix(a, b, m) / wsum;
  c.rgb *= 1.0 - 0.3 * (1.0 - m) * exp(-abs(f) / 0.03) * sin(PI * progress);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

