float lat(float s) {
  float s2 = s * s;
  return abs(s) < 0.25 ? s * (1.0 + s2 * (1.0 / 6.0 + s2 * (0.075 + s2 * 0.0446429))) : asin(clamp(s, -1.0, 1.0));
