uniform float drift; // = 1.1

const float TAU = 6.2831853;
const float PX = 0.0012;

float hash(float n) {
  float q = fract(n * 0.1031);
  q *= q + 33.33;
  return fract(q * (q + q));
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
