const float TAU = 6.2831853;
const int TAPS = 12;

float hash(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

float lum(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

float strand(float a, float n, float seed) {
  float x = fract(a) * n;
  float i = floor(x);
  float lo = hash(mod(i, n) + seed);
  float hi = hash(mod(i + 1.0, n) + seed);
  return mix(lo, hi, smoothstep(0.3, 0.7, x - i));
}

// strands fade out where they get thinner than a few pixels
float fine(float r, float n) {
  return smoothstep(0.004, 0.016, TAU * r / n);
}

float jag(float a, float r) {
  float spike = strand(a, 23.0, 23.0);
  return 0.75 + 0.6 * spike * spike
    + mix(0.15, 0.35 * strand(a, 53.0, 5.0), fine(r, 53.0))
    + mix(0.12, 0.3 * strand(a, 190.0, 11.0), fine(r, 190.0));
}

// 1 inside a jagged star of mean radius R; slope is the change of j per unit of arc
float star(float r, float R, float j, float slope) {
  float d = (R * j - r) / sqrt(1.0 + R * R * slope * slope);
  return smoothstep(-0.0015, 0.0015, d) * smoothstep(0.0, 0.004, R);
}

float localLum(vec2 q, vec2 k, bool incoming) {
  vec2 s = vec2(0.0);
  for (int i = 0; i < TAPS; i++) {
    float t = 2.39996 * float(i);
    vec2 o = 0.16 * sqrt((float(i) + 0.5) / float(TAPS)) * vec2(cos(t), sin(t));
    vec2 st = mirror((q + o) / k + 0.5);
    vec4 c = incoming ? getToColor(st) : getFromColor(st);
    s += vec2(lum(c.rgb), 1.0) * c.a;
  }
  return s.x / max(s.y, 1e-4);
}

vec4 drawing(vec4 c, float around, float rough, vec4 dark, vec4 light) {
  float t = mix(threshold, around, 0.35);
  float x = smoothstep(t - 0.02, t + 0.02, lum(c.rgb) + 0.8 * rough);
  return vec4(mix(mix(c.rgb, dark.rgb, dark.a), mix(c.rgb, light.rgb, light.a), x), c.a);
}

float scratch(float a, float r) {
  // redrawn on a steady beat, like hand-inked frames; a step larger than the strand counts, so no strand comes back
  float seed = 257.0 * floor(progress * 12.0 + 0.5);
  float ray = 0.45 * strand(a, 240.0, seed) + 0.35 * strand(a, 97.0, seed + 7.0) + 0.2 * strand(a, 31.0, seed + 3.0);
  return scratches * (ray - 0.5) * smoothstep(0.1, 0.7, r);
}

vec4 transition(vec2 uv) {
  vec2 k = vec2(ratio, 1.0);
  vec2 p = (uv - 0.5) * k;
  float R = 0.5 * length(k);
  float r = length(p);
  float a = atan(p.y, p.x + 1e-6) / TAU;
  // jag is at least 0.75, so a star of this mean radius covers the corners
  float reach = 1.5 * R;
  float j = jag(a, r);
  float da = 0.0006 / (r + 0.01);
  float slope = (jag(a + da, r) - j) / (TAU * 0.0006);
  float inked = 1.0 - star(r, reach * (1.0 - smoothstep(0.0, 0.28, progress)), j, slope);
  float swap = star(r, reach * smoothstep(0.41, 0.6, progress), j, slope);
  float color = star(r, reach * smoothstep(0.62, 0.95, progress), j, slope);

  float rough = (inked > 0.0 && swap < 1.0) || (swap > 0.0 && color < 1.0) ? scratch(a, r / R) : 0.0;
  vec4 A = vec4(0.0);
  vec4 B = vec4(0.0);
  if (swap < 1.0) {
    vec2 q = p * (1.0 - zoom * smoothstep(0.0, 0.5, progress));
    A = getFromColor(mirror(q / k + 0.5));
    if (inked > 0.0) A = mix(A, drawing(A, localLum(q, k, false), rough, ink, paper), inked);
  }
  if (swap > 0.0) {
    vec2 q = p * (1.0 - zoom * (1.0 - smoothstep(0.4, 1.0, progress)));
    B = getToColor(mirror(q / k + 0.5));
    if (color < 1.0) B = mix(drawing(B, localLum(q, k, true), rough, accent, paper), B, color);
  }
  vec4 col = mix(vec4(A.rgb * A.a, A.a), vec4(B.rgb * B.a, B.a), swap);
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image crawls out of the frame like an inchworm: its back edge creeps forward and the picture humps up into a tall shaded arch, then its front edge reaches ahead and the arch flattens, two strides, uncovering the incoming image behind
// Tags: crawl, hump, 3d, shadow, directional, organic

// @range(0.5, 1.5) How tall the arch grows toward the viewer
uniform float arch; // = 1.0

const float PI = 3.14159265;
const float STRIDE = 0.5;
const float AA = 0.002;
const vec3 LIGHT = vec3(-0.5847, 0.3118, 0.7484);

float iwEase(float x) {
  x = clamp(x, 0.0, 1.0);
  return x * x * (3.0 - 2.0 * x);
}

float iwHump(float x, float a, float span, float h) {
  float u = clamp((x - a) / span, 0.0, 1.0);
  float s = sin(PI * pow(u, 0.8));
  return h * s * s;
}

vec4 transition(vec2 uv) {
  float t = progress * 3.0;
  // overlapping beats keep the crawl flowing: gather, reach, gather
  float g = iwEase(t / 1.2) + iwEase((t - 1.8) / 1.2);
  float reach = iwEase((t - 0.8) / 1.4);
  // two gathers carry the back edge just past the right side of the frame, whatever its width
  float a = STRIDE * g * ratio + 0.003 * g;
  float span = (1.0 + STRIDE * reach) * ratio - a;
  // follows the sheet's length, eased off on wide frames so the arch never nears the eye
  float h = arch * 0.55 * (ratio - span) * sqrt((ratio + span) / ratio);
  h = min(h / (1.0 + 0.5 * h), 1.2);

  // seen from slightly below, so the raised arch lifts its bottom edge off the floor
  vec3 eye = vec3(0.5 * ratio, -1.0, 1.8);
  vec3 ray = vec3(uv.x * ratio, uv.y, 0.0) - eye;

  float s0 = 1.0 - (h + 0.001) / eye.z;
  float sl = s0;
  float fl = eye.z * (1.0 - s0) - iwHump(eye.x + s0 * ray.x, a, span, h);
  float sr = 1.0;
  int side = 0;
  for (int i = 1; i <= 40; i++) {
    float s = mix(s0, 1.0, float(i) / 40.0);
    float f = eye.z * (1.0 - s) - iwHump(eye.x + s * ray.x, a, span, h);
    float y = eye.y + s * ray.y;
    if ((fl > 0.0) != (f > 0.0) && y > -2.0 * AA && y < 1.0 + 2.0 * AA) {
      sr = s;
      side = fl > 0.0 ? 1 : 2;
      break;
    }
    sl = s;
    fl = f;
  }
  float fr = eye.z * (1.0 - sr) - iwHump(eye.x + sr * ray.x, a, span, h);
  for (int i = 0; i < 5; i++) {
    float sm = 0.5 * (sl + sr);
    float fm = eye.z * (1.0 - sm) - iwHump(eye.x + sm * ray.x, a, span, h);
    if ((fm > 0.0) == (fl > 0.0)) {
      sl = sm;
      fl = fm;
    } else {
      sr = sm;
      fr = fm;
    }
  }
  // a final secant step lands exactly on the floor where the sheet lies flat
  float sh = abs(fl - fr) > 1e-6 ? sl + (sr - sl) * fl / (fl - fr) : sr;
  vec3 hit = eye + sh * ray;

  float len = 0.0;
  float tot = 0.0;
  float prev = 0.0;
  for (int i = 1; i <= 24; i++) {
    float x = a + span * float(i) / 24.0;
    float z = iwHump(x, a, span, h);
    float seg = sqrt(span * span / 576.0 + (z - prev) * (z - prev));
    tot += seg;
    len += seg * clamp((hit.x - x) * 24.0 / span + 1.0, 0.0, 1.0);
    prev = z;
  }

  float e = 0.002 * ratio;
  float dz = (iwHump(hit.x + e, a, span, h) - iwHump(hit.x - e, a, span, h)) / (2.0 * e);
  vec3 n = normalize(vec3(-dz, 0.0, 1.0));
  float light = (0.45 + 0.55 * max(dot(n, LIGHT), 0.0)) / (0.45 + 0.55 * LIGHT.z);
  // the underside of the arch only gets light bounced off the floor
  light = side == 2 ? 0.35 : light;
  vec4 sheet = getFromColor(vec2(len / max(tot, 1e-6), clamp(hit.y, 0.0, 1.0)));
  sheet.rgb *= light;
  float cov = side > 0 ? smoothstep(-2.0 * AA, 0.0, hit.y) * smoothstep(-2.0 * AA, 0.0, 1.0 - hit.y) * smoothstep(a - 2.0 * AA, a, hit.x) : 0.0;

  float occ = 0.0;
  for (int i = 1; i <= 8; i++) {
    float z = h * float(i) / 8.0;
    float x = uv.x * ratio + z * LIGHT.x / LIGHT.z;
    float y = uv.y + z * LIGHT.y / LIGHT.z;
    float inside = smoothstep(-0.02, 0.0, y) * smoothstep(-0.02, 0.0, 1.0 - y);
    occ = max(occ, inside * smoothstep(0.0, 0.04, iwHump(x, a, span, h) - z));
  }
  vec4 floorColor = getToColor(uv);
  float ao = smoothstep(0.0, 0.3, iwHump(uv.x * ratio, a, span, h));
  floorColor.rgb *= (1.0 - 0.5 * occ) * (1.0 - 0.3 * ao);

  return mix(floorColor, sheet, cov);
}

// Author: gre
// License: MIT
// Description: The incoming image spreads over the outgoing one like drops of ink in water, blooming from a few points with curling, wispy edges and a darker rim, until it fills the frame
// Tags: ink, organic, fluid, noise

// @range(1, 8, 1) Number of ink drops
uniform float drops; // = 4.0
// @range(0, 1) How far the curling tendrils reach out of the blooms
uniform float tendrils; // = 0.7
// @range(0, 1) How dark the rim of ink at the front of the blooms is
uniform float rim; // = 0.5
// @param Random seed for the drop positions and the swirls
uniform float seed; // = 3.0

float hash (vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float vnoise (vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm (vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * vnoise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p + 7.3;
    a *= 0.5;
  }
  return v / 0.9375;
}

vec2 fold (vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec4 transition (vec2 uv) {
  float p = progress;
  vec2 q = vec2(uv.x * ratio, uv.y);
  vec2 o = vec2(seed * 3.1, seed * 1.7);
  vec2 sq = q * 2.2 + o;
  vec2 w1 = vec2(fbm(sq + vec2(0.0, 0.6 * p)), fbm(sq + vec2(5.2, 1.3) - vec2(0.5 * p, 0.0)));
  vec2 w2 = vec2(fbm(sq + 3.0 * w1 + vec2(1.7, 9.2)), fbm(sq + 3.0 * w1 + vec2(8.3, 2.8)));
  float swirl = fbm(sq * 0.8 + 2.5 * w2) - 0.5;
  vec2 flow = w2 - 0.5;
  float amp = 0.05 + 0.35 * tendrils;
  float n = clamp(floor(drops + 0.5), 1.0, 8.0);
  float rimW = 0.1;
  float feather = 0.05;
  float margin = 1.2 * amp + rimW + 0.08; // how far the swirls can pull the front back
  float f = -1e3; // > 0 inside the ink
  float fs = -1e3; // the same, only for the drops already fallen, which fades their haze in
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    if (fi < n) {
      vec2 hs = vec2(fi * 7.13 + seed, fi * 3.71 - seed);
      vec2 c = vec2(mix(0.15, 0.85, hash(hs)) * ratio, mix(0.15, 0.85, hash(hs + 19.7)));
      float start = 0.2 * fi / n;
      float s = clamp((p - start) / (1.0 - start), 0.0, 1.0);
      // distance to the farthest corner: each bloom alone covers the frame in the end
      vec2 m = max(c, vec2(ratio, 1.0) - c);
      float far = length(m) + margin;
      float s3 = s * s * s;
      float r = (far + 0.02) * s * (0.35 + 0.65 * s3 * s3) - 0.02;
      float reach = amp * min(1.0, max(r, 0.0) * 5.0);
      float g = r - length(q - c + 1.3 * reach * flow) + reach * 0.9 * swirl;
      f = max(f, g);
      fs = max(fs, g - 0.15 * (1.0 - min(1.0, s * 12.0)));
    }
  }
  float aa = 0.003;
  float inside = smoothstep(-aa, aa, f);
  float wisp = 1.0 - smoothstep(0.0, 0.08, abs(fbm(sq * 2.0 + 5.0 * w2) - 0.5));
  float soft = smoothstep(-feather, 0.0, fs) * (0.35 + 0.4 * wisp);
  float haze = 0.35 * wisp * (1.0 - smoothstep(0.0, 0.1, -fs));
  float cover = max(inside, max(soft, haze));
  float edge = 1.0 - smoothstep(0.0, rimW, f);
  vec4 to = getToColor(fold(uv - 0.015 * edge * flow / vec2(ratio, 1.0)));
  to.rgb = mix(to.rgb, to.rgb * to.rgb * 0.7, rim * edge);
  return mix(getFromColor(uv), to, cover);
}

// Author: gre
// License: MIT
// Description: A rectangle anchored in a corner, on an edge or in the center grows until the incoming image fills the frame, revealing it in place without scaling it; in reverse, the outgoing image shrinks into the rectangle
// Tags: wipe, shape, box
// Preview: 0.5

// @param Where the rectangle grows from: (0, 0) bottom left, (1, 1) top right, (0.5, 0) middle of the bottom edge, (0.5, 0.5) center
uniform vec2 anchor; // = vec2(1.0, 1.0)
// @range(0, 0.2) Softness of the rectangle's edge
uniform float smoothness; // = 0.0
// @range(0, 0.1) Width of a border drawn around the rectangle, in frame heights (0: no border)
uniform float borderWidth; // = 0.0
// @color Color of the border
uniform vec4 borderColor; // = vec4(1.0, 1.0, 1.0, 1.0)
// @param The outgoing image shrinks into the rectangle instead, toward the anchor
uniform bool reverse; // = false

const float AA = 0.001;

vec4 premultiplied(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);

  vec2 an = clamp(anchor, 0.0, 1.0);
  vec2 sq = vec2(ratio, 1.0);
  // the rectangle keeps the proportions that make it reach every far side of the frame
  // at once; measured in square pixels so its edge and border have an even width
  vec2 ext = max(an, 1.0 - an) * sq;
  vec2 d = abs(uv - an) * sq;
  float s = max(smoothness, AA);
  float bw = max(borderWidth, 0.0);

  // eased growth, from a rectangle whose border is not yet in the frame to one whose
  // soft edge has left it on every side
  float t = reverse ? 1.0 - progress : progress;
  float p = mix(t, t * t * (3.0 - 2.0 * t), 0.3);
  vec2 size = p * ext + mix(-(bw + s), s, p);
  // signed distance to the rectangle's edge, square-cornered, < 0 inside
  float e = max(d.x - size.x, d.y - size.y);

  vec4 inside = reverse ? a : b;
  vec4 c = premultiplied(reverse ? b : a);
  if (bw > 0.0) {
    // laid over the image outside the rectangle, so a translucent border tints it
    float m = 1.0 - smoothstep(bw - s, bw + s, e);
    c = premultiplied(borderColor) * m + c * (1.0 - borderColor.a * m);
  }
  c = mix(c, premultiplied(inside), 1.0 - smoothstep(-s, s, e));
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The camera stands inside a cube: the outgoing image covers the wall in front of it and the view turns toward the next inner wall, so the outgoing image swings away in perspective as the incoming one turns into view, the walls darkening into the shaded inner corner between them
// Tags: 3d, cube, rotate, perspective, directional

// @param Direction the view turns toward, snapped to its main axis (left, right, up or down): the incoming image is on the wall on that side
uniform vec2 direction; // = vec2(1.0, 0.0)
// @range(60, 120) Field of view along the turn, in degrees: at 90 the camera stays at the center of the cube, a wider view makes the walls recede more
uniform float fov; // = 90.0
// @range(0, 1) How much the walls darken as they turn away, and the shadow in the inner corners of the cube
uniform float shading; // = 0.6
// @color Color of the other faces of the cube, seen where the two walls leave the frame uncovered during the turn
uniform vec4 background; // = vec4(0.09, 0.09, 0.1, 1.0)

const float PI = 3.141592653589793;
const float EDGE = 0.002;

vec4 premultiply(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

float cornerShadow(float dist, float size) {
  float k = 1.0 - smoothstep(0.0, size, dist);
  return k * k;
}

// the image on a wall at the point l of the wall, in frame heights from its center (l.x along
// the turn, l.y across), premultiplied; s and vertical undo the mirroring and the swap of axes
// that transition() applies to the frame coordinates
vec4 wallColor(vec2 l, bool incoming, bool vertical, float s) {
  vec2 h = vec2(l.x * s, l.y);
  vec2 p = vertical ? h.yx : h;
  vec2 st = clamp(p / vec2(ratio, 1.0) + 0.5, 0.0, 1.0);
  return premultiply(incoming ? getToColor(st) : getFromColor(st));
}

vec4 transition(vec2 uv) {
  bool vertical = abs(direction.y) > abs(direction.x);
  float s = (vertical ? direction.y : direction.x) < 0.0 ? -1.0 : 1.0;
  // q.x: along the turn, toward the incoming wall; q.y: across; in frame heights
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  vec2 q = vertical ? p.yx : p;
  q.x *= s;
  float A = vertical ? 0.5 : 0.5 * ratio;
  float B = vertical ? 0.5 * ratio : 0.5;
  // focal length: a wall exactly fills the frame when seen square from that distance
  // (below about 53 degrees the camera would stand outside the cube)
  float F = A / tan(radians(clamp(fov, 55.0, 170.0)) * 0.5);

  float e = smoothstep(0.0, 1.0, progress);
  float th = 0.5 * PI * e;
  float c = cos(th);
  float sn = sin(th);
  float amount = max(sin(PI * e), 0.0); // 0 at both ends, so the images are untouched there
  float aa = EDGE * min(1.0, 40.0 * amount) + 1e-6;
  float shadow = shading * min(1.0, 4.0 * amount);

  // in the plane of the turn (a: along, z: depth), the outgoing wall is z = F, a in [-A, A],
  // the incoming wall is a = A, z in [F - 2A, F]; the camera starts in front of the center of
  // the first one and ends in front of the center of the second one
  vec2 cam = (A - F) * e * vec2(1.0, -1.0);
  vec2 d = vec2(q.x * c + F * sn, F * c - q.x * sn);

  vec2 P = vec2(A, F) - cam;
  float sc = F * (P.x * c - P.y * sn) / max(P.x * sn + P.y * c, 1e-6);

  float tf = d.y > 1e-6 ? (F - cam.y) / d.y : 1e6;
  float af = cam.x + tf * d.x;
  vec2 lf = vec2(af, q.y * tf);
  float ti = d.x > 1e-6 ? (A - cam.x) / d.x : 1e6;
  float ai = (F - A) - (cam.y + ti * d.y);
  vec2 li = vec2(ai, q.y * ti);

  float size = 0.8 * min(A, B);
  float edgeF = cornerShadow(A - af, size) + 0.5 * cornerShadow(B - abs(lf.y), size);
  float edgeI = cornerShadow(ai + A, size) + 0.5 * cornerShadow(B - abs(li.y), size);
  float shadeF = (1.0 - shading * 0.8 * (1.0 - c)) * (1.0 - 0.7 * shadow * min(edgeF, 1.0));
  float shadeI = (1.0 - shading * 0.8 * (1.0 - sn)) * (1.0 - 0.7 * shadow * min(edgeI, 1.0));

  // how much of the pixel each wall covers, from distances on screen in frame heights: split at
  // the corner line, cut across by the edges of the walls (lb = q.y * t), and at their far
  // edges (along the wall, a moves F * t / d.depth times faster than q.x)
  float wF = clamp(0.5 + (sc - q.x) / aa, 0.0, 1.0);
  float covF = wF * clamp(0.5 + (B / tf - abs(q.y)) / aa, 0.0, 1.0)
    * clamp(0.5 + (af + A) * d.y / (tf * F * aa), 0.0, 1.0);
  float covI = (1.0 - wF) * clamp(0.5 + (B / ti - abs(q.y)) / aa, 0.0, 1.0)
    * clamp(0.5 + (A - ai) * d.x / (ti * F * aa), 0.0, 1.0);
  vec4 colF = covF > 0.0 ? wallColor(lf, false, vertical, s) : vec4(0.0);
  vec4 colI = covI > 0.0 ? wallColor(li, true, vertical, s) : vec4(0.0);
  colF.rgb *= shadeF;
  colI.rgb *= shadeI;

  vec4 bg = premultiply(background);
  float cov = covF + covI;
  if (cov < 1.0) {
    float tb = min(B / max(abs(q.y), 1e-6), min(tf, ti));
    vec2 fl = cam + tb * d;
    float edgeB = cornerShadow(F - fl.y, size) + cornerShadow(A - fl.x, size);
    bg.rgb *= 1.0 - 0.5 * shadow * min(edgeB, 1.0);
  }
  vec4 col = colF * covF + colI * covI + bg * (1.0 - cov);
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The incoming image loads over the outgoing one like an interlaced picture on a slow connection: a first pass sweeps down drawing it in big blocky rows, then each new pass sweeps down again at twice the detail until the picture is sharp
// Tags: wipe, retro, pixelate, blocks, scanlines, vertical
// Preview: 0.2

// @range(24, 480) Number of rows of pixels of the picture being loaded, before its last pass draws it at full detail
uniform float rows; // = 120.0
// @range(2, 6, 1) Number of passes, the first one drawing blocks 2^(passes - 1) rows tall
uniform int passes; // = 5
// @range(0, 1) Brightness of the freshly drawn rows behind each sweep
uniform float glow; // = 0.5

vec4 transition(vec2 uv) {
  float lines = max(floor(rows), 1.0);
  float cols = max(floor(lines * ratio + 0.5), 1.0);
  // no more passes than fit: the first pass's blocks are never taller than the picture
  float n = max(min(clamp(float(passes), 2.0, 6.0), 1.0 + floor(log2(lines) + 0.01)), 2.0);
  float row = min(floor((1.0 - uv.y) * lines), lines - 1.0);
  float col = min(floor(uv.x * cols), cols - 1.0);

  float p = mix(progress, progress * progress * (3.0 - 2.0 * progress), 0.5);
  // each pass sweeps the whole frame in time T; the passes start one after another and overlap a little
  float T = 1.5 / (n + 0.5);

  // the finest pass that has drawn this pixel wins: try them from the finest (blocks 1 row tall) up
  float bestB = 0.0;
  float light = 0.0;
  for (int i = 0; i < 6; i++) {
    float k = n - 1.0 - float(i); // order of this pass, from 0 for the first one
    if (k < 0.0) break;
    float b = floor(exp2(float(i)) + 0.5); // block size of this pass, in pixel rows
    float u = clamp((p - (1.0 - T) * k / (n - 1.0)) / T, 0.0, 1.0);
    // the sweep, in block rows; the row it is on fills from left to right block by block.
    // Freshly drawn rows are brighter over a few rows behind it: the sweep runs on past the
    // bottom of the frame until that glow is gone, so the pass is over before its time ends
    float glowRows = max(1.5 * b, 0.05 * lines);
    float blockRows = ceil(lines / b);
    float sweep = u * (blockRows + glowRows / b);
    float behind = sweep - floor(row / b) - (floor(col / b) + 1.0) / ceil(cols / b);
    if (behind >= -1e-4) {
      bestB = b;
      light = 1.0 - smoothstep(0.0, glowRows, behind * b);
      break;
    }
  }

  if (bestB == 0.0) return getFromColor(uv);
  vec4 c;
  if (bestB <= 1.0) {
    c = getToColor(uv);
  } else {
    float top = floor(row / bestB) * bestB;
    float left = floor(col / bestB) * bestB;
    c = getToColor(vec2((left + 0.5) / cols, 1.0 - (top + 0.5) / lines));
  }
  c.rgb += 0.5 * glow * light * (1.0 - c.rgb);
  return c;
}

