// Description: The outgoing picture turns into a cloth of upright threads, which dive one by one, in a satin order, under crosswise threads dyed as the incoming picture; then the weave flattens into it
// Tags: fabric, weave, threads, textile, 3d
// Preview: 0.5

// @range(24, 120) Number of threads across the frame's diagonal
uniform float threads; // = 60.0
// @range(0, 1) Sheen of the threads
uniform float sheen; // = 0.5

float hash(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + 1.0), f.x), f.y);
}

// 1 where the upright thread lies on top, -1 where it has gone under
float over(vec2 c, float flip) {
  float satin = mod(c.x * 2.0 + c.y, 5.0) / 4.0;
  float when = 0.6 * satin + 0.4 * noise(c / 9.0 + 50.0);
  return 1.0 - 2.0 * smoothstep(when - 0.09, when + 0.09, flip);
}

vec4 pm(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 cloth(vec2 v, vec2 grid, float flip, float relief) {
  vec2 g = (v - 0.5) * grid;
  vec2 c = floor(g);
  vec2 l = g - c - 0.5;
  vec2 s = vec2(l.x < 0.0 ? -1.0 : 1.0, l.y < 0.0 ? -1.0 : 1.0);
  float o = over(c, flip);
  float oy = over(c + vec2(0.0, s.y), flip);
  float ox = over(c + vec2(s.x, 0.0), flip);
  float ky = smoothstep(0.1, 0.9, abs(l.y));
  float kx = smoothstep(0.1, 0.9, abs(l.x));
  float ra = sqrt(max(1.0 - l.x * l.x * 4.2, 0.0));
  float rb = sqrt(max(1.0 - l.y * l.y * 4.2, 0.0));
  float za = mix(o, oy, ky) + ra * 0.9;
  float zb = -mix(o, ox, kx) + rb * 0.9;
  float top = smoothstep(-0.15, 0.15, za - zb);
  vec3 na = normalize(vec3(l.x * 2.0, -(oy - o) * s.y * 0.5, 0.35 + ra));
  vec3 nb = normalize(vec3((ox - o) * s.x * 0.5, l.y * 2.0, 0.35 + rb));
  vec3 n = normalize(mix(nb, na, top));
  // a thread is dyed along its length, with one color across
  vec2 mid = (c + 0.5) / grid + 0.5;
  vec4 a = pm(getFromColor(vec2(mix(v.x, mid.x, 0.85 * relief), v.y)));
  vec4 b = pm(getToColor(vec2(v.x, mix(v.y, mid.y, 0.85 * relief))));
  float twist = mix(sin((l.x + c.x + l.y * 1.6) * 12.566), sin((l.y + c.y + l.x * 1.6) * 12.566), top);
  vec4 col = mix(b, a, top);
  vec3 lamp = normalize(vec3(-0.4, 0.6, 0.8));
  float lit = 0.55 + 0.6 * max(dot(n, lamp), 0.0);
  lit *= clamp(max(za, zb) * 0.5 + 0.6, 0.5, 1.05);
  lit *= 1.0 - 0.28 * (1.0 - smoothstep(0.0, 0.6, abs(za - zb)));
  float spec = pow(max(dot(reflect(vec3(0.0, 0.0, -1.0), n), lamp), 0.0), 8.0);
  vec3 shaded = col.rgb * lit * (1.0 + 0.07 * twist) * 1.12 + sheen * 0.35 * spec * (0.3 * col.a + col.rgb);
  // without depth the crossings alone give the plain pictures at both ends
  vec4 plain = mix(b, a, 0.5 + 0.5 * o);
  float tex = smoothstep(0.0, 1.0, relief);
  return vec4(mix(plain.rgb, shaded, tex), mix(plain.a, col.a, tex));
}

vec4 transition(vec2 uv) {
  float p = progress;
  float relief = smoothstep(0.0, 0.26, p) * (1.0 - smoothstep(0.74, 1.0, p));
  float e = clamp((p - 0.1) / 0.8, 0.0, 1.0);
  float flip = mix(-0.1, 1.1, mix(e, e * e * (3.0 - 2.0 * e), 0.5));
  vec2 asp = vec2(ratio, 1.0);
  vec2 grid = max(floor(threads * asp / length(asp)), 2.0);
  vec4 sum = vec4(0.0);
  // four samples, for the fine ribs
  for (int i = 0; i < 4; i++) {
    vec2 j = vec2(mod(float(i), 2.0), floor(float(i) * 0.5 + 0.01)) - 0.5;
    j = vec2(j.x * 0.8 - j.y * 0.4, j.x * 0.4 + j.y * 0.8) * 0.0016 * relief / asp;
    sum += 0.25 * cloth(uv + j, grid, flip, relief);
  }
  return sum.a > 0.0 ? vec4(min(sum.rgb / sum.a, 1.0), sum.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: Winds blow in opposite directions along rows of the outgoing picture, drawing it into the bands, curls and oval storm of a giant planet; the bands take the colors of the incoming picture strand by strand, and the same winds carry it into place
// Tags: liquid, wind, planet, swirl, distort

// @param Number of bands of wind
// @range(2, 10)
uniform float bands; // = 5.0
// @param How far the winds blow
// @range(0.2, 1.5)
uniform float wind; // = 1.0
// @param Strength of the oval storm
// @range(0, 1.5)
uniform float storm; // = 1.0

const int STEPS = 13;
const vec2 EYE = vec2(0.14, -0.13);
const vec2 OVAL = vec2(0.2, 0.105);

float hash(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + 1.0), f.x), f.y);
}

vec2 mirrored(vec2 u) {
  return 1.0 - abs(1.0 - mod(u, 2.0));
}

vec4 pm(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

// analytic curl of a stream function: jets, rows of eddies, ripples, one oval storm
vec2 flow(vec2 q) {
  float k = 3.14159265 * bands;
  float sk = sin(k * q.y), ck = cos(k * q.y);
  float h = 2.0 * bands * q.y;
  float ph = 13.0 * q.x + 1.3 * sin(h);
  float sp = 0.009 * sin(ph), cp = 0.009 * cos(ph);
  float f = (0.62 / k + sp) * ck;
  vec2 g = vec2(13.0 * cp * ck, 2.6 * bands * cos(h) * cp * ck - (0.62 + k * sp) * sk);
  vec2 m = 0.00175 * sin(vec2(26.0 * q.x - 29.0 * q.y, 20.0 * q.x + 33.0 * q.y) + 0.7);
  g += vec2(20.0 * m.y - 26.0 * m.x, 29.0 * m.x + 33.0 * m.y);
  vec2 s = (q - EYE) / OVAL;
  float u = exp(-0.35 * dot(s, s));
  float w = u * u * min(storm, 1.0);
  g = g * (1.0 - w) + (f * 0.7 * w - 0.1 * storm * u * u * u) * 2.0 * s / OVAL;
  return vec2(g.y, -g.x);
}

vec2 carry(vec2 q, float t) {
  float dt = t / float(STEPS);
  // midpoint steps, each guessing its midpoint from the step before
  vec2 v = flow(q);
  for (int i = 0; i < STEPS; i++) {
    v = flow(q + 0.5 * dt * v);
    q += dt * v;
  }
  return q;
}

vec4 transition(vec2 uv) {
  float t = mix(progress, smoothstep(0.0, 1.0, progress), 0.8);
  float span = 2.6 * wind;
  vec2 asp = vec2(ratio, 1.0);
  vec2 x = (uv - 0.5) * asp;
  vec2 qa = carry(x, -span * t);
  vec2 qb = carry(x, span * (1.0 - t));
  float calm = 4.0 * progress * (1.0 - progress);
  // along the winds, against filaments thinner than a pixel
  float smear = 0.045 * calm * calm;
  vec4 a = vec4(0.0), b = vec4(0.0);
  for (int j = -4; j <= 4; j++) {
    vec2 o = vec2(float(j) * smear * 0.25, 0.0);
    a += pm(getFromColor(mirrored((qa + o) / asp + 0.5)));
    b += pm(getToColor(mirrored((qb + o) / asp + 0.5)));
