// Description: A keyhole grows steadily from the center until the incoming image fills the frame, its bevelled rim and inner shadow making it read as a hole cut in a plate
// Tags: shape, wipe, keyhole, iris, reveal

// @param Center of the keyhole
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(0, 1) Strength of the bevelled rim around the keyhole and the shadow inside it (0 for a clean cut)
uniform float rim; // = 0.6
// @range(0, 0.05) Softness of the keyhole's edge
uniform float smoothness; // = 0.002

// The keyhole, in its own units (0.85 tall, from y = -0.4 to 0.45): a round head on top of a slot
// that widens downward.
#define HEAD vec2(0.0, 0.2)
#define HEAD_R 0.25
#define SLOT_Y -0.17
const float SLOT_HE = 0.23;
const float SLOT_TOP = 0.085;
const float SLOT_BOTTOM = 0.165;
const float SLOT_ROUND = 0.025;
// height of the point the keyhole grows around, in its head
const float GROW_Y = 0.1;
const float BEVEL = 0.028;
const float SHADE = 0.05;

float dot2(vec2 v) { return dot(v, v); }

float sdSlot(vec2 p) {
  p.y -= SLOT_Y;
  float r1 = SLOT_BOTTOM - SLOT_ROUND;
  float r2 = SLOT_TOP - SLOT_ROUND;
  float he = SLOT_HE - SLOT_ROUND;
  vec2 k1 = vec2(r2, he);
  vec2 k2 = vec2(r2 - r1, 2.0 * he);
  p.x = abs(p.x);
  vec2 ca = vec2(p.x - min(p.x, p.y < 0.0 ? r1 : r2), abs(p.y) - he);
  vec2 cb = p - k1 + k2 * clamp(dot(k1 - p, k2) / dot2(k2), 0.0, 1.0);
  float s = (cb.x < 0.0 && ca.y < 0.0) ? -1.0 : 1.0;
  return s * sqrt(min(dot2(ca), dot2(cb))) - SLOT_ROUND;
}

float sdKeyhole(vec2 p) {
  return min(length(p - HEAD) - HEAD_R, sdSlot(p));
}

// Scale at which the keyhole's head, a disk, reaches the point p (seen from the growth point):
// the root of |p - s h| = s HEAD_R, h being the head's center
float reach(vec2 p) {
  vec2 h = HEAD - vec2(0.0, GROW_Y);
  float k = HEAD_R * HEAD_R - dot2(h);
  float b = dot(p, h);
  return (sqrt(b * b + k * dot2(p)) - b) / k;
}

vec4 transition (vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  vec2 asp = vec2(ratio, 1.0);
  vec2 c = center * asp;
  float sm = max(smoothness, 0.0005);

  // The keyhole grows around a point of its head, at the center. It covers the frame (grown by a
  // margin, so the soft edge is past it) once its head, a disk, reaches the frame's corners.
  vec2 o = c;
  vec2 lo = -o - 2.5 * sm;
  vec2 hi = asp - o + 2.5 * sm;
  float full = max(max(reach(lo), reach(hi)), max(reach(vec2(lo.x, hi.y)), reach(vec2(hi.x, lo.y))));

  float p = progress;
  float s = full * p;
  if (s <= 0.0) return a;

  vec2 q = (uv * asp - o) / s + vec2(0.0, GROW_Y);
  float d = sdKeyhole(q);
  // the soft edge is just inside the outline, so a tiny keyhole shows nothing
  float hole = 1.0 - smoothstep(-sm, sm, d * s + sm);

  float fade = smoothstep(0.0, 0.08, p) * (1.0 - smoothstep(0.7, 1.0, p));
  float rimA = rim * fade;
  if (rimA > 0.0) {
    vec2 e = vec2(0.002, 0.0);
    vec2 n = vec2(sdKeyhole(q + e) - sdKeyhole(q - e), sdKeyhole(q + e.yx) - sdKeyhole(q - e.yx));
    float lit = -dot(n / max(length(n), 1e-6), vec2(-0.35, 0.94));
    float bevel = 1.0 - smoothstep(0.0, BEVEL, d);
    float shade = exp(-max(d, 0.0) / SHADE);
    a.rgb *= 1.0 - rimA * (0.35 * shade + bevel * 0.4 * max(-lit, 0.0));
    a.rgb += rimA * bevel * bevel * 0.3 * max(lit, 0.0) * a.a;

    float wall = smoothstep(-0.03, 0.03, sdKeyhole(q + vec2(0.0, 0.05)));
    float vign = exp(min(d, 0.0) / SHADE);
    b.rgb *= 1.0 - rimA * (0.5 * wall + 0.3 * vign);
  }

  return mix(a, b, hole);
}

// Author: gre
// License: MIT
// Description: The change lands on two beats: the first punch swaps only the light and color masses, so the outgoing picture's details stand drawn over the incoming one's blurred colors; the second snaps the details over too
// Tags: rhythm, beat, punch, blur, zoom
// Preview: 0.45

// @param How far each beat punches in
// @range(0, 0.4)
uniform float punch; // = 0.16
// @param Size of the blur that separates the masses from the details, in frame heights
// @range(0.02, 0.12)
uniform float spread; // = 0.07

const int TAPS = 14;

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 pm(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

float beat(float t) {
  return t < 0.0 ? 0.0 : t * 22.2 * exp(1.0 - t * 22.0);
}

vec4 transition(vec2 uv) {
  vec2 p = uv - 0.5;
  float low = smoothstep(0.2, 0.28, progress);
  float high = smoothstep(0.6, 0.68, progress);
  float kick = beat(progress - 0.2), snare = beat(progress - 0.6) * (1.0 - smoothstep(0.8, 1.0, progress));
  float split = smoothstep(0.02, 0.24, progress) * (1.0 - smoothstep(0.6, 0.95, progress));
  vec2 pl = p * (1.0 - punch * kick) + 0.5;
  vec2 ph = p * (1.0 - 0.1 * split - punch * snare) + 0.5;
  vec2 r = spread * split / vec2(ratio, 1.0);
  float jit = fract(52.9829189 * fract(dot(floor(uv * vec2(ratio, 1.0) * 1080.0 + 0.283), vec2(0.06711056, 0.00583715))));
  float gain = 1.0 + 0.6 * split;
  vec4 base = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    float f = float(i);
    float a = f * 2.4 + 0.9 * jit;
    vec2 d = sqrt((f + jit) / float(TAPS)) * vec2(cos(a), sin(a)) * r;
    // during a swap the taps pass to the incoming picture one by one
    float turn = mod(f * 5.0, float(TAPS));
    float l = clamp(low * float(TAPS) - turn, 0.0, 1.0);
    float h = clamp(high * float(TAPS) - turn, 0.0, 1.0) * gain;
    if (l < 1.0) base += (1.0 - l) * pm(getFromColor(mirror(pl + d)));
    if (l > 0.0) base += l * pm(getToColor(mirror(pl + d)));
    if (h < gain) base -= (gain - h) * pm(getFromColor(mirror(ph + d)));
    if (h > 0.0) base -= h * pm(getToColor(mirror(ph + d)));
  }
  base /= float(TAPS);
  base += gain * mix(pm(getFromColor(mirror(ph))), pm(getToColor(mirror(ph))), high);
  base.rgb *= 1.0 + 0.3 * (kick + snare);
  base = clamp(base, 0.0, 1.0);
  return base.a > 0.0 ? vec4(min(base.rgb / base.a, 1.0), base.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing picture pinches by its corners into a diamond kite with a taped hem and a ribbon tail of bows; it catches the wind, tugs on its string and swoops from side to side as it climbs away, fluttering and shrinking, into the sky of the incoming picture
// Tags: kite, fly, object, 3d, playful

// @range(0, 1) How hard the wind shakes the sail and the tail
uniform float flutter; // = 0.6
// @range(0, 1) Strength of the shading on the sail
uniform float shading; // = 0.6
// @color Ribbon tail, bows and hem tape
uniform vec4 ribbon; // = vec4(0.85, 0.25, 0.15, 1.0)
// @color Flying line
uniform vec4 lineColor; // = vec4(0.15, 0.15, 0.15, 0.8)

const float PI = 3.14159265;

vec2 rot(vec2 v, float a) {
  float c = cos(a), s = sin(a);
  return vec2(c * v.x - s * v.y, s * v.x + c * v.y);
}

float cross2(vec2 a, vec2 b) { return a.x * b.y - a.y * b.x; }

float segDist(vec2 q, vec2 a, vec2 b) {
  vec2 ab = b - a;
  float h = clamp(dot(q - a, ab) / dot(ab, ab), 0.0, 1.0);
  return length(q - a - ab * h);
}

vec2 kiteVertex(vec2 k, float tilt, float roll, vec2 c, float s, vec2 wob) {
  k += wob;
  // pitch back around the cross spar: the top recedes, the bottom comes closer
  vec3 k3 = vec3(k.x, k.y * cos(tilt), k.y * sin(tilt));
  return c + rot(s * k3.xy / (1.0 + 0.7 * k3.z), roll);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 q = (uv - 0.5) * asp;
  float pin = smoothstep(0.0, 0.26, p);
  // ends at speed: the kite must still be leaving the frame on the last frames
  float u = clamp((p - 0.16) / 0.84, 0.0, 1.0);
  float t = u * u * (1.7 - 0.7 * u);
  float env = pin * (1.0 - t * 0.5);

  vec2 c = vec2(0.28 * ratio * sin(2.0 * PI * 1.1 * t) * (1.0 - 0.4 * t), 0.12 * pin + 0.3 * t + 0.42 * t * t * t);
  float s = 0.72 * min(1.0, 1.1 * ratio) * mix(1.0, 0.1, t);
  float roll = 0.5 * sin(2.0 * PI * 1.25 * t + 0.6) * pin * (1.0 - 0.5 * t);
  float tilt = 0.55 * pin + 0.2 * sin(2.0 * PI * 2.5 * t);
  float w = 0.025 * flutter * pin;
  float ph = 34.0 * p;

  vec2 hr = 0.5 * asp;
  vec2 p0 = mix(vec2(-hr.x, -hr.y), kiteVertex(vec2(-0.4, 0.1), tilt, roll, c, s, w * vec2(sin(ph), cos(ph * 1.3))), pin);
  vec2 p1 = mix(vec2(hr.x, -hr.y), kiteVertex(vec2(0.0, -0.62), tilt, roll, c, s, w * vec2(sin(ph * 1.7 + 1.0), 0.0)), pin);
  vec2 p2 = mix(vec2(hr.x, hr.y), kiteVertex(vec2(0.4, 0.1), tilt, roll, c, s, w * vec2(sin(ph + 2.0), cos(ph * 1.1 + 2.0))), pin);
  vec2 p3 = mix(vec2(-hr.x, hr.y), kiteVertex(vec2(0.0, 0.44), tilt, roll, c, s, w * vec2(0.0, sin(ph * 0.9 + 3.0))), pin);

  // square -> quad homography, then its adjugate to go back from the screen
  float dx1 = p1.x - p2.x, dx2 = p3.x - p2.x, dx3 = p0.x - p1.x + p2.x - p3.x;
  float dy1 = p1.y - p2.y, dy2 = p3.y - p2.y, dy3 = p0.y - p1.y + p2.y - p3.y;
  float den = dx1 * dy2 - dx2 * dy1;
  float g = (dx3 * dy2 - dx2 * dy3) / den;
  float h = (dx1 * dy3 - dx3 * dy1) / den;
  float a = p1.x - p0.x + g * p1.x, b = p3.x - p0.x + h * p3.x;
  float d = p1.y - p0.y + g * p1.y, e = p3.y - p0.y + h * p3.y;
  float cx = p0.x, fy = p0.y;
  vec3 r0 = vec3(e - fy * h, cx * h - b, b * fy - cx * e);
  vec3 r1 = vec3(fy * g - d, a - cx * g, cx * d - a * fy);
  vec3 r2 = vec3(d * h - e * g, b * g - a * h, a * e - b * d);
  vec3 Q = vec3(q, 1.0);
  // dot(r2, Q) is positive all over the sail: kept off 0 past the vanishing line
  vec2 k = clamp(vec2(dot(r0, Q), dot(r1, Q)) / max(dot(r2, Q), 1e-4), -1.0, 2.0);

  float sd = min(min(cross2(p1 - p0, q - p0) / length(p1 - p0), cross2(p2 - p1, q - p1) / length(p2 - p1)),
                 min(cross2(p3 - p2, q - p2) / length(p3 - p2), cross2(p0 - p3, q - p3) / length(p0 - p3)));
  float cov = clamp(0.5 + sd / (0.0025 * pin + 1e-5), 0.0, 1.0);

  vec4 bg = getToColor(0.5 + (uv - 0.5) / (1.0 + 0.08 * (1.0 - p)));
  bg.rgb *= bg.a;

  float den2 = cross2(p2 - p0, p3 - p1);
  vec2 hub = p0 + (p2 - p0) * cross2(p1 - p0, p3 - p1) / den2;
  vec2 anchor = vec2(-0.3 * ratio, -0.9);
  float str = (1.0 - smoothstep(0.0025 * s + 0.0006, 0.0025 * s + 0.002, segDist(q, hub, anchor)))
            * smoothstep(0.15, 0.35, p) * (1.0 - smoothstep(0.5, 0.66, c.y));
  bg = mix(bg, vec4(lineColor.rgb, 1.0), str * lineColor.a);

  vec2 dn = normalize(p1 - hub + vec2(0.0, -0.4 * length(p1 - hub)));
  vec2 pr = vec2(-dn.y, dn.x);
  float L = 0.95 * s;
  vec2 tq = q - p1;
  float al = dot(tq, dn) / L;
  float wav = (0.08 * s) * sin(10.0 * al - 22.0 * p - 1.0) * al * (0.12 + 1.2 * flutter);
  float slope = (0.8 * s / L) * cos(10.0 * al - 22.0 * p - 1.0) * al * (0.12 + 1.2 * flutter);
  float ac = (dot(tq, pr) - wav) / sqrt(1.0 + slope * slope);
  float tail = (1.0 - smoothstep(0.004 * s, 0.004 * s + 0.0015, abs(ac))) * step(0.0, al) * (1.0 - smoothstep(0.97, 1.0, al));
  float bw = 0.055 * s;
  float bows = 0.0, fold = 0.0;
  for (int i = 0; i < 5; i++) {
    float bt = 0.2 + 0.18 * float(i);
    float ba = (al - bt) * L;
    float m = (1.0 - smoothstep(bw - 0.0015, bw, abs(ac))) * (1.0 - smoothstep(0.0, 0.0015, abs(ba) - 0.35 * bw * (0.25 + abs(ac) / bw)));
    fold = mix(fold, ac / bw, m);
    bows = max(bows, m);
  }
  tail = max(tail, bows) * pin * ribbon.a;
  bg = mix(bg, vec4(ribbon.rgb * (1.0 + 0.2 * bows * fold), 1.0), tail);

  vec4 col = getFromColor(clamp(k, 0.0, 1.0));
  float d1 = abs(k.x - k.y), d2 = abs(k.x + k.y - 1.0);
  float panel = sign(k.x - k.y) * 0.6 + sign(k.x + k.y - 1.0) * 0.4;
  float sh = 1.0 + shading * env * (0.13 * panel * cos(roll * 3.0 + tilt) - 0.4 * (1.0 - smoothstep(0.004, 0.01 + 0.002 / s, min(d1, d2))));
  float rim = min(min(k.x, 1.0 - k.x), min(k.y, 1.0 - k.y));
  // fabric billows between the spars and the taped hem
  float bulge = smoothstep(0.0, 0.18, min(min(d1, d2), rim));
  sh += shading * env * 0.1 * (bulge - 0.6);
  col.rgb *= sh;
  float hem = (1.0 - smoothstep(0.012, 0.018, rim)) * env;
  col.rgb = mix(col.rgb, ribbon.rgb * (0.85 + 0.15 * panel), 0.85 * hem * ribbon.a);
  vec4 o = mix(bg, vec4(col.rgb * col.a, col.a), cov);
  return o.a > 0.0 ? vec4(o.rgb / o.a, o.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image is kneaded like dough: its two halves squeeze and slide past each other into two rows, again and again, until the picture is drawn out into thin layers; the layers of the incoming image are pressed in between them, then the incoming image is unkneaded back into one picture
// Tags: knead, fold, stack, stretch, stripes, rhythm, shadow

// @range(1, 5, 1) Number of kneads on each side (each one stacks the picture into twice as many layers)
uniform int kneads; // = 3
// @range(0, 1) Depth of the shading on the layers and of the shadow the sliding half casts
uniform float shadow; // = 0.5
// @color Color seen in the corners the halves uncover while they slide
uniform vec4 backColor; // = vec4(0.1, 0.1, 0.1, 1.0)

vec4 img(vec2 q, bool incoming) {
  return incoming ? getToColor(q) : getFromColor(q);
}

// undoes n complete kneads: the bottom row came from the left half, the top row from the right half
vec2 unknead(vec2 q, int n) {
  for (int i = 0; i < 5; i++) {
    if (i >= n) break;
    q = q.y < 0.5 ? vec2(0.5 * q.x, 2.0 * q.y) : vec2(0.5 + 0.5 * q.x, 2.0 * q.y - 1.0);
  }
  return q;
}

// unknead of (row + t) / 2^n, with the row taken from its bits so t = 1 stays in that row
vec2 unkneadRow(float x, float row, float t, int n) {
  float h = exp2(float(n));
  for (int i = 0; i < 5; i++) {
    if (i >= n) break;
    h *= 0.5;
    float hi = step(h, row);
    row -= hi * h;
    x = 0.5 * x + 0.5 * hi;
  }
  return vec2(x, t);
}

float box(vec2 p, vec2 lo, vec2 hi, vec2 soft) {
  vec2 d = min(p - lo, hi - p) / soft;
  return clamp(min(d.x, d.y), 0.0, 1.0);
}

// rounded layer lit from above; equal at t = 0 and 1 so stacked layers meet without a seam
float layerShade(float t, float amount) {
  float c = 2.0 * t - 1.0;
  float c2 = c * c;
  return 1.0 + amount * (0.25 * c * (1.0 - c2) - 0.55 * c2 * c2);
}

float creases(float y, float rows, float amount) {
  return layerShade(fract(y * rows), amount);
}

// n complete kneads, then the next one at stage s; g fades the layer shading in and out over the transition
vec4 kneaded(vec2 uv, int n, float s, bool incoming, float g) {
  float env = 4.0 * s * (1.0 - s);
  float rows = exp2(float(n));
  float amount = shadow * g;
  // widening leads squashing so the corners they uncover stay small
  vec2 st = vec2(smoothstep(0.0, 0.75, s), smoothstep(0.25, 1.0, s));
  // edges soften only once the halves overlap, so no gap line shows where they meet
  vec2 soft = vec2(0.004 / ratio, 0.004) * smoothstep(0.0, 0.3, st.x) * smoothstep(0.0, 0.3, 1.0 - st.y) + 1e-6;
  vec2 hiL = vec2(0.5 + 0.5 * st.x, 1.0 - 0.5 * st.y);
  vec2 loR = vec2(0.5 - 0.5 * st.x, 0.5 * st.y);
  vec2 l = uv / hiL;
  vec2 r = (uv - loR) / (1.0 - loR);
  vec2 xs = vec2(0.1 / ratio, 0.1);
  // shading waits for the halves to separate so no seam shows at the cut
  float lift = env * smoothstep(0.0, 0.3, st.x);

  vec4 bottom = img(unknead(vec2(0.5 * l.x, l.y), n), incoming);
  bottom.rgb *= creases(l.y, rows, amount) * (1.0 - 0.7 * shadow * lift * (1.0 - smoothstep(0.0, xs.x, hiL.x - uv.x)));
  vec4 c = mix(backColor, bottom, box(uv, vec2(-1.0), hiL + soft, soft));

  vec2 off = vec2(0.02 / ratio, -0.03) * lift;
  float sh = 1.0 - smoothstep(0.0, 0.05, -min(ratio * min(uv.x - off.x - loR.x, 1.0 - uv.x + off.x), min(uv.y - off.y - loR.y, 1.0 - uv.y + off.y)));
  c.rgb *= 1.0 - shadow * 0.6 * lift * sh;

  vec4 top = img(unknead(vec2(0.5 + 0.5 * r.x, r.y), n), incoming);
  top.rgb *= creases(r.y, rows, amount) * (1.0 + 0.08 * lift) * (1.0 - 0.7 * shadow * lift * (1.0 - smoothstep(0.0, xs.x, uv.x - loR.x)));
  return mix(c, top, box(uv, loR, vec2(2.0), soft));
}

// incoming layers pressed in under each outgoing one, from alternate sides, until they fill the rows
vec4 interleave(vec2 uv, int n, float w, float g) {
  float rows = exp2(float(n));
  float amount = shadow * g;
  float y = uv.y * rows;
  float row = floor(y);
  float t = y - row;
  float side = mod(row, 2.0) < 1.0 ? uv.x : 1.0 - uv.x;
  float f = smoothstep(0.0, 1.0, clamp(1.7 * w - 0.7 * side, 0.0, 1.0));
  float tIn = clamp(t / max(f, 1e-4), 0.0, 1.0);
  float tOut = clamp((t - f) / max(1.0 - f, 1e-4), 0.0, 1.0);
  vec4 a = getToColor(unkneadRow(uv.x, row, tIn, n));
  vec4 b = getFromColor(unkneadRow(uv.x, row, tOut, n));
  a.rgb *= layerShade(tIn, amount);
  b.rgb *= layerShade(tOut, amount);
  // squeezed layers get darker toward their tip, as they thin out
  a.rgb *= 1.0 - 0.4 * shadow * (1.0 - smoothstep(0.0, 0.5, f));
  b.rgb *= 1.0 - 0.4 * shadow * (1.0 - smoothstep(0.0, 0.5, 1.0 - f));
  // the shift keeps row boundaries on the full layer when the other one is empty
  float edge = 0.0015 * min(1.0, 8.0 * f * (1.0 - f)) + 1e-6;
  return mix(a, b, smoothstep(-edge, edge, (t - f) / rows + edge * (1.0 - 2.0 * f)));
}

vec4 transition(vec2 uv) {
  int kn = int(clamp(float(kneads), 1.0, 5.0));
  float n = float(kn);
  const float SWAP = 1.2;
  float g = smoothstep(0.0, 0.12, progress) * smoothstep(0.0, 0.12, 1.0 - progress);
  float u = progress * (2.0 * n + SWAP);
  if (u < n) {
    float k = floor(u);
    return kneaded(uv, int(k), smoothstep(0.0, 1.0, u - k), false, g);
  }
  float v = 2.0 * n + SWAP - u;
  if (v < n) {
    float k = floor(v);
    return kneaded(uv, int(k), smoothstep(0.0, 1.0, v - k), true, g);
  }
  return interleave(uv, kn, (u - n) / SWAP, g);
}

// Author: gre
// License: MIT
// Description: The frame splits into an asymmetric magazine grid as paper gutters open between the panels; panel after panel in reading order, the incoming image pushes the outgoing one out of its panel from a different side, a colored accent band between them, then the gutters close over the full incoming image
// Tags: grid, panels, magazine, push, slide, layout

// @range(0, 0.08) Width of the gutters at their widest, as a part of the frame's shorter side
uniform float gutter; // = 0.04
// @range(0, 0.9) How much the panels' pushes overlap in time (0 pushes them one strictly after another, 0.9 almost all together)
uniform float overlap; // = 0.55
// @range(0, 0.6) Length of the accent band between the two images, as a part of the panel's length along its push
uniform float band; // = 0.22
// @range(0, 1) Darkness of the soft shadows the panels cast on the paper and the incoming image casts on the band
uniform float shadow; // = 0.4
// @color Color of the paper seen in the gutters
uniform vec4 paper; // = vec4(0.96, 0.95, 0.91, 1.0)
// @color Color of the accent band between the outgoing and incoming images
uniform vec4 accent; // = vec4(0.93, 0.27, 0.2, 1.0)

const int PANELS = 6;
// the gutters open over [0, OPEN] and close over [1 - OPEN, 1]
const float OPEN = 0.28;
// the first push starts at START, the last one ends at 1 - START
const float START = 0.1;
const float EDGE = 0.0025;

// panel i of the layout: xy its bottom-left corner, zw its top-right corner, in uv; panels in reading order
vec4 panelRect(int i, bool portrait) {
  if (portrait) {
    if (i == 0) return vec4(0.0, 0.68, 0.62, 1.0);
    if (i == 1) return vec4(0.62, 0.68, 1.0, 1.0);
    if (i == 2) return vec4(0.0, 0.36, 1.0, 0.68);
    if (i == 3) return vec4(0.0, 0.0, 0.46, 0.36);
    if (i == 4) return vec4(0.46, 0.17, 1.0, 0.36);
    return vec4(0.46, 0.0, 1.0, 0.17);
  }
  if (i == 0) return vec4(0.0, 0.42, 0.4, 1.0);
  if (i == 1) return vec4(0.4, 0.64, 1.0, 1.0);
  if (i == 2) return vec4(0.4, 0.0, 0.7, 0.64);
  if (i == 3) return vec4(0.7, 0.32, 1.0, 0.64);
  if (i == 4) return vec4(0.7, 0.0, 1.0, 0.32);
  return vec4(0.0, 0.0, 0.4, 0.42);
}

// direction the outgoing image of panel i is pushed toward (the incoming one enters from the opposite side)
vec2 panelDir(int i, bool portrait) {
  if (portrait) {
    if (i == 0) return vec2(1.0, 0.0);
    if (i == 1) return vec2(0.0, -1.0);
    if (i == 2) return vec2(-1.0, 0.0);
    if (i == 3) return vec2(0.0, 1.0);
    if (i == 4) return vec2(1.0, 0.0);
    return vec2(-1.0, 0.0);
  }
  if (i == 0) return vec2(0.0, -1.0);
  if (i == 1) return vec2(-1.0, 0.0);
  if (i == 2) return vec2(0.0, 1.0);
  if (i == 3) return vec2(1.0, 0.0);
  if (i == 4) return vec2(-1.0, 0.0);
  return vec2(1.0, 0.0);
}

float easeInOut(float t) {
  return t < 0.5 ? 4.0 * t * t * t : 1.0 - 4.0 * (1.0 - t) * (1.0 - t) * (1.0 - t);
}

// coverage of the interval [lo, hi] at x, with antialiased ends: the coverages of adjacent intervals add up to 1
float span1(float x, float lo, float hi, float aa) {
  return smoothstep(lo - aa, lo + aa, x) * (1.0 - smoothstep(hi - aa, hi + aa, x));
}

float boxDist(vec2 p, vec2 lo, vec2 hi) {
  vec2 d = abs(p - 0.5 * (lo + hi)) - 0.5 * (hi - lo);
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

vec4 transition(vec2 uv) {
  bool portrait = ratio < 1.0;
  vec2 aspect = vec2(ratio, 1.0) / min(ratio, 1.0);
  vec2 p = uv * aspect;
  float open = smoothstep(0.0, OPEN, progress) * (1.0 - smoothstep(1.0 - OPEN, 1.0, progress));
  float g = gutter * open;
  float ov = clamp(overlap, 0.0, 0.9);
  float span = (1.0 - 2.0 * START) / (1.0 + float(PANELS - 1) * (1.0 - ov));

  vec4 color = vec4(0.0);
  float cover = 0.0;
  float shade = 0.0;
  for (int i = 0; i < PANELS; i++) {
    vec4 r = panelRect(i, portrait);
    vec2 lo = r.xy * aspect + 0.5 * g;
    vec2 hi = r.zw * aspect - 0.5 * g;
    // no gutter along the frame's border: the panels there run past it
    lo = mix(lo, vec2(-1.0), step(r.xy, vec2(0.0)));
    hi = mix(hi, aspect + 1.0, step(vec2(1.0), r.zw));
    float t = clamp((progress - START - float(i) * span * (1.0 - ov)) / span, 0.0, 1.0);
    float lift = 1.0 + 1.2 * sin(3.141592653589793 * t);
    float sd = boxDist(p - vec2(0.2, -0.35) * g * lift, lo, hi);
    shade = max(shade, (1.0 - smoothstep(-0.2 * g, 0.6 * g * lift + 1e-4, sd)) / sqrt(lift));
    // separable coverage, so that the panels of the grid add up to exactly 1 once the gutters close
    float inside = span1(p.x, lo.x, hi.x, EDGE) * span1(p.y, lo.y, hi.y, EDGE);
    if (inside > 0.0) {
      vec2 dir = panelDir(i, portrait);
      vec4 c;
      if (t <= 0.0) {
        c = getFromColor(uv);
      } else if (t >= 1.0) {
        c = getToColor(uv);
      } else {
        float e = easeInOut(t);
        // a train slides along dir through the panel: outgoing image, accent band, incoming image
        float len = abs(dot(r.zw - r.xy, dir));
        float w = band * len;
        vec2 q = uv - dir * e * (len + w);
        // position along dir from the outgoing image's trailing edge (inside it when >= 0)
        float a = dot(q - (dir.x + dir.y < 0.0 ? r.zw : r.xy), dir);
        float af = a * abs(dot(aspect, dir));
        float wf = w * abs(dot(aspect, dir));
        float fromW = smoothstep(-EDGE, 0.0, af);
        float toW = 1.0 - smoothstep(-wf, -wf + EDGE, af);
        float bandShade = 1.0 - shadow * 0.5 * (1.0 - smoothstep(-wf, -wf + 0.35 * wf + 1e-4, af));
        vec4 b = vec4(accent.rgb * bandShade, accent.a);
        c = mix(b, getFromColor(clamp(q, r.xy, r.zw)), fromW);
        c = mix(c, getToColor(clamp(q + dir * (len + w), r.xy, r.zw)), toW);
      }
      color += c * inside;
      cover += inside;
    }
  }
  color /= max(cover, 1.0);
  cover = min(cover, 1.0);
  vec4 bg = vec4(paper.rgb * (1.0 - shadow * shade * open), paper.a);
  return color + bg * (1.0 - cover);
}

// Author: @Flexi23
// License: MIT
// Description: A leaf shape grows from the center to reveal the incoming image
// Tags: shape, wipe
// Preview: 0.5

// inspired by http://www.wolframalpha.com/input/?i=cannabis+curve

vec4 transition (vec2 uv) {
  vec2 leaf_uv = (uv - vec2(0.5))/10./max(pow(progress,3.5), 1e-6);
	leaf_uv.y += 0.35;
	float r = 0.18;
	float o = atan(leaf_uv.y, leaf_uv.x);
  return mix(getFromColor(uv), getToColor(uv), 1.-step(1. - length(leaf_uv)+r*(1.+sin(o))*(1.+0.9 * cos(8.*o))*(1.+0.1*cos(24.*o))*(0.9+0.05*cos(200.*o)), 1.));
}

// Author: gre
// License: MIT
// Description: The picture zooms into a giant LED screen of round glowing diodes on a dark panel; a refresh wave sweeps across it, each diode flicking with a bright pop as it switches to the incoming image, then the diodes melt back into the plain picture
// Tags: dots, glow, grid, wave

// @range(6, 80) Number of diodes across the shorter side
uniform float cells; // = 24.0
// @range(0, 1) Strength of the glow bleeding from the diodes into the dark panel
uniform float glow; // = 0.6
// @range(0, 1) Brightness of the flash of each diode as it switches
uniform float flash; // = 0.7
// @range(0, 0.5) How much the picture zooms in while it is a screen
uniform float zoom; // = 0.15
// @param Each diode is made of red, green and blue sub-diodes
uniform bool triads; // = false
// @param Direction in which the refresh wave sweeps across the screen
uniform vec2 direction; // = vec2(1.0, 0.0)
// @color Color of the panel between the diodes
uniform vec4 panel; // = vec4(0.02, 0.02, 0.025, 1.0)

const float RADIUS = 0.36;
const float EDGE = 0.05;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 mirrored(vec2 v) {
  vec2 m = mod(v, 2.0);
  return mix(m, 2.0 - m, step(1.0, m));
}

float disc(float d, float r) {
  return 1.0 - smoothstep(r - EDGE, r + EDGE, d);
}

vec4 transition(vec2 uv) {
  float led = smoothstep(0.0, 0.3, progress) * (1.0 - smoothstep(0.7, 1.0, progress));
  float z = 1.0 + max(zoom, 0.0) * smoothstep(0.0, 0.45, progress) * (1.0 - smoothstep(0.55, 1.0, progress));
  vec2 p = 0.5 + (uv - 0.5) / z;

  vec2 aspect = vec2(ratio, 1.0);
  vec2 toCells = aspect * max(cells, 1.0) / min(ratio, 1.0);
  vec2 q = (p - 0.5) * toCells;
  vec2 id = floor(q + 0.5);
  vec2 local = q - id;
  vec2 side = vec2(local.x < 0.0 ? -1.0 : 1.0, local.y < 0.0 ? -1.0 : 1.0);

  vec2 dir = length(direction) > 1e-4 ? normalize(direction) : vec2(1.0, 0.0);
  float extent = abs(dir.x) * ratio + abs(dir.y);

  vec4 own = vec4(0.0);
  float ownSwitch = 0.0;
  vec4 halo = vec4(0.0);
  float haloWeight = 0.0;
  // this diode and the three nearest ones, whose glow reaches this point
  for (int i = 0; i < 4; i++) {
    if (i > 0 && glow * led <= 0.0) break;
    vec2 o = vec2(mod(float(i), 2.0), floor(float(i) / 2.0)) * side;
    vec2 c = id + o;
    vec2 cuv = c / toCells + 0.5;
    // where the diode is seen in the frame, so that the wave crosses the visible screen
    float s = clamp(dot((cuv - 0.5) * z * aspect, dir) / extent + 0.5, 0.0, 1.0);
    float when = 0.2 + 0.52 * s + 0.05 * (hash12(c + 71.0) - 0.5);
    float sw = smoothstep(when - 0.012, when + 0.012, progress);
    float x = (progress - when) / 0.018;
    float pop = exp(-x * x) - 0.5 * exp(-(x + 1.6) * (x + 1.6));
    vec2 suv = mirrored(cuv);
    vec4 col = mix(getFromColor(suv), getToColor(suv), sw);
    col.rgb = col.rgb * (1.0 + 1.4 * flash * pop) + 0.2 * flash * max(pop, 0.0);
    if (i == 0) {
      own = col;
      ownSwitch = sw;
    }
    float d = length(local - o);
    float w = 0.9 * glow * exp(-6.0 * max(d - RADIUS, 0.0)) * (1.0 + 0.8 * flash * max(pop, 0.0));
    // the neighbors fade out where the next ones in the other direction take over, so the glow has no seam
    if (o.x != 0.0) w *= smoothstep(0.0, 0.2, abs(local.x));
    if (o.y != 0.0) w *= smoothstep(0.0, 0.2, abs(local.y));
    halo += w * col;
    haloWeight += w;
  }

  vec4 plain = mix(getFromColor(p), getToColor(p), ownSwitch);
  float d = length(local);
  // the diodes cover their whole cell with the plain picture when led = 0: the dark panel
  // shows up first between them, then they light up with the color of their center
  float r = mix(0.8, RADIUS, smoothstep(0.0, 0.6, led));
  vec4 gap = vec4(panel.rgb, panel.a * own.a);
  if (haloWeight > 0.0) {
    gap = mix(gap, halo / haloWeight, clamp(haloWeight * led, 0.0, 1.0));
  }
  vec4 body = own;
  if (triads) {
    vec3 sub = vec3(
      disc(length(local - vec2(0.0, 0.15)), 0.2),
      disc(length(local - vec2(-0.13, -0.075)), 0.2),
      disc(length(local - vec2(0.13, -0.075)), 0.2));
    float m = max(sub.r, max(sub.g, sub.b));
    body = vec4(gap.rgb * (1.0 - m) + own.rgb * 1.5 * sub, mix(gap.a, own.a, m));
    r = max(r, 0.45);
  } else {
    float k = clamp(d / RADIUS, 0.0, 1.0);
    body.rgb *= 0.8 + 0.45 * (1.0 - k * k);
  }
  float lit = smoothstep(0.0, 0.8, led);
  body = mix(plain, body, lit * mix(1.0, lit, smoothstep(0.0, 0.7, d)));
  vec4 color = mix(gap, body, disc(d, r));
  return clamp(color, 0.0, 1.0);
}

// Author: zhmy
// License: MIT
// Description: The outgoing image shrinks away to the left while the incoming one slides in from the right
// Tags: slide, zoom, horizontal

const vec4 black = vec4(0.0); // where no image is drawn: transparent
const vec2 boundMin = vec2(0.0, 0.0);
const vec2 boundMax = vec2(1.0, 1.0);

bool inBounds (vec2 p) {
    return all(lessThan(boundMin, p)) && all(lessThan(p, boundMax));
}

vec4 transition (vec2 uv) {
    vec2 spfr,spto = vec2(-1.);

    float size = mix(1.0, 3.0, progress*0.2);
    spto = (uv + vec2(-0.5,-0.5))*vec2(size,size)+vec2(0.5,0.5);
    spfr = (uv - vec2(1.-progress, 0.0));
    if(inBounds(spfr)){
        return getToColor(spfr);
    }else if(inBounds(spto)){
        return getFromColor(spto) * (1.0 - progress);
    } else{
        return black;
    }
}

// Author: gre
// License: MIT
// Description: A bright light sweeps across the frame and flares the lens: a long thin horizontal streak, a glowing core and a trail of colored ghost reflections; at its peak the incoming image spreads out from the light under its glare
// Tags: light, flare, glow, streak

// @range(-90, 90) Angle of the path of the light, in degrees (0 sweeps from left to right)
uniform float angle; // = -12.0
// @range(-0.5, 0.5) How far above the center of the frame the light passes
uniform float height; // = 0.18
// @range(0, 2) Brightness of the flare
uniform float intensity; // = 1.0
// @color Color of the streak and of the glare
uniform vec3 color; // = vec3(0.35, 0.6, 1.0)

const int BLOOM_TAPS = 12;
const int GHOSTS = 6;

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 premultiplied(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 frame(vec2 st, float m) {
  if (m <= 0.0) return premultiplied(getFromColor(st));
  if (m >= 1.0) return premultiplied(getToColor(st));
  return mix(premultiplied(getFromColor(st)), premultiplied(getToColor(st)), m);
}

vec3 highlight(vec4 c) {
  float lum = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
  return c.rgb * smoothstep(0.55, 0.95, lum);
}

vec4 transition(vec2 uv) {
  float p = progress;

  float env = 4.0 * p * (1.0 - p);
  float peak = pow(env, 24.0);
  vec2 aspect = vec2(ratio, 1.0);
  vec2 q = (uv - 0.5) * aspect;
  float r = radians(angle);
  vec2 dir = vec2(cos(r), -sin(r));
  vec2 normal = vec2(-dir.y, dir.x);
  float t = p - 0.5;
  float travel = 0.5 * (abs(dir.x) * ratio + abs(dir.y)) + 0.3;
  float along = travel * (2.0 * t) * (0.55 + 1.8 * t * t);
  vec2 src = dir * along + normal * height;

  vec2 d = q - src;
  float dist = length(d);
  float k = intensity * env;

  // the cut, under the glare: the incoming image spreads out from the light in a soft circle,
  // slower as the flare gets dimmer so that it still reads as intended
  float cut = mix(0.2, 0.06, clamp(intensity, 0.0, 1.0));
  float s = clamp((p - 0.5 + cut) / (2.0 * cut), 0.0, 1.0);
  float soft = 0.3;
  float reach = 0.5 * length(aspect) + length(src) + soft;
  float front = s * (reach + soft);
  float m = smoothstep(front, front - soft, dist);
  vec4 base = frame(uv, m);

  float ax = abs(d.x);
  float ay = abs(d.y);
  float thin = exp(-ay * 140.0) * exp(-ax * 0.7);
  float wide = exp(-ay * 30.0) * exp(-ax * 1.6);
  vec3 tint = color;
  vec3 streak = (thin * mix(vec3(1.0), tint, smoothstep(0.0, 0.3, ax)) + 0.5 * wide * tint) * 3.0;

  vec3 core = vec3(1.0, 0.97, 0.92) * exp(-dist * dist * 600.0) * 3.0 + mix(vec3(1.0), tint, 0.5) * exp(-dist * 7.0) * 0.6;

  vec3 ghosts = vec3(0.0);
  for (int i = 0; i < GHOSTS; i++) {
    float fi = float(i);
    float f = -0.45 + 0.42 * fi + 0.08 * sin(fi * 2.3);
    vec2 g = -src * f;
    float size = 0.025 + 0.06 * fract(fi * 0.618 + 0.2);
    float gd = length(q - g) / size;
    float disc = smoothstep(1.0, 0.8, gd) * (0.35 + 0.65 * smoothstep(0.4, 0.95, gd));
    vec3 hue = mix(tint, vec3(1.0, 0.65, 0.35), fract(fi * 0.53));
    hue = mix(hue, vec3(0.5, 1.0, 0.6), step(4.5, fi) * 0.6);
    ghosts += disc * hue * 0.45;
  }

  vec3 bloom = vec3(0.0);
  if (peak > 1e-3) {
    float radius = 0.06 * env;
    for (int i = 0; i < BLOOM_TAPS; i++) {
      float fi = float(i);
      float a = fi * 2.39996;
      float rr = radius * sqrt((fi + 0.5) / float(BLOOM_TAPS));
      vec2 o = vec2(cos(a), sin(a)) * rr / aspect;
      bloom += highlight(frame(mirror(uv + o), m));
    }
    bloom /= float(BLOOM_TAPS);
  }

  // at the peak, the glare: a wide halo around the light and a light veil over the frame, to hide the cut
  vec3 glare = mix(vec3(1.0), tint, 0.5) * peak * (0.45 + 2.2 * exp(-dist * 3.0));

  vec3 light = k * (streak + core + ghosts) + intensity * (bloom * 2.5 * peak + glare);
  light = 1.0 - exp(-light);

  // screened over the image; the flare only shows on the image, so transparency is kept
  vec3 c = base.rgb + light * base.a - base.rgb * light;
  if (base.a <= 0.0) return vec4(0.0);
  return vec4(clamp(c / base.a, 0.0, 1.0), base.a);
}

// Author: gre
// License: MIT
// Description: The incoming image pushes the outgoing one out of frame as if seen through a wide-angle lens: the frame bulges and bends the seam while the images speed past, with motion blur, color fringes toward the edges and a light vignette, then flattens back as the push lands
// Tags: slide, push, lens, distort, motion-blur, chromatic-aberration, directional

// @param Direction in which the images move, snapped to the nearest of the 8 horizontal, vertical and diagonal directions
uniform vec2 direction; // = vec2(-1.0, 0.0)
// @range(0, 1) Strength of the lens bulge at the peak
uniform float strength; // = 0.7
// @range(0, 1) Spread of the color fringes toward the edges
uniform float fringe; // = 0.5
// @range(0, 1) Length of the motion blur at full speed
uniform float blur; // = 0.35

const int SAMPLES = 24;

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 strip(vec2 q, vec2 d) {
  if (q.x >= 0.0 && q.x <= 1.0 && q.y >= 0.0 && q.y <= 1.0) {
    return getFromColor(q);
  }
  return getToColor(mirror(q + d));
}

vec4 transition(vec2 uv) {
  // snap to the nearest of the 8 directions: drop a component under tan(22.5deg) of the other
  vec2 ad = abs(direction);
  vec2 d = sign(direction) * step(0.4142 * max(ad.x, ad.y), ad);
  if (dot(d, d) == 0.0) d = vec2(-1.0, 0.0);
  float p = progress;
  // position: smooth start and landing; the motion blur follows the speed (1.875 at the peak)
  float pos = p * p * p * (p * (p * 6.0 - 15.0) + 10.0);
  float speed = 30.0 * p * p * (1.0 - p) * (1.0 - p) / 1.875;
  float len = clamp(blur, 0.0, 1.0) * 0.25 * speed;
  float h = 1.0 - abs(2.0 * p - 1.0);
  float hs = h * h * (3.0 - 2.0 * h);
  float k = clamp(strength, 0.0, 1.0) * 0.75 * hs;
  float ca = clamp(fringe, 0.0, 1.0) * 0.06 * hs;

  // round barrel lens that keeps the corners in place: 1.0 at the corners
  vec2 aspect = vec2(ratio, 1.0);
  float r = length((uv - 0.5) * aspect) / length(0.5 * aspect);
  float r2 = r * r;

  // each tap is both a step of the motion blur and a wavelength: the blue end is drawn in a bit
  // more than the red end, growing toward the edges, so colors split around the contours there
  float jitter = hash(uv * aspect * 731.0);
  vec3 col = vec3(0.0);
  vec3 wsum = vec3(0.0);
  float alpha = 0.0;
  for (int i = 0; i < SAMPLES; i++) {
    float t = (float(i) + 0.5) / float(SAMPLES);
    vec3 w = vec3(t, 1.0 - abs(2.0 * t - 1.0), 1.0 - t);
    vec2 q = 0.5 + (uv - 0.5) * (1.0 - k + k * r2) * (1.0 - ca * (1.0 - t) * r2);
    // spread the blur steps over the wavelengths, so every color gets an even blur; the steps
    // never reach past the two images, at the start and at the landing
    float b = fract((float(i) * 7.0 + jitter) / float(SAMPLES)) - 0.5;
    vec4 c = strip(q - d * clamp(pos + len * b, 0.0, 1.0), d);
    col += w * c.rgb * c.a;
    wsum += w * c.a;
    alpha += c.a;
  }
  col /= max(wsum, vec3(1e-5));
  col *= 1.0 - 0.45 * k * r2;
  return vec4(col, alpha / float(SAMPLES));
}

// Author: gre
// License: MIT
// Description: A round glass lens grows from a point over the outgoing image, casting a soft shadow on it, and shows the incoming image magnified through it, with a bright bevelled rim and faint color fringes; as the lens fills the frame the magnification relaxes until the incoming image lies flat
// Tags: lens, glass, circle, iris, magnify, reveal

// @param Point the lens grows from
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(0, 0.8) How strongly the lens magnifies the middle of the incoming image at the start
uniform float strength; // = 0.5
// @range(0, 1) Strength of the rim's light and shade and of the shadow the lens casts (0 for a clean cut)
uniform float shading; // = 0.6

const float AA = 0.0015;
const float BEVEL = 0.07;
// moment the lens has grown past the farthest corner
const float OPEN = 0.8;
// toward the light, from the top left (xy of a unit vector)
const vec2 LIGHT = vec2(-0.6, 0.8);

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 aspect = vec2(ratio, 1.0);
  float sh = clamp(shading, 0.0, 1.0);

  vec2 far = max(center, 1.0 - center) * aspect;
  float full = length(far) / (1.0 - BEVEL) + 2.0 * AA;
  float t = clamp(p / OPEN, 0.0, 1.0);
