}

// a strobe at time t0: a quick rise, a plateau of length hold, then a decay
float pulse(float p, float t0, float hold, float decay) {
  float x = p - t0;
  if (x < 0.0) return smoothstep(-0.012, 0.0, x);
  return exp(-max(x - hold, 0.0) / decay);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 q = vec2(uv.x * ratio, uv.y);
  // (seeds far apart, so that neighboring seeds share no hash keys)
  float k0 = floor(seed) * 61.0;
  int nb = bolts < 1 ? 1 : (bolts > 3 ? 3 : bolts);
  int nf = flashes < 1 ? 1 : (flashes > 4 ? 4 : flashes);
  // the images switch during the brightest strobe, the second one (or the only one)
  int cut = nf > 1 ? 1 : 0;

  float flash = 0.0;
  float lit = 0.0;
  float tCut = LEADER;
  float tLast = LEADER;
  float t = LEADER;
  for (int i = 0; i < 4; i++) {
    if (i < nf) {
      bool isCut = i == cut;
      float amp = isCut ? 1.0 : (i < cut ? 0.55 : 0.7 * pow(0.75, float(i - cut - 1)));
      float s = amp * pulse(p, t, isCut ? 0.025 : 0.004, isCut ? 0.03 : 0.022);
      flash = max(flash, s);
      lit = max(lit, pulse(p, t, 0.01, 0.045));
      if (isCut) tCut = t;
      tLast = t;
      t += (isCut ? 0.12 : 0.08) + 0.04 * hash(vec2(float(i), k0 + 5.0));
    }
  }
  float stutter = mix(0.7, 1.0, hash(vec2(floor(p * 70.0), k0 + 9.0)));
  flash *= stutter;
  float whiteout = pulse(p, tCut, 0.025, 0.02);
  float tail = p > tLast ? exp(-(p - tLast) / 0.1) * smoothstep(0.03, 0.06, p - tLast) : 0.0;
  flash = max(flash, 0.35 * tail * step(0.45, hash(vec2(floor(p * 40.0), k0 + 13.0))));

  float grow = clamp(p / LEADER, 0.0, 1.0);
  grow = (floor(grow * 7.0) + smoothstep(0.0, 1.0, fract(grow * 7.0))) / 7.0;
  float faint = 0.5 * mix(0.6, 1.0, hash(vec2(floor(p * 50.0), k0 + 11.0)));
  float boltLight = p < LEADER ? faint * smoothstep(0.0, 0.06, p) : max(lit * stutter, faint * exp(-(p - LEADER) / 0.12));
  boltLight = max(boltLight, 0.6 * flash * tail);
  boltLight *= 1.0 - smoothstep(tLast + 0.1, tLast + 0.3, p);

  float core = 0.0;
  float halo = 0.0;
  float near = 10.0;
  bool lightsOn = boltLight > 0.0 || flash > 0.0;
  for (int b = 0; b < 3; b++) {
    if (b < nb && lightsOn) {
      float fb = float(b);
      float kb = k0 + fb * 17.0;
      float x1 = strike * ratio;
      float y1 = -0.05;
      float bright = 1.0;
      if (b > 0) {
        float roomy = strike < 0.5 ? 1.0 : -1.0;
        bool cramped = min(strike, 1.0 - strike) < 0.25;
        float side = b == 1 || cramped ? roomy : -roomy;
        float dist = b == 2 && cramped ? 0.5 : 0.22;
        x1 = clamp(x1 + side * ratio * (dist + 0.12 * hash(vec2(fb, kb))), 0.08 * ratio, 0.92 * ratio);
        y1 = 0.25 + 0.25 * hash(vec2(fb, kb + 1.0));
        bright = 0.7;
      }
      float x0 = clamp(x1 + (hash(vec2(fb, kb + 2.0)) - 0.5) * 0.5 * min(ratio, 1.0), 0.1 * ratio, 0.9 * ratio);
      float tip = mix(1.02, y1, grow);
      // (the slope is measured over a few pixels, so it changes smoothly at the corners)
      float e = 0.01;
      float z0 = zigzag(1.0, kb);
      float z1 = zigzag(y1, kb);
      float x = boltX(q.y, x0, x1, y1, z0, z1, kb);
      float slope = (boltX(q.y + e, x0, x1, y1, z0, z1, kb) - boltX(q.y - e, x0, x1, y1, z0, z1, kb)) / (2.0 * e);
      float d = curveDist(q, x, slope, max(max(y1, tip) - q.y, q.y - 1.05));
      near = min(near, d);
      float w = 0.003 * mix(1.0, 0.7, fb / 2.0);
      core += bright * exp(-d * d / (w * w));
      halo += bright * (0.7 * exp(-d * 24.0) + 0.25 * exp(-d * 6.0));
      for (int j = 0; j < 3; j++) {
        float fj = float(j);
        float kj = kb + 3.0 + fj * 5.0;
        float tb = 0.12 + 0.2 * fj + 0.15 * hash(vec2(fj, kj));
        float yb = mix(1.0, y1, tb);
        float len = (0.3 + 0.25 * hash(vec2(fj, kj + 1.0))) * (1.0 - tb) * (1.0 - y1);
        float dir = (j == 1 ? -1.0 : 1.0) * (0.2 + 0.45 * hash(vec2(fj, kj + 2.0))) * min(ratio, 1.0);
        float xb = boltX(yb, x0, x1, y1, z0, z1, kb);
        float zb = zigzag(yb, kj);
        float bx = branchX(q.y, xb, yb, zb, dir, kj);
        float bs = (branchX(q.y + e, xb, yb, zb, dir, kj) - branchX(q.y - e, xb, yb, zb, dir, kj)) / (2.0 * e);
        float bd = curveDist(q, bx, bs, max(max(yb - len, tip) - q.y, q.y - yb));
        near = min(near, bd);
        float along = clamp((yb - q.y) / len, 0.0, 1.0);
        float fade = bright * (1.0 - 0.8 * along);
        float bw = w * mix(0.8, 0.4, along);
        core += fade * exp(-bd * bd / (bw * bw));
        halo += fade * 0.6 * (0.7 * exp(-bd * 24.0) + 0.25 * exp(-bd * 6.0));
      }
    }
  }

  float m = smoothstep(tCut, tCut + 0.025, p);
  vec4 c = vec4(0.0);
  if (m < 1.0) {
    vec4 a = getFromColor(uv);
    c += (1.0 - m) * vec4(a.rgb * a.a, a.a);
  }
  if (m > 0.0) {
    vec4 a = getToColor(uv);
    c += m * vec4(a.rgb * a.a, a.a);
  }
  if (c.a <= 0.0) return vec4(0.0);
  vec3 col = c.rgb / c.a;

  float live = smoothstep(0.0, 0.03, p) * (1.0 - smoothstep(0.85, 1.0, p));
  float dim = 0.4 * smoothstep(0.0, LEADER, p) * (1.0 - smoothstep(tCut, tLast + 0.15, p));
  float f = flash * mix(0.6 + 0.4 * exp(-near * 4.0), 1.0, smoothstep(0.6, 1.0, flash));
  col *= 1.0 - dim * live;
  col = col * (1.0 + 2.5 * f * live) + color * (1.1 * f * live);
  float g = 0.4 + 1.2 * glow;
  vec3 light = mix(color, vec3(1.0), 0.75) * min(core, 1.5) * 1.6 + color * g * halo;
  col += light * boltLight * live;
  col = mix(col, vec3(1.0), 0.92 * whiteout * live);
  return vec4(clamp(col, 0.0, 1.0), c.a);
}

// Author: gre
// License: MIT
// Description: Lightning strikes the outgoing picture a few times: each forked bolt cracks down as a white-hot slit through which the incoming picture already shows, and the slits widen from their channels until they swallow the frame
// Tags: electric, lightning, spark, branching, reveal

// @range(1, 5, 1) Number of strikes, one after the other across the frame
uniform int strikes; // = 3
// @range(0, 1) How jagged the bolts are
uniform float jag; // = 0.6

float h11(float n) { n = fract(n * 0.1031); n *= n + 33.33; n *= n + n; return fract(n); }
// piecewise linear on purpose: the kinks are what makes a bolt read as lightning
float zz(float x) { float i = floor(x); return mix(h11(i), h11(i + 1.0), x - i) - 0.5; }
float vn(vec2 p) {
  vec2 i = floor(p), f = p - i;
  f *= f * (3.0 - 2.0 * f);
  float a = h11(i.x + i.y * 57.0), b = h11(i.x + 1.0 + i.y * 57.0);
  float c = h11(i.x + (i.y + 1.0) * 57.0), d = h11(i.x + 1.0 + (i.y + 1.0) * 57.0);
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float boltX(float y, float s, float x0, float fine) {
  float a = 0.4 + jag;
  return x0 + (h11(s * 3.7) - 0.5) * 0.35 * (1.0 - y)
    + a * (0.07 * zz(y * 5.0 + s * 11.0) + fine * (0.03 * zz(y * 16.0 + s * 7.0) + 0.01 * zz(y * 47.0 + s * 5.0)));
}

// far drops the fine kinks once the rift is wide: their offset contours would tear into teeth
float bolt(vec2 P, float s, float x0, float age, float far) {
  float yf = 1.02 - age * 22.0;
  float fine = 1.0 - far;
  float fy = boltX(P.y, s, x0, fine);
  float h = mix(0.004, 0.1, far);
  float sl = (boltX(P.y + h, s, x0, fine) - boltX(P.y - h, s, x0, fine)) / (2.0 * h);
  float d = max(abs(P.x - fy) / sqrt(1.0 + sl * sl), yf - P.y);
  for (int k = 0; k < 3; k++) {
    float fk = float(k), sk = s * 13.0 + fk;
    float yb = 0.82 - 0.24 * fk - 0.08 * h11(sk);
    float side = h11(sk * 1.7) < 0.5 ? -1.0 : 1.0;
    float th = side * (0.45 + 0.5 * h11(sk * 2.3));
    vec2 dir = vec2(sin(th), -cos(th));
    float L = (0.42 - 0.08 * fk) * (0.7 + 0.5 * h11(sk * 3.1));
    float Lg = L * clamp((yb - yf) / (L * cos(th)), 0.0, 1.0);
    vec2 q = P - vec2(boltX(yb, s, x0, fine), yb);
    float u = dot(q, dir);
    float v = dot(q, vec2(-dir.y, dir.x)) - (0.4 + jag) * (0.04 * zz(u * 12.0 + sk * 5.0) + 0.012 * zz(u * 40.0 + sk)) * clamp(u * 8.0, 0.0, 1.0);
    float db = length(vec2(max(-u, 0.0) + max(u - Lg, 0.0), v));
    // branches are thinner, so they open later than the trunk
    d = min(d, yb < yf ? 9.0 : db * 1.7 + 0.004);
  }
  return d;
}

vec4 transition(vec2 uv) {
  float p = progress, R = ratio;
  vec2 P = vec2(uv.x * R, uv.y);
  float n = clamp(float(strikes), 1.0, 5.0);
  float x = clamp((p - 0.3) / 0.7, 0.0, 1.0);
  // sized to the typical widest gap between bolts; the late term mops up seed-dependent stragglers
  float grow = x * x * (0.55 * R / n + 0.04 * R + 0.04) + 0.12 * smoothstep(0.85, 1.0, p);
  float far = smoothstep(0.0, 0.08, grow);
  float rn = vn(P * 40.0) - 0.5 + 0.5 * (vn(P * 110.0) - 0.5);
  float e = 9.0, heat = 0.0;
  for (int i = 0; i < 5; i++) {
    float fi = float(i);
    if (fi < n) {
      float t0 = 0.05 + 0.3 * fi / max(n - 1.0, 1.0);
      float age = p - t0;
      if (age > 0.0) {
        float slot = floor((n - 1.0) * 0.5) + (mod(fi, 2.0) > 0.5 ? (fi + 1.0) * 0.5 : -fi * 0.5);
        float x0 = R * (slot + 0.5 + 0.5 * (h11(fi * 9.1 + 2.0) - 0.5)) / n;
        float d = bolt(P, fi + 1.0, x0, age, far);
        float w = 0.003 + 0.03 * sqrt(age);
        e = min(e, d - w * (1.0 + 0.9 * rn));
        heat += smoothstep(0.0, 0.008, age) * exp(-age * 14.0) * (0.75 + 0.5 * zz(age * 300.0 + fi * 7.0)) * exp(-max(d - w, 0.0) * 40.0);
      }
    }
  }
  e = e - grow + 0.012 * rn * smoothstep(0.0, 0.05, grow);
  float hole = 1.0 - smoothstep(-0.0025, 0.0025, e);
  float fade = 1.0 - smoothstep(0.7, 1.0, p);
  float rim = exp(-abs(e) * 260.0);
  float singe = exp(-max(e, 0.0) * 70.0) * smoothstep(0.0, 0.004, -e + 0.02) * fade;
  vec4 A = getFromColor(uv), B = getToColor(uv);
  vec3 a = A.rgb * (1.0 - 0.55 * singe * (1.0 - rim));
  a += heat * vec3(0.55, 0.62, 0.75);
  a += rim * fade * mix(vec3(1.0, 0.55, 0.25), vec3(0.85, 0.92, 1.0), clamp(heat * 2.0, 0.0, 1.0));
  vec3 b = B.rgb + (heat * 0.8 + 0.6 * rim) * fade * vec3(0.8, 0.88, 1.0) * exp(min(e, 0.0) * 80.0);
  return vec4(clamp(mix(a, b, hole), 0.0, 1.0), mix(A.a, B.a, hole));
}

// Author: gre
// License: MIT
// Description: The incoming image is printed like text on a terminal: line after line, the whole frame jolts up one row, pushing the outgoing image up, and a block cursor types the new row in cell by cell from left to right over a dimmed preview of the line
// Tags: text, terminal, typing, scroll, retro

// @range(3, 12, 1) Number of rows the incoming image is typed in
uniform int rows; // = 6
// @range(8, 60, 1) Number of character cells in a row
uniform int cells; // = 24
// @color Color of the block cursor
uniform vec4 cursor; // = vec4(0.62, 1.0, 0.72, 1.0)

const float FEED = 0.3;

vec4 transition(vec2 uv) {
  float n = float(rows);
  float u = progress * n;
  float k = min(floor(u), n - 1.0);
  float f = u - k;
  float s = clamp(f / FEED, 0.0, 1.0);
  // snaps a little past the line and settles back, like a platen jolting round
  float feed = s < 0.55 ? 1.06 * smoothstep(0.0, 0.55, s) : 1.06 - 0.06 * smoothstep(0.55, 1.0, s);
  float y = 1.0 - uv.y + (k + feed) / n;
  if (y < 1.0) return getFromColor(vec2(uv.x, 1.0 - y));

  // mirrored: the last feed's overshoot looks past the bottom of the image
  vec4 b = getToColor(vec2(uv.x, abs(2.0 - y)));
  float row = min(floor((y - 1.0) * n), n - 1.0);
  float c = float(cells);
  float typed = clamp((f - FEED) / (1.0 - FEED), 0.0, 1.0);
  float head = row < k ? c + 1.0 : (row > k ? -1.0 : floor(typed * (c + 1.0)));
  float cell = floor(uv.x * c);
  vec4 col = cell < head ? b : vec4(b.rgb * 0.16, b.a);
  float ly = fract((y - 1.0) * n);
  float lit = step(0.5, s);
  float box = (cell == head ? 1.0 : 0.0) * step(0.1, ly) * step(ly, 0.9) * lit;
  return mix(col, cursor, 0.9 * box * cursor.a);
}

// Author: gre
// License: MIT
// Description: The outgoing image breaks into a board of dots in four of its inks; neighbors of the same ink reach out and join into pills, bends and big soft-cornered shapes; dot by dot they let go, shrink and come back in the incoming image's inks, join again and swell into the incoming image
// Tags: dots, grid, links, flat, poster, palette, abstract
// Preview: 0.4

// @range(0.06, 0.25) Distance between the dots, as a part of the frame's shorter side
uniform float pitch; // = 0.125
// @range(0, 2.5) How vivid the inks are
uniform float vivid; // = 1.5

const int N = 8;
const int TAPS = 8;
// between these two moments only the dots show, so the palettes of both images are read instead of their shapes
const float FREED = 0.22;
const float CAUGHT = 0.78;

float luma(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec2 spot(int i) {
  return fract(vec2(0.754878, 0.569840) * float(i) + 0.4);
}

float hash(vec2 p) {
  vec3 q = fract(p.xyx * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float during(float a, float b) {
  return smoothstep(a, b, progress);
}

vec4 pixel(vec2 p, bool late) {
  return late ? getToColor(p) : getFromColor(p);
}

vec3 paint(vec4 sum, float level) {
  vec3 c = sum.rgb / sum.a;
  float l = luma(c);
  return clamp(l + (c - l) * vivid + 0.06 * (level - 1.5), 0.0, 1.0);
}

float halfPill(vec2 p, vec2 d, float len) {
  return length(p - d * clamp(dot(p, d) / dot(d, d), 0.0, 0.5 * len));
}

// a link growing from both of its dots
float link(vec2 p, vec2 d, float len, float r) {
  float m = min(halfPill(p, d, len), halfPill(p - d, -d, len));
  return len > 0.0 ? r - m : -9.0;
}

// rounds off the bend between two links
vec4 bent(vec4 a, vec4 b) {
  vec4 h = max(0.3 - abs(a - b), 0.0);
  return max(a, b) + h * h / 1.2;
}

float linked(vec3 same, vec3 d) {
  d = mix(vec3(-9.0), d, same);
  return max(d.x, max(d.y, d.z));
}

// keeps the two best scores: x and y hold the inks, z and w their scores
vec4 rank(vec4 best, float k, float score) {
  return score > best.z ? vec4(k, best.x, score, best.z) : score > best.w ? vec4(best.x, k, best.z, score) : best;
}

float toneOf(float k, float z, bool late) {
  return (k > 3.5) == late ? 0.5 - abs(z - mod(k, 4.0)) : -9.0;
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  bool late = progress > 0.5;
  vec2 frame = vec2(ratio, 1.0) / min(ratio, 1.0);

  // the color to fall back on where the spots of an image are all transparent
  vec3 own = (a.rgb * a.a + b.rgb * b.a) / max(a.a + b.a, 1e-4);
  vec2 sum = vec2(1e-4);
  vec2 ma = 1e-4 * vec2(luma(own), luma(own) * luma(own));
  vec2 mb = ma;
  vec3 ga = 1e-4 * own;
  vec3 gb = ga;
  for (int i = 0; i < N; i++) {
    vec4 ca = progress < CAUGHT ? getFromColor(spot(i)) : vec4(0.0);
    vec4 cb = progress > FREED ? getToColor(spot(i)) : vec4(0.0);
    vec2 l = vec2(luma(ca.rgb), luma(cb.rgb));
    sum += vec2(ca.a, cb.a);
    ma += vec2(l.x, l.x * l.x) * ca.a;
    mb += vec2(l.y, l.y * l.y) * cb.a;
    ga += ca.rgb * ca.a;
    gb += cb.rgb * cb.a;
  }
  vec3 ground = mix(mix(ga, gb, during(0.36, 0.64)) / mix(sum.x, sum.y, during(0.36, 0.64)), vec3(1.0), 0.75);
  ma /= sum.x;
  mb /= sum.y;
  ma.y = sqrt(max(ma.y - ma.x * ma.x, 0.0)) + 0.03;
  mb.y = sqrt(max(mb.y - mb.x * mb.x, 0.0)) + 0.03;

  vec2 g = (uv - 0.5) * frame / pitch + 0.5;
  vec2 cell = floor(g), f = g - cell;
  vec4 ink, size;
  for (int i = 0; i < 4; i++) {
    vec2 n = vec2(mod(float(i), 2.0), floor(0.5 * float(i)));
    vec2 id = cell + n;
    float t = (progress - 0.38 - 0.24 * hash(id + 50.0)) / 0.08;
    bool turned = t > 0.0;
    vec2 q = fold((id - 0.5) * pitch / frame + 0.5);
    float l = luma(pixel(q, turned).rgb);
    float y = turned ? (l - mb.x) / mb.y : (l - ma.x) / ma.y;
    float k = floor(clamp(y / 0.8 + 2.0, 0.0, 3.99)) + (turned ? 4.0 : 0.0);
    float s = smoothstep(0.0, 1.0, abs(t));
    if (i == 0) { ink.x = k; size.x = s; }
    else if (i == 1) { ink.y = k; size.y = s; }
    else if (i == 2) { ink.z = k; size.z = s; }
    else { ink.w = k; size.w = s; }
  }

  vec4 same = step(abs(ink.xzxy - ink.ywzw), vec4(0.5));
  vec2 diag = step(abs(ink.xy - ink.wz), vec2(0.5));
  float grow = 1.0 - during(0.06, 0.32) + during(0.68, 0.92);
  float radius = mix(0.35, 0.78, grow);
  // links along the two rows, along the two columns, then across a square of one ink
  vec4 w = min(size.xzxy, size.ywzw);
  vec4 len = same * smoothstep(0.2, 0.8, w) * vec2(during(0.2, 0.34), during(0.26, 0.42)).xxyy;
  vec2 wd = min(size.xy, size.wz);
  vec2 lend = same.x * same.y * same.z * during(0.3, 0.5) * smoothstep(0.2, 0.8, wd);
  vec2 X = vec2(1.0, 0.0), Y = X.yx;
  // shrunk away, a dot leaves no speck
  vec4 dots = (radius + 0.03) * size - 0.03 - vec4(length(f), length(f - X), length(f - Y), length(f - 1.0));
  vec4 l = vec4(link(f, X, len.x, radius * w.x), link(f - Y, X, len.y, radius * w.y), link(f, Y, len.z, radius * w.z), link(f - X, Y, len.w, radius * w.w));
  vec2 ld = vec2(link(f, X + Y, lend.x, radius * wd.x), link(f - X, Y - X, lend.y, radius * wd.y));
  vec4 sd = max(max(dots, ld.xyyx), bent(l.xxyy, l.zwzw));
  sd = max(sd, vec4(
    linked(vec3(same.xz, diag.x), sd.yzw),
    linked(vec3(same.x, diag.y, same.w), sd.xzw),
    linked(vec3(same.z, diag.y, same.y), sd.xyw),
    linked(vec3(diag.x, same.wy), sd.xyz)));
  sd = max(sd, -1.5);

  float bend = late ? 1.0 - during(0.78, 0.96) : during(0.04, 0.2);
  vec4 here = late ? b : a;
  vec2 acc = vec2(luma(here.rgb), 1.0) * here.a + vec2(0.0, 1e-5);
  if (progress < FREED || progress > CAUGHT) {
    float soft = 0.035 * (late ? 1.0 - during(0.8, 1.0) : during(0.0, 0.2));
    for (int i = 0; i < TAPS; i++) {
      float n = 2.39996 * float(i);
      vec4 c = pixel(fold(uv + soft * sqrt((float(i) + 0.5) / float(TAPS)) * vec2(cos(n), sin(n)) / frame), late);
      acc += vec2(luma(c.rgb), 1.0) * c.a;
    }
  }
  float z = (acc.x / acc.y - (late ? mb.x : ma.x)) / (late ? mb.y : ma.y);
  z = clamp(z / 0.8 + 1.5, -0.5, 3.5);

  // the inks of the dots, then of the picture itself, for the first and last beats
  vec4 dup = vec4(0.0, same.x, max(same.z, diag.y), max(diag.x, max(same.w, same.y)));
  vec4 tone = vec4(toneOf(ink.x, z, late), toneOf(ink.y, z, late), toneOf(ink.z, z, late), toneOf(ink.w, z, late));
  vec4 score = mix(0.3 * tone, sd, bend) - 99.0 * dup;
  vec4 best = vec4(-1.0, -1.0, mix(-0.2, 0.0, bend) - 0.2 * grow, -99.0);
  best = rank(best, ink.x, score.x);
  best = rank(best, ink.y, score.y);
  best = rank(best, ink.z, score.z);
  best = rank(best, ink.w, score.w);
  float k = clamp(floor(z), 0.0, 2.0) + (late ? 4.0 : 0.0);
  for (int i = 0; i < 2; i++) {
    float known = dot(step(abs(ink - k), vec4(0.5)), vec4(1.0));
    best = rank(best, k, mix(0.3 * toneOf(k, z, late), -1.5, bend) - 99.0 * known);
    k += 1.0;
  }

  vec2 level = mod(best.xy, 4.0);
  vec2 second = step(3.5, best.xy);
  // the ground needs no palette, and a far second neither
  second.x = best.x < 0.0 ? second.y : second.x;
  second.y = best.y < 0.0 || best.z - best.w > 0.02 + 0.0025 / pitch ? second.x : second.y;
  vec4 s0 = 1e-6 * vec4(own, 1.0), s1 = s0;
  for (int i = 0; i < N; i++) {
    if (second.x + second.y < 1.5) {
      vec4 c = getFromColor(spot(i));
      vec2 d = (luma(c.rgb) - ma.x) / ma.y / 0.8 + 1.5 - level;
      vec2 w = (1.0 - second) * c.a * (exp(-4.0 * d * d) + 1e-3);
      s0 += vec4(c.rgb, 1.0) * w.x;
      s1 += vec4(c.rgb, 1.0) * w.y;
    }
    if (second.x + second.y > 0.5) {
      vec4 c = getToColor(spot(i));
      vec2 d = (luma(c.rgb) - mb.x) / mb.y / 0.8 + 1.5 - level;
      vec2 w = second * c.a * (exp(-4.0 * d * d) + 1e-3);
      s0 += vec4(c.rgb, 1.0) * w.x;
      s1 += vec4(c.rgb, 1.0) * w.y;
    }
  }
  vec3 c0 = best.x < 0.0 ? ground : paint(s0, level.x);
  vec3 c1 = best.y < 0.0 ? ground : paint(s1, level.y);
  float aa = mix(0.015, 0.0025 / pitch, bend);
  vec3 col = mix(c1, c0, smoothstep(-aa, aa, best.z - best.w));

  float light = luma(here.rgb);
  float on = smoothstep(0.0, 0.12, progress - 0.06 * light) * smoothstep(0.0, 0.14, 1.0 - 0.06 * light - progress);
  return vec4(mix(here.rgb, col, on), mix(a.a, b.a, during(0.35, 0.65)));
}

// Author: gre
// License: MIT
// Description: The incoming image rises over the outgoing one like liquid filling a glass, its surface sloshing in waves, lit by a bright meniscus line, bending the image just below it, with a few bubbles rising through it
// Tags: liquid, water, wave, directional, reveal

// @param Direction the liquid rises toward
uniform vec2 direction; // = vec2(0.0, 1.0)
// @range(0, 0.3) Height of the waves on the surface, in frame heights
uniform float amplitude; // = 0.06
// @range(0.5, 6) Number of waves across the frame
uniform float waves; // = 1.5
// @color Color of the bright line along the surface and the rims of the bubbles (its alpha is its strength)
uniform vec4 highlight; // = vec4(1.0, 1.0, 1.0, 0.8)
// @range(0, 0.1) How much the incoming image is bent just below the surface
uniform float refraction; // = 0.03
// @range(0, 1) How many bubbles rise through the liquid
uniform float bubbles; // = 0.5

const float PI = 3.141592653589793;
const float AA = 0.0015;
const float LINE = 0.006;
const float CELL = 0.08;

float hash (vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// height of the surface above its mean level at x (across the frame, from -1 to 1), between -1 and 1:
// a slosh from side to side and a smaller wave running along it
float surface (float x, float t) {
  float k = PI * max(waves, 0.01);
  return 0.6 * sin(k * x + 0.5 * PI) * cos(2.0 * PI * 1.3 * t)
       + 0.4 * sin(1.7 * k * x - 9.0 * t + 1.3);
}

vec4 transition (vec2 uv) {
  vec4 a = getFromColor(uv);

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(0.0, 1.0);
  vec2 across = vec2(-dir.y, dir.x);
  // measured in square pixels, so the waves and bubbles are not stretched
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float e = 0.5 * (abs(dir.x) * ratio + abs(dir.y));
  float w = 0.5 * (abs(dir.y) * ratio + abs(dir.x));
  float d = dot(p, dir);
  float x = dot(p, across);
  float t = progress;
  float stir = sin(PI * t);
  float amp = max(amplitude, 0.0) * (0.35 + 0.65 * stir);
  // the surface starts fully below the frame and ends fully above it, waves and meniscus included
  float margin = max(amplitude, 0.0) + 2.0 * LINE + AA;
  float mean = mix(-e - margin, e + margin, mix(t, t * t * (3.0 - 2.0 * t), 0.5));
  float level = mean + amp * surface(x / w, t);
  // > 0 below the surface, in the liquid
  float depth = level - d;
  float m = smoothstep(-AA, AA, depth);

  float bend = refraction * stir * exp(-max(depth, 0.0) / 0.06);
  vec2 offset = bend * (dir * sin(18.0 * x - 7.0 * t) + across * cos(13.0 * x + 5.0 * t));
  vec4 b = getToColor(clamp(uv + offset / vec2(ratio, 1.0), 0.0, 1.0));

  float glow = 0.0;
  float rise = mean + 0.5 * t;
  vec2 bq = vec2(x, d - rise) / CELL;
  vec2 cell = floor(bq);
  float hs = hash(cell + 7.1);
  float r = (0.12 + 0.18 * hash(cell + 3.7)) * stir;
  float px = AA / CELL;
  if (hs < bubbles * 0.6 && r > px) {
    // placed so that it stays inside its cell, wobble and soft edge included
    vec2 c = cell + 0.5 + (0.42 - r - px) * (vec2(hash(cell + 1.3), hash(cell + 9.4)) * 2.0 - 1.0);
    c.x += 0.08 * sin(6.0 * t + 6.28 * hs);
    float dist = length(bq - c);
    float rim = smoothstep(0.7 * r - px, 0.7 * r + px, dist) * (1.0 - smoothstep(r - px, r + px, dist));
    float glint = 1.0 - smoothstep(0.25 * r - px, 0.25 * r + px, length(bq - c - 0.45 * r * vec2(-0.7, 0.7)));
    glow = max(rim * 0.6, glint) * smoothstep(0.0, 0.05, depth) * stir;
  }
  float line = 1.0 - smoothstep(LINE - AA, LINE + AA, abs(depth - LINE));
  line += 0.35 * stir * exp(-max(depth, 0.0) / 0.03) * m;
  float light = highlight.a * clamp(max(line, glow), 0.0, 1.0) * (0.4 + 0.6 * stir);
  b.rgb = mix(b.rgb, highlight.rgb, light);

  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: Boundless <info@boundless-beta.com>
// License: MIT
// Description: The image breaks into a grid of tiles that swirl along Lissajous curves, in a Scanimate style, and flip one by one to the incoming image before settling back
// Tags: tiles, grid, motion, retro

// @param Speed of the tiles along their curves
uniform float speed; // = 0.5;
// @param Number of loops of the curve, horizontally and vertically
uniform vec2 freq; // = vec2(2.,3.);
// @param Extra vertical speed, which bends the curve
uniform float offset; // = 2.;
// @range(0, 2) Size of the curve, relative to the image
uniform float zoom; // = 0.8;
// @range(0, 10) Spread of the tile-by-tile switch to the incoming image
uniform float fade; // = 3.;

const vec2 grid = vec2(10.,10.);
const float TAU = 6.283185307;

vec4 transition (vec2 uv) {
  // The tiles leave and come back with zero speed, so the image does not break apart in the first frame
  float p = 1.-pow(1.-smoothstep(0.,1.,1.-abs(1.-2.*progress)),3.);
  // Find the last tile that covers this pixel (looping backwards, the first hit), then sample the images once
  for (float jBig = grid.y-1.; jBig >= 0.; jBig--) {
    for (float iBig = grid.x-1.; iBig >= 0.; iBig--) {
      float i = iBig/grid.x;
      float j = jBig/grid.y;
      float k = i/grid.y+j; // order of the tile along the curve
      vec2 uv0 = uv + vec2(i,j) - 0.5 + 0.5/grid + vec2(cos(k*TAU*freq.x+progress*6.*speed),sin(k*TAU*freq.y+progress*6.*(1.+offset)*speed))*zoom/2.;
      uv0 = mix(uv, uv0, p);
      if (uv0.x >= i && uv0.x < i+1./grid.x && uv0.y >= j && uv0.y < j+1./grid.y) {
        float tileMix = clamp(progress*((1.+fade)*2.*progress)-fade+k*fade, 0., 1.);
        return mix(getFromColor(uv0), getToColor(uv0), tileMix);
      }
    }
  }
  return vec4(0.); // between the tiles: transparent
}

