// Simplex noise :
// Description : Array and textureless GLSL 2D simplex noise function.
//      Author : Ian McEwan, Ashima Arts.
//  Maintainer : ijm
//     Lastmod : 20110822 (ijm)
//     License : MIT  
//               2011 Ashima Arts. All rights reserved.
//               Distributed under the MIT License. See LICENSE file.
//               https://github.com/ashima/webgl-noise
// 

vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x) {
  return mod289(((x*34.0)+1.0)*x);
}

float snoise(vec2 v)
  {
  const vec4 C = vec4(0.211324865405187,  // (3.0-sqrt(3.0))/6.0
                      0.366025403784439,  // 0.5*(sqrt(3.0)-1.0)
                     -0.577350269189626,  // -1.0 + 2.0 * C.x
                      0.024390243902439); // 1.0 / 41.0
  vec2 i  = floor(v + dot(v, C.yy) );
  vec2 x0 = v -   i + dot(i, C.xx);

  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;

  i = mod289(i); // Avoid truncation effects in permutation
  vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0 ))
		+ i.x + vec3(0.0, i1.x, 1.0 ));

  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
  m = m*m ;
  m = m*m ;

// Gradients: 41 points uniformly over a line, mapped onto a diamond.
// The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)

  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

// Normalise gradients implicitly by scaling m
// Approximation of: m *= inversesqrt( a0*a0 + h*h );
  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );

  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

// Simplex noise -- end

float luminance(vec4 color){
  //(0.299*R + 0.587*G + 0.114*B)
  return color.r*0.299+color.g*0.587+color.b*0.114;
}

vec4 transition(vec2 uv) {
  vec2 center = vec2(1.0, direction);
  vec2 p = uv.xy / vec2(1.0).xy;
  {
    float x = progress;
    float dist = distance(center, p)- progress*exp(snoise(vec2(p.x, 0.0)));
    float r = x - rand(vec2(p.x, 0.1));
    float m;
    if(above){
     m = dist <= r && luminance(getFromColor(p))>l_threshold ? 1.0 : (progress*progress*progress);
    }
    else{
     m = dist <= r && luminance(getFromColor(p))<l_threshold ? 1.0 : (progress*progress*progress);  
    }
    return mix(getFromColor(p), getToColor(p), m);    
  }
}

// Author: gre
// License: MIT
// Description: The incoming image floats onto the outgoing one in thin bands of ink that a rake drags into zigzags and a fine comb pulls into feathers, like marbled paper; the bands widen until they cover the frame and the combs pull back out, leaving the incoming image clean
// Tags: ink, paint, organic, pattern, dissolve, distort

// @range(2, 16, 1) Number of teeth of the rake dragged up and down, along the longer side of the frame
uniform float tines; // = 6.0
// @range(0, 0.2) How far the teeth of the rake drag the picture, in frame heights (the fine comb drags it 0.6 times as far)
uniform float pull; // = 0.12
// @range(3, 30, 1) Number of bands of ink across the frame
uniform float bands; // = 12.0
// @range(0, 1) How dark the thin lines of ink between the two images are
uniform float veins; // = 0.5

// how sharply the picture is pulled into a point right at a tooth, relative to the spacing of the teeth
const float CUSP = 0.12;
// teeth of the fine comb pulled across, per frame height
const float COMB = 9.0;

// folds coordinates back into the frame, so a dragged image never shows its clamped edges
vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// pull of a tooth on the bath at distance t (in tooth spacings, 0..1): 1 at the tooth, 0 at the next one,
// pointed at the tooth like ink dragged by a needle
float drag(float t) {
  float far = CUSP / (1.0 + CUSP);
  return (CUSP / (t + CUSP) - far) / (1.0 - far);
}

float ease(float x) {
  x = clamp(x, 0.0, 1.0);
  return x * x * (3.0 - 2.0 * x);
}

// where the bath at p (in frame heights) was before the rake and the comb went through it
vec2 unrake(vec2 p, float rake, float comb) {
  // fine comb pulled across the frame, all teeth going the same way: feathers
  float c = p.y * COMB;
  float t = fract(c);
  p.x -= comb * drag(2.0 * min(t, 1.0 - t));
  // rake pulled up and down, its teeth going in turns one way and the other: zigzags
  // spaced along the longer side of the frame, with a tooth in the middle
  float s = max(ratio, 1.0) / max(tines, 1.0);
  float k = (p.x - 0.5 * ratio) / s;
  float u = fract(k);
  float side = mod(floor(k), 2.0) < 0.5 ? 1.0 : -1.0;
  p.y -= rake * side * (drag(u) - drag(1.0 - u));
  return p;
}

float bandPhase(vec2 q) {
  return q.y * bands + 0.35 * sin(q.x * 2.3 + 1.0) + 0.2 * sin(q.x * 5.1 - q.y * 3.0);
}

vec4 transition(vec2 uv) {
  float rake = pull * ease(progress / 0.35) * ease((1.0 - progress) / 0.35);
  float comb = 0.6 * pull * ease((progress - 0.15) / 0.3) * ease((0.85 - progress) / 0.3);
  vec2 p = vec2(uv.x * ratio, uv.y);
  vec2 q = unrake(p, rake, comb);
  // phase gradient on screen, to antialias the bands where the rake squeezed them
  float e = 0.001;
  float ph = bandPhase(q);
  float gx = bandPhase(unrake(p + vec2(e, 0.0), rake, comb)) - ph;
  float gy = bandPhase(unrake(p + vec2(0.0, e), rake, comb)) - ph;
  float aa = max(length(vec2(gx, gy)), 0.002);
  float cover = ease((progress - 0.08) / 0.84);
  // half width of the bands: from just below 0 to just above 0.5, so they are exactly empty then full
  float w = cover * (0.5 + 2.0 * aa) - aa;
  float d = abs(fract(ph) - 0.5); // 0 in the middle of a band, 0.5 between two
  float m = 1.0 - smoothstep(w - aa, w + aa, d);
  vec2 suv = mirror(vec2(q.x / ratio, q.y));
  vec4 col = mix(getFromColor(suv), getToColor(suv), m);
  float line = 1.0 - smoothstep(0.0, 2.5 * aa + 0.02, abs(d - w));
  float show = veins * 4.0 * cover * (1.0 - cover); // exactly 0 when the bands are empty or full
  col.rgb *= 1.0 - 0.6 * show * line;
  return col;
}

// Author: gre
// License: MIT
// Description: Two small dark bodies appear in the outgoing picture and circle each other, bending it around them; they spiral in faster and faster, their wake throwing out two winding arms that carry the incoming picture, and when they merge a burst runs outward and the arms tighten into rings that shake the picture and die away
// Tags: space, black-hole, spiral, waves, distort
// Preview: 0.5

// @range(0, 0.1) How far the waves push the pictures
uniform float strength; // = 0.05
// @range(1, 4) Number of turns before the bodies merge
uniform float turns; // = 2.0
// @range(0, 1) Brightness of the burst when the bodies merge
uniform float burst; // = 0.45
// @color Color of the bodies
uniform vec4 body; // = vec4(0.0, 0.0, 0.0, 1.0)

const float PI = 3.14159265;
const float MERGE = 0.56;
const float SOFT = 0.08;

float orbit(float x) {
  float end = pow(SOFT, 0.55);
  float n = pow(MERGE + SOFT, 0.55) - end;
  // the frequency reached at the merger is kept while the waves ring down
  return 2.0 * PI * turns / n * (0.55 * end / SOFT * max(x - MERGE, 0.0) + end - pow(max(MERGE - x, 0.0) + SOFT, 0.55));
}

vec4 scene(vec2 z, float p, vec2 asp, vec2 c1, float on, float M) {
  float r = length(z);
  vec2 d = z / max(r, 1e-4);
  // the waves leave the center and take time to reach the borders
  float x = p - 0.22 * r;
  float o2 = 2.0 * orbit(p - 0.4 * r);
  vec2 d2 = vec2(d.x * d.x - d.y * d.y, 2.0 * d.x * d.y);
  vec2 w = vec2(d2.x * cos(o2) + d2.y * sin(o2), d2.y * cos(o2) - d2.x * sin(o2));
  float after = max(x - MERGE, 0.0);
  float amp = on * exp(-after * 9.0) * (0.25 + 0.75 * smoothstep(0.1, MERGE, x)) / (0.7 + r);
  float k = smoothstep(0.42, 0.58, smoothstep(0.2, 0.68, x) + 0.6 * w.x * amp);
  vec2 q = z + strength * amp * (d * w.x + vec2(-d.y, d.x) * w.y) * smoothstep(0.0, 0.15, r);
  float front = (x - MERGE - 0.01) / 0.022;
  float flash = burst * on * exp(-front * front) / (0.6 + 1.4 * r);
  q -= 0.6 * strength * flash * front * d;
  vec2 g1 = z - c1;
  vec2 g2 = z + c1;
  q -= M * (g1 / (dot(g1, g1) + 1e-5) + g2 / (dot(g2, g2) + 1e-5));
  vec2 s = 1.0 - abs(1.0 - mod(q / asp + 0.5, 2.0));
  vec4 a = getFromColor(s), b = getToColor(s);
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), k);
  c.rgb = c.rgb * (1.0 + 0.35 * amp * w.y + 0.5 * flash) + 0.25 * flash * c.a;
  float hr = 0.75 * sqrt(M * (1.0 + exp(-dot(c1, c1) * 500.0)));
  float dark = min(1.0, M * 2000.0) * (1.0 - smoothstep(hr * 0.88, hr + 1e-5, min(length(g1), length(g2))));
  return mix(c, vec4(body.rgb * body.a, body.a), dark);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  float on = smoothstep(0.0, 0.22, p) * (1.0 - smoothstep(0.72, 1.0, p));
  float u = max(MERGE - p, 0.0) / MERGE;
  float o = orbit(p);
  vec2 c1 = 0.3 * min(1.0, ratio) * pow(u, 0.4) * smoothstep(0.0, 0.2, p) * vec2(cos(o), sin(o));
  float M = 0.0027 * on * (1.0 - smoothstep(0.62, 0.85, p));
  vec4 sum = vec4(0.0);
  float aa = 0.0022 * on;
  for (int i = 0; i < 4; i++) {
    vec2 e = vec2(mod(float(i), 2.0), floor(float(i) / 2.0 + 0.01)) - 0.5;
    sum += 0.25 * scene((uv - 0.5) * asp + aa * e, p, asp, c1, on, M);
  }
  return sum.a > 0.0 ? vec4(min(sum.rgb / sum.a, 1.0), sum.a) : vec4(0.0);
}

