  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);

  float ang = 2.0 * PI * drift * t + START;
  float k = max(bands, 1.0) * (1.0 - 0.75 * t);
  vec2 axis = vec2(cos(ang), sin(ang)) * 0.5 * k / f;
