float jag(float x) {
  return roughness * (0.2 * sin(x * 13.0 + 1.1) + 0.5 * tri(x * 23.0 + sin(x * 7.0)) + 0.25 * tri(x * 61.0 + 0.6 * sin(x * 17.0)));
}

float fibers(float x, float seed) {
  return rim * (0.7 + 0.3 * sin(x * 41.0 + seed) + 0.4 * tri(x * 89.0 + seed));
}

vec4 torn(vec4 bg, vec4 col, float e, float limit, float aa, float fiber) {
  vec4 c = vec4(mix(col.rgb, paper.rgb, clamp(0.5 + e / aa, 0.0, 1.0) * paper.a * fiber), col.a);
  return mix(bg, c, clamp(0.5 - (e - limit) / aa, 0.0, 1.0));
}

vec4 transition(vec2 uv) {
  float p = progress;
  float xr = uv.x * ratio;
  float y0 = outline(uv.x);
  float edge = y0 + jag(xr);
  // the outline stays within [LO, HI], so this carries both halves out of the frame
  float reach = HI + 0.5 * roughness + 2.0 * rim + 0.02;
  // the top peels from the left, the bottom from the right
  float move = reach * p * p * (0.2 + 0.8 * p);
  float up = move * (1.0 + 0.12 * (1.0 - uv.x) * (1.0 - p));
  float down = move * (1.0 + 0.12 * uv.x * (1.0 - p));
  float fiber = smoothstep(0.0, 0.15, p);
  float aa = 0.0015;

  float ty = uv.y - up;
  float by = uv.y + down;
  vec4 to = getToColor(uv);
  float d = min(0.7 * (y0 - ty), 1.5 * (by - y0));
  float sh = shadow.a * fiber * (1.0 - smoothstep(0.7, 1.0, p)) * (1.0 - smoothstep(-0.02, 0.07, d));
  vec4 c = vec4(mix(to.rgb, shadow.rgb, sh), to.a);
  // the bottom half reaches under the top one so their seam is invisible at the start
  c = torn(c, getFromColor(vec2(uv.x, min(by, 1.0))), by - edge, fibers(xr, 2.0) * 1.4 * fiber + 0.003, aa, fiber);
  c = torn(c, getFromColor(vec2(uv.x, max(ty, 0.0))), edge - ty, fibers(xr, 0.0) * fiber, aa, fiber);
  return c;
}

// Author: Ben Zhang
// License: MIT
// Description: A crossfade through a washed-out, overexposed white
// Tags: flash, light, fade

// @param Amount of overexposure
uniform float strength; // = 0.6
const float PI = 3.141592653589793;

vec4 transition (vec2 uv) {
  vec4 from = getFromColor(uv);
  vec4 to = getToColor(uv);

  float from_m = 1.0 - progress + sin(PI * progress) * strength;
  float to_m = progress + sin(PI * progress) * strength;

  return vec4(
    from.r * from.a * from_m + to.r * to.a * to_m,
    from.g * from.a * from_m + to.g * to.a * to_m,
    from.b * from.a * from_m + to.b * to.a * to_m,
    mix(from.a, to.a, progress)
  );
}

// Author: gre
// License: MIT
// Description: The incoming image is poured in like a paint-bucket fill from two points: the areas of its picture that match the paint's colour flood in almost at once and stop at their outlines, then the bucket's tolerance widens and the other shapes fill in one after another, a light sheen running along the advancing fill
// Tags: fill, flood, regions, paint, structure

// @param First point the fill is poured from
uniform vec2 seedA; // = vec2(0.3, 0.7)
// @param Second point the fill is poured from
uniform vec2 seedB; // = vec2(0.75, 0.25)
// @range(0, 1) How firmly outlines hold the fill back
uniform float hold; // = 0.8

const float W = 0.025;

// a small disc average, so fine texture does not break a flat area into specks
vec3 smoothTo(vec2 uv) {
  vec2 px = vec2(0.008 / ratio, 0.008);
  vec3 c = getToColor(clamp(uv, 0.0, 1.0)).rgb;
  vec2 g = vec2(1.0, 0.0);
  mat2 turn = mat2(0.5, 0.8660254, -0.8660254, 0.5);
  for (int i = 0; i < 6; i++) {
    c += getToColor(clamp(uv + g * px, 0.0, 1.0)).rgb;
    g = turn * g;
  }
  return c / 7.0;
}

float dist(vec2 p, vec2 seed) {
  return length((p - seed) * vec2(ratio, 1.0));
}

float gap(vec2 p) {
  return min(dist(p, seedA), dist(p, seedB));
}

float reach(float d, vec3 here, vec3 paint) {
  // the bucket's tolerance widens with time: a colour unlike the paint's waits at its outline;
  // hue counts more than brightness, so shading inside a shape does not split it
  float lh = dot(here, vec3(1.0)), lp = dot(paint, vec3(1.0));
  float t = 2.5 * length(here / (lh + 0.15) - paint / (lp + 0.15)) + 0.2 * abs(lh - lp);
  t = max(t - 0.05, 0.0);
  float c = min(1.3 * t / (t + 0.3), 1.0);
  float a = 0.85 * (0.4 * d + hold * max(c - 0.4 * d, 0.0)) + 0.15 * d;
  // the most a can reach, with c and d at 1
  return a / (0.49 + 0.51 * hold);
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  vec3 here = smoothTo(uv);
  // the frame corner farthest from both seeds sets the pour's reach
  float far = max(max(gap(vec2(0.0)), gap(vec2(1.0))), max(gap(vec2(0.0, 1.0)), gap(vec2(1.0, 0.0))));
  float dA = dist(uv, seedA) / far, dB = dist(uv, seedB) / far;
  float arrive = min(reach(dA, here, smoothTo(seedA)), reach(dB, here, smoothTo(seedB)));
  // a late, slower pour crosses every outline anyway, so paints unlike the whole picture never stall
  float d = min(min(dA, dB), 1.0);
  arrive = min(arrive, mix(d, 0.5 + 0.5 * d, hold));
  // arrivals bunch in the middle of the range: run the front faster early and slower late
  float front = mix(-W, 1.0 + W, progress + 0.07 * sin(6.2831853 * progress));
  float m = 1.0 - smoothstep(front - W, front, arrive);
  float rim = m * (1.0 - smoothstep(0.0, 0.04, front - arrive)) * (1.0 - progress);
  return mix(a, vec4(mix(b.rgb, vec3(1.0), 0.4 * rim), b.a), m);
}

// Author: gre
// License: MIT
// Description: The incoming image is painted over the outgoing one in layers of brush strokes, broad flat strokes of its colors first, then smaller and smaller ones, until the last fine strokes lay down its full detail
// Tags: paint, brush, artistic, dissolve, texture

// @range(0.12, 0.5) Length of the broadest brush strokes, in frame heights
uniform float brushSize; // = 0.3
// @range(-90, 90) Main direction of the brush strokes, in degrees
uniform float angle; // = 25.0
// @range(0, 1) How much the direction of the strokes changes from one layer to the next
uniform float crossing; // = 0.5
// @range(0, 1) How thick the paint looks: relief and shine of the brush marks while it is wet
uniform float impasto; // = 0.6

const float PI = 3.141592653589793;
// a stroke is about 2.5 times longer than wide: its cell is that much longer than high
const float ROW = 0.4;

float pdHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec4 pdHash4(vec2 p) {
  vec4 p4 = fract(vec4(p.xyxy) * vec4(0.1031, 0.1030, 0.0973, 0.1099));
  p4 += dot(p4, p4.wzxy + 33.33);
  return fract((p4.xxyz + p4.yzzw) * p4.zywx);
}

float pdNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(pdHash(i), pdHash(i + vec2(1.0, 0.0)), f.x),
    mix(pdHash(i + vec2(0.0, 1.0)), pdHash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

vec2 pdFold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

// Strokes lie in rows along the direction of their layer, each row shifted by its own amount.
// A pixel looks for strokes in the 2 nearest cells of the 2 nearest rows: a stroke never reaches
// further than 1 cell along its row (0.76 + 0.06 at its dry end + 0.06 of antialiasing + 0.02 of tilt
// + 0.08 of jitter = 0.98) nor than 1 row across (0.2 + 0.06 of antialiasing + 0.05 of tilt + 0.04 of bend
// + 0.02 of jitter = 0.37, out of ROW = 0.4).
// Antialiasing is 0.0025 frame heights, which fits in 0.06 cells when cells are at least MIN_SIZE long.
const float MIN_SIZE = 0.042;

// center of the stroke of a cell (row in y) whose row is shifted by `shift`, in cells of its layer
vec2 pdCenter(vec2 cell, float shift, vec4 h) {
  return vec2(cell.x + 0.5 + shift + (h.x - 0.5) * 0.16, cell.y + 0.5 + (h.y - 0.5) * 0.1);
}

vec2 pdToUv(vec2 p, vec2 off, float size, vec2 dir) {
  vec2 l = (p - off) * vec2(size, size * ROW);
  vec2 q = dir * l.x + vec2(-dir.y, dir.x) * l.y;
  return q / vec2(ratio, 1.0) + 0.5;
}

// the stroke centered at c (in cells of layer k, offset by `off`) seen from p.
// returns (coverage, relief shading, start time, streaks)
vec4 pdStroke(vec2 p, vec2 c, vec2 cell, vec4 h, float size, float k, vec2 off, float t0, float spread, float dur, float dry, vec2 dir) {
  vec2 d = (p - c) * vec2(1.0, ROW); // in stroke lengths
  float tilt = (h.z - 0.5) * 0.12;
  float a = d.x + tilt * d.y; // along the stroke
  float b = d.y - tilt * d.x - (h.w - 0.5) * 0.12 * a * a; // across it
  float L = 0.66 + 0.1 * h.w;
  float W = 0.17 + 0.03 * h.z;
  float aa = 0.0025 / size;
  float bw = b / W; // -1..1 across the core of the stroke
  float u = clamp(a / L, -1.0, 1.0);
  if (abs(bw) > 1.0 - 0.2 * u * u + aa / W || a > L + 0.06 + aa || a < 0.12 * bw * bw - L - aa) return vec4(0.0);
  vec2 world = (c - off) * vec2(size, size * ROW);
  float order = 0.55 * pdNoise(world * 3.0 + k * 5.0) + 0.45 * pdHash(cell * 1.7 + vec2(k * 9.0, 3.0));
  float start = t0 + spread * clamp((order - 0.15) / 0.7, 0.0, 1.0); // (order is mostly in 0.15..0.85)
  float s = clamp((progress - start) / dur, 0.0, 1.0);
  if (s <= 0.0) return vec4(0.0);
  s = 1.0 - (1.0 - s) * (1.0 - s);
  float seed = h.x * 37.0 + k * 11.0;
  // bristle streaks along the stroke (fewer on small strokes, so that they stay a few pixels wide)
  float hairs = clamp(size * 50.0, 3.0, 16.0);
  float br = 0.6 * pdNoise(vec2(bw * 0.4 * hairs + seed, a * 2.0)) + 0.4 * pdNoise(vec2(bw * 0.8 * hairs - seed, a * 1.2 + 5.0));
  float width = (0.8 + 0.2 * (1.0 - u * u)) * (0.92 + 0.08 * pdNoise(vec2(a * 6.0, seed))) - 0.1 * br;
  float side = 1.0 - smoothstep(width - aa / W, width + aa / W, abs(bw));
  float tail = smoothstep(-aa, aa, a + L - 0.12 * bw * bw);
  float head = mix(-L - 0.1, L + 0.2, s);
  float lay = smoothstep(0.0, 0.25, (head - a) / 0.2 - 0.6 * br);
  float lift = smoothstep(-aa, aa, L + 0.12 * (br - 0.5) - a);
  if (side * lay * lift <= 0.0) return vec4(0.0);
  float fb = pdNoise(vec2(bw * hairs + seed, a * 0.9 - seed));
  float dryness = dry * smoothstep(0.1, 1.0, u);
  float cover = side * tail * lay * lift * (1.0 - dryness * (1.0 - smoothstep(0.3, 0.6, fb)));
  float ridge = bw * (1.0 - 0.5 * abs(bw)) * 0.8 + (br - 0.5) + 0.7 * (fb - 0.5);
  float facing = dot(vec2(-dir.y, dir.x), vec2(-0.6, 0.8));
  return vec4(cover, -ridge * facing, start, br);
}

// how much stroke x shows through stroke y: hidden by y where y was laid down after it
float pdUnder(vec4 x, vec4 y) {
  return y.z > x.z ? 1.0 - y.x : 1.0;
}

// paints one layer of strokes at an angle `th`, under those that let `left` of it through.
// solid layers take the color of the incoming image under the middle of each stroke, the detail
// layers lay down the incoming image itself (`detail`, at this pixel), with less dry gaps
void pdLayer(inout vec4 acc, inout float left, vec2 q, float size, float k, float th, float t0, float spread, float dur, bool solid, vec4 detail) {
  if (progress <= t0 || abs(left) < 0.001) return;
  size = max(size, MIN_SIZE);
  vec2 dir = vec2(cos(th), sin(th));
  vec2 off = vec2(k * 0.37, k * 0.61);
  vec2 p = vec2(dot(q, dir), dot(q, vec2(-dir.y, dir.x))) / vec2(size, size * ROW) + off;
  float r = floor(p.y - 0.5);
  float sh0 = pdHash(vec2(r, 7.3));
  float sh1 = pdHash(vec2(r + 1.0, 7.3));
  float x0 = floor(p.x - sh0 - 0.5);
  float x1 = floor(p.x - sh1 - 0.5);
  vec2 c0 = vec2(x0, r);
  vec2 c1 = vec2(x0 + 1.0, r);
  vec2 c2 = vec2(x1, r + 1.0);
  vec2 c3 = vec2(x1 + 1.0, r + 1.0);
  vec2 kk = vec2(k * 41.0, k * 17.0);
  vec4 h0 = pdHash4(c0 + kk);
  vec4 h1 = pdHash4(c1 + kk);
  vec4 h2 = pdHash4(c2 + kk);
  vec4 h3 = pdHash4(c3 + kk);
  vec2 m0 = pdCenter(c0, sh0, h0);
  vec2 m1 = pdCenter(c1, sh0, h1);
  vec2 m2 = pdCenter(c2, sh1, h2);
  vec2 m3 = pdCenter(c3, sh1, h3);
  float dry = solid ? 0.85 : 0.4;
  vec4 s0 = pdStroke(p, m0, c0, h0, size, k, off, t0, spread, dur, dry, dir);
  vec4 s1 = pdStroke(p, m1, c1, h1, size, k, off, t0, spread, dur, dry, dir);
  vec4 s2 = pdStroke(p, m2, c2, h2, size, k, off, t0, spread, dur, dry, dir);
  vec4 s3 = pdStroke(p, m3, c3, h3, size, k, off, t0, spread, dur, dry, dir);
  float v0 = s0.x * pdUnder(s0, s1) * pdUnder(s0, s2) * pdUnder(s0, s3);
  float v1 = s1.x * pdUnder(s1, s0) * pdUnder(s1, s2) * pdUnder(s1, s3);
  float v2 = s2.x * pdUnder(s2, s0) * pdUnder(s2, s1) * pdUnder(s2, s3);
  float v3 = s3.x * pdUnder(s3, s0) * pdUnder(s3, s1) * pdUnder(s3, s2);
  vec4 k0 = detail;
  vec4 k1 = detail;
  vec4 k2 = detail;
  vec4 k3 = detail;
  // only the strokes that show are sampled
  if (solid) {
    if (v0 > 0.0) k0 = getToColor(pdFold(pdToUv(m0, off, size, dir)));
    if (v1 > 0.0) k1 = getToColor(pdFold(pdToUv(m1, off, size, dir)));
    if (v2 > 0.0) k2 = getToColor(pdFold(pdToUv(m2, off, size, dir)));
    if (v3 > 0.0) k3 = getToColor(pdFold(pdToUv(m3, off, size, dir)));
  }
  float relief = impasto * (solid ? 0.18 : 0.12) * (1.0 - smoothstep(0.7, 0.95, progress));
  k0.rgb *= 1.0 + relief * (s0.y + 0.5 * (s0.w - 0.5));
  k1.rgb *= 1.0 + relief * (s1.y + 0.5 * (s1.w - 0.5));
  k2.rgb *= 1.0 + relief * (s2.y + 0.5 * (s2.w - 0.5));
  k3.rgb *= 1.0 + relief * (s3.y + 0.5 * (s3.w - 0.5));
  float vis = v0 + v1 + v2 + v3;
  acc += left * (k0 * v0 + k1 * v1 + k2 * v2 + k3 * v3);
  left *= 1.0 - vis;
}

vec4 transition(vec2 uv) {
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  vec4 to = getToColor(uv);
  float sz = brushSize;
  float th = angle * PI / 180.0;
  float x = crossing * 0.6;
  vec4 col = vec4(0.0);
  float left = 1.0;
  pdLayer(col, left, q, sz * 0.2, 4.0, th - x * 0.3, 0.68, 0.2, 0.08, false, to);
  pdLayer(col, left, q, sz * 0.22, 3.0, th + x * 0.4, 0.56, 0.22, 0.08, false, to);
  pdLayer(col, left, q, sz * 0.36, 2.0, th - x * 0.7, 0.38, 0.26, 0.09, true, to);
  pdLayer(col, left, q, sz * 0.6, 1.0, th + x, 0.2, 0.28, 0.1, true, to);
  pdLayer(col, left, q, sz, 0.0, th, 0.0, 0.3, 0.12, true, to);
  col += left * getFromColor(uv);
  col = mix(col, to, smoothstep(0.92, 1.0, progress));
  return clamp(col, 0.0, 1.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image is a sheet of paper that folds in half in 3D along a vertical crease, then in half again along a horizontal one, its lit and shaded faces turning to show the back of the paper, and the small folded packet flies off the frame, leaving its shadow on the incoming image underneath
// Tags: paper, fold, 3d, shadow
// Preview: 0.2

// @param Direction the folded packet flies off toward
uniform vec2 direction; // = vec2(1.0, 0.5)
// @range(0, 1) How much the sheet tilts and recedes while it folds, so that the folds are seen in 3D
uniform float tilt; // = 0.6
// @range(0, 1) How much the faces darken as they turn away from the light, and the shadows they cast
uniform float shading; // = 0.6
// @color Color of the back of the paper, through which the print faintly shows
uniform vec4 paper; // = vec4(0.95, 0.94, 0.9, 1.0)

const float PI = 3.141592653589793;
const float EDGE = 0.0015;
const float SHOW = 0.1;
const float CREASE = 0.02;
const vec3 LIGHT = vec3(-0.3995, 0.4494, 0.799);

vec4 front(vec2 st) {
  return getFromColor(st / vec2(ratio, 1.0));
}

vec4 back(vec2 st) {
  vec4 c = front(st);
  return vec4(mix(paper.rgb, c.rgb, SHOW), c.a * paper.a);
}

// the face of the packet's top layer: the image itself during the first fold, then the back
// of the right half, laid mirrored over the left half
vec4 topFace(vec2 st, bool second) {
  return second ? back(vec2(ratio - st.x, st.y)) : front(st);
}

// distance inside the rectangle [0, h] x [0, k] (negative outside)
float inside(vec2 p, float h, float k) {
  return min(min(p.x, h - p.x), min(p.y, k - p.y));
}

// The sheet in its own frame: a flat part [0, h] x [0, k] lying at z = 0 and a flap of the same
// size hinged on its edge x = h, turned toward the viewer so that it lies along `along`, with the
// normal n. During the second fold, x and y are swapped so that the crease is always along y.
// Where the ray o + t * v meets the flap's plane: (t, distance from the hinge, y), t < 0 if never.
vec3 hitFlap(vec3 o, vec3 v, float h, vec3 n, vec3 along) {
  float den = dot(n, v);
  if (abs(den) < 1e-5) return vec3(-1.0, 0.0, 0.0);
  vec3 hinge = vec3(h, 0.0, 0.0);
  float t = dot(n, hinge - o) / den;
  vec3 q = o + t * v;
  return vec3(t, dot(q - hinge, along), q.y);
}

// how much the point q is shaded, lit by l: by the flap, and by the flat part once it lifts
// above the incoming image
float shadowAt(vec3 q, vec3 l, float h, float k, vec3 n, vec3 along) {
  float sh = 0.0;
  if (q.z < -1e-4) {
    float soft = 0.004 - 0.4 * q.z;
    sh = smoothstep(-soft, soft, inside(q.xy - q.z / l.z * l.xy, h, k));
  }
  vec3 hit = hitFlap(q, l, h, n, along);
  if (hit.x > 0.0) {
    float height = hit.x * l.z;
    float soft = 0.004 + 0.3 * height;
    sh = max(sh, min(4.0 * n.x * n.x, 1.0) * smoothstep(-soft, soft, inside(hit.yz, h, k)) / (1.0 + 3.0 * height));
  }
  return sh;
}

// a vector of the frame into the frame of the sheet, turned by yaw (around y), pitch (around x)
// and spin (around z), each given as (cos, sin)
vec3 toSheet(vec3 v, vec2 yaw, vec2 pitch, vec2 spin) {
  v = vec3(yaw.x * v.x + yaw.y * v.z, v.y, yaw.x * v.z - yaw.y * v.x);
  v = vec3(v.x, pitch.x * v.y + pitch.y * v.z, pitch.x * v.z - pitch.y * v.y);
  return vec3(spin.x * v.x + spin.y * v.y, spin.x * v.y - spin.y * v.x, v.z);
}

vec4 transition(vec2 uv) {
  float w = ratio;
  float shade = clamp(shading, 0.0, 1.0);
  float s = 2.0 * smoothstep(0.0, 0.62, progress);
  bool second = s > 1.0;
  float x = second ? s - 1.0 : s;
  float a = PI * mix(x, x * x * (3.0 - 2.0 * x), 0.6);
  float f = clamp((progress - 0.5) / 0.47, 0.0, 1.0);

  float turn = clamp(tilt, 0.0, 1.0) * (smoothstep(0.0, 0.25, progress) - smoothstep(0.4, 0.8, progress));
  vec2 yaw = vec2(cos(0.45 * turn), sin(0.45 * turn));
  vec2 pitch = vec2(cos(0.55 * turn), -sin(0.55 * turn));
  float dist = 2.5 * max(w, 1.0);
  float recede = dist * 0.35 * turn;

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  // the point of the sheet held in the middle of the frame slides to the middle of the packet
  vec2 c = vec2(0.5 * w - 0.25 * w * min(s, 1.0), 0.5 - 0.25 * max(s - 1.0, 0.0));
  float reach = 0.5 * (abs(dir.x) * w + abs(dir.y)) + length(vec2(0.25 * w, 0.25)) + 0.4;
  float lift = 0.3 * smoothstep(0.0, 0.5, f);
  float turned = (dir.x < 0.0 ? 0.7 : -0.7) * f * f;
  vec2 spin = vec2(cos(turned), sin(turned));

  // the eye, the ray toward the point of the frame and the light, in the frame of the sheet,
  // where the sheet lies on the plane z = 0 and the incoming image on z = -lift
  vec3 center = vec3(vec2(0.5 * w, 0.5) + dir * reach * f * f, -recede);
  vec3 eye = vec3(0.5 * w, 0.5, dist);
  vec3 e = toSheet(eye - center, yaw, pitch, spin) + vec3(c, 0.0);
  vec3 d = toSheet(vec3(uv.x * w, uv.y, 0.0) - eye, yaw, pitch, spin);
  vec3 l = toSheet(LIGHT, yaw, pitch, spin);
  if (second) {
    e.xy = e.yx;
    d.xy = d.yx;
    l.xy = l.yx;
  }
  float h = second ? 0.5 : 0.5 * w;
  float k = second ? 0.5 * w : 1.0;
  float creased = sin(a);
  vec3 n = vec3(-creased, 0.0, cos(a));
  vec3 along = vec3(cos(a), 0.0, creased);

  vec4 col = getToColor(uv);
  if (d.z < 0.0) {
    vec3 g = e + d * (e.z + lift) / -d.z;
    col.rgb *= 1.0 - 0.7 * shade * (1.0 - f * f) * shadowAt(g, l, h, k, n, along);
  }

  float t = d.z < 0.0 ? e.z / -d.z : -1.0;
  vec3 p = e + t * d;
  float m = clamp(inside(p.xy, h, k) / (EDGE * t) + 1.0, 0.0, 1.0);
  if (t > 0.0 && m > 0.0) {
    vec4 img = topFace(second ? p.yx : p.xy, second);
    float sh = shadowAt(p, l, h, k, n, along);
    img.rgb *= (1.0 - 0.7 * shade * sh) * (1.0 - 0.5 * shade * creased * exp(-abs(h - p.x) / CREASE));
    col = mix(col, img, m);
  }

  vec3 hit = hitFlap(e, d, h, n, along);
  if (hit.x > 0.0) {
    float r = hit.y;
    // edges seen at a grazing angle are narrower on screen
    float dr = dot(along, normalize(d));
    float fore = sqrt(max(1.0 - dr * dr, 0.0025));
    float mf = clamp(min(min(r, h - r) * fore, min(hit.z, k - hit.z)) / (EDGE * hit.x) + 1.0, 0.0, 1.0);
    if (mf > 0.0) {
      bool up = dot(n, e - vec3(h, 0.0, 0.0)) > 0.0;
      vec2 st = vec2(h + r, hit.z);
      if (second) st = st.yx;
      vec4 img = up ? topFace(st, second) : back(st);
      // lit by the light, relative to the sheet lying flat
      float lit = dot(up ? n : -n, l) - l.z;
      img.rgb *= max(1.0 + 0.6 * shade * lit, 0.0) * (1.0 - 0.5 * shade * creased * exp(-abs(r) / CREASE));
      col = mix(col, img, mf);
    }
  }
  return col;
}

// Author: gre
// License: MIT
// Description: The incoming image is rebuilt as a stack of cut paper sheets, one per band of brightness: from the darkest to the lightest, each sheet slides in lifted above the stack, drops into place with a soft shadow on the sheets below, then the paper flattens into the photo
// Tags: paper, layers, cut, shadow, stylized
// Preview: 0.6

// @range(2, 8, 1) Number of paper sheets, one per band of brightness of the incoming image
uniform int layers; // = 5
// @range(0, 1) How much of the incoming image's colors the paper takes: 0 is plain paper in shades of the paper color
uniform float colorful; // = 0.7
// @range(0, 1) Darkness of the shadows the sheets cast on the ones below
uniform float shadow; // = 0.6
// @color Color of the lightest sheet of paper, the darker ones are shades of it
uniform vec4 paper; // = vec4(0.97, 0.94, 0.88, 1.0)

const float MAX_LAYERS = 8.0;
// part of the progress at which the last sheet lands, and longest duration of the slide of one sheet
const float STACKED = 0.74;
const float SLIDE = 0.2;
// height a sheet falls from, as the extra distance its shadow is cast at
const float LIFT = 3.0;
const vec2 SHADOW = vec2(0.012, -0.018);
// softness of the cut edges and of the shadows' edges, in brightness
const float CUT = 0.012;
const float SHADOW_CUT = 0.05;
// radius over which the brightness is softened before it is cut, so that the cuts follow smooth curves,
// and the wider one for the shadows, in frame heights
const float BLUR = 0.004;
const float SHADOW_BLUR = 0.01;
const float EDGE = 0.0015;

float luma(vec4 c) {
  return dot(c.rgb, vec3(0.299, 0.587, 0.114));
}

float plHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float grain(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(plHash(i), plHash(i + vec2(1.0, 0.0)), f.x),
    mix(plHash(i + vec2(0.0, 1.0)), plHash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// mirrored coordinates, so that a shifted lookup never smears the frame's border
vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// brightness of the incoming image at p (whose color is c) softened over a disc of the given radius in frame heights
float softLuma(vec2 p, vec4 c, float radius, vec2 aspect) {
  vec2 r = radius / aspect;
  float l = luma(c);
  l += luma(getToColor(mirror(p + r * vec2(0.0, 1.0))));
  l += luma(getToColor(mirror(p + r * vec2(0.866, -0.5))));
  l += luma(getToColor(mirror(p + r * vec2(-0.866, -0.5))));
  return l / 4.0;
}

// coverage of sheet k of n: the whole frame for the first one, else where the softened brightness l reaches its threshold
float cut(float k, float n, float l, float soft) {
  if (k < 0.5) return 1.0;
  float thr = k / n;
  return smoothstep(thr - soft, thr + soft, l);
}

vec4 transition(vec2 uv) {
  float n = clamp(float(layers), 2.0, MAX_LAYERS);
  float sh = clamp(shadow, 0.0, 1.0);
  vec2 aspect = vec2(ratio, 1.0);
  vec2 shadowOffset = SHADOW / aspect;
  float toPhoto = smoothstep(STACKED - 0.03, 1.0, progress);

  // the incoming image where the sheets lie on the stack, and where they cast their shadow
  // (only looked up once the first sheet has landed)
  vec4 rest = getToColor(uv);
  float restLuma = 0.0;
  vec4 restShadowColor = vec4(0.0);
  float restShadow = 0.0;
  float n1 = n - 1.0;
  // duration of the slide of one sheet, short enough that at most two sheets slide at once
  float slide = min(SLIDE, 2.0 * STACKED / (n1 + 2.0));
  float spacing = (STACKED - slide) / n1;
  if (progress >= slide) {
    restLuma = softLuma(uv, rest, BLUR, aspect);
    vec2 ps = uv - shadowOffset;
    restShadowColor = getToColor(mirror(ps));
    restShadow = softLuma(ps, restShadowColor, SHADOW_BLUR, aspect);
  }

  vec4 color = getFromColor(uv);
  for (float k = 0.0; k < MAX_LAYERS; k += 1.0) {
    if (k < n) {
      float t = clamp((progress - k * spacing) / slide, 0.0, 1.0);
      if (t > 0.0) {
        float e = 1.0 - (1.0 - t) * (1.0 - t) * (1.0 - t);
        float lift = 1.0 - smoothstep(0.5, 1.0, t);
        vec2 q = (uv - 0.5) / (1.0 + 0.03 * lift) + 0.5;
        q.y -= (1.0 - e) * 1.15;
        vec2 so = shadowOffset * (1.0 + LIFT * lift);
        vec4 src = rest;
        float l = restLuma;
        float ls = restShadow;
        float shadowAlpha = restShadowColor.a;
        if (t < 1.0) {
          src = getToColor(mirror(q));
          l = softLuma(q, src, BLUR, aspect);
          vec4 cs = getToColor(mirror(q - so));
          ls = softLuma(q - so, cs, SHADOW_BLUR, aspect);
          shadowAlpha = cs.a;
        }
        float m = cut(k, n, l, CUT) * src.a * smoothstep(-EDGE, EDGE, q.y);
        float s = cut(k, n, ls, SHADOW_CUT) * shadowAlpha * smoothstep(-EDGE, EDGE, q.y - so.y);
        color.rgb *= 1.0 - sh * (1.0 - toPhoto) * (0.7 - 0.35 * lift) * s * (1.0 - m);
        // the sheet's color: a shade of paper for its band of brightness, tinted by the photo
        // (the dark bands are lifted a little, as paper is never black)
        float level = 0.25 + 0.75 * k / n1;
        vec3 plain = paper.rgb * level;
        vec3 tinted = clamp(level + 1.25 * (src.rgb - luma(src)), 0.0, 1.0);
        vec3 sheet = mix(plain, tinted, 0.9 * clamp(colorful, 0.0, 1.0));
        sheet *= 0.975 + 0.05 * grain(q * aspect * 160.0 + k * 37.0);
        color = mix(color, vec4(sheet, paper.a), m);
      }
    }
  }
  return mix(color, rest, toPhoto);
}

// Author: gre
// License: MIT
// Description: The outgoing image is folded into a paper plane: its two left corners fold back to the middle, it folds in half behind itself, the wings fold out, and the plane banks and glides away into the distance over the incoming image
// Tags: paper, fold, origami, plane, 3d, fly

// @range(0, 1) Darkness of the faces turned away from the light and of the plane's shadow
uniform float shading; // = 0.5
// @color Color of the back of the paper
uniform vec4 paper; // = vec4(0.96, 0.95, 0.91, 1.0)

const float PI = 3.141592653589793;
const float K = 0.1;
// the corner folds run from the nose to this far along the top and bottom edges
const float HINGE = 0.75;
const float CAM = 2.6;
const vec3 LIGHT = vec3(-0.36, 0.48, 0.8);

float W, af, ah, aw, roll, yaw;
bool portrait;
vec2 hu;
vec3 shift;

vec3 rot(vec3 p, vec3 a, vec3 d, float ang) {
  p -= a;
  float c = cos(ang), s = sin(ang);
  return a + p * c + cross(d, p) * s + d * dot(d, p) * (1.0 - c);
}

// sheet point (x in [0, W], y in [-0.5, 0.5], z = 0) to world, for one piece of the plane
vec3 place(vec3 p, bool top, bool flap, bool wing) {
  if (flap) p = rot(p, vec3(0.0), vec3(hu.x, top ? hu.y : -hu.y, 0.0), top ? -af : af);
  if (!top) p = rot(p, vec3(0.0), vec3(1.0, 0.0, 0.0), ah);
  if (wing) p = rot(p, vec3(0.0), normalize(vec3(1.0, K, 0.0)), top ? aw : -aw);
  vec3 pivot = vec3(0.5 * W, 0.1, 0.0);
  p = rot(p, pivot, vec3(1.0, 0.0, 0.0), roll);
  p = rot(p, pivot, vec3(0.0, 0.0, 1.0), yaw);
  return p - vec3(0.5 * W, 0.0, 0.0) + shift;
}

// signed distance inside the piece, in sheet coordinates: (outer edges, creases)
vec2 inside(vec2 s, bool top, bool flap, bool wing) {
  float d = min(min(s.x, W - s.x), min(s.y + 0.5, 0.5 - s.y));
  vec2 m = vec2(s.x, top ? s.y : -s.y);
  float hinge = m.x * hu.y - m.y * hu.x;
  // a flap is seen where it lands, mirrored across its hinge; the part that would cross the
  // middle is dropped once it is hidden behind the sheet
  vec2 f = flap ? 2.0 * dot(m, hu) * hu - m : m;
  float n = inversesqrt(1.0 + K * K);
  float crease = (K * f.x - f.y) * n;
  float c = min(min(m.y, flap ? -hinge : hinge), wing ? -crease : crease);
  if (flap && af > 0.6 * PI) c = min(c, f.y);
  return vec2(d, c);
}

// n faces the camera
vec4 shadeFace(vec2 s, vec3 n, bool front) {
  float lit = clamp(dot(n, LIGHT), 0.0, 1.0);
  vec2 t = vec2(s.x / W, s.y + 0.5);
  vec4 c = front ? getFromColor(portrait ? vec2(t.y, 1.0 - t.x) : t) : paper;
  // flat on the frame (lit == LIGHT.z) the face keeps its exact color
  c.rgb *= lit < LIGHT.z ? 1.0 - shading * (LIGHT.z - lit) / LIGHT.z : 1.0 + 0.3 * shading * (lit - LIGHT.z) / (1.0 - LIGHT.z);
  return c;
}

vec4 transition(vec2 uv) {
  // the nose points along the long side of the frame
  portrait = ratio < 1.0;
  W = portrait ? 1.0 / ratio : ratio;
  vec2 st = portrait ? vec2(1.0 - uv.y, uv.x) : uv;
  hu = normalize(vec2(HINGE * W, 0.5));
  float p = progress;
  float e1 = smoothstep(0.0, 0.24, p);
  float e2 = smoothstep(0.2, 0.42, p);
  float e3 = smoothstep(0.4, 0.62, p);
  float e4 = smoothstep(0.55, 1.0, p);
  af = PI * e1 * 0.999;
  ah = PI * e2 * 0.999;
  // wings stop short of flat so they keep a slight V
  aw = 0.4 * PI * e3;
  roll = -0.9 * e3 + 0.35 * sin(PI * e4);
  yaw = -0.25 * e3 - 0.2 * e4;
  float f = e4 * e4;
  shift = vec3(0.35 * e3 - 3.3 * f, 0.15 * e3 + 2.2 * f, -1.2 * e3 - 5.5 * f);

  vec3 O[8], EX[8], EY[8];
  for (int i = 0; i < 8; i++) {
    bool top = i < 4;
    bool flap = mod(float(i), 4.0) > 1.5;
    bool wing = mod(float(i), 2.0) > 0.5;
    O[i] = place(vec3(0.0), top, flap, wing);
    EX[i] = place(vec3(1.0, 0.0, 0.0), top, flap, wing) - O[i];
    EY[i] = place(vec3(0.0, 1.0, 0.0), top, flap, wing) - O[i];
  }

  vec3 ro = vec3(0.0, 0.0, CAM);
  vec3 rd = normalize(vec3((st - 0.5) * vec2(W, 1.0), 0.0) - ro);
  float px = 0.003;

  // the two nearest layers, so a crease edge blends with the layer behind it, not the background
  float t1 = 1e4, t2 = 1e4, k1 = -1.0, k2 = -1.0;
  vec2 s1 = vec2(0.0), s2 = vec2(0.0);
  vec3 n1 = vec3(0.0), n2 = vec3(0.0);
  float a1 = 0.0, a2 = 0.0;
  bool f1 = true, f2 = true;
  for (int i = 0; i < 8; i++) {
    bool top = i < 4;
    bool flap = mod(float(i), 4.0) > 1.5;
    bool wing = mod(float(i), 2.0) > 0.5;
    vec3 n = cross(EX[i], EY[i]);
    float den = dot(rd, n);
    if (abs(den) < 1e-4) continue;
    float t = dot(O[i] - ro, n) / den;
    vec3 q = ro + t * rd - O[i];
    vec2 s = vec2(dot(q, EX[i]), dot(q, EY[i]));
    vec2 dd = inside(s, top, flap, wing);
    // pieces are widened by a pixel so neighbours overlap without a seam and the flat sheet covers the frame;
    // between coplanar pieces the one the pixel lies deepest in wins; between stacked ones, the nearer one if it covers it
    float d = min(dd.x, dd.y) + px;
    if (t <= 0.0 || d <= -px) continue;
    // a piece seen edge-on is thinner than a pixel, so it fades instead of aliasing
    float a = smoothstep(-px, px, d) * smoothstep(0.0, 0.1, abs(den));
    vec3 nf = den < 0.0 ? n : -n;
    // a (nearly) coplanar piece never becomes the layer behind, or it would hide the real one where both end on a crease
    if (abs(t - t1) < 0.01) {
      bool take = abs(t - t1) < 1e-4 ? dd.y > k1 : (t < t1 ? dd.y > 0.0 || dd.y > k1 : k1 < 0.0 && dd.y > k1);
      if (take) { t1 = t; s1 = s; n1 = nf; k1 = dd.y; f1 = den < 0.0; }
      a1 = max(a1, a);
    } else if (t < t1) {
      t2 = t1; s2 = s1; n2 = n1; a2 = a1; f2 = f1; k2 = k1;
      t1 = t; s1 = s; n1 = nf; a1 = a; k1 = dd.y; f1 = den < 0.0;
    } else if (abs(t - t2) < 0.01) {
      bool take = abs(t - t2) < 1e-4 ? dd.y > k2 : (t < t2 ? dd.y > 0.0 || dd.y > k2 : k2 < 0.0 && dd.y > k2);
      if (take) { t2 = t; s2 = s; n2 = nf; k2 = dd.y; f2 = den < 0.0; }
      a2 = max(a2, a);
    } else if (t < t2) {
      t2 = t; s2 = s; n2 = nf; a2 = a; f2 = den < 0.0; k2 = dd.y;
    }
  }

  vec4 bg = getToColor(uv);
  // the plane's shadow on the incoming image, seen as a table that stays below it as it flies off
  vec3 g = ro + rd * (CAM - shift.z + 0.6) / -rd.z;
  float sh = 0.0;
  for (int i = 0; i < 8; i++) {
    if (a1 >= 1.0) break;
    bool top = i < 4;
    bool flap = mod(float(i), 4.0) > 1.5;
    bool wing = mod(float(i), 2.0) > 0.5;
    vec3 n = cross(EX[i], EY[i]);
    float den = dot(LIGHT, n);
    if (abs(den) < 1e-4) continue;
    float t = dot(O[i] - g, n) / den;
    vec3 q = g + t * LIGHT - O[i];
    vec2 dd = inside(vec2(dot(q, EX[i]), dot(q, EY[i])), top, flap, wing);
    // the penumbra widens with the height above the table; creases are overlapped so they cast no light seams
    float w = 0.005 + 0.03 * t;
    if (t > 0.0) sh = max(sh, smoothstep(-w, w, min(dd.x, dd.y + 2.0 * w)) / (1.0 + t));
  }
  bg.rgb *= 1.0 - 0.6 * shading * sh * (1.0 - e4);

  vec4 col = bg;
  if (a2 > 0.0) col = mix(col, shadeFace(s2, n2, f2), a2);
  if (a1 > 0.0) col = mix(col, shadeFace(s1, n1, f1), a1);
  return col;
}

// Author: gre
// License: MIT
// Description: The outgoing image tears in two along a ragged line, and the halves are pulled apart to reveal the incoming one
// Tags: split, horizontal, shadow

// @range(0, 0.3) How far the tear wanders from the middle, relative to the image height
uniform float roughness; // = 0.12
// @range(0, 0.5) How much the top of each half leans away first, so that the tear opens from the top
uniform float tilt; // = 0.1
// @range(0, 0.05) Width of the white torn edge, relative to the image height
uniform float rim; // = 0.012
// @color Color of the paper fibers on the torn edges
uniform vec4 paper; // = vec4(1.0, 0.98, 0.94, 1.0)
// @color Color of the shadow cast on the incoming image
uniform vec4 shadow; // = vec4(0.0, 0.0, 0.0, 0.35)

float tri (float x) {
  return abs(fract(x) - 0.5) - 0.25;
}

// horizontal position of the tear at height y: smooth meanders...
float meander (float y) {
  return 0.5 * ratio + roughness * (0.5 * sin(y * 4.7 + 1.3) + 0.25 * sin(y * 11.3 + 4.1));
}

// ...and sharp jags
float tear (float y) {
  return meander(y) + roughness * (0.1 * sin(y * 29.0 + 0.7) + 0.35 * tri(y * 19.0 + sin(y * 7.0)) + 0.12 * tri(y * 47.0 + 0.6 * sin(y * 13.0)));
}

float fibers (float y, float seed) {
  return rim * (0.7 + 0.3 * sin(y * 37.0 + seed) + 0.4 * tri(y * 83.0 + seed));
}

// the left half (or the mirrored right half) slides out, its top leaning away first:
// from a point on screen to the point of the paper (the frame edges stay covered)
vec2 unfold (vec2 q, float away, float lean) {
  return vec2(q.x + away + lean * q.y, q.y);
}

// a torn half over bg; e: distance past the torn edge, limit: how far the fibers reach, aa: edge softness
vec4 torn (vec4 bg, vec4 col, float e, float limit, float aa) {
  vec4 c = vec4(mix(col.rgb, paper.rgb, clamp(0.5 + e / aa, 0.0, 1.0) * paper.a), col.a);
  return mix(bg, c, clamp(0.5 - (e - limit) / aa, 0.0, 1.0));
}

vec4 transition (vec2 uv) {
  float p = progress;
  float away = p * p * (0.5 * ratio + 0.1 + roughness + 2.0 * rim); // far enough to leave the frame
  float lean = tilt * p * (2.0 - p);
  float fiber = smoothstep(0.0, 0.15, p); // no torn edge on the intact image
  float aa = 0.002 * fiber + 1e-6;
  vec2 q = vec2(uv.x * ratio, uv.y);
  vec2 l = unfold(q, away, lean);
  vec2 r = unfold(vec2(ratio - q.x, q.y), away, lean);
  float el = l.x - tear(l.y); // > 0 right of the left half's torn edge
  float er = r.x - (ratio - tear(r.y)); // > 0 left of the right half's torn edge
  vec2 sq = q - vec2(0.01, 0.0);
  float dl = unfold(sq, away, lean).x - meander(sq.y);
  float dr = unfold(vec2(ratio - sq.x, sq.y), away, lean).x - (ratio - meander(sq.y));
  vec4 to = getToColor(uv);
  float sh = shadow.a * (1.0 - smoothstep(-0.02, 0.08, min(dl, dr)));
  vec4 c = vec4(mix(to.rgb, shadow.rgb, sh), to.a);
  if (r.x >= 0.0) {
    c = torn(c, getFromColor(vec2(1.0 - r.x / ratio, r.y)), er, fibers(r.y, 2.0) * 1.5 * fiber, aa);
  }
  if (l.x >= 0.0) {
    c = torn(c, getFromColor(vec2(l.x / ratio, l.y)), el, fibers(l.y, 0.0) * fiber, aa);
  }
  return c;
}

// Author: gre
// License: MIT
// Description: The camera tracks sideways past a dark, out-of-focus pillar standing close to the lens: the pillar rushes across the frame while the images far behind it drift slowly the same way with a slight push in, and the cut to the incoming image happens hidden behind it
// Tags: push, parallax, depth, camera, wipe, directional

// @param Direction in which everything moves, snapped to its main axis (left, right, up or down)
uniform vec2 direction; // = vec2(-1.0, 0.0)
// @range(0, 0.25) How far each image drifts behind the pillar, as a part of the frame
uniform float parallax; // = 0.1
// @range(0.1, 1) Width of the pillar, as a part of the shorter side of the frame
uniform float width; // = 0.45
// @range(0, 1) How out of focus the pillar is, and how much it blurs as it rushes past
uniform float blur; // = 0.5
// @color Color of the pillar, lit from the side it moves toward
uniform vec4 pillar; // = vec4(0.2, 0.17, 0.15, 1.0)

// mirror the coordinates back into the frame
vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  // the main axis of the direction, to the left when there is none
  vec2 d = abs(direction.x) >= abs(direction.y)
    ? vec2(direction.x > 0.0 ? 1.0 : -1.0, 0.0)
    : vec2(0.0, direction.y > 0.0 ? 1.0 : -1.0);
  // u: position along the motion in frame heights, from 0 on the side everything comes from to len
  float len = d.x != 0.0 ? ratio : 1.0;
  float u = (dot(uv - 0.5, d) + 0.5) * len;
  // v: across the motion, 0 to 1
  float v = d.x != 0.0 ? uv.y : uv.x;

  float p = progress;
  // the camera's travel: eased in and out, with a little linear motion so it never stands still
  float e = 0.7 * p * p * (3.0 - 2.0 * p) + 0.3 * p;
  float speed = 0.7 * 6.0 * p * (1.0 - p) + 0.3;

  // the images, far away, drift slowly: the outgoing one leaves the way it moves, the incoming one
  // comes from the opposite side, so each is exactly in place at its end of the transition. Each
  // is scaled up just enough that its drift never reaches past its edges
  float drift = clamp(parallax, 0.0, 0.25);
  float da = drift * e;
  float db = drift * (1.0 - e);
  vec4 a = getFromColor(mirror(0.5 + (uv - 0.5) * (1.0 - 2.0 * da) - d * da));
  vec4 b = getToColor(mirror(0.5 + (uv - 0.5) * (1.0 - 2.0 * db) + d * db));

  // the pillar, close to the lens, crosses the whole frame. Its edges are soft: out of focus, and
  // smeared by its own speed on screen, but it starts and ends fully out of frame
  float w = clamp(width, 0.1, 1.0) * min(ratio, 1.0);
  float bl = clamp(blur, 0.0, 1.0);
  float defocus = w * (0.02 + 0.08 * bl);
  // the motion blur follows the pillar's speed on screen, about len + w frame heights per progress
  float smear = 0.035 * bl * (len + w);
  float soft = min(defocus + smear * speed, 0.8 * w);
  // at both ends (where the speed is 0.3) the pillar's blurred edge just touches the frame's edge
  float reach = 0.5 * w + 0.5 * min(defocus + smear * 0.3, 0.8 * w) + 0.001;
  float c = -reach + (len + 2.0 * reach) * e;
  // x: across the pillar, -1 on its leading edge to 1 on its trailing edge
  float x = (c - u) / (0.5 * w);
  float edge = soft / w;
  float cover = 1.0 - smoothstep(1.0 - edge, 1.0 + edge, abs(x));
  if (cover <= 0.0) return u < c ? b : a;

