  if (flip <= 0.0) {
    col = tree(P, s0, false, thr, dmax, seamFade);
  } else if (flip >= 1.0) {
    col = tree(P, s0, true, thr, dmax, seamFade);
  } else {
    col = mix(tree(P, s0, false, thr, dmax, seamFade), tree(P, s0, true, thr, dmax, seamFade), flip);
