    behind(x - bend * (1.0 + disp), uv.y, cut, soft).r,
    g.g,
    behind(x - bend * (1.0 - disp), uv.y, cut, soft).b,
    g.a
  );

  float seam = smoothstep(0.82, 1.0, abs(u));
  float hl = (u + 0.45) / 0.16;
