// @range(0, 3) Length of the teeth, relative to their width
uniform float depth; // = 1.0
// @param Two toothed edges part from the middle instead of one sweeping across
uniform bool jaws; // = false
// @range(0, 0.1) Softness of the edge
uniform float smoothness; // = 0.004

const float AA = 0.0015;

// signed distance to a zigzag line of period w and peak-to-peak height h, centered on y = 0,
// its tips pointing up at x = 0; positive above it
float zigzag(vec2 q, float w, float h) {
  // fold into half a tooth: the slope from the bottom of a notch to the tip of a tooth
  float x = abs(fract(q.x / w) - 0.5) * w;
  vec2 a = vec2(0.0, -0.5 * h);
  vec2 ab = vec2(0.5 * w, h);
  vec2 aq = vec2(x, q.y) - a;
  float d = length(aq - ab * clamp(dot(aq, ab) / dot(ab, ab), 0.0, 1.0));
  return q.y > h * (2.0 * x / w - 0.5) ? d : -d;
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  // measured in square pixels, so the teeth are not stretched
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float e = 0.5 * (abs(dir.x) * ratio + abs(dir.y));
  float w = 0.5 * (abs(dir.y) * ratio + abs(dir.x));
  float period = 2.0 * w / float(teeth < 1 ? 1 : teeth);
  // position across the edge, with the notches on the sides of the frame so that it shows
  // whole teeth, and along the direction
  vec2 q = vec2(dot(p, vec2(-dir.y, dir.x)) + w + 0.5 * period, dot(p, dir));
  float h = max(depth, 0.0) * period;
  // the soft edge never gets wide enough to blur small teeth away
  float s = max(min(smoothness, 0.25 * period), AA);
  float t = mix(progress, progress * progress * (3.0 - 2.0 * progress), 0.35);

  float d;
  if (jaws) {
    // the two edges are the same zigzag, interlocked at the start (crossed by the soft
    // edge, measured across the slopes of the teeth), then moving apart until each one
    // has left the frame on its side
    float overlap = s * sqrt(1.0 + 4.0 * h * h / (period * period));
    float o = mix(-overlap, e + 0.5 * h + s, t);
    d = max(zigzag(q - vec2(0.0, o), period, h), -zigzag(q + vec2(0.0, o), period, h));
  } else {
    // the edge starts fully ahead of the frame and ends fully past it
    float c = mix(-e - 0.5 * h - s, e + 0.5 * h + s, t);
    d = zigzag(q - vec2(0.0, c), period, h);
  }
  // > 0 where the incoming image shows
  float m = 1.0 - smoothstep(-s, s, d);

  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A squeegee sweeps back and forth across the frame four times, pushing a bead of ink ahead of its blade and printing the incoming image one halftone ink at a time, yellow, magenta, cyan then black, slightly out of register and streaky, until the layers settle into register and the dots melt into the full picture
// Tags: print, ink, halftone, cmyk, squeegee, wipe

// @range(30, 160) Number of halftone dots across the frame height: more makes a finer screen, which can shimmer at small sizes
uniform float dots; // = 70.0
// @range(0, 0.03) How far the ink layers are printed out of register, in frame heights
uniform float misregistration; // = 0.01
// @range(0, 1) Amount of ink texture: squeegee streaks and ink-starved specks
uniform float grit; // = 0.5

const float PI = 3.141592653589793;
// the four passes end here, then the layers settle into register and the dots melt into the picture
const float PRINTED = 0.8;
// share of black taken out of the three colors (an exact separation, whatever the amount)
const float BLACK = 0.6;
// widths across the squeegee, in frame heights: bead of ink ahead of the blade, rubber blade, holder behind it
const float BEAD = 0.03;
const float RUBBER = 0.009;
const float HOLDER = 0.075;
const float SHADOW = 0.018;
const float SHADOW_SOFT = 0.02;
const float AA = 0.0015;

float spHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float spNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(spHash(i), spHash(i + vec2(1.0, 0.0)), f.x),
    mix(spHash(i + vec2(0.0, 1.0)), spHash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// mirrored coordinates, so that a shifted lookup never smears the frame's border
vec2 spMirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// amount of ink of pass i (yellow, magenta, cyan, black) separating the color c
float separation(vec3 c, float i) {
  float k = BLACK * (1.0 - max(max(c.r, c.g), c.b));
  if (i > 2.5) return k;
  float channel = i < 0.5 ? c.b : (i < 1.5 ? c.g : c.r);
  return clamp((1.0 - channel - k) / (1.0 - k), 0.0, 1.0);
}

vec3 inkFilter(float i) {
  if (i < 0.5) return vec3(1.0, 1.0, 0.0);
  if (i < 1.5) return vec3(1.0, 0.0, 1.0);
  if (i < 2.5) return vec3(0.0, 1.0, 1.0);
  return vec3(0.0);
}

vec3 inkColor(float i) {
  if (i < 0.5) return vec3(1.0, 0.84, 0.05);
  if (i < 1.5) return vec3(0.86, 0.06, 0.48);
  if (i < 2.5) return vec3(0.0, 0.58, 0.86);
  return vec3(0.07, 0.07, 0.08);
}

vec4 transition(vec2 uv) {
  vec2 aspect = vec2(ratio, 1.0);
  vec2 p = (uv - 0.5) * aspect;
  float settle = smoothstep(PRINTED, 1.0, progress);
  float rough = clamp(grit, 0.0, 1.0) * (1.0 - settle);
  float cells = max(dots, 1.0);

  vec4 from = getFromColor(uv);
  vec4 to = getToColor(uv);
  vec3 col = from.rgb;
  float alpha = from.a;
  float shade = 1.0;
  vec4 tool = vec4(0.0);

  for (int n = 0; n < 4; n++) {
    float i = float(n);
    float t = clamp((progress - i * PRINTED / 4.0) / (PRINTED / 4.0), 0.0, 1.0);
    // the passes run one after another: none of the next ones has started yet
    if (t <= 0.0) break;
    float dir = mod(i, 2.0) < 0.5 ? 1.0 : -1.0;
    float tilt = mod(i, 2.0) < 0.5 ? 0.05 : 0.07;
    float m = dir * p.x + tilt * p.y;
    float extent = 0.5 * ratio + 0.5 * abs(tilt);
    // the squeegee speeds up into the frame and slows down out of it, without stopping: it starts with
    // its bead and shadow just outside the frame, and ends with its holder and shadow just past it
    float e = mix(t, t * t * (3.0 - 2.0 * t), 0.55);
    float front = mix(-extent - 1.15 * BEAD - SHADOW - SHADOW_SOFT, extent + HOLDER + SHADOW + SHADOW_SOFT, e);
    // across the blade: u < 0 ahead of it, u > 0 behind it, v along it
    float u = front - m;
    float v = dir * p.y - tilt * p.x;
    float cover = smoothstep(-AA, AA, u);

    float a = 2.4 * i + 0.7;
    vec2 offset = misregistration * (1.0 - settle) * vec2(cos(a), sin(a)) * (0.6 + 0.4 * mod(i * 3.0, 4.0) / 3.0);
    vec4 s = getToColor(spMirror(uv + offset / aspect));
    float amount = separation(s.rgb, i);
    float streak = spNoise(vec2(v * 90.0, m * 2.0 + i * 13.0));
    streak = smoothstep(0.3, 0.9, streak);
    float speck = step(spHash(floor(p * 260.0) + i * 17.3), 0.07 * rough);
    amount *= 1.0 - rough * (0.3 * streak + speck);
    float ga = radians(i < 0.5 ? 0.0 : (i < 1.5 ? 75.0 : (i < 2.5 ? 15.0 : 45.0)));
    vec2 g = mat2(cos(ga), sin(ga), -sin(ga), cos(ga)) * p * cells;
    // a dot grows from each cell's center (and a hole shrinks at its corners past half): the ink covers
    // the part of the cell where the spot is below the level whose area matches the amount of ink
    vec2 cell = 2.0 * PI * fract(g);
    float spot = 0.5 - 0.25 * (cos(cell.x) + cos(cell.y));
    float d = 1.0 - 2.0 * amount;
    float level = 0.5 - 0.5 * sign(d) * pow(abs(d), 1.5);
    float w = 0.16;
    float dotted = smoothstep(-w, w, level * (1.0 + 2.0 * w) - w - spot);
    float c = mix(dotted, amount, settle) * mix(s.a, 1.0, settle);
    vec3 ink = 1.0 - c * (1.0 - inkFilter(i));
    float wet = (1.0 - smoothstep(0.75, 1.0, t)) * exp(-max(u, 0.0) / 0.1) * cover * c;
    ink *= 1.0 - 0.12 * wet;
    vec3 printed = (n == 0 ? vec3(1.0) : col) * ink + 0.06 * wet * streak;
    col = mix(col, printed, cover);
    if (n == 0) alpha = mix(from.a, to.a, cover);

    if (t > 0.0 && t < 1.0) {
      float us = u + dir * SHADOW;
      shade *= 1.0 - 0.35 * smoothstep(-BEAD - SHADOW_SOFT, -BEAD + SHADOW_SOFT, us)
        * (1.0 - smoothstep(HOLDER - SHADOW_SOFT, HOLDER + SHADOW_SOFT, us));
      float bead = BEAD * (0.55 + 0.6 * spNoise(vec2(v * 7.0, i * 5.0)));
      float bx = clamp((u + 0.5 * bead) / (0.5 * bead), -1.0, 1.0);
      float bz = sqrt(1.0 - bx * bx);
      float beadMask = smoothstep(-bead - AA, -bead + AA, u) * (1.0 - smoothstep(-AA, AA, u));
      vec3 bc = inkColor(i) * (0.45 + 0.55 * bz) * (0.92 + 0.16 * spNoise(vec2(v * 30.0, u * 120.0)));
      bc += 0.35 * pow(smoothstep(0.75, 1.0, bz), 3.0) * (0.6 + 0.4 * spNoise(vec2(v * 40.0, i)));
      float rubber = smoothstep(-AA, AA, u) * (1.0 - smoothstep(RUBBER - AA, RUBBER + AA, u));
      float holder = smoothstep(RUBBER - AA, RUBBER + AA, u) * (1.0 - smoothstep(HOLDER - AA, HOLDER + AA, u));
      float hx = clamp((u - RUBBER) / (HOLDER - RUBBER) * 2.0 - 1.0, -1.0, 1.0);
      vec3 metal = vec3(0.62, 0.64, 0.67) * (0.55 + 0.45 * sqrt(1.0 - hx * hx));
      metal += 0.3 * (1.0 - smoothstep(0.0, 0.15, abs(hx + 0.35 * dir)));
      metal *= 1.0 - 0.5 * smoothstep(0.8, 1.0, abs(hx));
      vec3 rc = vec3(0.1, 0.11, 0.12) + 0.12 * (1.0 - smoothstep(0.0, 0.004, abs(u - 0.0025)));
      // (the squeegee only tints the print: over a transparent image, it adds no alpha)
      tool = vec4(beadMask * bc + rubber * rc + holder * metal, beadMask + rubber + holder);
    }
  }
  col = col * shade * (1.0 - tool.a) + tool.rgb;
  return vec4(col, alpha);
}

// Author: gre
// License: MIT
// Description: The picture becomes a field of overlapping reversible sequins; an unseen hand strokes across it in three sweeps from top to bottom, and the sequins under its round tip turn over in the direction of the stroke with a glint, showing the incoming picture on their backs, while those just outside each sweep lift and fall back
// Tags: sequins, flip, stroke, sparkle, 3d

// @range(8, 40) Rows of sequins stacked across the height of the frame
uniform float rows; // = 16.0
// @range(0, 2) Strength of the glints
uniform float sparkle; // = 1.0

const float PI = 3.14159265;
const float PASSES = 3.0;
const float FLIP = 0.16;
const float PITCH = 1.25;
const float R = 0.75;
const vec3 L = vec3(-0.4504, 0.6006, 0.6606);
const vec3 HALF = vec3(-0.2472, 0.3295, 0.9112);

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float ease(float t) {
  t = clamp(t, 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

float laneDist(vec2 c, float k) {
  return abs(c.y - 1.0 + (k + 0.5) / PASSES - 0.03 * sin(6.0 * c.x + 2.0 * k)) * PASSES;
}

// signed turn of the sequin centred at c (frame heights, y up): positive turns toward +x
float turnAt(vec2 c, float jitter) {
  float own = 0.0, best = 1e3;
  for (int i = 0; i < 3; i++) {
    float m = laneDist(c, float(i));
    if (m < best) { best = m; own = float(i); }
  }
  float a = 0.0;
  for (int i = 0; i < 3; i++) {
    float k = float(i);
    float d = mod(k, 2.0) < 0.5 ? 1.0 : -1.0;
    float along = d > 0.0 ? c.x / ratio : 1.0 - c.x / ratio;
    float m = laneDist(c, k);
    // the round tip reaches the middle of its lane first
    float t = 0.06 + ((k + along) / PASSES + 0.05 * m * m) * 0.62 + jitter;
    float f = (progress - t) / FLIP;
    if (k == own) a += d * PI * ease(f);
    else a += d * 0.8 * clamp(1.0 - 2.5 * (m - 0.5), 0.0, 1.0) * sin(PI * clamp(f * 0.8, 0.0, 1.0));
  }
  return a;
}

vec2 centerOf(vec2 id) {
  return vec2((id.x + 0.5 + 0.5 * mod(id.y, 2.0)) * PITCH, id.y + 0.5);
}

float angleOf(vec2 id) {
  return turnAt(centerOf(id) / rows, 0.02 * hash12(id));
}

// the point of the disc of sequin id, turned by a, seen at p
vec2 poseOf(vec2 p, vec2 id, float a) {
  float sa = sin(a);
  vec2 s = p - centerOf(id) - vec2(0.25 * sa, 0.0);
  return vec2(s.x / max(abs(cos(a)), 0.02), s.y) / (1.0 + 0.25 * abs(sa));
}

float depthOf(vec2 id, float a) {
  // each row hangs over the top of the row below it
  return 2.0 * abs(sin(a)) + 0.01 * id.y;
}

vec4 shadeSequin(vec2 uv, vec2 p, vec2 id, float a, float e) {
  vec2 q = poseOf(p, id, a);
  float ca = cos(a), sa = sin(a);
  bool back = ca < 0.0;
  vec2 src = uv + e * (q - (p - centerOf(id))) / rows / vec2(ratio, 1.0);
  src = 1.0 - abs(1.0 - abs(src));
  vec4 col = back ? getToColor(src) : getFromColor(src);
  float face = back ? -1.0 : 1.0;
  vec3 nrm = normalize(vec3(face * sa + 0.45 * q.x, 0.45 * q.y, abs(ca)));
  float dif = 0.85 + 0.3 * dot(nrm, L) - 0.25 * smoothstep(0.75, 1.0, length(q) / R);
  float spec = pow(max(dot(nrm, HALF), 0.0), 40.0) + 0.6 * pow(abs(sa), 6.0);
  vec3 c = col.rgb * mix(1.0, dif, e) + sparkle * e * spec * vec3(1.0, 0.96, 0.88) * 0.7;
  return vec4(c, col.a);
}

vec4 transition(vec2 uv) {
  float e = ease(progress / 0.08) * ease((1.0 - progress) / 0.08);
  vec2 p = uv * vec2(ratio, 1.0) * rows;
  float aaw = rows / 260.0;
  float j0 = floor(p.y);

  float z1 = -1e3, z2 = -1e3, a1 = 0.0, a2 = 0.0, ang1 = 0.0, ang2 = 0.0;
  vec2 id1 = vec2(0.0), id2 = vec2(0.0);
  float near = 1e3, aHome = 0.0;
  for (int dj = -1; dj <= 1; dj++) {
    float j = j0 + float(dj);
    float i0 = floor(p.x / PITCH - 0.5 * mod(j, 2.0));
    for (int di = -1; di <= 1; di++) {
      vec2 id = vec2(i0 + float(di), j);
      float a = angleOf(id);
      float dc = length(p - centerOf(id));
      if (dc < near) { near = dc; aHome = a; }
      vec2 q = poseOf(p, id, a);
      float r = length(q);
      float squash = mix(1.0, max(abs(cos(a)), 0.02), q.x * q.x / max(r * r, 1e-6));
      float cov = clamp((R - r) * (1.0 + 0.25 * abs(sin(a))) * squash / aaw + 0.5, 0.0, 1.0);
      if (cov <= 0.0) continue;
      float z = depthOf(id, a);
      if (z > z1) {
        z2 = z1; a2 = a1; id2 = id1; ang2 = ang1;
        z1 = z; a1 = cov; id1 = id; ang1 = a;
      } else if (z > z2) {
        z2 = z; a2 = cov; id2 = id; ang2 = a;
      }
    }
  }

  // contact shadows of the sequins lying over each visible layer, cast down and to the right
  float sh1 = 0.0, sh2 = 0.0;
  for (int dj = -1; dj <= 1; dj++) {
    float j = j0 + float(dj);
    float i0 = floor(p.x / PITCH - 0.5 * mod(j, 2.0));
    for (int di = -1; di <= 1; di++) {
      vec2 id = vec2(i0 + float(di), j);
      float a = angleOf(id);
      float z = depthOf(id, a);
      for (int l = 0; l < 2; l++) {
        float zl = l == 0 ? z1 : z2;
        float gap = z - zl;
        if (zl < -1e2 || gap <= 1e-4) continue;
        vec2 q = poseOf(p - vec2(0.08, -0.1) * (1.0 + 2.5 * gap), id, a);
        float s = 1.0 - smoothstep(R - 0.1, R + 0.12 + 0.1 * gap, length(q));
        if (l == 0) sh1 = max(sh1, s); else sh2 = max(sh2, s);
      }
    }
  }

  vec4 under = abs(aHome) > 0.5 * PI ? getToColor(uv) : getFromColor(uv);
  under.rgb *= 1.0 - 0.45 * e;
  vec4 c = under;
  if (a2 > 0.0) {
    vec4 c2 = shadeSequin(uv, p, id2, ang2, e);
    c2.rgb *= 1.0 - 0.4 * e * sh2;
    c = mix(c, c2, a2);
  }
  if (a1 > 0.0) {
    vec4 c1 = shadeSequin(uv, p, id1, ang1, e);
    c1.rgb *= 1.0 - 0.4 * e * sh1;
    c = mix(c, c1, a1);
  }
  return c;
}

// Author: lbl
// License: MIT
// Description: The outgoing image cracks like a pane of glass from an impact point, then its shards break loose from the impact outward, tumbling in 3D and falling away with gravity to reveal the incoming image behind
// Tags: shatter, fragments, glass, 3d

// @param Impact point where the cracks start, from (0, 0) at the bottom left to (1, 1) at the top right
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(3, 8) Approximate number of rows of shards across the height of the frame
uniform float shards; // = 6.0
// @range(0.5, 3) Strength of the gravity: the shards fall faster, and break loose over a longer time
uniform float gravity; // = 1.0
// @param Random seed: another value gives other shards, tumbling another way
uniform float seed; // = 0.0

// distance from the camera to the pane, as a part of the frame's height
const float EYE = 2.5;
// how far the corners of the shards are moved from a regular grid, as a part of a cell
const float JITTER = 0.32;
// width of the anti-aliased edges, the crack lines and the bevels, as a part of the frame's height
const float EDGE = 0.0012;
const float CRACK_WIDTH = 0.0025;
const float BEVEL = 0.006;

vec3 hash32(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yxz + 33.33);
  return fract((p3.xxy + p3.yzz) * p3.zyx);
}

float cellSize() {
  return 1.0 / clamp(shards, 3.0, 8.0);
}

vec2 seedOffset() {
  return vec2(37.0, 17.0) * floor(seed);
}

vec2 corner(vec2 p) {
  return (p + JITTER * (2.0 * hash32(p + seedOffset()).xy - 1.0)) * cellSize();
}

// signed distance from q to the line a -> b, positive on its left
float side(vec2 q, vec2 a, vec2 b) {
  vec2 d = b - a;
  return (d.x * (q.y - a.y) - d.y * (q.x - a.x)) / length(d);
}

bool diagonalUp(vec2 c) {
  return hash32(c + seedOffset() + 0.5).z > 0.5;
}

// distance from q to the edges of the triangle p0 p1 p2 (counterclockwise), positive inside
float triangleDist(vec2 q, vec2 p0, vec2 p1, vec2 p2) {
  return min(min(side(q, p0, p1), side(q, p1, p2)), side(q, p2, p0));
}

// the shard that contains q on the unbroken pane: (its cell, its triangle, the distance from q to its nearest crack)
vec4 locate(vec2 q) {
  vec2 c = floor(q / cellSize());
  // the cells' sides are not straight: step to the neighbor cell when q is beyond one of them
  vec2 a, b, cc, d;
  for (int i = 0; i < 2; i++) {
    a = corner(c);
    b = corner(c + vec2(1.0, 0.0));
    cc = corner(c + 1.0);
    d = corner(c + vec2(0.0, 1.0));
    c.x += side(q, d, a) < 0.0 ? -1.0 : (side(q, b, cc) < 0.0 ? 1.0 : 0.0);
    a = corner(c);
    b = corner(c + vec2(1.0, 0.0));
    cc = corner(c + 1.0);
    d = corner(c + vec2(0.0, 1.0));
    c.y += side(q, a, b) < 0.0 ? -1.0 : (side(q, cc, d) < 0.0 ? 1.0 : 0.0);
  }
  a = corner(c);
  b = corner(c + vec2(1.0, 0.0));
  cc = corner(c + 1.0);
  d = corner(c + vec2(0.0, 1.0));
  bool up = diagonalUp(c);
  float d0 = up ? triangleDist(q, a, b, cc) : triangleDist(q, a, b, d);
  float d1 = up ? triangleDist(q, a, cc, d) : triangleDist(q, b, cc, d);
  return vec4(c, d1 > d0 ? 1.0 : 0.0, abs(max(d0, d1)));
}

// Rodrigues' rotation of v around the unit axis k
vec3 rotate(vec3 v, vec3 k, float c, float s) {
  return v * c + cross(k, v) * s + k * dot(k, v) * (1.0 - c);
}

vec2 impact() {
  return clamp(center, 0.0, 1.0) * vec2(ratio, 1.0);
}

float reach() {
  vec2 c = impact();
  return length(max(c, vec2(ratio, 1.0) - c));
}

float fallMargin() {
  return 0.1 + 1.5 * cellSize();
}

// the time a shard breaks loose: the nearer the impact the sooner, and late enough to fall out of the frame by the end
// (dn: its distance to the impact, as a part of the reach)
float releaseTime(vec2 mid, float dn, float h, float g, float margin) {
  float latest = max(0.98 - sqrt(2.0 * (mid.y + margin) / g), 0.04);
  return 0.04 + (latest - 0.04) * (0.8 * pow(dn, 0.8) + 0.2 * h);
}

float flash(vec2 q) {
  float f = sin(3.141592653589793 * clamp(progress / 0.12, 0.0, 1.0));
  vec2 d = q - impact();
  return 0.6 * f * exp(-dot(d, d) / (0.004 + 0.02 * progress));
}

vec4 transition(vec2 uv) {
  float s = cellSize();
  vec2 a = vec2(uv.x * ratio, uv.y);
  vec3 eye = vec3(0.5 * ratio, 0.5, -EYE);
  vec3 ray = vec3(a, 0.0) - eye;
  vec3 light = normalize(vec3(-0.35, 0.55, -1.0));
  vec3 halfway = normalize(light - normalize(ray));
  float g = 12.0 * clamp(gravity, 0.5, 3.0);
  vec2 imp = impact();
  float rch = reach();
  float margin = fallMargin();
  // the cracks run from the impact to the farthest corner, before the last shards break loose
  float crackTime = clamp(0.6 * (0.94 - sqrt(2.0 * (1.0 + margin) / g)), 0.05, 0.22);

  vec4 pane = vec4(0.0);
  float paneDepth = 1e9;
  vec4 here = locate(a);
  vec2 hc = here.xy;
  vec2 ha = corner(hc), hb = corner(hc + vec2(1.0, 0.0)), hcc = corner(hc + 1.0), hd = corner(hc + vec2(0.0, 1.0));
  bool hup = diagonalUp(hc);
  vec2 hcenter = here.z < 0.5 ? (hup ? ha + hb + hcc : ha + hb + hd) : (hup ? ha + hcc + hd : hb + hcc + hd);
  vec3 hh = hash32(hc + vec2(0.31, 0.57) * (here.z + 1.0) + seedOffset());
  hcenter /= 3.0;
  if (progress < releaseTime(hcenter, clamp(length(hcenter - imp) / rch, 0.0, 1.0), hh.x, g, margin)) {
    vec4 col = getFromColor(uv);
    float crack = clamp((progress - crackTime * length(a - imp) / rch) / 0.03, 0.0, 1.0);
    // cracked shards settle at slightly different angles (no change while flat: dot(n, light) = -light.z)
    float tilt = 0.06 * crack * (hh.x - 0.5);
    vec3 n = rotate(vec3(0.0, 0.0, -1.0), normalize(vec3(hh.yz - 0.5, 0.0) + 1e-4), cos(tilt), sin(tilt));
    col.rgb *= 1.0 + 1.2 * (dot(n, light) + light.z);
    col.rgb += crack * 0.35 * pow(max(dot(n, halfway), 0.0), 400.0) * col.a;
    float line = crack * (1.0 - smoothstep(0.0, CRACK_WIDTH, here.w));
    col.rgb = mix(col.rgb, vec3(0.95, 0.98, 1.0) * col.a, 0.85 * line);
    pane = col;
    paneDepth = 1.0;
  }

  // the two nearest loose shards: depth along the ray, color, coverage
  float t1 = 1e9, t2 = 1e9;
  vec4 c1 = vec4(0.0), c2 = vec4(0.0);
  float a1 = 0.0, a2 = 0.0;
  float shadow = 0.0;

  // the shards that broke loose, searched in the cells around and above the pixel since they fall,
  // looking a bit toward the impact and the middle since they drift away and grow toward the camera
  vec2 look = a - 0.06 * progress * (a - imp) / rch - (a - eye.xy) * 0.06 * progress;
  vec2 g0 = floor(look / s) - 1.0;
  float rows = ceil(1.0 / s);
  float j0 = max(g0.y, -1.0);
  // a shard from above had no time to fall down to here
  float highest = g0.y + min(10.5, 4.0 + (0.5 * g * progress * progress + 0.25 * progress) / s);
  float raySq = dot(ray, ray);
  for (int ci = 0; ci < 3; ci++) {
    vec2 cd = corner(vec2(g0.x + float(ci), j0)), ccc = corner(vec2(g0.x + float(ci) + 1.0, j0));
    for (int ri = 0; ri < 11; ri++) {
      vec2 c = vec2(g0.x + float(ci), j0 + float(ri));
      if (c.y > rows || c.y > highest) break;
      vec2 ca = cd, cb = ccc;
      cd = corner(c + vec2(0.0, 1.0));
      ccc = corner(c + 1.0);
      bool up = diagonalUp(c);
      for (int k = 0; k < 2; k++) {
        vec2 p0 = (k == 1 && !up) ? cb : ca;
        vec2 p1 = k == 0 ? cb : ccc;
        vec2 p2 = (k == 0 && up) ? ccc : cd;
        vec2 mid = (p0 + p1 + p2) / 3.0;
        vec3 h1 = hash32(c + vec2(0.31, 0.57) * float(k + 1) + seedOffset());
        vec2 away = mid - imp;
        float dist = length(away);
        float dn = clamp(dist / rch, 0.0, 1.0);
        float e = progress - releaseTime(mid, dn, h1.x, g, margin);
        if (e <= 0.0) continue;
        vec2 d0 = p0 - mid, d1 = p1 - mid, d2 = p2 - mid;
        float size2 = max(dot(d0, d0), max(dot(d1, d1), dot(d2, d2)));
        // it fell too far or not enough to be met from here, whatever its own speed and the slants of the rays
        if (abs(mid.y - 0.5 * g * e * e - a.y) > 1.25 * sqrt(size2) + 0.36 * e) continue;
        float near = 1.0 - dn;
        vec3 vel = vec3(away / max(dist, 1e-3) * (0.03 + 0.08 * h1.y) * (0.4 + near), -(0.05 + 0.2 * near * h1.z));
        vec3 pos = vec3(mid, 0.0) + vel * e - vec3(0.0, 0.5 * g * e * e, 0.0);
        if (pos.y + 1.5 * s < -0.05) continue;
        // neither the eye nor the light can reach the shard from here
        vec3 missed = cross(pos - eye, ray);
        vec3 unlit = cross(pos - vec3(a, 0.0), light);
        bool seen = dot(missed, missed) < size2 * raySq;
        bool lit = dot(unlit, unlit) < size2;
        if (!seen && !lit) continue;
        vec3 h2 = hash32(c + vec2(0.73, 0.19) * float(k + 1) + seedOffset());
        vec3 axis = normalize(vec3(h2.x - 0.5, h2.y - 0.5, 0.3 * (h2.z - 0.5)) + 1e-4);
        float angle = (3.0 + 5.0 * h2.z) * (h2.x < 0.5 ? -1.0 : 1.0) * e;
        float cs = cos(angle), sn = sin(angle);
        vec3 n = rotate(vec3(0.0, 0.0, -1.0), axis, cs, sn);
        float rel = smoothstep(0.0, 0.04, e);

        float den = dot(ray, n);
        float t = dot(pos - eye, n) / (abs(den) > 1e-4 ? den : 1e-4);
        if (seen && t > 0.0 && t < t2 && t < paneDepth) {
          vec2 q = mid + rotate(eye + t * ray - pos, axis, cs, -sn).xy;
          float border = min(min(q.x, ratio - q.x), min(q.y, 1.0 - q.y));
          float inside = triangleDist(q, p0, p1, p2);
          float ed = min(inside, border);
          if (ed > 0.0) {
            vec3 nf = den > 0.0 ? -n : n;
            vec4 col = getFromColor(vec2(q.x / ratio, q.y));
            col.rgb *= mix(1.0, clamp(dot(nf, light) / -light.z, 0.45, 1.1), rel);
            float glint = max(dot(nf, halfway), 0.0);
            col.rgb += rel * 0.3 * pow(glint, 60.0) * col.a;
            float line = 0.85 * (1.0 - smoothstep(0.0, CRACK_WIDTH, inside)) * (1.0 - rel);
            float bevel = 0.8 * rel * (1.0 - smoothstep(0.0, BEVEL, ed)) * (0.3 + 0.7 * pow(glint, 6.0));
            col.rgb = mix(col.rgb, vec3(0.92, 0.97, 0.97) * col.a, max(line, bevel));
            float cover = mix(1.0, smoothstep(0.0, 2.0 * EDGE, ed), rel);
            if (t < t1) {
              t2 = t1; c2 = c1; a2 = a1;
              t1 = t; c1 = col; a1 = cover;
            } else {
              t2 = t; c2 = col; a2 = cover;
            }
          }
        }

        float lden = dot(light, n);
        float ts = dot(pos - vec3(a, 0.0), n) / (abs(lden) > 1e-4 ? lden : 1e-4);
        if (lit && ts > 0.0) {
          vec2 qs = mid + rotate(vec3(a, 0.0) + ts * light - pos, axis, cs, -sn).xy;
          float eds = min(triangleDist(qs, p0, p1, p2), min(min(qs.x, ratio - qs.x), min(qs.y, 1.0 - qs.y)));
          if (eds > 0.0) {
            shadow = max(shadow, rel * smoothstep(0.0, 0.004 + 0.08 * ts, eds) * 0.45 * (1.0 - smoothstep(0.1, 0.9, ts)));
          }
        }
      }
    }
  }

  // the incoming image behind, then the pane still in place, then the loose shards in front
  vec4 back = getToColor(uv);
  back.rgb *= 1.0 - shadow;
  pane.rgb *= 1.0 - shadow;
  if (paneDepth == 1.0) back = pane;
  vec4 color = c1 * a1 + c2 * min(a2, 1.0 - a1) + back * max(1.0 - a1 - a2, 0.0);
  color.rgb += flash(a) * color.a;
  return color;
}

