vec4 transition (vec2 uv) {
  vec2 q = vec2(uv.x * ratio, uv.y);
  vec2 wob = (vec2(sdNoise(q * 6.0), sdNoise(q * 6.0 + 17.0)) - 0.5) * 0.004;
  vec2 su = uv + wob * (1.0 - progress);
  vec2 dx = vec2(0.001 * lineWidth / ratio, 0.0);
  vec2 dy = vec2(0.0, 0.001 * lineWidth);
  vec2 tl = sdTone(su - dx + dy), tm = sdTone(su + dy), tr = sdTone(su + dx + dy);
  vec2 ml = sdTone(su - dx), mr = sdTone(su + dx);
  vec2 bl = sdTone(su - dx - dy), bm = sdTone(su - dy), br = sdTone(su + dx - dy);
  vec2 gx = (tr + 2.0 * mr + br) - (tl + 2.0 * ml + bl);
  vec2 gy = (tl + 2.0 * tm + tr) - (bl + 2.0 * bm + br);
  float g = max(length(vec2(gx.x, gy.x)), length(vec2(gx.y, gy.y))) * max(edges, 0.0);
  float outline = smoothstep(0.12, 0.5, g);
  vec4 toC = getToColor(uv);
  float l = clamp((tm.x + bm.x + ml.x + mr.x) * 0.25, 0.0, 1.0);

  float grain = 0.65 + 0.35 * sdNoise(q * vec2(180.0, 60.0));
  float order = sdNoise(q * 3.0 + 4.0);
  float fine = sdNoise(q * 24.0);
  float drawOutline = smoothstep(0.0, 0.1, progress - (0.22 * order + 0.05 * fine));
  float drawHatch = smoothstep(0.0, 0.12, progress - (0.2 + 0.2 * order + 0.05 * fine));

  float fill = smoothstep(0.0, 0.22, progress - (0.4 + 0.25 * l + 0.1 * order));

  float dark = 1.0 - l;
  float h1 = sdHatch(q, vec2(0.7071, 0.7071), smoothstep(0.35, 0.9, dark));
  float h2 = sdHatch(q, vec2(0.7071, -0.7071), smoothstep(0.65, 1.0, dark));
  float hatch = hatching * 0.8 * max(h1, 0.8 * h2) * toC.a;

  hatch *= drawHatch * (1.0 - 0.6 * fill);
  float pencil = max(outline * drawOutline, hatch) * grain;
  pencil *= 1.0 - smoothstep(0.7, 1.0, progress);

  vec4 base = mix(getFromColor(uv), paper, smoothstep(0.02, 0.38, progress));
  float sat = smoothstep(0.55, 1.0, progress);
  vec4 tone = vec4(paper.rgb * mix(0.3, 1.0, l), paper.a * toC.a);
  vec4 col = mix(tone, toC, sat);
  base = mix(base, col, fill);
  return mix(base, ink, pencil);
}

// Author: gre
// License: MIT
// Description: The outgoing picture rounds into a paper lantern lit warmly from inside and drifts off into the dusk over the incoming picture, while little lanterns made of the same picture rise on both sides; as the last ones float away, day breaks on the incoming picture
// Tags: lantern, night, light, rise, poetic

// @range(0, 1) How dark the dusk gets
uniform float dusk; // = 0.85
// @range(0, 1) Strength of the glow
uniform float glow; // = 0.8
// @color Light of the flame
uniform vec3 flame; // = vec3(1.0, 0.66, 0.28)

const int COUNT = 18;

float hash(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

// half width of a lantern of half height 1, down to the round mouth
float profile(float y, float lip) {
  float v = clamp(y, -1.0, 1.0);
  float t = max(v, 0.0);
  float b = max(-v, 0.0);
  float w = 0.72 * sqrt(max(1.0 - t * t * t * t, 0.0)) * (1.0 - 0.3 * b * b);
  float m = max(lip - 1.0 - v, 0.0) / lip;
  return w * sqrt(max(1.0 - m * m, 0.0));
}

// slope of the outline, to keep its feather even on the caps
float steep(float y, float lip) {
  float g = (profile(y + 0.01, lip) - profile(y - 0.01, lip)) * 50.0;
  return sqrt(1.0 + g * g);
}

// l in half heights; k = 0 is the flat picture, 1 the lit lantern; premultiplied
vec4 paper(vec2 l, float w, float k, float lip, float flick) {
  float mouth = mix(ratio, profile(lip - 1.0, lip), k);
  // under the rim w follows the mouth, but the paper keeps its width
  float x = clamp(l.x / max(l.y < lip - 1.0 ? mouth : w, 1e-4), -1.0, 1.0);
  float turn = asin(x * 0.999);
  float bx = mix(x, turn * 0.6366, k);
  vec2 crop = mix(vec2(1.0), min(vec2(0.8 / ratio, ratio / 0.8), 1.0), k);
  vec4 c = getFromColor(clamp(0.5 + 0.5 * vec2(bx, l.y) * crop, 0.0, 1.0));
  vec2 f = (l + vec2(0.0, 0.7)) * vec2(1.25, 0.72);
  float core = exp(-dot(f, f)) * flick;
  vec3 lit = (c.rgb * 0.75 + 0.2 * flame) * mix(vec3(0.7, 0.58, 0.56), 0.55 + 1.3 * flame, core);
  lit += flame * 0.3 * core * core;
  lit *= 1.0 - 0.45 * x * x * x * x;
  lit *= 1.0 - 0.13 * smoothstep(0.88, 1.0, cos(l.y * 20.0));
  lit *= 1.0 - 0.07 * smoothstep(0.92, 1.0, cos(turn * 9.0));
  vec2 e = vec2(l.x / mouth, (l.y + 1.0 - lip) / lip);
  float r = length(e);
  float inside = 1.0 - smoothstep(0.82, 0.92, r);
  vec3 hole = flame * (0.45 + 0.95 * exp(-dot(e, e) * 2.5)) * flick;
  lit = mix(lit, flame * vec3(0.45, 0.36, 0.3), 1.0 - smoothstep(0.98, 1.06, r));
  lit = mix(lit, hole, inside);
  return vec4(mix(c.rgb, lit, k) * c.a, c.a);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 q = (uv - 0.5) * asp;
  float side = min(ratio, 1.0);

  float night = smoothstep(0.0, 0.25, p) * (1.0 - smoothstep(0.66, 1.0, p));
  vec4 c = getToColor(uv);
  float lum = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  vec3 moon = mix(vec3(lum), c.rgb, 0.6) * vec3(0.32, 0.42, 0.78) + vec3(0.02, 0.03, 0.08);
  c.rgb = mix(c.rgb, moon, dusk * night) * c.a;

  vec3 halo = vec3(0.0);
  // far to near, so the nearer lanterns overlap
  for (int i = 0; i < COUNT; i++) {
    float f = float(i);
    float z = 0.2 + 0.8 * f / float(COUNT - 1);
    float sz = mix(0.028, 0.115, z * z) * mix(side, 1.0, 0.15);
    float t = p - 0.17 - 0.2 * hash(f + 3.0);
    if (t <= 0.0) continue;
    // the bigger ones keep to the sides, off the subject
    float v = fract(f * 0.618034 + 0.2) * 2.0 - 1.0;
    float x = 0.5 * (ratio + 0.06) * sign(v) * mix(abs(v), 0.5 + 0.5 * abs(v), smoothstep(0.25, 0.5, z));
    x += 0.025 * side * sin(p * 8.0 + f * 2.1);
    float y = -0.5 - 1.3 * sz + t * (1.5 + 1.4 * z) + 0.7 * t * t;
    vec2 d = q - vec2(x, y);
    float sw = 0.1 * sin(p * 9.0 + f * 1.7);
    d = vec2(d.x + sw * d.y, d.y - sw * d.x) / sz;
    float on = smoothstep(0.0, 0.06, t);
    float flick = 0.92 + 0.08 * sin(p * 60.0 + f * 4.0);
    halo += on * flame * (0.3 * exp(-dot(d, d) * 0.55) + 0.06 * exp(-length(d) * 0.7)) * flick;
    if (abs(d.x) < 0.8 && abs(d.y) < 1.0) {
      float w = profile(d.y, 0.09);
      float m = smoothstep(0.0, 0.003 / sz * steep(d.y, 0.09), w - abs(d.x));
      vec4 s = paper(d, w, 1.0, 0.09, flick);
      s.rgb = mix(s.rgb, (0.75 * s.rgb * vec3(0.8, 0.85, 1.0) + vec3(0.03, 0.03, 0.06) * s.a), 1.0 - z);
      c = s * m + c * (1.0 - s.a * m);
    }
  }

  float k = smoothstep(0.01, 0.3, p);
  float up = smoothstep(0.2, 0.92, p);
  float S = mix(0.5, 0.15 * side, smoothstep(0.0, 0.6, p));
  float lip = max(0.09 * k, 1e-3);
  vec2 pos = vec2(0.26 * ratio * smoothstep(0.08, 0.55, p) + 0.03 * side * sin(p * 8.0) * k, 1.0 * up * up + 0.1 * up - 0.03 * k * (1.0 - up));
  vec2 d = q - pos;
  float sw = 0.08 * sin(p * 9.0) * k;
  d = vec2(d.x + sw * d.y, d.y - sw * d.x) / S;
  float flick = 0.94 + 0.06 * sin(p * 50.0);
  float w = mix(ratio, profile(d.y, lip), k);
  // a hair wider than the frame while still flat
  float slack = 0.004 / S * (1.0 - k) + 0.03 * (1.0 - smoothstep(0.0, 0.05, p));
  float m = smoothstep(0.0, 0.004 / S * mix(1.0, steep(d.y, lip), k), w + slack - abs(d.x)) * smoothstep(0.0, 0.004 / S, 1.0 + slack - abs(d.y));
  halo += k * flame * (0.5 * exp(-dot(d, d) * 0.5) + 0.12 * exp(-length(d) * 0.6)) * flick;
  c.rgb += glow * night * 0.55 * halo * (0.35 * c.a + c.rgb);
  vec4 s = paper(d, w, k, lip, flick);
  // the flat picture replaces the incoming one, the lantern floats over it
  c = s * m + c * (1.0 - m * mix(1.0, s.a, k));
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A bright blade stroke slashes diagonally across the outgoing image with a flash, then the two cut halves slip along the cut in opposite directions and fly off the frame, casting soft shadows on the incoming image beneath
// Tags: split, slide, flash, shadow

// @range(-75, 75) Angle of the cut against the horizontal, in degrees
uniform float angle; // = 25.0
// @range(0, 0.3) How far the halves move apart across the cut as they slide, relative to the image height
uniform float separation; // = 0.06
// @color Color of the blade stroke and its flash (alpha sets the intensity)
uniform vec4 flash; // = vec4(1.0, 0.96, 0.88, 1.0)
// @color Color of the shadow cast on the incoming image
uniform vec4 shadow; // = vec4(0.0, 0.0, 0.0, 0.45)

// part of the transition during which the blade crosses the frame
const float CUT = 0.18;
const float EDGE = 0.0015;
const vec2 SHADOW_OFFSET = vec2(0.015, -0.022);
const float SHADOW_BLUR = 0.035;

// signed distance (aspect units) to the frame rectangle centered on 0, negative inside
float boxDistance (vec2 q) {
  vec2 d = abs(q) - 0.5 * vec2(ratio, 1.0);
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// one half of the outgoing image, moved by v; s = 1 for the half above the cut, -1 below
// returns the image point of screen point q (xy) and a signed distance to the half (z, negative inside);
// the half overhangs its edges by half an edge width so that the still image covers the frame exactly
vec3 piece (vec2 q, vec2 v, vec2 n, float s) {
  vec2 y = q - v;
  return vec3(y, max(boxDistance(y), -s * dot(y, n)) - 0.5 * EDGE);
}

vec4 transition (vec2 uv) {
  float p = progress;
  float a = radians(angle);
  vec2 T = vec2(cos(a), sin(a));
  vec2 N = vec2(-T.y, T.x);
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  float d = dot(q, N);
  float along = dot(q, T);

  float t = clamp((p - 0.8 * CUT) / (1.0 - 0.8 * CUT), 0.0, 1.0);
  float open = separation * (1.0 - pow(1.0 - t, 3.0));
  float margin = length(SHADOW_OFFSET) + SHADOW_BLUR + 2.0 * EDGE;
  float exitX = (ratio + separation + margin) / max(abs(T.x), 1e-3);
  float exitY = (1.0 + separation + margin) / max(abs(T.y), 1e-3);
  float slide = min(exitX, exitY) * t * t * (1.5 - 0.5 * t);
  vec2 vUp = T * slide + N * open;

  vec4 to = getToColor(uv);
  vec2 sq = q - SHADOW_OFFSET;
  float sdUp = piece(sq, vUp, N, 1.0).z;
  float sdDown = piece(sq, -vUp, N, -1.0).z;
  float sh = shadow.a * smoothstep(0.0, 0.1, t) * (1.0 - smoothstep(-0.5 * SHADOW_BLUR, SHADOW_BLUR, min(sdUp, sdDown)));
  vec4 c = vec4(mix(to.rgb, shadow.rgb, sh), to.a);

  float reach = 0.5 * length(vec2(ratio, 1.0)) + 0.1;
  float k = clamp(p / CUT, 0.0, 1.0);
  float head = mix(-reach, reach, 1.0 - (1.0 - k) * (1.0 - k));
  float behind = head - along;
  float drawn = clamp(0.5 + behind / EDGE, 0.0, 1.0);

  float rim = flash.a * smoothstep(0.0, CUT, p) * (1.0 - 0.6 * t) * drawn;
  for (int i = 0; i < 2; i++) {
    float s = i == 0 ? 1.0 : -1.0;
    vec3 h = piece(q, s * vUp, N, s);
    float cover = clamp(0.5 - h.z / EDGE, 0.0, 1.0);
    vec4 col = getFromColor(clamp(h.xy / vec2(ratio, 1.0) + 0.5, 0.0, 1.0));
    float e = max(s * dot(h.xy, N), 0.0);
    col.rgb = mix(col.rgb, flash.rgb, rim * exp(-e / 0.004) * col.a);
    c = mix(c, col, cover);
  }

  float tail = drawn * (0.35 + 0.65 * exp(-max(behind, 0.0) * 4.0));
  float env = smoothstep(0.0, 0.03, p) * (1.0 - smoothstep(CUT, CUT + 0.12, p));
  float core = exp(-abs(d) / 0.0025) + 0.35 * exp(-abs(d) / 0.02);
  float spark = exp(-length(vec2(behind, d)) / 0.03) * (1.0 - k);
  float glow = flash.a * env * (core * tail + spark);
  float burst = flash.a * 0.25 * smoothstep(0.6 * CUT, CUT, p) * (1.0 - smoothstep(CUT, CUT + 0.15, p));
  c.rgb = mix(c.rgb, flash.rgb, burst * c.a);
  c.rgb += flash.rgb * glow * c.a;
  return c;
}

// Author: lizhongjian
// License: MIT
// Description: The outgoing image slides to the right, uncovering a crossfade to the incoming one
// Tags: slide, horizontal, blend

vec4 transition (vec2 uv) {
  vec2 newUV = uv;
  newUV.x -= progress;
  if(uv.x >= progress)
  {
    return getFromColor(newUV);
  }


  return mix(
    getFromColor(uv),
    getToColor(uv),
    progress
  );
}

// Author: gre
// License: MIT
// Description: A slide projector changes slides: the outgoing picture is jerked up out of the frame, blurring as it leaves the focal plane, the bare lamp flickers on the screen for an instant, then the incoming picture drops in from the top, bounces and hunts for focus before it sharpens
// Tags: retro, projector, slide, vertical, bounce, focus, flicker

// @range(0, 1) How high the incoming slide bounces when it lands in the gate
uniform float bounce; // = 0.5
// @range(0, 1) How out of focus the slides get while they move
uniform float defocus; // = 0.5
// @range(0, 1) How much the lamp flickers during the change
uniform float flicker; // = 0.5
// @color Color of the lamp light on the screen while the gate is empty
uniform vec4 lampColor; // = vec4(1.0, 0.95, 0.84, 1.0)

const float PI = 3.14159265;
const float MOUNT = 0.07;
const float CLEAR = 1.0 + MOUNT;
const int TAPS = 16;

float hash(float n) {
  vec3 p3 = fract(vec3(n) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// height of the outgoing picture on the screen: a short dip as the lift arm grabs the slide, then
// it is jerked up, still accelerating as it leaves the frame
float liftOut(float p) {
  float u = clamp((p - 0.05) / 0.3, 0.0, 1.0);
  float d = clamp(p / 0.12, 0.0, 1.0);
  float s = sin(PI * d);
  return CLEAR * u * u * (0.6 + 0.4 * u) - (0.004 + 0.012 * bounce) * s * s;
}

// height of the incoming picture: it falls into the gate under gravity, then makes two small hops
float dropIn(float p) {
  float v = clamp((p - 0.37) / 0.19, 0.0, 1.0);
  float y = CLEAR * (1.0 - v * v);
  float w = clamp((p - 0.56) / 0.22, 0.0, 1.0);
  float h = 0.06 * bounce;
  // hop lengths in proportion to the square root of their heights (1 and 0.15)
  float s1 = clamp(w / 0.72, 0.0, 1.0);
  float s2 = clamp((w - 0.72) / 0.28, 0.0, 1.0);
  return y + h * 4.0 * s1 * (1.0 - s1) + h * 0.15 * 4.0 * s2 * (1.0 - s2);
}

// how far out of focus the projection is (0 to 1): the outgoing slide leaves the focal plane as it
// is lifted, the incoming one lands out of focus, sharpens, overshoots and comes back sharp
float blurAmount(float p) {
  float s = clamp((p - 0.56) / 0.4, 0.0, 1.0);
  float k = 1.0 - s;
  float hunt = abs(cos(s * PI * 1.5)) * k;
  return smoothstep(0.04, 0.3, p) * (p < 0.56 ? 1.0 : hunt);
}

float band(float y, float a, float b, float aa) {
  return clamp((min(y - a, b - y)) / aa + 0.5, 0.0, 1.0);
}

// the gate seen on the screen at y (frame coordinates) with the outgoing slide at height yf and
// the incoming one at height yt, premultiplied; light is the brightness of the bare lamp there and
// shade the one of the pictures
vec4 gate(vec2 q, float yf, float yt, float light, float shade) {
  // edges get sharp as a slide comes to rest, so that it then covers the whole frame
  float af = 0.0015 * min(abs(yf) * 400.0, 1.0) + 1e-6;
  float at = 0.0015 * min(abs(yt) * 400.0, 1.0) + 1e-6;
  vec4 c = vec4(lampColor.rgb * lampColor.a * light, lampColor.a);
  float mf = band(q.y, yf - MOUNT, yf + 1.0 + MOUNT, af);
  float mt = band(q.y, yt - MOUNT, yt + 1.0 + MOUNT, at);
  c.rgb *= 1.0 - 0.96 * max(mf, mt);
  float pf = band(q.y, yf, yf + 1.0, af);
  if (pf > 0.0) {
    vec4 t = getFromColor(vec2(q.x, q.y - yf));
    c = mix(c, vec4(t.rgb * t.a * shade, t.a), pf);
  }
  float pt = band(q.y, yt, yt + 1.0, at);
  if (pt > 0.0) {
    vec4 t = getToColor(vec2(q.x, q.y - yt));
    c = mix(c, vec4(t.rgb * t.a * shade, t.a), pt);
  }
  return c;
}

vec4 transition(vec2 uv) {
  float p = progress;

  float yf = liftOut(p);
  float yt = dropIn(p);
  // vertical speed of the slide that moves (one at a time), for the motion blur
  float dp = 0.004;
  float vf = (liftOut(p + dp) - liftOut(p - dp)) / (2.0 * dp);
  float vt = (dropIn(p + dp) - dropIn(p - dp)) / (2.0 * dp);
  float smear = min(max(abs(vf), abs(vt)) * 0.012, 0.07);

  float b = blurAmount(p);
  float radius = defocus * 0.02 * b;
  float zoom = 1.0 + 0.025 * defocus * b;
  vec2 c0 = (uv - 0.5) / zoom + 0.5;

  float env = smoothstep(0.0, 0.12, p) * (1.0 - smoothstep(0.72, 1.0, p));
  float fc = p * 30.0;
  float fl = mix(hash(floor(fc)), hash(floor(fc) + 1.0), smoothstep(0.3, 0.7, fract(fc)));
  vec2 d = (uv - 0.5) * vec2(ratio, 1.0) / (0.5 * sqrt(ratio * ratio + 1.0));
  float light = (1.0 - 0.3 * dot(d, d)) * (1.0 - 0.3 * flicker * fl * env);
  float shade = mix(1.0, 0.92 * light, env);

  vec4 c;
  if (radius + smear < 1e-4) {
    c = gate(c0, yf, yt, light, shade);
    return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
  }
  c = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    float fi = float(i);
    float a = fi * 2.39996;
    vec2 o = sqrt((fi + 0.5) / float(TAPS)) * vec2(cos(a) / ratio, sin(a)) * radius;
    o.y += ((fi + 0.5) / float(TAPS) - 0.5) * smear;
    // the gate is the frame: fold the taps back so its edges stay sharp
    vec2 q = 1.0 - abs(1.0 - abs(c0 + o));
    c += gate(q, yf, yt, light, shade);
  }
  c /= float(TAPS);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: Mark Craig
// mrmcsoftware on github and youtube ( http://www.youtube.com/MrMcSoftware )
// License: MIT
// Description: The outgoing image slides out, or the incoming one slides in, toward an edge, a corner or the center
// Tags: slide, directional

// Slides Transition by Mark Craig (Copyright © 2022)

uniform int type; // = 0
// @param Slide the incoming image in instead of the outgoing one out
uniform bool In; // = false
// type: slide to/from which edge, which corner, or center
// In: if true slide new image in, otherwise slide old image out

#define rad2 rad / 2.0

vec4 transition(vec2 uv)
{
vec2 uv0 = uv;
float rad = In ? progress : 1.0 - progress;
float xc1, yc1;
// I used if/else instead of switch in case it's an old GPU
if (type == 0) { xc1 = .5 - rad2; yc1 = 0.0; }
else if (type == 1) { xc1 = 1.0 - rad; yc1 = .5 - rad2; }
else if (type == 2) { xc1 = .5 - rad2; yc1 = 1.0 - rad; }
else if (type == 3) { xc1 = 0.0; yc1 = .5 - rad2; }
else if (type == 4) { xc1 = 1.0 - rad; yc1 = 0.0; }
else if (type == 5) { xc1 = 1.0 - rad; yc1 = 1.0 - rad; }
else if (type == 6) { xc1 = 0.0; yc1 = 1.0 - rad; }
else if (type == 7) { xc1 = 0.0; yc1 = 0.0; }
else if (type == 8) { xc1 = .5 - rad2; yc1 = .5 - rad2; }
uv.y = 1.0 - uv.y;
vec2 uv2;
if ((uv.x >= xc1) && (uv.x <= xc1 + rad) && (uv.y >= yc1) && (uv.y <= yc1 + rad))
	{
	uv2 = vec2((uv.x - xc1) / rad, 1.0 - (uv.y - yc1) / rad);
	return(In ? getToColor(uv2) : getFromColor(uv2));
	}
return(In ? getFromColor(uv0) : getToColor(uv0));
}

// Author: gre
// License: MIT
// Description: Black lines slide in from the edges over the outgoing image and divide it into panels whose shapes sink, tone after tone, into flat colors; the lines keep shifting, the panels widening and narrowing, while the incoming image's colors pour across them, then its shapes surface out of the colors and the lines slide out
// Tags: grid, lines, panels, flat, palette, abstract, painting
// Preview: 0.25

// @range(0, 0.04) Width of the lines, as a part of the frame's shorter side
uniform float thickness; // = 0.016
// @color Color of the lines
uniform vec4 lineColor; // = vec4(0.04, 0.04, 0.04, 1.0)
// @range(0, 1) How far the lines keep shifting
uniform float shift; // = 0.7
// @range(0, 2) How vivid the flat colors are
uniform float vivid; // = 0.8

const int LEVELS = 4;
const int TAPS = 16;
const int SPOTS = 7;

float hash(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec4 pixel(vec2 p, bool incoming) {
  return incoming ? getToColor(p) : getFromColor(p);
}

// the flat color of a panel: what stands out wins, since the average of several hues is mud
vec4 paint(vec2 lo, vec2 hi, bool incoming) {
  vec4 acc = vec4(0.0);
  float total = 0.0;
  for (int i = 0; i < SPOTS; i++) {
    vec4 c = pixel(mix(lo, hi, 0.15 + 0.7 * fract(vec2(0.754878, 0.569840) * float(i) + 0.4)), incoming);
    float w = 0.05 + max(c.r, max(c.g, c.b)) - min(c.r, min(c.g, c.b));
    w *= w;
    acc += vec4(c.rgb * c.a, c.a) * w;
    total += w;
  }
  vec3 c = acc.rgb / max(acc.a, 1e-5);
  float y = dot(c, vec3(0.299, 0.587, 0.114));
  return vec4(clamp(y + (c - y) * (1.0 + vivid), 0.0, 1.0), acc.a / total);
}

vec4 transition(vec2 uv) {
  bool late = progress > 0.5;
  float u = late ? 1.0 - progress : progress;
  vec2 frame = vec2(ratio, 1.0);
  vec2 p = uv * frame;
  vec2 lo = vec2(0.0);
  vec2 hi = frame;
  // the panel at rest, where its colors are read, so that they hold still while the lines move
  vec2 restLo = lo;
  vec2 restHi = hi;
  float id = 1.0;
  float edge = 1.0;
  float width = 0.5 * thickness * min(ratio, 1.0) * smoothstep(0.0, 0.15, u);
  for (int l = 0; l < LEVELS; l++) {
    if (l == LEVELS - 1 && hash(id + 11.0) < 0.45) {
      id *= 2.0;
      continue;
    }
    float rest = 0.3 + 0.4 * hash(id + 2.0);
    float s = rest + 0.26 * shift * sin((hash(id + 60.0) > 0.5 ? 6.0 : -6.0) * (progress - 0.5) + 2.0 * hash(id + 80.0) - 1.0);
    float enter = smoothstep(0.0, 0.28, u - 0.025 * float(l));
    s = mix((hash(id + 31.0) > 0.5) != late ? 1.06 : -0.06, s, enter);
    vec2 axis = (mod(float(l), 2.0) < 0.5) == (ratio >= 1.0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 at = mix(lo, hi, s);
    vec2 restAt = mix(restLo, restHi, rest);
    float v = dot(p - at, axis);
    edge = min(edge, abs(v) - width);
    float side = step(0.0, v);
    lo = mix(lo, at, axis * side);
    hi = mix(hi, at, axis * (1.0 - side));
    restLo = mix(restLo, restAt, axis * side);
    restHi = mix(restHi, restAt, axis * (1.0 - side));
    id = id * 2.0 + side;
  }

  float sunk = clamp((u - 0.08) / 0.32, 0.0, 1.0);
  vec4 here = pixel(uv, late);
  vec4 acc = vec4(here.rgb, 1.0) * here.a + vec4(0.0, 0.0, 0.0, 1e-5);
  float r = 0.03 * smoothstep(0.02, 0.3, u);
  for (int i = 0; i < TAPS; i++) {
    float a = 2.399963 * float(i);
    vec4 c = pixel(fold(uv + r * sqrt((float(i) + 0.5) / float(TAPS)) * vec2(cos(a), sin(a)) / frame), late);
    acc += vec4(c.rgb, 1.0) * c.a;
  }
  vec4 soft = vec4(acc.rgb / acc.a, here.a);
  soft.rgb = mix(here.rgb, soft.rgb, smoothstep(0.0, 0.1, u));

  float pour = smoothstep(0.0, 1.0, (progress - 0.38 - 0.1 * hash(id + 90.0)) / 0.14);
  float way = hash(id + 70.0);
  vec2 q = (p - lo) / max(hi - lo, 1e-4);
  q = way < 0.5 ? q : 1.0 - q;
  bool tall = hi.y - lo.y > hi.x - lo.x;
  float len = tall ? hi.y - lo.y : hi.x - lo.x;
  float front = ((tall ? q.y : q.x) - pour) * len;
  float flow = 1.0 - smoothstep(-0.0015, 0.0015, front + mix(0.0015, -0.0015, pour));
  restLo /= frame;
  restHi /= frame;
  vec4 flat0 = paint(restLo, restHi, false);
  vec4 flat1 = paint(restLo, restHi, true);
  vec4 col = late ? flat1 : flat0;
  // the tones of a panel sink into its color one after another, the closest first
  float sink = smoothstep(0.0, 0.12, 1.9 * sunk * sunk - length(soft.rgb - col.rgb));
  col = mix(flat0, flat1, flow);
  col.rgb = mix(soft.rgb, col.rgb, sink);
  col.a = mix(here.a, col.a, sink);
  float ink = 1.0 - smoothstep(-0.0015, 0.0015, edge);
  ink *= smoothstep(0.0, 0.002, width);
  return mix(col, vec4(lineColor.rgb, lineColor.a * col.a), ink);
}

// Author: gre
// License: MIT
// Description: The outgoing image settles into flowing bands of its flat tones; a pale and a dark disc of the incoming image's colors glide past each other, the bands parting around them and taking the incoming colors in their wake, then the bands reshape into the incoming image
// Tags: circle, flow, stripes, flat, poster, palette, abstract
// Preview: 0.45

// @range(0.5, 2) Width of the bands
uniform float lanes; // = 1.0
// @range(0.1, 0.28) Radius of the discs, in frame heights
uniform float radius; // = 0.19
// @range(0, 2.5) How vivid the flat colors are
uniform float vivid; // = 1.5

const int N = 9;
const int TAPS = 14;
// between these two moments the shapes are free of both images, so the palettes of both are read instead of their shapes
const float FREED = 0.26;
const float CAUGHT = 0.74;
// from one tone to the next, in deviations
const float GAP = 0.62;

float luma(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec2 spot(int i) {
  return fract(vec2(0.754878, 0.569840) * float(i) + 0.4);
}

float ease(float a, float b, float x) {
  x = clamp((x - a) / (b - a), 0.0, 1.0);
  return x * x * x * (x * (x * 6.0 - 15.0) + 10.0);
}

// the most common color around the tone z, pushed to the lightness of that tone
vec3 paint(vec4 sum, vec2 stats, float z) {
  vec3 c = sum.rgb / sum.a;
  return clamp(stats.x + 1.2 * z * stats.y + (c - luma(c)) * vivid, 0.0, 1.0);
}

// each wake trails its disc: the upper one runs to the right, the lower one to the left
float wakeOf(float k, float u, float x, float px, float width) {
  float v = u - k + 2.0;
  v = k < 0.5 ? max(v, 0.0) : k > 3.5 ? min(v, 0.0) : v;
  float cap = width * sqrt(max(0.25 - v * v, 0.0));
  float way = k > 1.5 ? -1.0 : 1.0;
  return smoothstep(-0.002, 0.002, x - 0.06 - 0.09 * abs(k - 2.0) - way * px + cap);
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  bool late = progress > 0.5;
  float bend = smoothstep(0.0, 1.0, (late ? 0.98 - progress : progress - 0.02) / 0.36);
  bend *= bend;

  vec2 asp = vec2(ratio, 1.0);
  // the color to fall back on where the spots of an image are all transparent
  vec3 own = (a.rgb * a.a + b.rgb * b.a) / max(a.a + b.a, 1e-4);
  vec2 sum = vec2(1e-4);
  vec2 ma = 1e-4 * vec2(luma(own), luma(own) * luma(own));
  vec2 mb = ma;
  vec4 broad = vec4(1e-6);
  for (int i = 0; i < N; i++) {
    vec4 ca = progress < CAUGHT ? getFromColor(spot(i)) : vec4(0.0);
    vec4 cb = progress > FREED ? getToColor(spot(i)) : vec4(0.0);
    vec2 l = vec2(luma(ca.rgb), luma(cb.rgb));
    sum += vec2(ca.a, cb.a);
    ma += vec2(l.x, l.x * l.x) * ca.a;
    mb += vec2(l.y, l.y * l.y) * cb.a;
    vec2 q = (uv - spot(i)) * asp;
    broad += vec4(vec2(l.x, 1.0) * ca.a, vec2(l.y, 1.0) * cb.a) * exp(-26.0 * dot(q, q));
  }
  ma /= sum.x;
  mb /= sum.y;
  ma.y = sqrt(max(ma.y - ma.x * ma.x, 0.0)) + 0.03;
  mb.y = sqrt(max(mb.y - mb.x * mb.x, 0.0)) + 0.03;

  vec4 here = late ? b : a;
  vec2 acc = vec2(luma(here.rgb), 1.0) * here.a;
  if (progress < FREED || progress > CAUGHT) {
    float soft = 0.045 * smoothstep(0.0, 0.2, late ? 1.0 - progress : progress);
    for (int i = 0; i < TAPS; i++) {
      float g = 2.39996 * float(i);
      vec2 q = fold(uv + soft * sqrt((float(i) + 0.5) / float(TAPS)) * vec2(cos(g), sin(g)) / asp);
      vec4 c = late ? getToColor(q) : getFromColor(q);
      acc += vec2(luma(c.rgb), 1.0) * c.a;
    }
  }
  // fine detail melts into a broad field before the shapes move, so their edges do not tear
  vec2 melted = late ? broad.zw : broad.xy;
  float y = mix(acc.x / max(acc.y, 1e-4), melted.x / melted.y, smoothstep(0.0, 0.54, bend));
  y = (y - (late ? mb.x : ma.x)) / (late ? mb.y : ma.y);

  vec2 p = (uv - 0.5) * asp;
  float width = 0.14 * lanes;
  float x = (2.0 * mix(progress, ease(0.0, 1.0, progress), 0.5) - 1.0) * (ratio + 0.5);
  float bob = 0.07 * sin(9.0 * progress);
  vec2 d1 = p - vec2(x, bob - 0.23);
  vec2 d2 = p - vec2(-x, bob + 0.23);
  float r2 = radius * radius;
  // stream function of a flow parting around both discs
  float psi = p.y + 0.02 * sin(5.0 * p.x + 6.0 * progress);
  psi -= r2 * (d1.y / max(dot(d1, d1), r2) + d2.y / max(dot(d2, d2), r2));
  float u = psi / width;
  float l1 = length(d1), l2 = length(d2);
  float inside = radius - min(l1, l2);

  float field = mix(y, GAP * u, bend);
  float k = clamp(floor(field / GAP + 2.0), 0.0, 3.0);
  vec2 z = (vec2(k, k + 1.0) - 2.0) * GAP;
  if (inside > -0.002) {
    // the rim of a disc lies between the closest lane and the disc
    z = vec2(clamp(floor(field / GAP + 2.5), 0.0, 4.0) - 2.0, l1 < l2 ? 2.0 : -2.0) * GAP;
  }
  vec2 n = z / GAP + 2.0;
  vec2 head = vec2(wakeOf(n.x, u, x, p.x, width), inside > -0.002 ? 1.0 : wakeOf(n.y, u, x, p.x, width));
  float aa = mix(0.03, 0.0016, smoothstep(0.0, 0.5, bend));
  float top = smoothstep(-aa, aa, mix(0.22, width / GAP, bend) * (field - 0.5 * (z.x + z.y)));
  top = inside > -0.002 ? smoothstep(-0.0015, 0.0015, inside) : top;
  // how much each image shows, as most places need the palette of only one
  vec2 share = vec2(1.0 - top, top);
  float showA = dot(share, 1.0 - head), showB = dot(share, head);
  vec4 a0 = 1e-6 * vec4(own, 1.0), a1 = a0, b0 = a0, b1 = a0;
  for (int i = 0; i < N; i++) {
    if (showA > 0.0) {
      vec4 c = getFromColor(spot(i));
      vec2 d = (luma(c.rgb) - ma.x) / ma.y - z;
      vec2 w = c.a * (exp(-6.0 * d * d) + 1e-3);
      a0 += vec4(c.rgb, 1.0) * w.x;
      a1 += vec4(c.rgb, 1.0) * w.y;
    }
    if (showB > 0.0) {
      vec4 c = getToColor(spot(i));
      vec2 d = (luma(c.rgb) - mb.x) / mb.y - z;
      vec2 w = c.a * (exp(-6.0 * d * d) + 1e-3);
      b0 += vec4(c.rgb, 1.0) * w.x;
      b1 += vec4(c.rgb, 1.0) * w.y;
    }
  }
  vec3 c0 = mix(paint(a0, ma, z.x), paint(b0, mb, z.x), head.x);
  vec3 c1 = mix(paint(a1, ma, z.y), paint(b1, mb, z.y), head.y);
  vec3 col = mix(c0, c1, top);

  float flatness = smoothstep(0.02, 0.2, progress) * (1.0 - smoothstep(0.8, 0.98, progress));
  return vec4(mix(here.rgb, col, flatness), mix(a.a, b.a, smoothstep(0.35, 0.65, progress)));
}

// Author: gre
// License: MIT
// Description: The outgoing image is a sheet cut with rows of staggered slits that is pulled from both ends: it lengthens, the slits open into diamonds and the strands between them twist and thin out like expanded metal until only the incoming image is left behind
// Tags: paper, stretch, pattern, 3d, shadow

// @range(0.05, 0.4) Length of a slit and its bridge, relative to the image height
uniform float size; // = 0.16
// @range(0, 3) How much the sheet lengthens as it is pulled
uniform float stretch; // = 1.6
// @range(0, 1) Strength of the shading of the twisting strands and of their shadow
uniform float shading; // = 0.7
// @range(0, 1) How much the sheet narrows at its waist as it is pulled
uniform float neck; // = 0.8
// @param Pull the sheet sideways instead, with vertical slits
uniform bool horizontal; // = false

vec4 transition(vec2 uv) {
  float t = progress;
  float q = t * t * (3.0 - 2.0 * t);
  if (q <= 0.0) return getFromColor(uv);
  vec2 asp = vec2(ratio, 1.0);
  // work with the slits along x and the pull along y
  vec2 p = (uv - 0.5) * asp;
  if (horizontal) p = p.yx;
  float Sy = 1.0 + stretch * q;
  // (ys: -0.5 to 0.5 along the sheet's length)
  float ys = clamp(p.y / (Sy * (horizontal ? ratio : 1.0)), -0.5, 0.5);
  float hw = 0.5 * (horizontal ? 1.0 : ratio);
  float wf = 1.0 - 0.7 * neck * q * (1.0 - 4.0 * ys * ys);
  // (no edge on the frame's border at the start)
  float side = (hw * wf - abs(p.x)) / (0.003 * min(1.0, 200.0 * q) + 1e-7);
  p.x /= wf;
  float a = 0.5 * size;
  float b = 0.22 * size * Sy;
  float j = floor(p.y / b + 0.5);
  float xo = mod(j, 2.0) * a;
  float i = floor((p.x - xo) / (2.0 * a) + 0.5);
  vec2 c = vec2(i * 2.0 * a + xo, j * b);
  vec2 d = p - c;
  // check the two neighbouring rows too: the diamonds interlock
  vec2 d2 = p - vec2(c.x + (p.x > c.x ? a : -a), c.y + (p.y > c.y ? b : -b));
  if (abs(d2.x) / a + abs(d2.y) / b < abs(d.x) / a + abs(d.y) / b) d = d2;

  // the hole: a slit (the bridges between slits keep the sheet whole) that opens into a diamond,
  // slightly larger than the cell at the end, so the strands have gone edge-on
  float grow = 1.0 + 0.12 * q;
  float A = max(a * mix(0.72, 1.0, q) * grow, 1e-4);
  float H = max(b * sqrt(q) * grow, 1e-5);
  float f = abs(d.x) / A + abs(d.y) / H - 1.0;
  float dist = f / sqrt(1.0 / (A * A) + 1.0 / (H * H));
  float e = 0.004;
  // (the edge moves in by its whole softness at the end, so even the finest strands are gone)
  float hole = max(smoothstep(0.0, e, e * q * q * q * q - dist), clamp(0.5 - side, 0.0, 1.0));

  vec4 img = vec4(0.0);
  if (hole < 1.0) {
    vec2 sp = vec2(p.x, p.y / Sy);
    if (horizontal) sp = sp.yx;
    img = getFromColor(clamp(sp / asp + 0.5, 0.0, 1.0));
    float facet = clamp(d.x * d.y / (0.25 * a * b + 1e-6), -1.0, 1.0);
    float rim = clamp(1.0 - dist / (0.25 * b + 1e-5), 0.0, 1.0);
    img.rgb *= 1.0 + shading * q * (0.35 * facet - 0.25 * rim);
    if (hole <= 0.0) return img;
  }
  vec4 bg = getToColor(uv);
  // soft shadow of the mesh (only within the sheet, not beside its waist)
  float sh = (1.0 - smoothstep(0.0, 0.25 * b + e, -dist)) * clamp(0.5 + side, 0.0, 1.0);
  bg.rgb *= 1.0 - 0.45 * shading * sh * (1.0 - q);
  return mix(img, bg, hole);
}

// Author: gre
// License: MIT
// Description: A slit is cut across the middle of the outgoing image and the incoming image is pulled down through it from behind, bulging the old picture above the slit, then swings back up in front of it to cover the frame
// Tags: slit, thread, paper, layers, through

// @range(0.5, 0.95) Width of the incoming sheet while it passes through the slit
uniform float sheet; // = 0.84
// @range(0, 1) Strength of shadows and the bulge of the hidden sheet
uniform float depth; // = 0.8

const vec2 LIGHT = vec2(-0.6, 0.8);

vec2 rectE(vec2 q, vec2 lo, vec2 hi, vec2 box) {
  return max(lo - q, q - hi) * box;
}

float rectD(vec2 q, vec2 lo, vec2 hi, vec2 box) {
  vec2 e = rectE(q, lo, hi, box);
  return max(e.x, e.y);
}

float bump(vec2 q, vec2 lo, vec2 hi, vec2 box, float y0) {
  vec2 e = rectE(q, lo, hi, box) + 0.1;
  float d = length(max(e, 0.0)) + min(max(e.x, e.y), 0.0) - 0.1;
  return (1.0 - smoothstep(-0.12, 0.05, d)) * smoothstep(y0, y0 + 0.1, q.y);
}

vec4 transition(vec2 uv) {
  vec2 box = vec2(ratio, 1.0);
  float px = 1.0 / 200.0;
  float t = progress;
  float k = clamp(depth, 0.0, 1.0);
  float s0 = clamp(sheet, 0.5, 0.95);
  float y0 = 0.5;

  // down then up as one swing: the phase lengths match the deceleration into the turn to the acceleration out of it
  float yStart = y0 + 0.012;
  // at the turn the sheet's top edge and its AA fringe sit just under the slit, so the layer switch is invisible
  float yTurn = y0 - 0.004 - 1.5 * px - s0;
  float t0 = 0.06;
  float tTurn = t0 + (1.0 - t0) / (1.0 + sqrt(max(-yTurn, 0.0) / (yStart - yTurn)));
  float down = smoothstep(t0, tTurn, t);
  float rise = smoothstep(tTurn, 1.0, t);
  float s = mix(s0, 1.0, rise);
  float yb = mix(mix(yStart, yTurn, down), 0.0, rise);
  vec2 lo = vec2(0.5 - 0.5 * s, yb), hi = vec2(0.5 + 0.5 * s, yb + s);
  float through = step(tTurn, t);
  float threading = smoothstep(t0, t0 + 0.12, t) * (1.0 - smoothstep(tTurn - 0.1, tTurn, t));
  float enter = smoothstep(t0, t0 + 0.15, t);
  float hidden = (1.0 - through) * enter;

  float cut = smoothstep(0.0, 0.12, t);
  float halfL = (0.5 * s0 + 0.035) * cut;
  float along = clamp(abs(uv.x - 0.5) / max(halfL, 1e-4), 0.0, 1.0);
  float onSlit = (1.0 - smoothstep(halfL - px, halfL, abs(uv.x - 0.5))) * cut;
  float gap = (0.004 + 0.007 * threading * (1.0 - along * along)) * cut;
  float dy = uv.y - y0;

  vec2 grad = vec2(0.0);
  if (hidden * k > 0.0) {
    vec2 e = vec2(0.01, 0.0);
    float bx = bump(uv + e.xy, lo, hi, box, y0) - bump(uv - e.xy, lo, hi, box, y0);
    float by = bump(uv + e.yx, lo, hi, box, y0) - bump(uv - e.yx, lo, hi, box, y0);
    grad = vec2(bx, by) * hidden * k;
  }
  vec4 c = getFromColor(uv - 0.01 * grad);
  c.rgb *= 1.0 - 1.2 * dot(grad, LIGHT);

  c.rgb *= 1.0 - onSlit * 0.85 * (1.0 - smoothstep(gap - 0.5 * px, gap + 0.5 * px, abs(dy)));
  float lipLit = onSlit * smoothstep(gap - 0.5 * px, gap + 0.5 * px, -dy) * (1.0 - smoothstep(gap, gap + 0.012, -dy));
  c.rgb += 0.12 * lipLit;

  float below = 1.0 - smoothstep(-0.5 * px, 0.5 * px, uv.y - (y0 - gap));
  float front = mix(below, 1.0, through);
  float lift = mix(1.0, 0.6, rise);
  float sh = rectD(uv - vec2(0.008, -0.014) * lift, lo, hi, box);
  float shadowFront = mix(below, 1.0, smoothstep(tTurn, tTurn + 0.08, t));
  c.rgb *= 1.0 - 0.45 * k * shadowFront * (1.0 - smoothstep(-0.02, 0.025, sh)) * (1.0 - rise * rise) * enter;

  float d = rectD(uv, lo, hi, box);
  // AA fades out so the full-frame border lands exact
  float aa = px * (1.0 - rise) + 1e-4;
  float cov = (1.0 - smoothstep(-aa, aa, d - 0.004 * rise)) * front;
  vec4 to = getToColor(clamp((uv - lo) / s, 0.0, 1.0));
  float lip = (y0 - gap - uv.y) / px;
  float lipShade = threading * step(0.0, lip);
  to.rgb *= 1.0 - 0.5 * k * lipShade * exp(-lip / 5.0);
  to.rgb *= 1.0 - 0.12 * k * smoothstep(-0.01, 0.0, d) * (1.0 - rise);
  return mix(c, to, cov);
}

// Author: gre
// License: MIT
// Description: The frame is cut into vertical reels that spin downward like drums, motion-blurred with speed, carrying the outgoing image then the incoming one, and stop one after another from left to right with a small mechanical bounce
// Tags: 3d, spin, stripes, motion-blur

// @range(1, 16, 1) Number of reels
uniform int reels; // = 5
// @range(0, 1) Amount of vertical motion blur while the reels spin fast
uniform float blur; // = 0.6
// @range(0, 0.9) Delay between the first and the last reel's stop, as a part of the transition
uniform float stagger; // = 0.45
// @range(0, 1) Size of the bounce when a reel stops
uniform float bounce; // = 0.5
// @color Color of the separators between the reels
uniform vec4 separator; // = vec4(0.04, 0.04, 0.05, 1.0)

const float PI = 3.141592653589793;
// half of the arc of the drum seen in the frame, in radians
const float ARC = 1.15;
const float SETTLE = 0.1;
const float LINE = 0.006;
const float EDGE = 0.0015;

float stopTime(float i, float n) {
  float order = n > 1.0 ? i / (n - 1.0) : 1.0;
  return (1.0 - SETTLE) * (1.0 - clamp(stagger, 0.0, 0.9) * (1.0 - order));
}

// how far the reel has turned at time t, in image heights: it speeds up, slows down to its stop
// a little past the incoming image and springs back onto it
float reelOffset(float t, float stopT, float turns) {
  float amp = 0.07 * bounce;
  // speed at the stop, matched with the start of the bounce
  float v1 = amp * PI * stopT / (turns * SETTLE);
  float u = clamp(t / stopT, 0.0, 1.0);
  float g = u * u * (3.0 - 2.0 * u) + v1 * (u * u * u - u * u);
  float b = clamp((t - stopT) / SETTLE, 0.0, 1.0);
  return turns * g + amp * sin(PI * b) * (1.0 - b) * (1.0 - b);
}

// the reel's speed at time t, the derivative of reelOffset, in image heights per transition
float reelSpeed(float t, float stopT, float turns) {
  float amp = 0.07 * bounce;
  float v1 = amp * PI * stopT / (turns * SETTLE);
  if (t < stopT) {
    float u = max(t / stopT, 0.0);
    return turns * (6.0 * u * (1.0 - u) + v1 * u * (3.0 * u - 2.0)) / stopT;
  }
  float b = min((t - stopT) / SETTLE, 1.0);
  return amp * (1.0 - b) * (PI * cos(PI * b) * (1.0 - b) - 2.0 * sin(PI * b)) / SETTLE;
}

vec4 transition (vec2 uv) {
  float n = max(float(reels), 1.0);
  float i = min(floor(uv.x * n), n - 1.0);
  float lx = uv.x * n - i;
  float stopT = stopTime(i, n);
  // an odd number of turns, more for the reels that spin longer, so they land on the incoming image
  float turns = 2.0 * floor(stopT * 4.0) + 1.0;

  float drum = smoothstep(0.0, 0.12, progress) * (1.0 - smoothstep(stopT, stopT + SETTLE, progress));
  float y = 2.0 * uv.y - 1.0;
  // theta: the angle around the drum's axis, 0 facing the viewer
  float theta = asin(clamp(y * sin(ARC), -1.0, 1.0));
  float v = mix(uv.y, 0.5 + theta / (2.0 * ARC), drum);
  float depth = (1.0 - cos(theta)) * drum;
  float px = 0.5 + (lx - 0.5) * (1.0 + 0.2 * depth);

  // offset from the resting position, -turns at the start, 0 once landed
  float off = reelOffset(progress, stopT, turns) - turns;
  float speed = abs(reelSpeed(progress, stopT, turns));
  float spread = blur * min(speed * 0.02, 0.22) * drum;

  vec4 c = vec4(0.0);
  float wsum = 0.0;
  for (int k = 0; k < 8; k++) {
    float f = float(k) / 7.0 - 0.5;
    float w = 1.0 - abs(f);
    float vv = v + off + spread * f;
    float seg = floor(vv);
    vec2 q = vec2((i + clamp(px, 0.0, 1.0)) / n, vv - seg);
    vec4 s = mod(seg, 2.0) < 0.5 ? getToColor(q) : getFromColor(q);
    // a thin shadow at the seams between the images, not at the frame's top and bottom edges
    s.rgb *= 1.0 - 0.6 * drum * (1.0 - y * y) * (1.0 - smoothstep(0.0, 0.02, min(q.y, 1.0 - q.y)));
    c += w * s;
    wsum += w;
    if (spread < 1e-4) break;
  }
  c /= wsum;

  float facing = cos(theta);
  c.rgb *= mix(1.0, 0.25 + 0.75 * facing * facing, drum);
  c.rgb += drum * 0.07 * c.a * exp(-12.0 * (y - 0.3) * (y - 0.3));

  float env = smoothstep(0.0, 0.1, progress) * (1.0 - smoothstep(0.9, 1.0, progress));
  float reelW = ratio / n;
  float persp = reelW / (1.0 + 0.2 * depth);
  float dSide = min(px, 1.0 - px) * persp;
  float dInner = min(i > 0.5 ? px : 2.0, i < n - 1.5 ? 1.0 - px : 2.0) * persp;
  float line = 1.0 - smoothstep(0.5 * LINE - EDGE, 0.5 * LINE + EDGE, dInner);
  float outside = 1.0 - smoothstep(-EDGE, 0.0, dSide);
  c.rgb *= 1.0 - 0.35 * env * (1.0 - smoothstep(0.0, 0.03 * reelW + LINE, dInner));
  return mix(c, separator, max(line * env, outside));
}

// Author: gre
