  col = mix(col, vec3(1.0), smoothstep(0.5, 1.0, hi - lo));
  vec3 rgb = mix(white, ray * (0.2 + 1.2 * col) + 0.1 * col * d * alpha, saturation * smoothstep(0.0, 0.45, d));
  return alpha > 0.0 ? vec4(min(rgb / alpha, 1.0), alpha) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: Comic-style speed lines shoot in from the edges of the frame toward a focus point as the outgoing image punches in; at the peak it cuts to the incoming image, which settles back as the lines retract to the edges
// Tags: comic, lines, radial, zoom, stylized

// @param Point the lines converge to, from (0, 0) at the bottom left to (1, 1) at the top right
uniform vec2 center; // = vec2(0.5, 0.5)
// @color Color of the lines
uniform vec4 lineColor; // = vec4(1.0, 1.0, 1.0, 1.0)
// @range(30, 240) Number of lines around the focus point
uniform float density; // = 110.0
// @range(0, 1) Size of the clear area around the focus point at the peak, from almost nothing to the whole frame
uniform float focus; // = 0.35
// @range(0, 0.5) How much the images punch in toward the focus point
uniform float zoom; // = 0.12

const float PI = 3.141592653589793;
const float AA = 0.0012;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// how far the lines are in, from 0 (all out of the frame) to 1 (peak), for a line with random h:
// each line shoots in up to a little later than the others and retracts the same way
float reachOf(float h) {
  float d = 0.05 * h;
  float a = 1.0 - clamp((progress - d) / 0.4, 0.0, 1.0);
  float b = clamp((progress - 0.5 - d) / 0.4, 0.0, 1.0);
  return (1.0 - a * a * a) * (1.0 - b * b * b);
}

// coverage of one layer of lines: n angular cells around the focus point (a in 0..1),
// at most one tapered line per cell. e is the elliptical radius (1 at the edges of the frame),
// r the radius in frame heights, E the elliptical radius where the ray leaves the frame
float layer(float a, float e, float r, float n, float seed, float E) {
  // (a can be exactly 1, which is cell 0 again)
  float cell = mod(floor(a * n), n);
  float h1 = hash12(vec2(cell, seed));
  float h2 = hash12(vec2(cell, seed + 7.0));
  float h3 = hash12(vec2(cell, seed + 13.0));
  float on = step(0.22, h1);
  float h4 = hash12(vec2(cell, seed + 50.0 + floor(progress * 12.0)));
  // (a share of the way from the frame's edge to the focus point, so that the burst stays even
  // when the focus point is off-center)
  float len = 1.0 - 0.85 * h2 * h2 - 0.15 * h4;
  float tipPeak = E * (1.0 - (1.0 - focus) * (0.55 + 0.45 * len));
  float tip = mix(E + 0.05, tipPeak, reachOf(h3));
  float t = clamp((e - tip) / max(E * (0.2 + 0.5 * h2), 1e-4), 0.0, 1.0);
  float cellWidth = 2.0 * PI * r / n;
  // its position across the cell, and its width, kept so that its antialiased edges stay in the cell
  float offset = 0.3 + 0.4 * h3;
  float width = min(cellWidth * (0.06 + 0.22 * h1) * sqrt(t), (0.5 - abs(offset - 0.5)) * cellWidth - AA);
  float across = abs(fract(a * n) - offset) * cellWidth;
  return on * (1.0 - smoothstep(width - AA, width + AA, across)) * step(tip, e);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 d = (uv - center) * asp;
  float r = length(d);
  // (nudged off zero, where atan is undefined)
  float a = atan(d.y, d.x + 1e-6) / (2.0 * PI) + 0.5;
  // elliptical radius, following the shape of the frame: 1 at the middle of its edges
  // when the focus point is in the middle
  float e = length((uv - center) * 2.0);
  // where the ray from the focus point through this pixel leaves the frame, so that every line
  // enters the frame at once
  vec2 w = uv - center;
  vec2 room = vec2(w.x > 0.0 ? 1.0 - center.x : center.x, w.y > 0.0 ? 1.0 - center.y : center.y);
  vec2 exits = room / max(abs(w), vec2(1e-6));
  float E = e * min(exits.x, exits.y);

  float k = p < 0.5 ? smoothstep(0.0, 0.5, p) : 1.0 - smoothstep(0.5, 1.0, p);
  float s = 1.0 - zoom * k * k;
  // (between the focus point and uv, so in the frame)
  vec2 q = center + (uv - center) * s;
  vec4 c = p < 0.5 ? getFromColor(q) : getToColor(q);

  // two interleaved layers of lines so that their spacing looks random
  float n = max(floor(density), 2.0);
  float l = layer(a, e, r, n, 1.0, E);
  l = max(l, layer(fract(a + 0.5 / n), e, r, n, 31.0, E));
  l *= lineColor.a;

  vec4 pc = vec4(c.rgb * c.a, c.a);
  pc = pc * (1.0 - l) + vec4(lineColor.rgb, 1.0) * l;
  return pc.a > 0.0 ? vec4(pc.rgb / pc.a, pc.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image wraps itself onto a shaded ball that shrinks and rolls away, revealing the incoming image under its shadow
// Tags: 3d, sphere, roll, wrap, shape

// @param Direction the ball rolls away toward
uniform vec2 direction; // = vec2(1.0, 0.0)
// @range(0.1, 0.5) Radius of the ball once wrapped, relative to the shorter side of the frame
uniform float size; // = 0.3
// @range(0, 1) Strength of the light and shading on the ball
uniform float shading; // = 0.6
// @range(0, 1) Darkness of the soft shadow the ball casts on the incoming image
uniform float shadow; // = 0.5

const float PI = 3.14159265;
const float AA = 0.0015;
const vec3 LIGHT = vec3(-0.5, 0.6, 1.0) / 1.2689;

vec4 transition(vec2 uv) {
  vec4 b = getToColor(uv);

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  vec2 side = vec2(-dir.y, dir.x);
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float shorter = min(ratio, 1.0);
  float r0 = clamp(size, 0.1, 0.5) * shorter;

  // the image curves into a ball (infinite radius: exactly flat at the start), then the
  // ball shrinks while rolling away until it and its shadow have left the frame
  float w = clamp(progress / 0.45, 0.0, 1.0);
  w = 1.0 - (1.0 - w) * (1.0 - w);
  float away = smoothstep(0.3, 1.0, progress);
  away *= away;
  float wrapped = r0 / max(w, 1e-4);
  float radius = wrapped * mix(1.0, 0.5, away);
  // the image is pulled tighter as it wraps, so that it ends up covering the whole ball
  // (its shortest half extent reaches around to the back)
  float tight = mix(1.0, min(1.0, 0.48 * shorter / (PI * r0)), w * w);
  float paper = radius * tight;
  float e = 0.5 * (abs(dir.x) * ratio + abs(dir.y));
  // far enough that the ball (0.5 * r0 by then) and its shadow (within 0.9 * r0 of it) have left
  float full = e + 1.1 * r0 + 2.0 * AA;
  float travel = away * full;
  vec2 center = dir * travel;
  // rolling without slipping: the integral of dtravel / radius while the radius shrinks
  float angle = -2.0 * full * log(1.0 - 0.5 * away) / wrapped;

  vec2 d = p - center;
  float r = length(d);

  vec2 sd = d - vec2(0.25, -0.3) * radius * w;
  float sh = shadow * w * (1.0 - smoothstep(0.6 * radius, 1.4 * radius, length(sd)));
  vec4 bg = vec4(b.rgb * b.a * (1.0 - sh), b.a);

  vec4 ball = vec4(0.0);
  float cover = 1.0 - smoothstep(radius - AA, radius + AA, r);
  if (cover > 0.0) {
    // normal of the visible point of the ball (no squared radius, which overflows when it is huge)
    vec2 nd = d / radius;
    vec3 n = vec3(nd, sqrt(max(1.0 - dot(nd, nd), 0.0)));
    float u = dot(n.xy, dir);
    float s = dot(n.xy, side);
    float cu = cos(angle), su = sin(angle);
    vec3 q = vec3(u * cu - n.z * su, s, u * su + n.z * cu);
    // the image is wrapped around the ball from its front point, distances kept along the surface
    float lq = length(q.xy);
    float arc = atan(lq, q.z) * paper;
    vec2 img = lq > 0.0 ? (q.x * dir + q.y * side) / lq * arc : vec2(0.0);
    vec2 iuv = img / vec2(ratio, 1.0) + 0.5;
    vec2 edge = min(iuv, 1.0 - iuv) * vec2(ratio, 1.0);
    float inside = cover * smoothstep(-AA, AA, min(edge.x, edge.y));
    if (inside > 0.0) {
      vec4 c = getFromColor(clamp(iuv, 0.0, 1.0));
      float diff = max(dot(n, LIGHT), 0.0);
      float spec = pow(max(reflect(-LIGHT, n).z, 0.0), 24.0);
      float k = shading * w;
      vec3 lit = c.rgb * mix(1.0, 0.25 + 0.85 * diff, k) + 0.35 * k * spec;
      ball = vec4(clamp(lit, 0.0, 1.0) * c.a, c.a) * inside;
    }
  }

  // the ball over the incoming image, premultiplied so transparent images do not bleed their color
  vec4 c = ball + bg * (1.0 - ball.a);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image curls round into a spinning top standing on its point, which whirls faster and faster with its picture streaking round it, wobbles, then skitters off out of the frame, uncovering the incoming image under its shadow
// Tags: 3d, spin, curl, shadow

// @range(0, 1) Lean of the wobble while the top spins
uniform float wobble; // = 0.5
// @range(2, 12) Turns of the top before it leaves
uniform float turns; // = 7.0

const float PI = 3.14159265;
const float CAM = 3.0;
const float GROUND = 0.07;

float a1, c1, rMax, hSheet, spin, tilt, prec, wRow;
vec3 shift;

// radius of the top along its height, 0 at the point, 1 at the belly, then a shoulder into the stem
float profile(float v) {
  v = clamp(v, 0.0, 1.0);
  float s = min(v / 0.6, 1.0);
  return max(mix(1.0 - pow(1.0 - s, 1.6), 0.08, smoothstep(0.58, 0.85, v)), 0.02);
}

// the point and the stem narrow ahead of the belly so the half-curled sheet doesn't read as a jar
float widthAt(float v) {
  float e = clamp(abs(v - 0.6) / 0.6, 0.0, 1.0);
  return mix(1.0, 2.0 * PI * rMax * profile(v) / ratio, 1.0 - pow(1.0 - a1, 1.0 + 3.0 * e));
}

// atan(q.x, q.y) with comparisons for the quadrant: some backends turn atan(-0.0, y) into -pi, and a series
// for small angles, where their atan is too coarse once scaled by the bend radius
float angleOf(vec2 q) {
  vec2 a = abs(q);
  float b;
  if (a.x < 0.25 * a.y) {
    float w = a.x / a.y;
    float w2 = w * w;
    b = w * (1.0 - w2 * (1.0 / 3.0 - w2 * (0.2 - w2 / 7.0)));
  } else if (a.x < a.y) {
    b = atan(a.x / a.y);
  } else {
    b = 0.5 * PI - atan(a.y / max(a.x, 1e-9));
  }
  if (q.y < 0.0) b = PI - b;
  return q.x < 0.0 ? -b : b;
}

vec3 rotY(vec3 p, float a) {
  float c = cos(a), s = sin(a);
  return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}

// (arc along the row, height on the sheet 0..1, distance to the sheet)
vec3 unbend(vec3 p) {
  float base = -0.5 + GROUND * a1;
  vec3 apex = vec3(0.0, base, -rMax * a1);
  vec3 q = rotY(p - shift - apex, -prec);
  float c = cos(tilt), s = sin(tilt);
  q.xy = mat2(c, -s, s, c) * q.xy;
  q = rotY(q, prec + spin) + apex;
  float v = (q.y - base) / hSheet;
  wRow = widthAt(v);
  float k = c1 * 2.0 * PI / (ratio * wRow);
  float zf = -a1 * rMax * (1.0 - profile(v));
  // radial distance overestimates the true one by up to the steepest slope of the profile
  float sl = a1 * rMax * 5.2 / hSheet;
  float lip = inversesqrt(1.0 + sl * sl);
  if (k < 1e-3) return vec3(q.x, v, (q.z - zf) * lip);
  float R = 1.0 / k;
  vec2 d = vec2(q.x, q.z - zf + R);
  return vec3(angleOf(d) * R, v, (length(d) - R) * lip);
}

float sdf(vec3 p) {
  vec3 u = unbend(p);
  vec2 o = max(abs(u.xy - vec2(0.0, 0.5)) - vec2(0.5 * ratio * wRow, 0.5), 0.0) * vec2(1.0, hSheet);
  return length(vec3(o, u.z));
}

// once the row is closed, both sides of the seam fade to the same colour
vec4 sheet(float s, float v) {
  float o = s < 0.5 ? s + 1.0 : s - 1.0;
  float m = 0.5 * (1.0 - smoothstep(0.0, 0.05, min(s, 1.0 - s))) * smoothstep(0.9, 1.0, c1);
  vec2 inset = vec2(0.004 * m, 0.0);
  return mix(
    getFromColor(clamp(vec2(s, v), inset, 1.0 - inset)),
    getFromColor(clamp(vec2(o, v), inset, 1.0 - inset)), m);
}

vec4 transition(vec2 uv) {
  float t = progress;
  a1 = smoothstep(0.0, 0.3, t);
  c1 = min(1.0, 1.06 * a1);
  float a2 = smoothstep(0.2, 0.75, t);
  float a3 = smoothstep(0.6, 1.0, t);
  // sized from the shorter side so a portrait frame still gives a squat top
  rMax = 0.27 * min(1.0, 1.4 * ratio);
  hSheet = mix(1.0, 2.6 * rMax, a1);
  spin = turns * 2.0 * PI * a2 * a2 + 8.0 * a3;
  float x2 = clamp((t - 0.2) / 0.55, 0.0, 1.0);
  float x3 = clamp((t - 0.6) / 0.4, 0.0, 1.0);
  float da2 = 6.0 * x2 * (1.0 - x2) / 0.55;
  float da3 = 6.0 * x3 * (1.0 - x3) / 0.4;
  float omega = turns * 4.0 * PI * a2 * da2 + 8.0 * da3;
  prec = 9.0 * a2 * a2 + 3.0 * a3;
  tilt = wobble * 0.3 * a2 * a2 * (1.0 - a3) + 0.45 * a3 * a3;
  float hop = 0.05 * abs(sin(a3 * 3.0 * PI)) * (1.0 - a3);
  shift = vec3(a3 * a3 * (0.5 * ratio + 2.5 * rMax + 0.5), hop, 0.0);

  // any eye position leaves the flat frame exact; a raised one looks down onto the shoulder
  vec3 ro = vec3(0.0, 1.1, CAM);
  vec3 rd = normalize(vec3((uv - 0.5) * vec2(ratio, 1.0), 0.0) - ro);
  float hd = (CAM - 0.6) / -rd.z;
  float hEnd = (CAM + 1.2) / -rd.z;
  float minD = 1e3;
  bool hit = false;
  for (int i = 0; i < 100; i++) {
    float d = sdf(ro + rd * hd);
    minD = min(minD, d);
    if (d < 4e-4) { hit = true; break; }
    hd += d * 0.9;
    if (hd > hEnd) break;
  }

  vec4 bg = getToColor(uv);
  float shadowAmt = a1 * (1.0 - a3);
  vec3 foot = vec3(shift.x, -0.5 + GROUND * a1, -rMax);
  vec2 fs = (ro + (foot - ro) * (CAM / (CAM - foot.z))).xy;
  vec2 fd = ((uv - 0.5) * vec2(ratio, 1.0) - fs - vec2(0.5 * rMax, 0.0)) / vec2(rMax * 1.4, 0.04);
  float contact = exp(-dot(fd, fd)) / (1.0 + 20.0 * shift.y);
  bg.rgb *= 1.0 - (0.25 * (1.0 - smoothstep(0.0, 0.08, minD)) + 0.5 * contact) * shadowAmt;
  if (!hit) return bg;
  // converge past the loose march tolerance so every backend lands on the same texel
  for (int j = 0; j < 3; j++) hd += sdf(ro + rd * hd);

  vec3 p = ro + rd * hd;
  vec3 u = unbend(p);
  float w = wRow;
  vec2 e = vec2(1e-3, 0.0);
  vec3 n = normalize(vec3(
    unbend(p + e.xyy).z - unbend(p - e.xyy).z,
    unbend(p + e.yxy).z - unbend(p - e.yxy).z,
    unbend(p + e.yyx).z - unbend(p - e.yyx).z));
  bool front = dot(n, rd) < 0.0;
  if (!front) n = -n;
  float s0 = u.x / (ratio * w) + 0.5;
  // a trail behind each point, brightest at its head, so the spin reads in a still frame
  float blur = min(omega / (2.0 * PI) * 0.012, 0.4) * smoothstep(0.9, 1.0, c1);
  vec4 c = vec4(0.0);
  float tw = 0.0;
  for (int j = 0; j < 12; j++) {
    float f = float(j) / 11.0;
    float wt = 1.0 - 0.8 * f;
    float s = s0 - blur * f;
    s = s < 0.0 ? s + 1.0 : s;
    c += sheet(s, u.y) * wt;
    tw += wt;
    if (blur == 0.0) break;
  }
  c /= tw;
  vec3 L = normalize(vec3(-0.5, 0.7, 1.0));
  float diff = max(dot(n, L), 0.0);
  float spec = pow(max(dot(reflect(-L, n), -rd), 0.0), 24.0);
  float shade = mix(1.0, 0.45 + 0.7 * diff, a1);
  if (front) c.rgb = c.rgb * shade + 0.35 * spec * a1 * c.a;
  else c.rgb *= 0.35 * shade;
  float aa = 1.5 / 200.0;
  float ex = mix(1.0, smoothstep(0.0, aa, 0.5 * ratio * w - abs(u.x)), c1 * (1.0 - c1) * 4.0);
  float ey = mix(1.0, smoothstep(0.0, aa / hSheet, 0.5 - abs(u.y - 0.5)), min(a1 * 4.0, 1.0));
  return mix(bg, c, min(ex, ey));
}

// Author: gre
// License: MIT
// Description: Square blocks switch to the incoming image one after another along a rectangular spiral, from the border inward or from the center outward
// Tags: wipe, grid, blocks, spiral

// @param Number of blocks (columns, rows)
uniform ivec2 grid; // = ivec2(8, 6)
// @param Spiral from the top left corner inward; false spirals from the center outward, ending at the top left corner
uniform bool inward; // = true
// @param Turn clockwise; false turns counterclockwise
uniform bool clockwise; // = true
// @range(0, 0.5) Duration of each block's fade, as a fraction of the transition
uniform float smoothness; // = 0.05

// Position of the cell c (from the top left corner) along the spiral that runs clockwise
// from the top left corner of a n.x by n.y grid inward, from 0 to n.x * n.y - 1
float spiralIndex(vec2 c, vec2 n) {
  // ring: distance to the border, in cells
  float k = min(min(c.x, c.y), min(n.x - 1.0 - c.x, n.y - 1.0 - c.y));
  vec2 s = n - 2.0 * k;
  vec2 l = c - k;
  float before = n.x * n.y - s.x * s.y;
  float along;
  if (l.y == 0.0) along = l.x; // top side, to the right
  else if (l.x == s.x - 1.0) along = s.x - 1.0 + l.y; // right side, down
  else if (l.y == s.y - 1.0) along = 2.0 * s.x + s.y - 3.0 - l.x; // bottom side, to the left
  else along = 2.0 * (s.x - 1.0) + 2.0 * (s.y - 1.0) - l.y; // left side, up
  return before + along;
}

vec4 transition(vec2 uv) {
  vec2 n = max(vec2(grid), vec2(1.0));
  vec2 c = min(floor(vec2(uv.x, 1.0 - uv.y) * n), n - 1.0);
  // the transposed spiral turns the other way from the same corner; walking the spiral
  // outward reverses it too
  if (clockwise != inward) {
    c = c.yx;
    n = n.yx;
  }
  float count = n.x * n.y;
  float i = spiralIndex(c, n);
  if (!inward) i = count - 1.0 - i;

  // the blocks switch one after another, each one fading in over w blocks of time, the first
  // fade starting at 0 and the last ending at 1; without fade, block i switches at (i + 0.5) / count
  float w = max(smoothness, 0.0) * count;
  float o = max(0.5 * (1.0 - w), 0.0);
  float x = progress * (count - 1.0 + 2.0 * o + w) - i - o;
  float m = w > 0.0 ? smoothstep(0.0, w, x) : step(0.0, x);

  if (m <= 0.0) return getFromColor(uv);
  if (m >= 1.0) return getToColor(uv);
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  // mixed premultiplied, so transparent images do not bleed their color
  vec4 col = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing picture is redrawn as one continuous spiral line winding inward on paper, thick in its darks and thin in its lights; the line thins to a hairline spiral from the center out, swells again into the shapes of the incoming picture and spreads back into the full photo
// Tags: spiral, line-art, graphic, stylized, math

// @range(15, 80) Number of strokes of the line across the frame height
uniform float strokes; // = 44.0
// @range(0, 8) Number of turns the spiral winds
uniform float winding; // = 4.0
// @color Color of the line
uniform vec4 ink; // = vec4(0.09, 0.1, 0.17, 1.0)
// @color Color of the paper
uniform vec4 paper; // = vec4(0.96, 0.94, 0.89, 1.0)

const float TAU = 6.283185307;

vec4 weighted(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

float shade(vec4 c) {
  return clamp(1.1 * (1.0 - dot(c.rgb, vec3(0.299, 0.587, 0.114))) - 0.04, 0.0, 1.0) * c.a;
}

// half width of the stroke whose center passes at radius rc, at the angle of the unit vector dir
float strokeWidth(vec2 dir, float rc, float n, float style, float aa) {
  vec2 asp = vec2(ratio, 1.0);
  float t = progress - 0.1 * (rc / (0.5 * length(asp)) - 0.5);
  float dark = 0.0;
  for (int i = 0; i < 5; i++) {
    float a = float(i) - 2.0;
    // along the stroke, the outer two across it
    vec2 o = abs(a) > 1.5 ? dir * a * 0.1 : vec2(-dir.y, dir.x) * a * 0.3;
    vec2 cuv = clamp((dir * max(rc, 0.0) + o / n) / asp + 0.5, 0.0, 1.0);
    dark += 0.2 * (t < 0.5 ? shade(getFromColor(cuv)) : shade(getToColor(cuv)));
  }
  // flat around t = 0.5, where the images are swapped
  float k = smoothstep(0.02, 0.21, abs(t - 0.5));
