  float r = length(vec2(q.x, q.y / FLAT)) / radius;

  float core = 1.0 - smoothstep(0.72, 1.08, r);
  float ring = (r - 0.9) / 0.09;
  float spot = max(core * (1.0 - 0.1 * r * r), 0.12 * (1.0 - smoothstep(0.9, 2.4, r))) + 0.16 * exp(-ring * ring);

  float s = darkness * smoothstep(0.0, 0.18, p) * (1.0 - smoothstep(0.72, 1.0, p));
  vec3 light = 1.0 - s + s * spot * warmth;

  float lit = smoothstep(0.42, 0.58, p) * (1.0 - smoothstep(LIT, 1.0, r));
  vec4 col = mix(getFromColor(uv), getToColor(uv), lit);
  return vec4(col.rgb * light, col.a);
}

// Author: gre
// License: MIT
// Description: Squares grow along a diagonal sweep to reveal the incoming image
// Tags: squares, grid, wipe, directional
// Preview: 0.5

// @param Number of squares (columns, rows)
uniform ivec2 squares;// = ivec2(10,10)
// @param Direction of the sweep
uniform vec2 direction;// = vec2(1.0, -0.5)
// @param Softness of the sweep
uniform float smoothness; // = 1.6

const vec2 center = vec2(0.5, 0.5);
vec4 transition (vec2 p) {
  vec2 v = normalize(direction);
  v /= abs(v.x)+abs(v.y);
  float d = v.x * center.x + v.y * center.y;
  float offset = smoothness;
  float pr = smoothstep(-offset, 0.0, v.x * p.x + v.y * p.y - (d-0.5+progress*(1.+offset)));
  vec2 squarep = fract(p*vec2(squares));
  vec2 squaremin = vec2(pr/2.0);
  vec2 squaremax = vec2(1.0 - pr/2.0);
  float a = (1.0 - step(progress, 0.0)) * step(squaremin.x, squarep.x) * step(squaremin.y, squarep.y) * step(squarep.x, squaremax.x) * step(squarep.y, squaremax.y);
  return mix(getFromColor(p), getToColor(p), a);
}

// Author: gre
// License: MIT
// Description: The outgoing image is squeezed into a line with color separation, revealing the incoming one
// Tags: squeeze, chromatic, vertical

// @param Amount of color separation
uniform float colorSeparation; // = 0.04

vec4 transition (vec2 uv) {
  float y = 0.5 + (uv.y-0.5) / (1.0-progress);
  if (y < 0.0 || y > 1.0) {
     return getToColor(uv);
  }
  else {
    vec2 fp = vec2(uv.x, y);
    vec2 off = progress * vec2(0.0, colorSeparation);
    vec4 c = getFromColor(fp);
    vec4 cn = getFromColor(fp - off);
    vec4 cp = getFromColor(fp + off);
    return vec4(cn.r, c.g, cp.b, c.a);
  }
}

// Author: gre
// License: MIT
// Description: The outgoing image starts to turn around a pole like the night sky in a long exposure: its lights leave trails that lengthen into concentric arcs over the smeared image, their colors change to those of the incoming image along the arcs, and the trails catch up into the sharp incoming image
// Tags: rotate, trails, long-exposure, light, motion-blur, sky

// @range(-2, 2) How far the sky turns counterclockwise, in radians
uniform float turn; // = 1.0
// @range(0.5, 2) How closely packed the trails are
uniform float density; // = 1.0
// @range(0, 2) Brightness of the trails
uniform float glow; // = 1.0
// @param Point the sky turns around
uniform vec2 pole; // = vec2(0.5, 0.58)

const int TAPS = 13;

float hash(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

vec2 mirrored(vec2 u) {
  return 1.0 - abs(1.0 - mod(u, 2.0));
}

vec2 rot(vec2 v, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(v.x * c - v.y * s, v.x * s + v.y * c);
}

vec4 premultiplied(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 fromAt(vec2 v) {
  return premultiplied(getFromColor(mirrored(v / vec2(ratio, 1.0) + pole)));
}

vec4 toAt(vec2 v) {
  return premultiplied(getToColor(mirrored(v / vec2(ratio, 1.0) + pole)));
}

// share of the incoming image in the light that has turned by a part of the whole turn
float incoming(float a) {
  return smoothstep(0.3, 0.7, a);
}

// bright lights burn in more than the dark
float burn(vec4 c, float k) {
  return 1.0 + 2.5 * k * dot(c.rgb, c.rgb) / 3.0;
}

vec4 transition(vec2 uv) {
  float head = smoothstep(0.0, 0.76, progress);
  float tail = smoothstep(0.24, 1.0, progress);
  float k = smoothstep(0.03, 0.45, head - tail);
  vec2 d = (uv - pole) * vec2(ratio, 1.0);
  float r = length(d);

  // each image is averaged over its own part of the exposure
  vec2 f = min(vec2(tail, head), 0.7);
  vec2 g = max(vec2(tail, head), 0.3);
  f.y = max(f.y, f.x + 1e-5);
  g.y = max(g.y, g.x + 1e-5);
  // shifted from one thin arc to the next, the taps blend into grain that runs along the trails
  float shift = hash(vec2(floor(r * 300.0), 7.0));
  vec4 sum = vec4(0.0);
  float total = 0.0;
  for (int i = 0; i < TAPS; i++) {
    float u = (float(i) + shift) / float(TAPS);
    float a = mix(f.x, f.y, u);
    vec4 c = fromAt(rot(d, -a * turn));
    float w = (f.y - f.x) * (1.0 - incoming(a)) * burn(c, k);
    sum += w * c;
    total += w;
    a = mix(g.x, g.y, u);
    c = toAt(rot(d, (1.0 - a) * turn));
    w = (g.y - g.x) * incoming(a) * burn(c, k);
    sum += w * c;
    total += w;
  }
  vec4 col = sum / total;
  if (col.a <= 0.0) return vec4(0.0);
  col.rgb *= 1.0 - 0.45 * k;

  vec2 e = d / max(r, 1e-4);
  float middle = 0.5 * (head + tail) * turn;
  float reach = 0.5 * (head - tail) * abs(turn);
  for (int l = 0; l < 2; l++) {
    float w = (l == 0 ? 0.014 : 0.027) / max(density, 0.1);
    float ring = floor(r / w);
    float x = r / w - ring;
    float rim = smoothstep(0.0, 0.2, min(x, 1.0 - x));
    // only the brightest trail of each ring is drawn, so that only its light is read
    float best = 0.0;
    float at = 0.0;
    vec2 home = vec2(0.0);
    for (int j = 0; j < 6; j++) {
      vec2 id = vec2(ring + 400.0 * float(l), float(j));
      float rc = (ring + 0.3 + 0.4 * hash(id + 5.0)) * w;
      float ta = 6.2831853 * (float(j) + hash(id)) / 6.0;
      // measured from the middle of the arc, so the branch cut of atan falls on the far side
      vec2 q = rot(e, -ta - middle);
      float off = q.x < -0.9 ? 3.0 : atan(q.y, q.x);
      float on = clamp(off, -reach, reach);
      float dist = length(vec2(r - rc, (off - on) * r));
      float mag = hash(id + 31.0);
      float wide = w * mix(0.1, 0.24, mag * mag);
      float aged = mix(0.4, 1.0, 0.5 + 0.5 * on * sign(turn) / max(reach, 1e-4));
      float lit = exp(-dist * dist / (wide * wide)) * (0.3 + 0.9 * mag) * aged * rim;
      if (lit > best) {
        best = lit;
        at = on;
        home = rc * vec2(cos(ta), sin(ta));
      }
    }
    vec4 c = mix(fromAt(home), toAt(rot(home, turn)), incoming(0.5 * (head + tail) + at / (abs(turn) < 1e-3 ? 1e-3 : turn)));
    col.rgb += k * glow * best * c.rgb * (0.5 + 1.1 * dot(c.rgb, vec3(0.333)));
  }
  return vec4(min(col.rgb / col.a, 1.0), col.a);
}

// Author: Ben Lucas
// License: MIT
// Description: A growing star reveals the incoming image
// Tags: wipe, shape, star
#define PI 3.141592653589793
#define STAR_ANGLE 1.2566370614359172

// @param Thickness of the star's border
uniform float border_thickness;// = 0.01
uniform float star_rotation;// = 0.75
// @color Color of the star's border
uniform vec4 border_color; // = vec4(1.0)
// @param Center of the star
uniform vec2 star_center;// = vec2(0.5)

vec2 rotate(vec2 v, float theta) {
    float cosTheta = cos(theta);
    float sinTheta = sin(theta);

    return vec2(
        cosTheta * v.x - sinTheta * v.y,
        sinTheta * v.x + cosTheta * v.y
    );
}

bool inStar(vec2 uv, vec2 center, float radius){
  vec2 uv_centered = uv - center;
  uv_centered = rotate(uv_centered, star_rotation * STAR_ANGLE);
  float theta = atan(uv_centered.y, uv_centered.x) + PI;

  vec2 uv_rotated = rotate(uv_centered, -STAR_ANGLE * (floor(theta / STAR_ANGLE) + 0.5));

  float slope = 0.3;
  if(uv_rotated.y > 0.0){
      return (radius + uv_rotated.x * slope > uv_rotated.y);
  } else {
     return (-radius - uv_rotated.x * slope < uv_rotated.y);
  }
}

vec4 transition (vec2 uv) {
  float progressScaled = (2.0 * border_thickness + 1.0) * progress - border_thickness;
  if(inStar(uv, star_center, progressScaled)){
    return getToColor(uv);
  } else if(inStar(uv, star_center, progressScaled+border_thickness)){
    return border_color;
  } else {
    return getFromColor(uv);
  }
}

// Author: Ben Lucas
// License: MIT
// Description: Cuts to the incoming image halfway, hidden behind a burst of TV static
// Tags: static, noise, retro

uniform float n_noise_pixels ; // = 200.0
uniform float static_luminosity ; // = 0.8

float rnd (vec2 st) {
    return fract(sin(dot(st.xy,
                         vec2(10.5302340293,70.23492931)))*
        12345.5453123);
}

vec4 staticNoise (vec2 st, float offset, float luminosity, float alpha) {
  float staticR = luminosity * rnd(st * vec2(offset * 2.0, offset * 3.0));
  float staticG = luminosity * rnd(st * vec2(offset * 3.0, offset * 5.0));
  float staticB = luminosity * rnd(st * vec2(offset * 5.0, offset * 7.0));
  return vec4(staticR, staticG, staticB, alpha);
}

float staticIntensity(float t)
{
  float transitionProgress = abs(2.0*(t-0.5));
  float transformedThreshold =1.2*(1.0 - transitionProgress)-0.1;
  return min(1.0, transformedThreshold);
}

vec4 transition (vec2 uv) {

  float baseMix = step(0.5, progress);
  vec4 transitionMix = mix(
    getFromColor(uv),
    getToColor(uv),
    baseMix
  );

  vec2 uvStatic = floor(uv * n_noise_pixels)/n_noise_pixels;

  vec4 staticColor = staticNoise(uvStatic, progress, static_luminosity, transitionMix.a); // static where the image is

  float staticThresh = staticIntensity(progress);
  float staticMix = step(rnd(uvStatic), staticThresh);

  return mix(transitionMix, staticColor, staticMix);
}

// Author: Ben Lucas
// License: MIT
// Description: A wipe from top to bottom with a band of TV static at its edge
// Tags: wipe, static, noise, vertical

#define PI 3.14159265359

float rnd (vec2 st) {
    return fract(sin(dot(st.xy,
                         vec2(10,70)))*
        12345.5453123);
}

// @param Wipe from top to bottom; false wipes from bottom to top
uniform bool u_transitionUpToDown; // = true
// @param Maximum height of the static band
uniform float u_max_static_span; // = 0.5

vec4 transition (vec2 uv) {


  float span = u_max_static_span*pow(sin(PI*progress),0.5);

  float transitionEdge = u_transitionUpToDown ? 1.0-uv.y : uv.y;
  float mixRatio = 1.0 - step(progress, transitionEdge);

  vec4 transitionMix = mix(
    getFromColor(uv),
    getToColor(uv),
    mixRatio
  );

  float noiseEnvelope = smoothstep(progress-span, progress, transitionEdge) * (1.0 - smoothstep(progress, progress + span, transitionEdge));
  vec4 noise = vec4(vec3(rnd(uv*(1.0+progress))), transitionMix.a); // static where the image is


  return mix(transitionMix, noise, noiseEnvelope);
}

// Author: gre
// License: MIT
// Description: The incoming picture arrives wound on a heavy roller that rolls across the outgoing one from left to right, pressing it down and bunching it up in its shadow just ahead of its contact line, and lays the incoming picture down flat behind it as it unrolls
// Tags: roller, cylinder, press, directional, 3d

// @range(0.06, 0.3) Radius of the roller, in frame heights (frame widths in portrait)
uniform float radius; // = 0.15
// @range(0, 1) How hard the roller presses the outgoing picture: bunching and shadow ahead of it
uniform float press; // = 0.7

const float PI = 3.141592653589793;

vec2 mirrored(vec2 v) {
  vec2 m = mod(v, 2.0);
  return mix(m, 2.0 - m, step(1.0, m));
}

vec4 transition(vec2 uv) {
  float t = progress * progress * (3.0 - 2.0 * progress);
  float r = radius * min(ratio, 1.0);
  float X = uv.x * ratio;
  float xc = mix(-r - 0.02, ratio + r + 0.02, t);
  float A = press * smoothstep(0.0, r, xc + r) * (1.0 - smoothstep(0.94, 1.0, progress));
  float L = 0.7 * r;
  float u = max(X - xc - r, 0.0) / L;

  // pulling the sample back by a decaying amount compresses the picture into the ridge without folding it
  vec4 a = getFromColor(mirrored(vec2(uv.x - 1.6 * L * A * exp(-u) / ratio, uv.y)));
  a.rgb *= 1.0 - A * (0.45 * exp(-u / 0.35) + 0.35 * exp(-u / 1.2));

  vec4 b = getToColor(uv);
  b.rgb *= 1.0 - 0.4 * A * (1.0 - smoothstep(0.0, 0.4 * r, xc - r - X));
  vec4 col = X < xc ? b : a;

  float ph = asin(clamp((X - xc) / r, -1.0, 1.0));
  // the wound sheet leaves the roller at the hidden contact line under its axis, so rows count from there around the front
  float row = xc + r * (PI - ph);
  float zoom = 1.0 + 0.3 * r * (1.0 + cos(ph));
  vec4 c = getToColor(mirrored(vec2(row / ratio, 0.5 + (uv.y - 0.5) / zoom)));
  c.rgb = c.rgb * (0.4 + 0.65 * max(cos(ph + 0.5), 0.0)) + 0.3 * c.a * pow(max(cos(ph + 0.6), 0.0), 40.0);
  return mix(col, c, smoothstep(0.0, 0.004, r - abs(X - xc)));
}

// @range(0.5, 1) How much the images zoom out
uniform float zoom; // = 0.88
// Corner radius as a fraction of the image height
uniform float corner_radius;  // = 0.22

// Author: Ted Schundler
// License: BSD 2 Clause
// Description: Both images shrink into rounded cards that swap, like a stereo viewer toy
// Tags: cards, zoom, retro
// Free for use and modification by anyone with credit

// Copyright (c) 2016, Theodore K Schundler
