}

// Author: gre
// License: MIT
// Description: The outgoing image parts like a theater tableau curtain: each half is drawn up and out toward its top corner, opening a high rounded arch while the fabric gathers into pleats fanning toward the corners, then the two swags fly up out of the frame
// Tags: 3d, fold, split, reveal, shadow

// @range(2, 16, 1) Number of pleats in each half (fewer in a portrait image)
uniform float folds; // = 6.0
// @range(0, 1) Depth of the shading on the pleats and swags
uniform float shading; // = 0.7
// @range(0.2, 0.9) Height the swags are drawn up to before they fly out
uniform float hitch; // = 0.6

const float PI = 3.141592653589793;

// the opening edge: a superellipse from the top middle to the hem corner c, then the hem down to the
// outer leg; it rises with x, so it inverts both ways for an exact distance
float edgeX(float y, vec2 c, float k, float q) {
  if (y >= c.y) {
    float t = clamp((1.0 - y) / max(1.0 - c.y, 1e-4), 0.0, 1.0);
    return 0.5 - (0.5 - c.x) * pow(max(1.0 - pow(1.0 - t, q), 0.0), 1.0 / q);
  }
  // continued below the outer leg so nothing there counts as an edge
  float r = (y / max(c.y, 1e-4) - k) / (1.0 - k);
  return c.x * (r >= 0.0 ? sqrt(r) : -sqrt(-r));
}

float edgeY(float x, vec2 c, float k, float q) {
  if (x >= c.x) {
    float b = clamp((0.5 - x) / max(0.5 - c.x, 1e-4), 0.0, 1.0);
    return 1.0 - (1.0 - c.y) * (1.0 - pow(max(1.0 - pow(b, q), 0.0), 1.0 / q));
  }
  float r = x / c.x;
  return c.y * (k + (1.0 - k) * r * r);
}

vec4 transition(vec2 uv) {
  float p = progress;
  float G = smoothstep(0.0, 0.62, p);
  float f = clamp((p - 0.42) / 0.58, 0.0, 1.0);
  float fly = f * f * (3.0 - 2.0 * f);
  // the outer legs rise to k of the hitch height; the lift keeps accelerating so the swags leave at speed
  float k = 0.7 * fly;
  float lift = (1.08 - k * hitch) * f * f;
  float bunch = clamp(0.2 / ratio, 0.1, 0.18);
  vec2 c = vec2(0.5 - (0.5 - bunch) * G, hitch * smoothstep(0.0, 0.8, G));
  // a narrow wedge opening from the hem first, rounding into an arch as it widens
  float q = mix(0.6, 2.0, smoothstep(0.0, 0.7, G));
  float right = step(0.5, uv.x);
  float x = mix(uv.x, 1.0 - uv.x, right);
  float y = uv.y - lift;

  float e = edgeX(y, c, k, q);
  float dx = (e - x) * ratio;
  float dy = y - edgeY(x, c, k, q);
  float d = dx * abs(dy) / max(length(vec2(dx, dy)), 1e-6);
  float w = 0.002 * G + 1e-4;
  float inside = clamp(1.0 + d / w, 0.0, 1.0);

  float span = mix(c.x, e, step(c.y, y));
  float u = clamp(x / max(span, 1e-4), 0.0, 1.0);
  float hem = c.y * mix(u * u, 1.0, k);
  float v = clamp((1.0 - y) / max(1.0 - hem, 1e-4), 0.0, 1.0);

  float n = max(2.0, floor(folds * min(ratio, 1.0) + 0.5));
  // a slow wobble keeps the pleats from looking machined
  float a = 2.0 * PI * n * u + 0.7 * sin(PI * n * u * 0.73 + 1.3);
  float squeeze = 1.0 - 2.0 * span;
  float amp = G * mix(0.3, 0.95, squeeze) * (0.8 + 0.2 * sin(PI * n * u * 0.41 + 0.4));
  float su = clamp(u + amp * sin(a) / (2.0 * PI * n), 0.0, 1.0);
  vec4 from = getFromColor(vec2(mix(0.5 * su, 1.0 - 0.5 * su, right), 1.0 - v));

  float slope = 2.2 * amp * cos(a);
  float tilt = 1.1 * G * v * v * (0.3 + 0.7 * u);
  vec3 nrm = normalize(vec3(-slope, -tilt, 1.0));
  // lit in each half's mirrored frame so both swags stay symmetric
  vec3 L = normalize(vec3(-0.35, 0.6, 1.0));
  float diffuse = max(dot(nrm, L), 0.0) / L.z;
  float sheen = pow(max(dot(nrm, normalize(L + vec3(0.0, 0.0, 1.0))), 0.0), 10.0);
  float crease = 0.5 + 0.5 * sin(a);
  float edge = exp(-max(d, 0.0) * 70.0);
  float light = diffuse * (1.0 - 0.5 * crease * crease * amp) * (1.0 - 0.3 * squeeze * v * G) * (1.0 - 0.3 * edge)
    + 0.22 * sheen * amp;
  from.rgb *= mix(1.0, light, shading * smoothstep(0.0, 0.25, G));

  vec4 to = getToColor(uv);
  float shadow = 0.5 * shading * exp(max(-d, 0.0) * -30.0) * G * (1.0 - fly);
  to.rgb *= 1.0 - shadow;
  return mix(to, from, inside);
}

// License: MIT
// Author: chenkai
// Description: The outgoing image is flung away along a curve with motion blur
// Tags: motion-blur, rotate, slide
// ported from https://codertw.com/%E7%A8%8B%E5%BC%8F%E8%AA%9E%E8%A8%80/671116/

float rand (vec2 co) {
  return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

vec4 motionBlurFrom(vec2 _st, vec2 speed) {
    vec2 texCoord = _st.xy / vec2(1.0).xy;
    // Premultiplied sums, so that transparent samples do not darken the blur
    vec3 color = vec3(0.0);
    float alpha = 0.0;
    float total = 0.0;
    float offset = rand(_st);
    for (float t = 0.0; t <= 20.0; t++) {
        float percent = (t + offset) / 20.0;
        float weight = 4.0 * (percent - percent * percent);
        vec2 newuv = texCoord + speed * percent;
        newuv = fract(newuv);
        vec4 c = getFromColor(newuv);
        color += c.rgb * c.a * weight;
        alpha += c.a * weight;
        total += weight;
    }
    return vec4(color / max(alpha, 1e-5), alpha / total);
}

vec4 motionBlurTo(vec2 _st, vec2 speed) {
    vec2 texCoord = _st.xy / vec2(1.0).xy;
    vec3 color = vec3(0.0);
    float alpha = 0.0;
    float total = 0.0;
    float offset = rand(_st);
    for (float t = 0.0; t <= 20.0; t++) {
        float percent = (t + offset) / 20.0;
        float weight = 4.0 * (percent - percent * percent);
        vec2 newuv = texCoord + speed * percent;
        newuv = fract(newuv);
        vec4 c = getToColor(newuv);
        color += c.rgb * c.a * weight;
        alpha += c.a * weight;
        total += weight;
    }
    return vec4(color / max(alpha, 1e-5), alpha / total);
}


float A(float aA1, float aA2) {
    return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}
float B(float aA1, float aA2) {
    return 3.0 * aA2 - 6.0 * aA1;
}
float C(float aA1) {
    return 3.0 * aA1;
}
float GetSlope(float aT, float aA1, float aA2) {
    return 3.0 * A(aA1, aA2)*aT*aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}
float CalcBezier(float aT, float aA1, float aA2) {
    return ((A(aA1, aA2)*aT + B(aA1, aA2))*aT + C(aA1))*aT;
}
float GetTForX(float aX, float mX1, float mX2) {
    float aGuessT = aX;
    for (int i = 0; i < 4; ++i) {
        float currentSlope = GetSlope(aGuessT, mX1, mX2);
        if (currentSlope == 0.0) return aGuessT;
        float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
        aGuessT -= currentX / currentSlope;
    }
    return aGuessT;
}
float KeySpline(float aX, float mX1, float mY1, float mX2, float mY2) {
    if (mX1 == mY1 && mX2 == mY2) return aX;
    return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2); // x to t, t to y
}

float normpdf(float x) {
    float d = x - .5;
    return exp(-20.*d*d);
}

vec2 rotateUv(vec2 uv, float angle, vec2 anchor, float zDirection) {
    uv = uv - anchor;
    float s = sin(angle);
	float c = cos(angle);
	mat2 m = mat2(c, -s, s, c);
    uv = m * uv;
    uv += anchor;
    return uv;
}



vec4 transition (vec2 uv) {
    vec2 myst = uv;
    float animationTime = progress;
    float easingTime = KeySpline(animationTime, .68,.01,.17,.98);
    float blur = max(normpdf(easingTime) - exp(-5.0), 0.0) / (1.0 - exp(-5.0));
    float r = 0.;
    float rotation = 180./180.*3.14159;
    if (easingTime <= .5) {
        r = rotation * easingTime;
    } else {
        r = -rotation + rotation * easingTime;
    }

    vec2 mystCurrent = myst;
    mystCurrent.y *= 1./ratio;
    mystCurrent = rotateUv(mystCurrent, r, vec2(1., 0.), -1.);
    mystCurrent.y *= ratio;

    // frame timeInterval by fps=30
    float timeInterval = 0.0167*2.0;
    if (easingTime <= .5) {
        r = rotation * (easingTime+timeInterval);
    } else {
        r = -rotation + rotation * (easingTime+timeInterval);
    }

    vec2 mystNext = myst;
    mystNext.y *= 1./ratio;
    mystNext = rotateUv(mystNext, r, vec2(1., 0.), -1.);
    mystNext.y *= ratio;

    vec2 speed  = (mystNext - mystCurrent) / timeInterval * blur * 0.5;
    if (easingTime <= .5) {
        return motionBlurFrom(mystCurrent, speed);
    } else {
        return motionBlurTo(mystCurrent, speed);
    }
}

// Author: gre
// License: MIT
// Description: The outgoing image is reduced to three flat inks that overprint, light and dark, warm and cool, green and purple; one after another their shapes snap into a slanted plane, a disc and a band, which glide and turn through each other while they take the incoming image's colors, then break one after another into its shapes
// Tags: overprint, ink, flat, poster, palette, geometric, abstract

// @range(0, 2) How vivid the inks are
uniform float vivid; // = 1.0
// @range(0.5, 1.5) Size of the disc and of the band
uniform float size; // = 1.0

const int N = 14;
// between these two moments the inks are free of both images, so the palettes of both are read instead of their shapes
const float FREED = 0.36;
const float CAUGHT = 0.64;

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec2 spot(int i) {
  return fract(vec2(0.754878, 0.569840) * float(i) + 0.4);
}

// light and dark, warm and cool, green and purple
vec3 axes(vec3 c) {
  return vec3(dot(c, vec3(0.299, 0.587, 0.114)), 0.5 * (c.r - c.b), 0.5 * c.g - 0.25 * (c.r + c.b));
}

// the two chroma axes leave the luma alone
vec3 colorOf(vec3 k) {
  vec3 c = vec3(k.y, 0.0, -k.y) + k.z * vec3(-0.6, 0.6, -0.6);
  return c + k.x - dot(c, vec3(0.299, 0.587, 0.114));
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  bool late = progress > 0.5;

  vec3 ma = vec3(0.0);
  vec3 mb = vec3(0.0);
  vec3 va = vec3(0.0);
  vec3 vb = vec3(0.0);
  vec2 sum = vec2(1e-4);
  for (int i = 0; i < N; i++) {
    vec4 ca = progress < CAUGHT ? getFromColor(spot(i)) : vec4(0.0);
    vec4 cb = progress > FREED ? getToColor(spot(i)) : vec4(0.0);
    vec3 ka = axes(ca.rgb);
    vec3 kb = axes(cb.rgb);
    sum += vec2(ca.a, cb.a);
    ma += ka * ca.a;
    mb += kb * cb.a;
    va += ka * ka * ca.a;
    vb += kb * kb * cb.a;
  }
  ma /= sum.x;
  mb /= sum.y;
  va = sqrt(max(va / sum.x - ma * ma, 0.0)) + 0.03;
  vb = sqrt(max(vb / sum.y - mb * mb, 0.0)) + 0.03;

  vec4 here = late ? b : a;
  // the inks come free, and later set, one after another
  vec3 lag = vec3(0.0, 0.06, 0.12);
  vec3 bend = smoothstep(0.0, 1.0, (late ? vec3(0.96) - lag.zyx - progress : vec3(progress) - 0.04 - lag) / 0.2);
  vec3 y = vec3(0.0);
  if (min(bend.x, min(bend.y, bend.z)) < 1.0) {
    // fine detail melts into a broad field before the shapes move, so their edges do not tear
    vec3 melt = smoothstep(0.0, 0.55, bend);
    vec4 acc = vec4(axes(here.rgb), 1.0) * here.a;
    vec4 broad = vec4(late ? mb : ma, 1.0) * 1e-3;
    if (min(melt.x, min(melt.y, melt.z)) < 1.0) {
      float soft = smoothstep(0.0, 0.2, progress) * (1.0 - smoothstep(0.8, 1.0, progress));
      for (int i = 0; i < N; i++) {
        float r = 0.055 * soft * sqrt((float(i) + 0.5) / float(N));
        float g = 2.39996 * float(i);
        vec2 q = fold(uv + r * vec2(cos(g), sin(g)) / vec2(ratio, 1.0));
        vec4 c = late ? getToColor(q) : getFromColor(q);
        acc += vec4(axes(c.rgb), 1.0) * c.a;
      }
    }
    if (max(melt.x, max(melt.y, melt.z)) > 0.0) {
      for (int i = 0; i < N; i++) {
        vec2 q = (uv - spot(i)) * vec2(ratio, 1.0);
        vec4 c = late ? getToColor(spot(i)) : getFromColor(spot(i));
        broad += vec4(axes(c.rgb), 1.0) * c.a * exp(-26.0 * dot(q, q));
      }
    }
    y = mix(acc.rgb / max(acc.a, 1e-4), broad.rgb / broad.a, melt);
    y = (y - (late ? mb : ma)) / (late ? vb : va) * 0.22;
  }

  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float t = progress * 3.14159;
  vec2 center = vec2(0.22 * ratio * cos(t), 0.1 * sin(t));
  float disc = 0.36 * size * min(1.0, 0.4 + 0.5 * ratio) - length(p - center);
  vec2 d = vec2(cos(t * 0.5 + 0.6), sin(t * 0.5 + 0.6));
  float band = 0.17 * size - abs(dot(p, d) - 0.1 * cos(t));
  vec2 e = vec2(cos(-t * 0.7 + 2.2), sin(-t * 0.7 + 2.2));
  float plane = dot(p, e) - 0.08 * sin(2.0 * t);
  vec3 aa = mix(vec3(0.02), vec3(0.002), bend);
  vec3 ink = smoothstep(-aa, aa, mix(y, vec3(plane, disc, band), bend));

  float turn = smoothstep(0.37, 0.63, progress);
  // a transparent image has no palette to turn to
  turn = turn * sum.y / (turn * sum.y + (1.0 - turn) * sum.x);
  ink = (2.0 * ink - 1.0) * vec3(1.15, 1.25, 1.4);
  vec3 k = mix(ma + va * ink, mb + vb * ink, turn);
  vec3 col = colorOf(k);
  // an overprint takes the hue of the closest place of the images, so that none strays from them
  vec4 pa = vec4(0.0);
  vec4 pb = vec4(0.0);
  for (int i = 0; i < N; i++) {
    if (turn < 1.0) {
      vec4 q = getFromColor(spot(i));
      vec3 d = q.rgb - col;
      pa += vec4(q.rgb, 1.0) * (q.a * exp(-30.0 * dot(d, d)) + 1e-5);
    }
    if (turn > 0.0) {
      vec4 q = getToColor(spot(i));
      vec3 d = q.rgb - col;
      pb += vec4(q.rgb, 1.0) * (q.a * exp(-30.0 * dot(d, d)) + 1e-5);
    }
  }
  vec3 near = axes(mix(pa.rgb / max(pa.a, 1e-5), pb.rgb / max(pb.a, 1e-5), turn));
  k.yz = mix(k.yz, near.yz, 0.6) * (1.0 + 0.6 * vivid);
  col = clamp(colorOf(k), 0.0, 1.0);

  float flatness = smoothstep(0.0, 0.16, progress) * (1.0 - smoothstep(0.84, 1.0, progress));
  return vec4(mix(here.rgb, col, flatness), mix(a.a, b.a, smoothstep(0.34, 0.66, progress)));
}

// Author: gre
// License: MIT
// Description: From one corner on, the outgoing image's shapes comb out into bold wavy stripes of its own flat colors that stream steadily across the frame; the stripes take the incoming image's colors one after another, then pile up into its shapes from the same corner on
// Tags: stripes, waves, flat, poster, palette, abstract

// @range(1, 5) Number of stripes across the frame height
uniform float stripes; // = 2.2
// @range(0, 0.3) How far the stripes swing, in frame heights
uniform float swing; // = 0.12
// @range(0, 2.5) How vivid the flat colors are
uniform float vivid; // = 1.4

const int N = 14;
// between these two moments the shapes are free of both images, so the palettes of both are read instead of their shapes
const float FREED = 0.36;
const float CAUGHT = 0.64;

float luma(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec2 spot(int i) {
  return fract(vec2(0.754878, 0.569840) * float(i) + 0.4);
}

// how much the color c stands for a tone: the ones that stand out win, since the average of several hues is mud
float weight(vec4 c, vec2 stats, vec3 tint, float z) {
  float l = luma(c.rgb);
  float d = (l - stats.x) / stats.y - z;
  float s = 0.4 * length(c.rgb - l) + length(c.rgb - l - tint);
  float w = exp(-4.0 * d * d) * (0.1 + s);
  w *= w * w;
  return c.a * w * w + 1e-7;
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  bool late = progress > 0.5;

  vec2 ma = vec2(0.0);
  vec2 mb = vec2(0.0);
  vec3 ta = vec3(0.0);
  vec3 tb = vec3(0.0);
  vec2 sum = vec2(1e-4);
  for (int i = 0; i < N; i++) {
    vec4 ca = progress < CAUGHT ? getFromColor(spot(i)) : vec4(0.0);
    vec4 cb = progress > FREED ? getToColor(spot(i)) : vec4(0.0);
    vec2 l = vec2(luma(ca.rgb), luma(cb.rgb));
    sum += vec2(ca.a, cb.a);
    ma += vec2(l.x, l.x * l.x) * ca.a;
    mb += vec2(l.y, l.y * l.y) * cb.a;
    ta += (ca.rgb - l.x) * ca.a;
    tb += (cb.rgb - l.y) * cb.a;
  }
  ma /= sum.x;
  mb /= sum.y;
  ta /= sum.x;
  tb /= sum.y;
  ma.y = sqrt(max(ma.y - ma.x * ma.x, 0.0)) + 0.03;
  mb.y = sqrt(max(mb.y - mb.x * mb.x, 0.0)) + 0.03;

  vec4 here = late ? b : a;
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float stream = clamp(0.5 + (p.y + 0.45 * p.x) / (1.0 + 0.45 * ratio), 0.0, 1.0);
  float when = late ? 0.84 + 0.12 * stream - progress : progress - 0.04 - 0.12 * stream;
  float bend = smoothstep(0.0, 1.0, when / 0.2);
  float y = 0.0;
  if (bend < 1.0) {
    // fine detail melts into a broad field before the shapes move, so their edges do not tear
    float melt = smoothstep(0.0, 0.55, bend);
    vec2 acc = vec2(luma(here.rgb) * here.a, here.a);
    vec2 broad = vec2(late ? mb.x : ma.x, 1.0) * 1e-3;
    if (melt < 1.0) {
      float soft = smoothstep(0.0, 0.2, progress) * (1.0 - smoothstep(0.8, 1.0, progress));
      for (int i = 0; i < N; i++) {
        float r = 0.055 * soft * sqrt((float(i) + 0.5) / float(N));
        float g = 2.39996 * float(i);
        vec2 q = fold(uv + r * vec2(cos(g), sin(g)) / vec2(ratio, 1.0));
        vec4 c = late ? getToColor(q) : getFromColor(q);
        acc += vec2(luma(c.rgb) * c.a, c.a);
      }
    }
    if (melt > 0.0) {
      for (int i = 0; i < N; i++) {
        vec2 q = (uv - spot(i)) * vec2(ratio, 1.0);
        vec4 c = late ? getToColor(spot(i)) : getFromColor(spot(i));
        broad += vec2(luma(c.rgb), 1.0) * c.a * exp(-26.0 * dot(q, q));
      }
    }
    y = mix(acc.x / max(acc.y, 1e-4), broad.x / broad.y, melt);
    y = (y - (late ? mb.x : ma.x)) / (late ? mb.y : ma.y);
  }
  float s = p.y + 0.45 * p.x + swing * sin(4.2 * p.x - 1.6 * p.y + 7.0 * progress) - 1.1 * progress;
  float g = fract(s * stripes);
  // each stripe climbs from dark to light over most of its width, then drops back with a crisp edge
  float wave = min(g / 0.93, (1.0 - g) / 0.07);
  float aa = mix(0.03, 0.002 * stripes * (g > 0.93 ? 13.0 : 1.0), bend);
  vec3 col = vec3(0.0);
  float left = 1.0;
  for (int j = 4; j >= 0; j--) {
    float k = float(j);
    // the tone, in deviations from the mean
    float z = (k - 2.0) * 0.62;
    float h = mix(0.22 * (y - z + 0.31), wave - 0.2 * k, bend);
    float cover = j == 0 ? 1.0 : smoothstep(-aa, aa, h);
    if (cover <= 0.0) continue;
    float turn = smoothstep(0.0, 1.0, (progress - (0.44 - 0.02 * k)) / 0.18);
    vec4 pa = vec4(0.0);
    vec4 pb = vec4(0.0);
    for (int i = 0; i < N; i++) {
      if (turn < 1.0) {
        vec4 q = getFromColor(spot(i));
        pa += vec4(q.rgb, 1.0) * weight(q, ma, ta, z);
      }
      if (turn > 0.0) {
        vec4 q = getToColor(spot(i));
        pb += vec4(q.rgb, 1.0) * weight(q, mb, tb, z);
