  float reach2 = reach * reach * dot(ray, ray);
  vec2 lastCell = vec2(-1e4), lastSide = vec2(0.0);
  for (int k = 0; k < 32; k++) {
    float wk = float(k) * dw;
    if (wk > 1.0 + dw) break;
    wk = min(wk, 1.0);
    vec2 back = c + (P - c) * (EYE - ZEND * wk) / EYE;
    vec2 home = back - DRIFT * wk * flyDir(floor(back / size), size, c);
    home = back - DRIFT * wk * flyDir(floor(home / size), size, c);
    vec2 f = home / size;
    vec2 cell = floor(f);
    vec2 side = step(0.5, fract(f)) * 2.0 - 1.0;
    // consecutive steps often land on the same cells
    if (cell == lastCell && side == lastSide) continue;
    // none of the tiles near here has come that far, or they all have passed
    float far = length(home - c);
    float near = 1.5 * length(size);
    if (wk > flight(far - near, 0.0, size, dmax) + 2.0 * dw || wk < flight(far + near, 1.0, size, dmax) - 2.0 * dw) continue;
    vec2 pastCell = lastCell, pastSide = lastSide;
    lastCell = cell;
    lastSide = side;
    for (int j = 0; j < 4; j++) {
      vec2 g = cell + vec2(j == 1 || j == 3 ? side.x : 0.0, j >= 2 ? side.y : 0.0);
      if (g.x < 0.0 || g.y < 0.0 || g.x >= grid.x || g.y >= grid.y) continue;
      vec2 past = g - pastCell;
      if ((past.x == 0.0 || past.x == pastSide.x) && (past.y == 0.0 || past.y == pastSide.y)) continue;
      if (g == g1 || g == g2) continue;
      float u = flight(length((g + 0.5) * size - c), hash4(g).x, size, dmax);
      if (u >= 1.0) continue;
      vec2 dir = flyDir(g, size, c);
      vec2 h0 = (g + 0.5) * size;
      vec3 tc = vec3(h0 + dir * DRIFT * u, ZEND * u);
      // the ray passes out of reach of the tile
      vec3 off = cross(tc - eye, ray);
      if (dot(off, off) > reach2) continue;
      vec4 h = hash4(g + 31.0);
      float a = spinAmt * 2.4 * (h.x - 0.5) * u;
      float b = spinAmt * (0.5 + 0.7 * h.y) * (h.z < 0.5 ? -1.0 : 1.0) * 1.8 * u;
      vec3 ax = normalize(vec3(-dir.y + 0.4 * (h.w - 0.5), dir.x, 0.0));
      float ca = cos(a), sa = sin(a), cb = cos(b), sb = sin(b);
      vec3 a1 = turn(vec3(ca, sa, 0.0), ax, cb, sb);
      vec3 a2 = turn(vec3(-sa, ca, 0.0), ax, cb, sb);
      vec3 nrm = turn(vec3(0.0, 0.0, 1.0), ax, cb, sb);
      float den = dot(ray, nrm);
      if (abs(den) < 1e-5) continue;
      float lam = dot(tc - eye, nrm) / den;
      if (lam <= 0.0 || lam >= z2) continue;
      vec3 hit = eye + lam * ray - tc;
      vec2 l = vec2(dot(hit, a1), dot(hit, a2));
      // anti-aliased edges, scaled to the screen; at rest the edges are hard, so that the tiles join without seams
      vec2 box = 0.5 * size - abs(l);
      float e = min(box.x, box.y) * EYE / (EYE - tc.z) * max(abs(nrm.z), 0.15);
      float m = clamp(e / (2.0 * EDGE) + 0.5 + 0.5 * (1.0 - smoothstep(0.0, 0.06, u)), 0.0, 1.0);
      if (m <= 0.0) continue;
      vec3 nf = den < 0.0 ? nrm : -nrm;
      float lit = 1.0 - 0.6 * shadeAmt * (1.0 - clamp(dot(nf, L) / L.z, 0.0, 1.0));
      float lift = smoothstep(0.0, 0.15, u);
      lit += shadeAmt * lift * (0.2 * pow(max(dot(nf, HV), 0.0), 60.0) + 0.3 * (1.0 - smoothstep(0.0, 0.003, e)));
      if (den >= 0.0) lit *= 0.55;
      if (lam < z1) {
        z2 = z1; g2 = g1; q2 = q1; m2 = m1; s2 = s1; lift2 = lift1;
        z1 = lam; g1 = g; q1 = h0 + l; m1 = m; s1 = lit; lift1 = lift;
      } else {
        z2 = lam; g2 = g; q2 = h0 + l; m2 = m; s2 = lit; lift2 = lift;
      }
    }
  }

  float shTo = 0.0, sh1 = 0.0, sh2 = 0.0;
  if (shadeAmt > 0.0) {
    vec2 base = floor(P / size);
    for (int y = -1; y <= 1; y++) {
      for (int x = -1; x <= 1; x++) {
        vec2 g = base + vec2(float(x), float(y));
        if (g.x < 0.0 || g.y < 0.0 || g.x >= grid.x || g.y >= grid.y) continue;
        float far = length((g + 0.5) * size - c);
        if (flight(far, 0.0, size, dmax) <= 0.0) continue;
        float u = flight(far, hash4(g).x, size, dmax);
        float z = ZEND * u;
        // the shadow fades before it can reach beyond the next tile
        float w = smoothstep(0.0, 0.03, u) * (1.0 - smoothstep(0.1 * size.y, 0.7 * size.y, z));
        if (w <= 0.0) continue;
        vec2 o = P + L.xy / L.z * z - ((g + 0.5) * size + flyDir(g, size, c) * DRIFT * u);
        float blur = 0.004 + 0.25 * z;
        vec2 sb = 0.5 * size - abs(o) + 0.5 * blur;
        float sh = smoothstep(0.0, blur, sb.x) * smoothstep(0.0, blur, sb.y) * w;
        // a tile casts no shadow on itself
        shTo = max(shTo, sh);
        if (g != g1) sh1 = max(sh1, sh);
        if (g != g2) sh2 = max(sh2, sh);
      }
    }
  }
  float dark = 0.5 * shadeAmt;

  float settle = 1.0 - progress;
  vec2 tq = c + (P - c) / (1.0 + 0.06 * settle * settle);
  vec4 col = getToColor(tq / aspect);
  col.rgb *= (1.0 - dark * shTo) * (1.0 - 0.25 * shadeAmt * (1.0 - smoothstep(0.2, 0.9, progress)));
  if (m2 > 0.0) {
    vec4 img = getFromColor(clamp(q2 / aspect, 0.0, 1.0));
    img.rgb *= s2 * mix(1.0 - dark * sh2, 1.0, lift2);
    col = mix(col, img, m2);
  }
  if (m1 > 0.0) {
    vec4 img = getFromColor(clamp(q1 / aspect, 0.0, 1.0));
    img.rgb *= s1 * mix(1.0 - dark * sh1, 1.0, lift1);
    col = mix(col, img, m1);
  }
  return col;
}

// Author: gre
// License: MIT
// Description: Gaps open between the tiles of the outgoing image over a track that winds through every tile; the tiles glide along it like a train, the outgoing ones leaving at the bottom right while the incoming ones enter at the bottom left and wind through the frame until they settle in place
// Tags: grid, tiles, geometric, slide

// @range(1, 3, 1) Size of the track: 2 to the power of order tiles along each side
uniform int order; // = 2
// @range(0.05, 0.4) Width of the gaps between the tiles, as a part of a tile
uniform float gap; // = 0.26
// @range(0, 1) Strength of the bevel and of the shadow the tiles cast on the track
uniform float shading; // = 0.6
// @color Color of the tray under the tiles
uniform vec4 tray; // = vec4(0.11, 0.11, 0.13, 1.0)
// @color Color of the track
uniform vec4 track; // = vec4(0.62, 0.6, 0.55, 1.0)

const float EDGE = 0.0016;

// Hilbert curve from the bottom left cell to the bottom right one; -1 and n*n are the cells just outside
vec2 cellAt(float d, float n) {
  if (d < 0.0) return vec2(-1.0, 0.0);
  if (d > n * n - 0.5) return vec2(n, 0.0);
  vec2 p = vec2(0.0);
  float t = d;
  float s = 1.0;
  for (int i = 0; i < 3; i++) {
    if (s < n) {
      float rx = mod(floor(t / 2.0), 2.0);
      float ry = abs(mod(t, 2.0) - rx);
      if (ry < 0.5) {
        if (rx > 0.5) p = s - 1.0 - p;
        p = p.yx;
      }
      p += s * vec2(rx, ry);
      t = floor(t / 4.0);
      s *= 2.0;
    }
  }
  return p;
}

float indexAt(vec2 c, float n) {
  float d = 0.0;
  vec2 p = c;
  float s = n / 2.0;
  for (int i = 0; i < 3; i++) {
    if (s >= 1.0) {
      float rx = mod(floor(p.x / s), 2.0);
      float ry = mod(floor(p.y / s), 2.0);
      d += s * s * (rx > 0.5 ? 3.0 - ry : ry);
      if (ry < 0.5) {
        if (rx > 0.5) p = n - 1.0 - p;
        p = p.yx;
      }
      s /= 2.0;
    }
  }
  return d;
}

float turns(vec2 a, vec2 c, vec2 b) {
  a -= c;
  b -= c;
  return abs(a.x * b.y - a.y * b.x);
}

float sdBox(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

float sdSegment(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - abs(v));
}

vec4 transition(vec2 uv) {
  float n = floor(exp2(clamp(float(order), 1.0, 3.0)) + 0.5);
  float N = n * n;
  vec2 asp = vec2(ratio, 1.0);
  float open = smoothstep(0.0, 0.12, progress) * (1.0 - smoothstep(0.88, 1.0, progress));
  float q = clamp((progress - 0.07) / 0.86, 0.0, 1.0);
  float D = N * mix(q, q * q * (3.0 - 2.0 * q), 0.7);
  float K = floor(D);
  float f = D - K;
  // slower at the cells so that the grid reads, never stopping
  f -= 0.5 * sin(6.2831853 * f) / 6.2831853;

  vec2 g = uv * n;
  vec2 cell = clamp(floor(g), 0.0, n - 1.0);
  float dc = indexAt(cell, n);
  float px = EDGE * n;
  float hs = 0.5 - 0.5 * clamp(gap, 0.05, 0.4) * open;
  float radius = 0.1 * open;

  vec2 gs = g * asp;
  float tw = 0.1 * min(ratio, 1.0);
  vec2 cc = (cell + 0.5) * asp;
  float dl = min(sdSegment(gs, cc, (cellAt(dc - 1.0, n) + 0.5) * asp),
                 sdSegment(gs, cc, (cellAt(dc + 1.0, n) + 0.5) * asp));
  vec4 col = mix(tray, track, (1.0 - smoothstep(tw - px, tw + px, dl)) * (0.65 + 0.35 * smoothstep(0.0, 0.35 * tw, dl)));

  float shadow = 0.0;
  vec4 acc = vec4(0.0);
  float alpha = 0.0;
  for (int i = 0; i < 9; i++) {
    vec2 nc = cell + vec2(mod(float(i), 3.0), floor(float(i) / 3.0)) - 1.0;
    bool entry = nc.x == -1.0 && nc.y == 0.0;
    if (!entry && (min(nc.x, nc.y) < 0.0 || max(nc.x, nc.y) > n - 1.0)) continue;
    // one tile per path segment: the one between cell k and cell k + 1
    float k = entry ? -1.0 : indexAt(nc, n);
    float j = k - K;
    if (j < -N) continue;
    vec2 c1 = cellAt(k + 1.0, n);
    vec2 lc = g - 0.5 - mix(nc, c1, f);
    vec2 lp = lc * asp;
    // two tiles on either side of a turn are only max(f, 1 - f) apart on each axis: shrink them to pass
    float lim = mix(0.5, 0.25 + 0.5 * (sqrt((f - 0.5) * (f - 0.5) + 0.0025) - 0.05), open);
    float h = max(turns(cellAt(k - 1.0, n), nc, c1), turns(nc, c1, cellAt(k + 2.0, n))) > 0.5 ? min(hs, lim) : hs;
    // at rest the tiles in the grid overlap by a few pixels so that no seam shows, the entry tile stays outside
    vec2 hb = h * asp + 3.0 * px * (1.0 - open) * (k >= 0.0 && k < N ? 1.0 : -1.0);
    float sd = sdBox(lp, hb, radius * h);
    // fading before half a cell keeps the shadow inside the cells that search for this tile
    float fade = 1.0 - smoothstep(0.4, 0.5, max(abs(lc.x), abs(lc.y)));
    shadow = max(shadow, open * fade * (1.0 - smoothstep(-0.04, 0.12, sdBox(lp - vec2(0.04, -0.06), hb, radius * h))));
    float cover = 1.0 - smoothstep(-px, px, sd);
    if (cover <= 0.0) continue;
    vec2 src = cellAt(j >= 0.0 ? j : j + N, n);
    vec2 suv = mirror((src + 0.5 + 0.5 * lp / (h * asp)) / n);
    vec4 c = j >= 0.0 ? getFromColor(suv) : getToColor(suv);
    float rim = 1.0 - smoothstep(0.0, 0.05, -sd);
    float lit = dot(normalize(lp / hb + 1e-5), vec2(-0.7071, 0.7071));
    c.rgb *= 1.0 + shading * open * (rim * 0.35 * lit - 0.08 * (1.0 - rim));
    acc = mix(acc, c, cover);
    alpha = mix(alpha, 1.0, cover);
  }
  col.rgb *= 1.0 - 0.6 * shading * shadow;
  return mix(col, acc / max(alpha, 1e-4), alpha);
}

// Author: gre
// License: MIT
// Description: The image is cut into tiles that ride concentric rectangular rings like the dials of a combination lock: the rings turn a quarter of the way round in alternating directions, the tiles turning the corners like links of a chain, then the tiles flip over to the incoming image in a ripple running round each ring, and the rings turn back until every tile clicks home
// Tags: tiles, rings, rotate, flip, puzzle, mechanical

// @range(2, 4, 1) Number of rings, from the border to the center
uniform int rings; // = 3
// @range(0, 0.4) Delay between the innermost ring and the outermost one, as a part of the transition
uniform float stagger; // = 0.15
// @range(0, 1) Darkness of the shadows cast by the lifted tiles
uniform float shadow; // = 0.5
// @color Color of the tray seen between the tiles
uniform vec4 backColor; // = vec4(0.1, 0.1, 0.11, 1.0)

const float PI = 3.141592653589793;
const float GAP = 0.035;
const float EYE = 3.0;
const vec2 LIGHT = vec2(0.12, -0.16);

float ringOf(vec2 c, vec2 dims) {
  return min(min(c.x, c.y), min(dims.x - 1.0 - c.x, dims.y - 1.0 - c.y));
}

// counted counterclockwise from the ring's bottom left corner
float indexOf(vec2 c, float r, vec2 wh) {
  vec2 q = c - r;
  if (q.y < 0.5) return q.x;
  if (q.x > wh.x - 0.5) return wh.x + q.y;
  if (q.y > wh.y - 0.5) return 2.0 * wh.x + wh.y - q.x;
  return 2.0 * (wh.x + wh.y) - q.y;
}

vec2 cellAt(float k, float r, vec2 wh) {
  float L = 2.0 * (wh.x + wh.y);
  k = mod(k, L);
  vec2 q = k < wh.x ? vec2(k, 0.0)
    : k < wh.x + wh.y ? vec2(wh.x, k - wh.x)
    : k < 2.0 * wh.x + wh.y ? vec2(2.0 * wh.x + wh.y - k, wh.y)
    : vec2(0.0, L - k);
  return q + r;
}

float smooth3(float u) {
  return u * u * (3.0 - 2.0 * u);
}

// overshoots by about 1.5% near the end so the ring settles like a detent
float ease(float u) {
  float s = sin(PI * u);
  return smooth3(u) + 0.6 * u * u * u * s * s;
}

float edge(float d, float px) {
  return clamp(0.5 - d / px, 0.0, 1.0);
}

vec4 transition(vec2 uv) {
  float R = clamp(float(rings), 2.0, 4.0);
  float sh = 2.0 * R;
  float lg = max(sh, floor(sh * max(ratio, 1.0 / ratio) + 0.5));
  vec2 dims = ratio >= 1.0 ? vec2(lg, sh) : vec2(sh, lg);
  vec2 P = uv * dims;
  vec2 here = clamp(floor(P), vec2(0.0), dims - 1.0);
  float px = sh / 600.0;
  float open = sin(PI * progress);
  // resting tiles overlap by a few pixels to hide their seams
  float hs = 0.5 - GAP * open + 2.0 * px * (1.0 - smoothstep(0.0, 0.1, open));
  float st = clamp(stagger, 0.0, 0.4);

  float z1 = -9.0, z2 = -9.0, cov1 = 0.0, cov2 = 0.0, a1 = 0.0, a2 = 0.0;
  vec2 s1 = P, s2 = P;
  float shade = 0.0;
  for (int pass = 0; pass < 2; pass++) {
    for (int j = 0; j < 9; j++) {
      vec2 c = here + vec2(mod(float(j), 3.0), floor(float(j) / 3.0)) - 1.0;
      if (c.x >= 0.0 && c.y >= 0.0 && c.x < dims.x && c.y < dims.y) {
        float r = ringOf(c, dims);
        vec2 wh = dims - 1.0 - 2.0 * r;
        float L = 2.0 * (wh.x + wh.y);
        float t = clamp((progress - st * (R - 1.0 - r) / (R - 1.0)) / (1.0 - st), 0.0, 1.0);
        float u1 = clamp(t / 0.34, 0.0, 1.0), u2 = clamp((t - 0.66) / 0.34, 0.0, 1.0);
        float s = floor(0.25 * L + 0.5) * (mod(r, 2.0) < 0.5 ? 1.0 : -1.0) * (ease(u1) - ease(u2));
        float k = indexOf(c, r, wh);
        float fs = s - floor(s);
        float h = mod(k - floor(s), L);
        vec2 home = cellAt(h, r, wh) + 0.5;
        vec2 ctr = mix(c, cellAt(k + 1.0, r, wh), fs) + 0.5;
        float a = PI * smooth3(smooth3(clamp((t - 0.34 - 0.2 * h / L) / 0.12, 0.0, 1.0)));
        float sa = max(sin(a), 0.0), ca = cos(a);
        float ride = 0.5 * (sin(PI * u1) + sin(PI * u2));
        float lift = 0.5 * ride + sa;
        float sc = 1.0 + 0.04 * ride + 0.15 * sa;
        if (pass == 0) {
          // perspective flip about the tile's vertical axis
          vec2 d = (P - ctr) / sc;
          float den = EYE * ca + d.x * sa;
          den = abs(den) < 1e-5 ? 1e-5 : den;
          float x = d.x * EYE / den;
          vec2 lp = vec2(x, d.y * (EYE - x * sa) / EYE);
          vec2 ink = sc * vec2(max(abs(ca), 0.05), 1.0);
          vec2 e = (abs(lp) - hs) * ink;
          float cv = den * ca > 0.0 || abs(ca) < 0.05 ? edge(e.x, px) * edge(e.y, px) : 0.0;
          float z = lift + 0.001 * cv;
          vec2 src = home + vec2(ca < 0.0 ? -lp.x : lp.x, lp.y);
          // the incoming face lies flat in the slot under a flipping tile, so no tray shows
          vec2 f = abs(P - ctr) - hs;
          float under = sa > 0.0 ? edge(f.x, px) * edge(f.y, px) : 0.0;
          for (int m = 0; m < 2; m++) {
            float cm = m == 0 ? cv : under;
            float zm = m == 0 ? z : -1.0;
            float am = m == 0 ? a : PI;
            vec2 sm = m == 0 ? src : home + P - ctr;
            if (cm > 0.0 && zm > z1) {
              z2 = z1; cov2 = cov1; a2 = a1; s2 = s1;
              z1 = zm; cov1 = cm; a1 = am; s1 = sm;
            } else if (cm > 0.0 && zm > z2) {
              z2 = zm; cov2 = cm; a2 = am; s2 = sm;
            }
          }
        } else if (lift > z1 + 0.01) {
          vec2 d = (P - ctr - LIGHT * lift) / sc;
          vec2 b = abs(d * vec2(1.0 / max(abs(ca), 0.05), 1.0)) - hs;
          float w = length(max(b, 0.0)) + min(max(b.x, b.y), 0.0);
          float blur = 0.04 + 0.12 * lift;
          shade = max(shade, min(lift - max(z1, 0.0), 1.0) * (1.0 - smoothstep(-blur, blur, w)));
        }
      }
    }
  }

  vec4 col = backColor;
  if (cov2 > 0.0) {
    vec2 q = clamp(s2 / dims, 0.0, 1.0);
    vec4 c2 = cos(a2) < 0.0 ? getToColor(q) : getFromColor(q);
    float sa = sin(a2);
    c2.rgb *= 1.0 - 0.45 * sa * sa + 0.2 * sa * abs(cos(a2));
    col = mix(col, c2, cov2);
  }
  vec2 q = clamp(s1 / dims, 0.0, 1.0);
  vec4 c1 = cos(a1) < 0.0 ? getToColor(q) : getFromColor(q);
  float sa = sin(a1);
  c1.rgb *= 1.0 - 0.45 * sa * sa + 0.2 * sa * abs(cos(a1));
  col = mix(col, c1, cov1);
  col.rgb *= 1.0 - 0.6 * shadow * shade;
  return col;
}

// Author: gre
// License: MIT
// Description: The frame is cut into tiles that swap places in pairs, round after round along the rows then along the columns, one tile of each pair lifting to swing over the other with a soft shadow; each tile turns to the incoming image during one of its swaps, so the incoming picture arrives scrambled and the last rounds sort it out
// Tags: tiles, grid, shuffle, swap, slide, puzzle, shadow

// @range(2, 8, 1) Number of tiles along the longer side of the frame (the tiles stay about square)
uniform int tiles; // = 5
// @range(0, 0.15) Width of the gaps that open between the tiles, as a part of a tile
uniform float gap; // = 0.05
// @range(0, 1) Darkness of the shadows the tiles cast
uniform float shadow; // = 0.55
// @color Color of the tray seen under the tiles
uniform vec4 tray; // = vec4(0.07, 0.07, 0.08, 1.0)

const float MAX_TILES = 8.0;
// rounds of swaps, along the rows in even rounds and along the columns in odd ones
const int ROUNDS = 4;
// the gaps open over [0, OPEN] and close over [1 - OPEN, 1]
const float OPEN = 0.15;
// the swaps run over [START, 1 - START]
const float START = 0.07;
// each round sweeps across the frame from its top left corner, a swap starting WAVE later than the one a cell
// before it, plus up to JITTER, in swap durations. The next round follows 1 + WAVE + JITTER behind, so that
// the rounds overlap without a tile ever starting a swap before it has finished the one before
const float WAVE = 0.4;
const float JITTER = 0.15;
// growth of the lifted tile of a swap and shrink of the other one, as seen in perspective
const float GROW = 0.08;
const float SINK = 0.03;
// how far the tile that slides over swings out of its line, in cells
const float SWING = 0.2;
const float EDGE = 0.0015;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float boxDist(vec2 p, vec2 b, float r) {
  vec2 d = abs(p) - b + r;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - r;
}

// the cell that cell c swaps with in round k (c itself when it has no partner). Each line of the
// round pairs its cells two by two, from its first or from its second cell; a line of two cells
// swaps them in one of its two rounds only, so that the second swap does not undo the first
vec2 partner(vec2 c, float k, vec2 n) {
  bool rows = mod(k, 2.0) < 0.5;
  float a = rows ? c.x : c.y;
  float len = rows ? n.x : n.y;
  float line = rows ? c.y : c.x;
  float par = len < 2.5 ? mod(line + floor(0.5 * k), 2.0) : step(0.5, hash12(vec2(line, 7.0 * k + 1.0)));
  float b = mod(a - par, 2.0) < 0.5 ? a + 1.0 : a - 1.0;
  if (a < par || b >= len) b = a;
  return rows ? vec2(b, c.y) : vec2(c.x, b);
}

bool differ(vec2 a, vec2 b) {
  return abs(a.x - b.x) + abs(a.y - b.y) > 0.5;
}

// time of the swap of cells c and b in round k, from 0 when it starts to 1 when it ends;
// sw is the duration of a swap and the time between two rounds
float swapTime(vec2 c, vec2 b, float k, vec2 n, vec2 sw) {
  vec2 m = 0.5 * (c + b);
  float t0 = START + k * sw.y + sw.x * (WAVE * (m.x + n.y - 1.0 - m.y) + JITTER * hash12(min(c, b) + 13.0 * k));
  return (progress - t0) / sw.x;
}

// the swap of the tile that cell c holds now, the first swap of the cell that is not over yet:
// x its round (ROUNDS once the cell has no swap left), y its time, zw the partner cell
vec4 currentSwap(vec2 c, vec2 n, vec2 sw) {
  for (int i = 0; i < ROUNDS; i++) {
    float k = float(i);
    vec2 b = partner(c, k, n);
    if (differ(b, c)) {
      float u = swapTime(c, b, k, n, sw);
      if (u < 1.0) return vec4(k, max(u, 0.0), b);
    }
  }
  return vec4(float(ROUNDS), 0.0, c);
}

// lift of the tile of cell c during its current swap: positive for the tile that slides over,
// negative for the one that slides under
float swapLift(vec2 c, vec4 cur) {
  if (cur.x >= float(ROUNDS)) return 0.0;
  float u = cur.y;
  float bell = 16.0 * u * u * (1.0 - u) * (1.0 - u);
  bool over = (hash12(min(c, cur.zw) + 13.0 * cur.x + 3.7) < 0.5) == (c.x + c.y < cur.z + cur.w);
  return over ? bell : -bell;
}

// center of that tile, in cells: the tile that slides over swings out a little to pass around the other
vec2 swapPos(vec2 c, vec4 cur, float lift) {
  float u = cur.y;
  float e = u * u * u * (u * (6.0 * u - 15.0) + 10.0);
  vec2 side = (cur.zw - c).yx * (hash12(cur.zw + c + 1.9 * cur.x) < 0.5 ? 1.0 : -1.0);
  return mix(c, cur.zw, e) + 0.5 + SWING * max(lift, 0.0) * side;
}

// whether the tile of a cell, or its shadow, stays away from the point d, in cells from the center of the cell:
// the tile moves by a cell along one side and swings out by SWING along the other
bool outOfReach(vec2 d, float reach) {
  d = abs(d);
  return max(d.x, d.y) > 1.0 + reach || min(d.x, d.y) > SWING + reach;
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - abs(v));
}

// the color of a tile: its image points src (outgoing xy, incoming zw) turned by w, brightened as it lifts,
// with a pale rim along its edge (at distance e) and darkened by the shadows sh of the tiles above it
vec4 tileColor(vec4 src, float w, float lift, float e, float sh) {
  vec4 c = w <= 0.0 ? getFromColor(mirror(src.xy)) : w >= 1.0 ? getToColor(mirror(src.zw))
    : mix(getFromColor(mirror(src.xy)), getToColor(mirror(src.zw)), w);
  float up = max(lift, 0.0);
  float rim = 0.2 * up * (1.0 - smoothstep(0.0, 0.006, e));
  c.rgb = mix(clamp(c.rgb * (1.0 + 0.06 * up + 0.1 * min(lift, 0.0)) * (1.0 - sh), 0.0, 1.0), vec3(1.0), rim);
  return c;
}

bool above(vec2 a, vec2 b) {
  return a.x + 0.001 * a.y > b.x + 0.001 * b.y;
}

// how much a tile at height z is darkened by the shadow h
float shadowOn(vec2 h, float z) {
  return h.x > z + 0.01 ? h.y : 0.0;
}

vec4 transition(vec2 uv) {
  // at least two tiles along each side, so that the tiles move along both
  float nl = clamp(float(tiles), 2.0, MAX_TILES);
  vec2 n = ratio >= 1.0
    ? vec2(nl, clamp(floor(nl / ratio + 0.5), 2.0, MAX_TILES))
    : vec2(clamp(floor(nl * ratio + 0.5), 2.0, MAX_TILES), nl);
  vec2 cell = vec2(ratio, 1.0) / n;
  vec2 x = uv * vec2(ratio, 1.0);
  vec2 here = clamp(floor(uv * n), vec2(0.0), n - 1.0);
  float open = smoothstep(0.0, OPEN, progress) * (1.0 - smoothstep(1.0 - OPEN, 1.0, progress));
  float g = clamp(gap, 0.0, 0.15) * open * min(cell.x, cell.y);
  // without gaps, the tiles overlap a little to hide their seams
  vec2 hb = vec2(0.5 * cell - 0.5 * g + EDGE * max(1.0 - 0.5 * g / EDGE, 0.0));
  float rad = 0.6 * g;
  // duration of a swap, and time between two rounds: the last swap ends at 1 - START
  float gapK = 1.0 + WAVE + JITTER;
  float sd = (1.0 - 2.0 * START) / (float(ROUNDS - 1) * gapK + 1.0 + WAVE * (n.x + n.y - 2.0) + JITTER);
  vec2 sw = vec2(sd, sd * gapK);

  // half a lifted tile, its shadow and their soft edges, in cells
  float reach = 0.5 * (1.0 + GROW) + 0.16 + 0.006 / min(cell.x, cell.y);
  // the two highest tiles seen here: height, coverage, lift, turn, edge distance, outgoing and incoming image points
  float z1 = -9.0, z2 = -9.0, m1 = 0.0, m2 = 0.0, l1 = 0.0, l2 = 0.0, w1 = 0.0, w2 = 0.0, e1 = 0.0, e2 = 0.0;
  vec4 s1 = vec4(0.0), s2 = vec4(0.0);
  // the three highest shadows cast here: height of the tile, darkness
  vec2 h1 = vec2(-9.0, 0.0), h2 = h1, h3 = h1;
  float sh0 = 0.0;
  vec2 light = vec2(0.45, -0.75) * min(cell.x, cell.y);
  for (int j = 0; j < 5; j++) {
    for (int i = 0; i < 5; i++) {
      vec2 o = vec2(float(i) - 2.0, float(j) - 2.0);
      vec2 c = here + o;
      if (c.x < 0.0 || c.y < 0.0 || c.x >= n.x || c.y >= n.y || outOfReach(uv * n - c - 0.5, reach)) continue;
      vec4 cur = currentSwap(c, n, sw);
      float lift = swapLift(c, cur);
      float up = max(lift, 0.0);
      float sc = 1.0 + GROW * up - SINK * max(-lift, 0.0);
      vec2 away = x - swapPos(c, cur, lift) * cell;
      vec2 q = away / sc;
      float e = -boxDist(q, hb, rad) * sc;

      vec2 d = away - light * (0.15 * g / min(cell.x, cell.y) + 0.06 * up);
      float blur = 0.003 + 0.25 * g + 0.04 * up * min(cell.x, cell.y);
      float sdist = boxDist(d, hb * sc, rad);
      vec2 cs = vec2(lift, (1.0 - smoothstep(-blur, blur, sdist)) * (0.75 - 0.25 * up));
      sh0 = max(sh0, cs.y);
      // among shadows of tiles as high, the darkest counts
      if (cs.y > 0.0) {
        if (above(cs, h1)) { h3 = h2; h2 = h1; h1 = cs; }
        else if (above(cs, h2)) { h3 = h2; h2 = cs; }
        else if (above(cs, h3)) h3 = cs;
      }

      float cov = clamp(e / EDGE + 0.5, 0.0, 1.0);
      // where resting tiles overlap at their edges, the one that covers this point fully comes first
      float z = lift + 0.001 * cov;
      if (cov <= 0.0 || z <= z2) continue;
      // the cell the tile started from, the one it ends in, and its swaps before and from the current one
      vec2 s = c, h = c;
      float before = 0.0, after = 0.0;
      for (int k = ROUNDS - 1; k >= 0; k--) {
        if (float(k) < cur.x) {
          vec2 b = partner(s, float(k), n);
          if (differ(b, s)) before += 1.0;
          s = b;
        }
      }
      for (int k = 0; k < ROUNDS; k++) {
        if (float(k) >= cur.x) {
          vec2 b = partner(h, float(k), n);
          if (differ(b, h)) after += 1.0;
          h = b;
        }
      }
      // each tile turns to the incoming image during one of its swaps, so the incoming image comes
      // scrambled and the last rounds sort it out; a tile that never moves turns in place at the end
      float turn = floor(hash12(h + 21.3) * (before + after));
      float w = before + after < 0.5 ? smoothstep(1.0 - 2.0 * OPEN, 1.0 - START, progress)
        : before > turn ? 1.0 : before == turn ? smoothstep(0.35, 0.65, cur.y) : 0.0;
      vec2 l = q / cell + 0.5;
      vec4 src = vec4((s + l) / n, (h + l) / n);
      if (z > z1) {
        z2 = z1; m2 = m1; l2 = l1; w2 = w1; e2 = e1; s2 = s1;
        z1 = z; m1 = cov; l1 = lift; w1 = w; e1 = e; s1 = src;
      } else {
        z2 = z; m2 = cov; l2 = lift; w2 = w; e2 = e; s2 = src;
      }
    }
  }

  float sh1 = shadowOn(h1, z1), sh2 = shadowOn(h1, z2);
  sh1 = max(sh1, max(shadowOn(h2, z1), shadowOn(h3, z1)));
  sh2 = max(sh2, max(shadowOn(h2, z2), shadowOn(h3, z2)));
  float k = clamp(shadow, 0.0, 1.0);
  vec4 col = vec4(tray.rgb * (1.0 - k * sh0), tray.a);
  // the lower tile only shows where the top one does not cover this point fully
  if (m2 > 0.0 && m1 < 1.0) col = mix(col, tileColor(s2, w2, l2, e2, k * sh2), m2);
  if (m1 > 0.0) col = mix(col, tileColor(s1, w1, l1, e1, k * sh1), m1);
  return col;
}

// Author: numb3r23
// License: MIT
// Description: The incoming image is revealed tile by tile in a diagonal wave
// Tags: tiles, wave, wipe
// Ported from https://gist.github.com/numb3r23/169781bb76f310e2bfde

// @param Number of tiles (columns, rows)
uniform ivec2 tileCount; // = ivec2(8, 8)
uniform bool flipX; // = true
uniform bool flipY; // = false

vec4 transition(vec2 uv) {
  vec2 tileSize = 1.0 / vec2(tileCount);
  vec2 posInTile = fract(uv * vec2(tileCount));
  vec2 tileNum = floor(uv * vec2(tileCount));
  float countTiles = float(tileCount.x * tileCount.y);

  // Diagonal wave from bottom-left to top-right
  float offset = (tileNum.y + tileNum.x * float(tileCount.y)) / countTiles;
  float timeOffset = clamp((progress - offset) * countTiles, 0.0, 0.5);
  float sinTime = 1.0 - abs(cos(fract(timeOffset) * 3.1415926));

  vec2 texC = posInTile;

  if (sinTime <= 0.5) {
    if (flipX) {
      if (texC.x < sinTime || texC.x > 1.0 - sinTime)
        return getFromColor(uv);
      texC.x = texC.x < 0.5
        ? (texC.x - sinTime) * 0.5 / (0.5 - sinTime)
        : (texC.x - 0.5) * 0.5 / (0.5 - sinTime) + 0.5;
    }
    if (flipY) {
      if (texC.y < sinTime || texC.y > 1.0 - sinTime)
        return getFromColor(uv);
      texC.y = texC.y < 0.5
        ? (texC.y - sinTime) * 0.5 / (0.5 - sinTime)
        : (texC.y - 0.5) * 0.5 / (0.5 - sinTime) + 0.5;
    }
    vec2 globalUV = tileNum * tileSize + texC * tileSize;
    return getFromColor(globalUV);
  } else {
    if (flipX) {
      if (texC.x > sinTime || texC.x < 1.0 - sinTime)
        return getToColor(uv);
      texC.x = texC.x < 0.5
        ? (texC.x - sinTime) * 0.5 / (0.5 - sinTime)
        : (texC.x - 0.5) * 0.5 / (0.5 - sinTime) + 0.5;
      texC.x = 1.0 - texC.x;
    }
    if (flipY) {
      if (texC.y > sinTime || texC.y < 1.0 - sinTime)
        return getToColor(uv);
      texC.y = texC.y < 0.5
        ? (texC.y - sinTime) * 0.5 / (0.5 - sinTime)
        : (texC.y - 0.5) * 0.5 / (0.5 - sinTime) + 0.5;
      texC.y = 1.0 - texC.y;
    }
    vec2 globalUV = tileNum * tileSize + texC * tileSize;
    return getToColor(globalUV);
  }
}

// Author: gre
// License: MIT
// Description: The outgoing image slumps from the sky down into layered hills of its own flat colors; as the view travels over them, the hills turn one after another, from the farthest to the nearest, into those of the incoming image, which then grows out of the ground up to the sky
// Tags: hills, landscape, layers, flat, palette, parallax, abstract

// @range(0, 0.1) Height of the waves running along the hills, in frame heights
uniform float waves; // = 0.04
// @range(0, 2) How fast the view travels over the hills
uniform float travel; // = 1.0
// @range(0, 2.5) How vivid the flat colors are
uniform float vivid; // = 1.4

const int N = 14;
// between these two moments the shapes are free of both images, so the palettes of both are read instead of their shapes
const float FREED = 0.36;
const float CAUGHT = 0.64;

float luma(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec2 spot(int i) {
  return fract(vec2(0.754878, 0.569840) * float(i) + 0.4);
}

// how much the color c stands for a tone: the ones that stand out win, since the average of several hues is mud
float weight(vec4 c, vec2 stats, vec3 tint, float z) {
  float l = luma(c.rgb);
  float d = (l - stats.x) / stats.y - z;
  float s = 0.4 * length(c.rgb - l) + length(c.rgb - l - tint);
  float w = exp(-4.0 * d * d) * (0.1 + s);
  w *= w * w;
  return c.a * w * w + 1e-7;
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  bool late = progress > 0.5;

  vec2 ma = vec2(0.0);
  vec2 mb = vec2(0.0);
  vec3 ta = vec3(0.0);
  vec3 tb = vec3(0.0);
  vec2 sum = vec2(1e-4);
  for (int i = 0; i < N; i++) {
    vec4 ca = progress < CAUGHT ? getFromColor(spot(i)) : vec4(0.0);
    vec4 cb = progress > FREED ? getToColor(spot(i)) : vec4(0.0);
    vec2 l = vec2(luma(ca.rgb), luma(cb.rgb));
    sum += vec2(ca.a, cb.a);
    ma += vec2(l.x, l.x * l.x) * ca.a;
    mb += vec2(l.y, l.y * l.y) * cb.a;
    ta += (ca.rgb - l.x) * ca.a;
    tb += (cb.rgb - l.y) * cb.a;
  }
  ma /= sum.x;
  mb /= sum.y;
  ta /= sum.x;
  tb /= sum.y;
  ma.y = sqrt(max(ma.y - ma.x * ma.x, 0.0)) + 0.03;
  mb.y = sqrt(max(mb.y - mb.x * mb.x, 0.0)) + 0.03;

  vec4 here = late ? b : a;
  float when = late ? 0.84 + 0.12 * uv.y - progress : progress - 0.04 - 0.12 * (1.0 - uv.y);
  float bend = smoothstep(0.0, 1.0, when / 0.2);
  float y = 0.0;
  if (bend < 1.0) {
    // fine detail melts into a broad field before the shapes move, so their edges do not tear
    float melt = smoothstep(0.0, 0.55, bend);
    vec2 acc = vec2(luma(here.rgb) * here.a, here.a);
    vec2 broad = vec2(late ? mb.x : ma.x, 1.0) * 1e-3;
    if (melt < 1.0) {
      float soft = smoothstep(0.0, 0.2, progress) * (1.0 - smoothstep(0.8, 1.0, progress));
      for (int i = 0; i < N; i++) {
        float r = 0.055 * soft * sqrt((float(i) + 0.5) / float(N));
        float g = 2.39996 * float(i);
        vec2 q = fold(uv + r * vec2(cos(g), sin(g)) / vec2(ratio, 1.0));
        vec4 c = late ? getToColor(q) : getFromColor(q);
        acc += vec2(luma(c.rgb) * c.a, c.a);
      }
    }
    if (melt > 0.0) {
      for (int i = 0; i < N; i++) {
        vec2 q = (uv - spot(i)) * vec2(ratio, 1.0);
        vec4 c = late ? getToColor(spot(i)) : getFromColor(spot(i));
        broad += vec2(luma(c.rgb), 1.0) * c.a * exp(-26.0 * dot(q, q));
      }
    }
    y = mix(acc.x / max(acc.y, 1e-4), broad.x / broad.y, melt);
    y = (y - (late ? mb.x : ma.x)) / (late ? mb.y : ma.y);
  }
  float aa = mix(0.03, 0.002, bend);
  // the four hills, from the farthest to the nearest; the sky is behind them
  vec4 nears = vec4(0.25, 0.5, 0.75, 1.0);
  vec4 ks = vec4(3.0, 2.0, 1.0, 0.0);
  vec4 zc = (ks - 2.0) * 0.62 + 0.31;
  vec4 turns = smoothstep(0.0, 1.0, (progress - (0.36 - 0.02 * (ks - 4.0))) / 0.18);
  vec4 top = vec4(0.0);
  if (bend > 0.0) {
    vec4 grownA = vec4(0.0);
    vec4 grownB = vec4(0.0);
    vec4 totalA = vec4(1e-4);
    vec4 totalB = vec4(1e-4);
    vec4 xa = uv.x + 0.5 * travel * nears * progress;
    vec4 xb = uv.x + 0.5 * travel * nears * (progress - 1.0);
    for (int i = 0; i < N; i++) {
      if (progress < CAUGHT) {
        vec4 c = getFromColor(spot(i));
        vec4 dx = fract(spot(i).x - xa + 0.5) - 0.5;
        vec4 w = exp(-16.0 * dx * dx) * c.a;
        totalA += w;
        grownA += w * smoothstep(-0.5, 0.5, zc - (luma(c.rgb) - ma.x) / ma.y);
      }
      if (progress > FREED) {
        vec4 c = getToColor(spot(i));
        vec4 dx = fract(spot(i).x - xb + 0.5) - 0.5;
        vec4 w = exp(-16.0 * dx * dx) * c.a;
        totalB += w;
        grownB += w * smoothstep(-0.5, 0.5, zc - (luma(c.rgb) - mb.x) / mb.y);
      }
    }
    top = 0.04 + 0.78 * mix(grownA / totalA, grownB / totalB, turns) + 0.02 * ks;
    top += waves * sin(uv.x * ratio * (3.0 + 1.6 * nears) + 9.6 * nears + travel * progress * (4.0 + 9.0 * nears));
  }
  vec4 covers = smoothstep(-aa, aa, mix(0.22 * (zc - y), top - uv.y, bend));
  vec3 col = vec3(0.0);
  float left = 1.0;
  for (int j = 4; j >= 0; j--) {
    float cover = j == 4 ? covers.w : j == 3 ? covers.z : j == 2 ? covers.y : j == 1 ? covers.x : 1.0;
    if (cover <= 0.0) continue;
    float k = 4.0 - float(j);
    // the tone, in deviations from the mean
    float z = (k - 2.0) * 0.62;
    float turn = smoothstep(0.0, 1.0, (progress - (0.36 - 0.02 * (k - 4.0))) / 0.18);
    vec4 pa = vec4(0.0);
    vec4 pb = vec4(0.0);
    for (int i = 0; i < N; i++) {
      if (turn < 1.0) {
        vec4 q = getFromColor(spot(i));
        pa += vec4(q.rgb, 1.0) * weight(q, ma, ta, z);
      }
      if (turn > 0.0) {
        vec4 q = getToColor(spot(i));
        pb += vec4(q.rgb, 1.0) * weight(q, mb, tb, z);
      }
    }
    vec3 c = mix(pa.rgb / max(pa.a, 1e-7), pb.rgb / max(pb.a, 1e-7), turn);
    float goal = mix(ma.x + 1.2 * z * ma.y, mb.x + 1.2 * z * mb.y, turn);
    c = clamp(goal + (c - luma(c)) * vivid, 0.0, 1.0);
    col += left * cover * c;
    left *= 1.0 - cover;
    if (left <= 0.0) break;
  }

  float flatness = smoothstep(0.0, 0.16, progress) * (1.0 - smoothstep(0.84, 1.0, progress));
  return vec4(mix(here.rgb, col, flatness), mix(a.a, b.a, smoothstep(0.34, 0.66, progress)));
}

// Author: gre
// License: MIT
// Description: The brightest parts of the outgoing image burst into flat vivid color, and a run of five colors pours down through its tones from light to dark; the contours bend into the shapes of the incoming image, whose lights open first and whose shadows close the run
// Tags: color, flat, poster, pop, luminance, contour, abstract

// @color First color, over the lights of the outgoing image
uniform vec4 color1; // = vec4(1.0, 0.86, 0.3, 1.0)
// @color Second color
uniform vec4 color2; // = vec4(1.0, 0.42, 0.3, 1.0)
// @color Third color
uniform vec4 color3; // = vec4(0.86, 0.16, 0.5, 1.0)
// @color Fourth color
uniform vec4 color4; // = vec4(0.36, 0.16, 0.62, 1.0)
// @color Last color, giving way to the incoming image
uniform vec4 color5; // = vec4(0.1, 0.5, 0.75, 1.0)
// @range(0, 1) How far the colors spread from the brightest place rather than follow the shapes
uniform float spread; // = 0.3
// @range(0, 0.06) Smoothness of the contours, in frame heights
uniform float softness; // = 0.03

const int SPOTS = 7;
const int TAPS = 16;

float luma(vec4 c) {
  return dot(c.rgb, vec3(0.299, 0.587, 0.114));
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec2 spot(int i) {
  return fract(vec2(0.754878, 0.569840) * float(i) + 0.4);
}

vec4 pixel(vec2 p, bool incoming) {
  return incoming ? getToColor(p) : getFromColor(p);
}

// x: when the colors reach this place, from 0 on the lights to 1 in the shadows; y: how torn the contour is there
vec2 delay(vec2 uv, vec4 here, bool incoming, float sharp) {
  vec2 k = vec2(ratio, 1.0);
  vec2 tone[SPOTS];
  vec3 stats = vec3(0.0, 0.0, 1e-4);
  for (int i = 0; i < SPOTS; i++) {
    vec4 c = pixel(spot(i), incoming);
    tone[i] = vec2(luma(c), c.a);
    stats += vec3(tone[i].x, tone[i].x * tone[i].x, 1.0) * c.a;
  }
  float mean = stats.x / stats.z;
  float dev = sqrt(max(stats.y / stats.z - mean * mean, 0.0)) + 0.02;

  vec3 light = vec3(0.5, 0.5, 1.0) * 1e-4;
  vec2 broad = vec2(mean, 1.0) * 1e-3;
  for (int i = 0; i < SPOTS; i++) {
    vec2 d = (uv - spot(i)) * k;
    broad += vec2(tone[i].x, 1.0) * tone[i].y * exp(-22.0 * dot(d, d));
    light += vec3(spot(i), 1.0) * tone[i].y * exp(2.5 * (tone[i].x - mean) / dev);
  }
  float y = mean + 1.4 * (broad.x / broad.y - mean);

  float grain = 0.0;
  if (sharp > 0.0) {
    float l = luma(here);
    vec3 acc = vec3(l, l * l, 1.0) * here.a + vec3(0.0, 0.0, 1e-4);
    for (int i = 0; i < TAPS; i++) {
      float q = (float(i) + 0.5) / float(TAPS);
      float a = 2.399963 * float(i);
      vec4 c = pixel(fold(uv + softness * sqrt(q) * vec2(cos(a), sin(a)) / k), incoming);
      l = luma(c);
      acc += vec3(l, l * l, 1.0) * c.a * (1.0 - 0.7 * q);
    }
    l = acc.x / acc.z;
    grain = sharp * sqrt(max(acc.y / acc.z - l * l, 0.0)) / dev;
    // the tone is drawn to those of the spots, which irons out the grain of plain areas
    vec2 near = vec2(l, 1.0) * 0.02;
    for (int i = 0; i < SPOTS; i++) {
      float d = (tone[i].x - l) / dev;
      near += vec2(tone[i].x, 1.0) * tone[i].y * exp(-9.0 * d * d);
    }
    y = mix(y, near.x / near.y, sharp);
  }

  vec2 c = light.xy / light.z;
  float far = length((uv - c) * k) / length((0.5 + abs(c - 0.5)) * k);
  // a plain image has no shapes to follow
  float w = mix(0.9, spread, smoothstep(0.03, 0.12, dev));
  float dark = 1.0 - smoothstep(-1.8, 1.8, (y - mean) / dev);
  return vec2(mix(dark, far, w), min(0.06 * (1.0 - w) * grain, 0.04));
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  // the shapes of one image melt before those of the other form, so a pixel reads the details of one only
  vec2 da = delay(uv, a, false, 1.0 - smoothstep(0.38, 0.5, progress));
  vec2 db = delay(uv, b, true, smoothstep(0.5, 0.62, progress));
  float t = mix(-0.02, 2.5, progress);
  float lead = t - da.x;
  float tail = 1.4 + db.x - t;
  float s = 5.0 * clamp(lead / (lead + tail), 0.0, 1.0);
  // contours that run through fine texture are drawn softer, as it would tear them
  float aa = 0.015 + 2.0 * (da.y + db.y);
  vec4 col = mix(color1, color2, smoothstep(1.0 - aa, 1.0 + aa, s));
  col = mix(col, color3, smoothstep(2.0 - aa, 2.0 + aa, s));
  col = mix(col, color4, smoothstep(3.0 - aa, 3.0 + aa, s));
  col = mix(col, color5, smoothstep(4.0 - aa, 4.0 + aa, s));
  col.a *= mix(a.a, b.a, 0.2 * s);
  col = mix(a, col, smoothstep(0.0, 0.012 + 2.0 * da.y, lead));
  return mix(col, b, smoothstep(0.0, 0.012 + 2.0 * db.y, -tail));
}

// Author: zhmy
// License: MIT
// Description: The outgoing image shrinks away upward while the incoming one slides in from the bottom
// Tags: slide, zoom, vertical

const vec4 black = vec4(0.0); // where no image is drawn: transparent
const vec2 boundMin = vec2(0.0, 0.0);
const vec2 boundMax = vec2(1.0, 1.0);

bool inBounds (vec2 p) {
    return all(lessThan(boundMin, p)) && all(lessThan(p, boundMax));
}

vec4 transition (vec2 uv) {
    vec2 spfr,spto = vec2(-1.);
    float size = mix(1.0, 3.0, progress*0.2);
    spto = (uv + vec2(-0.5,-0.5))*vec2(size,size)+vec2(0.5,0.5);
    spfr = (uv + vec2(0.0, 1.0 - progress));
    if(inBounds(spfr)){
        return getToColor(spfr);
    } else if(inBounds(spto)){
        return getFromColor(spto) * (1.0 - progress);
    } else{
        return black;
    }
}

// Author: gre
// License: MIT
// Description: Twisting waves run out from the center, each ring of the outgoing image rocking against the next until its shapes stretch into circles of flame-like tongues; the incoming image comes in along the rings, which widen until they meet, and the rocking dies down on it
// Tags: twist, wave, rings, distortion, liquid

// @range(2, 12) Waves over the height of the frame
uniform float rings; // = 5.0
// @range(0, 2) How far the rings turn, in radians
uniform float turn; // = 0.7

const float TAU = 6.28318530718;
const int TAPS = 8;

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec4 premultiply(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 transition(vec2 uv) {
  vec2 asp = vec2(ratio, 1.0);
  float env = smoothstep(0.0, 0.4, progress) * (1.0 - smoothstep(0.6, 1.0, progress));
  float level = 2.6 * smoothstep(0.1, 0.9, progress) - 1.3;
  vec4 sum = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    vec2 o = fract(vec2(0.754878, 0.569840) * (float(i) + 0.5)) - 0.5;
    vec2 x = (uv - 0.5) * asp + o * env / 450.0;
    float ph = TAU * (rings * length(x) - 2.5 * progress);
    float a = turn * env * sin(ph), c = cos(a), s = sin(a);
    vec2 q = fold(vec2(c * x.x - s * x.y, s * x.x + c * x.y) / asp + 0.5);
    sum += mix(premultiply(getFromColor(q)), premultiply(getToColor(q)), smoothstep(-0.06, 0.06, level + cos(ph)));
  }
  return vec4(sum.rgb / max(sum.a, 1e-5), sum.a / float(TAPS));
}

// Author: gre
// License: MIT
// Description: The image is cut into a mosaic of triangles that turn over in perspective in a wave spreading from a point, each one rolling away from it about one of its three axes, catching a glint of light and casting a soft shadow, and showing its part of the incoming image on its back
// Tags: triangles, tiles, flip, 3d, wave, geometric

// @range(2, 20, 1) Number of rows of triangles across the height of the frame
uniform int rows; // = 6
// @param Point the wave of flips spreads from (0,0 is the bottom left corner, 1,1 the top right one)
uniform vec2 center; // = vec2(0.0, 1.0)
// @range(0, 0.9) How long the wave takes to cross the frame, as a part of the transition: 0 turns every triangle at once
uniform float stagger; // = 0.75
// @range(0, 1) Strength of the light and shadows on the turning triangles and of the shade in the holes they leave
uniform float shading; // = 0.6

const float PI = 3.141592653589793;
const float SQRT3 = 1.7320508075688772;
const float EDGE = 0.0012;
// distance of the eye from the sheet, in triangle sides
const float EYE = 3.0;
// how high a turning triangle lifts off the sheet, in triangle sides
const float LIFT = 0.3;
const vec3 LIGHT = vec3(-0.4, 0.45, 0.8);

float easeInOut(float t) {
  return mix(t, t * t * (3.0 - 2.0 * t), 0.75);
}

// signed distance (positive inside) from p to an equilateral triangle centered on
// its centroid, with inradius r, pointing up (o = 1) or down (o = -1), measured on
// screen when the triangle is squeezed by k along b (turned about the axis a)
float triDistSqueezed(vec2 p, float r, float o, vec2 a, vec2 b, float k) {
  vec2 n0 = vec2(0.0, -o);
  vec2 n1 = vec2(0.5 * SQRT3, 0.5) * o;
  vec2 n2 = vec2(-0.5 * SQRT3, 0.5) * o;
  float d0 = (r - dot(p, n0)) * k / length(vec2(dot(n0, a) * k, dot(n0, b)));
  float d1 = (r - dot(p, n1)) * k / length(vec2(dot(n1, a) * k, dot(n1, b)));
  float d2 = (r - dot(p, n2)) * k / length(vec2(dot(n2, a) * k, dot(n2, b)));
  return min(d0, min(d1, d2));
}

float triDist(vec2 p, float r, float o) {
  return triDistSqueezed(p, r, o, vec2(1.0, 0.0), vec2(0.0, 1.0), 1.0);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

float aa(float d, float e) {
  return clamp(d / max(2.0 * e, 1e-6) + 0.5, 0.0, 1.0);
}

vec4 transition(vec2 uv) {
  vec2 frame = vec2(ratio, 1.0);
  vec2 pos = uv * frame;
  float h = 1.0 / max(float(rows), 1.0);
  float side = 2.0 * h / SQRT3;
  float inradius = side / (2.0 * SQRT3);
  vec2 e1 = vec2(side, 0.0);
  vec2 e2 = vec2(0.5 * side, h);
  // skewed lattice coordinates: each cell holds an upward and a downward triangle
  float lv = pos.y / h;
  vec2 cell = floor(vec2(pos.x / side - 0.5 * lv, lv));
  float eye = EYE * side;

  vec2 origin = center * frame;
  vec2 farthest = max(origin, frame - origin);
  float reach = max(length(farthest), 1e-4);
  float st = clamp(stagger, 0.0, 0.9);
  float sh = clamp(shading, 0.0, 1.0);
  vec3 l = normalize(LIGHT);
  vec3 hv = normalize(l + vec3(0.0, 0.0, 1.0));
  vec2 a0 = vec2(0.0, 1.0);
  vec2 a1 = vec2(0.5 * SQRT3, 0.5);
  vec2 a2 = vec2(-0.5 * SQRT3, 0.5);

  float wFrom = 0.0;
  float wTo = 0.0;
  float hole = 0.0;
  float shadow = 0.0;
  vec4 c1 = vec4(0.0);
  vec4 c2 = vec4(0.0);
  float m1 = 0.0;
  float m2 = 0.0;
  float z1 = -1e9;
  float z2 = -1e9;
  vec4 col;

  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      for (int k = 0; k < 2; k++) {
        vec2 nc = cell + vec2(float(i), float(j));
        float o = k == 0 ? 1.0 : -1.0;
        vec2 base = nc.x * e1 + nc.y * e2;
        vec2 ctr = base + (k == 0 ? 1.0 : 2.0) * (e1 + e2) / 3.0;
        vec2 q = pos - ctr;

        vec2 toward = ctr - origin;
        float dist = length(toward);
        vec2 dir = dist > 1e-5 ? toward / dist : vec2(1.0, 0.0);
        float delay = clamp(dist / reach, 0.0, 1.0);
        float t = clamp((progress - delay * st) / (1.0 - st), 0.0, 1.0);

        if (t <= 0.0 || t >= 1.0) {
          float m = aa(triDist(q, inradius, o), EDGE);
          if (t <= 0.0) wFrom += m;
          else wTo += m;
          continue;
        }

        // turn about the median of the triangle that lies most across the wave,
        // so the triangle rolls over away from the origin of the wave
        vec2 a = a0;
        if (abs(dot(a1, dir)) < abs(dot(a, dir))) a = a1;
        if (abs(dot(a2, dir)) < abs(dot(a, dir))) a = a2;
        vec2 b = vec2(-a.y, a.x);
        if (dot(b, dir) > 0.0) b = -b;

        float ang = PI * easeInOut(t);
        float ca = cos(ang);
        float sa = sin(ang);
        float lift = LIFT * side * sa;

        // the hole it leaves shows the incoming image in its shade, the outgoing one
        // right as it takes off so its edges stay seamless
        float mh = aa(triDist(q, inradius, o), EDGE);
        float k2 = smoothstep(0.0, 0.2, t);
        wFrom += mh * (1.0 - k2);
        wTo += mh * k2;
        hole = max(hole, mh * sa);
        vec2 sq = q + LIGHT.xy / LIGHT.z * lift;
        float sk = 0.3 + 0.7 * abs(ca);
        vec2 sp = dot(sq, a) * a + dot(sq, b) / sk * b;
        float sd = triDistSqueezed(sp, inradius, o, a, b, sk);
        float blur = 0.004 + 0.3 * lift;
        shadow = max(shadow, 0.5 * sa * (1.0 - smoothstep(-blur, blur, -sd)));

        // ray from the eye above the ctr through this point to the turned plane,
        // spanned by a and (b cos, sin) and lifted by lift
        float qb = dot(q, b);
        float den = eye * ca + sa * qb;
        if (abs(den) < 1e-6) continue;
        float s = (eye - lift) * ca / den;
        if (s <= 0.0) continue;
        float hz = eye * (1.0 - s);
        float alpha = s * dot(q, a);
        float beta = s * qb * ca + (hz - lift) * sa;
        vec2 lp = alpha * a + beta * b;
        float d = triDistSqueezed(lp, inradius, o, a, b, max(abs(ca), 1e-3)) / s;
        float m = aa(d, EDGE);
        if (m <= 0.0) continue;

        bool front = ca > 0.0;
        if (front) {
          col = getFromColor(mirror((ctr + lp) / frame));
        } else {
          col = getToColor(mirror((ctr + alpha * a - beta * b) / frame));
        }
        vec3 n = vec3(-sa * b, ca) * (front ? 1.0 : -1.0);
        float lit = dot(n, l) / l.z;
        col.rgb *= 1.0 - sh * (1.0 - clamp(lit, 0.0, 1.0)) * 0.65 + sh * 0.15 * max(lit - 1.0, 0.0);
        float spec = pow(max(dot(n, hv), 0.0), 60.0);
        col.rgb += sh * sa * (0.45 * spec + 0.15 * (1.0 - smoothstep(0.0, 3.0 * EDGE, d))) * col.a;

        if (hz > z1) {
          c2 = c1; m2 = m1; z2 = z1;
          c1 = col; m1 = m; z1 = hz;
        } else if (hz > z2) {
          c2 = col; m2 = m; z2 = hz;
        }
      }
    }
  }

  vec4 color = mix(getFromColor(uv), getToColor(uv), wTo / max(wFrom + wTo, 1e-6));
  color.rgb *= 1.0 - sh * clamp(max(shadow, 0.8 * hole), 0.0, 1.0);
  color = mix(color, c2, m2);
  color = mix(color, c1, m1);
  return color;
}

// Author: gre
// License: MIT
// Description: A grid of square tiles, each holding two quarter-circle arcs, links into long winding paths; starting from the middle and spreading outward, the paths are drawn as thin lines of the incoming image, then thicken into bands with a dark outline and a soft shadow until they merge over the whole frame
// Tags: truchet, pattern, tiles, paths, graphic, reveal

// @range(3, 20, 1) Number of tiles across the frame's height
uniform float cells; // = 8.0
// @range(0, 1) Strength of the dark outline and of the shadow along the bands
uniform float outline; // = 0.6
// @range(0, 1) How much the paths are staggered from the middle outward: 0 draws them all at once
uniform float spread; // = 0.75

const float AA = 0.0012;
const float LINE = 0.003;
const float SHADOW = 0.025;
// half width of the thin line a path is first drawn as, in tiles
const float STROKE = 0.08;

float hash12(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

float vnoise(vec2 v) {
  vec2 i = floor(v);
  vec2 f = fract(v);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
    mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

vec4 transition(vec2 uv) {
  float n = max(floor(cells + 0.5), 1.0);
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  vec2 g = p * n + 0.5;
  vec2 cell = floor(g);
  vec2 q = fract(g);
  // each tile is mirrored at random, so its two arcs (centered on opposite corners) link up with its neighbors' in two ways
  if (hash12(cell + 17.0) > 0.5) q.x = 1.0 - q.x;
  // distance to the nearest arc, in tiles: continuous across the tiles' edges, at most 0.5 (at the corners)
  float d = min(abs(length(q) - 0.5), abs(length(q - 1.0) - 0.5));

  float T = clamp(length(p) / (0.5 * length(vec2(ratio, 1.0))) + 0.4 * (vnoise(p * 3.0 + 4.0) - 0.5), 0.0, 1.0);
  float lag = 0.8 * clamp(spread, 0.0, 1.0);
  // every point is fully covered at progress 0.95
  float s = clamp((progress - lag * T) / (0.95 - lag), 0.0, 1.0);
  // in tiles: the paths are first drawn as thin lines, then the bands widen past the tiles' corners
  float aa = AA * n;
  float k = clamp((s - 0.25) / 0.75, 0.0, 1.0);
  float w = STROKE * smoothstep(0.0, 0.3, s) + (0.5 + LINE * n + 3.0 * aa - STROKE) * k * k;
  // signed distance to the edge of the bands (negative inside), in tiles
  float e = d - w;

  float band = 1.0 - smoothstep(-2.0 * aa, 0.0, e);
  float gap = max(e + aa, 0.0);
  float fall = 1.0 - smoothstep(0.0, SHADOW * n, gap);
  float edge = max(0.8 * (1.0 - smoothstep(LINE * n, LINE * n + 2.0 * aa, gap)), 0.4 * fall * fall);
  float shade = clamp(outline, 0.0, 1.0) * smoothstep(0.0, STROKE, w) * edge;

  vec4 a = getFromColor(uv);
  a.rgb *= 1.0 - shade;
  vec4 b = getToColor(uv);
  // mixed premultiplied, so transparent images do not bleed their color
  vec4 o = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), band);
  return o.a > 0.0 ? vec4(o.rgb / o.a, o.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image is thrown away like a rigid card, tumbling end over end with a slight spin as it flies off into the distance in perspective, its darker back showing on every flip and its soft shadow shrinking on the incoming image behind it
// Tags: 3d, rotate, flip, card, perspective

// @range(-4, 4) Number of turns end over end, negative to tumble the other way
uniform float flips; // = 2.0
// @range(-1, 1) Turns of the secondary spin around the line of sight
uniform float spin; // = 0.15
// @param Where the card flies toward on screen, in frame heights from the center
uniform vec2 direction; // = vec2(0.0, 0.3)
// @range(0.1, 1) Strength of the perspective
uniform float perspective; // = 0.6
// @range(0, 1) Shading of the card as it turns, darkness of its back and of its shadow
uniform float shading; // = 0.7

const float PI = 3.141592653589793;
const float EDGE = 0.0015;
// direction toward the light: above, to the right, in front
const vec3 LIGHT = vec3(0.348, 0.696, -0.628);

vec3 roll(vec3 v, float c, float s) {
  return vec3(c * v.x - s * v.y, s * v.x + c * v.y, v.z);
}

float cardDistance(vec2 q) {
  vec2 e = abs(q) - vec2(0.5 * ratio, 0.5);
  return max(e.x, e.y);
}

// casts the ray d from the eye onto the card's plane, rel being the card's center from the eye:
// (the point hit in the card's axes, the distance along d), or a negative distance when it misses
vec3 castOnCard(vec3 d, vec3 rel, vec3 U, vec3 V, vec3 N) {
  float dn = dot(d, N);
  if (abs(dn) < 1e-6) return vec3(0.0, 0.0, -1.0);
  float k = dot(rel, N) / dn;
  vec3 h = k * d - rel;
  return vec3(dot(h, U), dot(h, V), k);
}

vec2 cardUv(vec2 q) {
  return clamp(vec2(q.x / ratio, q.y) + 0.5, 0.0, 1.0);
}

vec4 transition(vec2 uv) {
  float t = clamp(progress / 0.95, 0.0, 1.0);
  float size = exp(-2.8 * t * t * (0.4 + 0.6 * t));
  float away = 1.0 - size;
  float turn = t * t * (3.0 - 2.0 * t);
  float a = 2.0 * PI * flips * turn;
  float r = 2.0 * PI * spin * turn;
  float cr = cos(r), sr = sin(r);
  // end over end around its horizontal axis, then around the line of sight
  vec3 U = roll(vec3(1.0, 0.0, 0.0), cr, sr);
  vec3 V = roll(vec3(0.0, cos(a), sin(a)), cr, sr);
  vec3 N = roll(vec3(0.0, -sin(a), cos(a)), cr, sr);

  // the camera, at dist in front of the plane z = 0, sees the frame at rest on it
  float dist = 1.0 / clamp(perspective, 0.1, 1.0);
  vec2 seen = direction * away + vec2(0.0, 0.12 * t * (1.0 - t));
  vec3 rel = vec3(seen / size, dist / size);
  float fade = 1.0 - smoothstep(0.8, 1.0, t);
  float shadowAmount = 0.6 * shading * sqrt(size) * fade;

  vec2 p = vec2((uv.x - 0.5) * ratio, uv.y - 0.5);
  vec4 color = getToColor(uv);

  if (shadowAmount > 0.0) {
    vec3 ds = vec3(p - vec2(-0.05, -0.08) * min(4.0 * t, 1.0) * size, dist);
    vec3 hs = castOnCard(ds, rel, U, V, N);
    if (hs.z > 0.0) {
      float blur = 0.005 + 0.06 * min(3.0 * t, 1.0) * size;
      float sd = cardDistance(hs.xy) * max(abs(dot(ds, N)) / length(ds), 0.05) / hs.z;
      float sh = (1.0 - smoothstep(-blur, blur, sd)) * getFromColor(cardUv(hs.xy)).a;
      color.rgb *= 1.0 - shadowAmount * sh;
    }
  }

  vec3 d = vec3(p, dist);
  vec3 hit = castOnCard(d, rel, U, V, N);
  if (hit.z <= 0.0) return color;
  float dn = dot(d, N);
  // anti-aliased edges: a screen pixel covers more of the card when it is far or seen at a grazing angle
  float grazing = max(abs(dn) / length(d), 0.05);
  float e = EDGE * min(20.0 * t, 1.0) * hit.z / grazing;
  float m = clamp(0.5 - cardDistance(hit.xy) / max(e, 1e-6), 0.0, 1.0) * fade;
  if (m <= 0.0) return color;

  vec4 card = getFromColor(cardUv(hit.xy));
  // the side facing the camera: the front, or the back which shows the image through, darker and duller
  bool front = dn > 0.0;
  vec3 facing = front ? -N : N;
  float lit = min((0.35 + 0.65 * max(dot(facing, LIGHT), 0.0)) / (0.35 + 0.65 * -LIGHT.z), 1.0);
  float shade = mix(1.0, lit * (front ? 1.0 : 0.55), shading);
  if (!front) card.rgb = mix(card.rgb, vec3(dot(card.rgb, vec3(0.299, 0.587, 0.114))), 0.4 * shading);
  float glint = pow(max(dot(facing, normalize(LIGHT - normalize(d))), 0.0), 60.0);
  card.rgb = card.rgb * shade + 0.35 * shading * glint * smoothstep(0.0, 0.2, t);
  if (m >= 1.0) return card;
  // blend premultiplied, so that a transparent layer gives no color to the other one
  vec4 mixed = mix(vec4(color.rgb * color.a, color.a), vec4(card.rgb * card.a, card.a), m);
  return mixed.a > 0.0 ? vec4(mixed.rgb / mixed.a, mixed.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The camera flies down a tunnel lined with the outgoing image toward the incoming one, which opens at its far end and grows to fill the frame
// Tags: zoom, 3d, warp, radial

// @range(0.5, 10) How far and fast the camera flies down the tunnel
uniform float speed; // = 6.0
// @range(-2, 2) How much the walls spiral as they rush by
uniform float twist; // = 0.5

vec2 rotate(vec2 v, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(c * v.x - s * v.y, s * v.x + c * v.y);
}

vec4 transition(vec2 uv) {
  vec2 aspect = vec2(ratio, 1.0);
  vec2 c = (uv - 0.5) * aspect;
  float r = length(c);
  // A tube as wide as the frame's corners runs from the camera to an end wall
  // at depth `far`; the outgoing image is projected onto it from the starting
  // point of view, so it looks flat at first. The camera flies to one unit
  // before the end wall, where the incoming image hangs.
  float R = length(0.5 * aspect);
  float far = 1.0 + speed;
  // the distance to the end wall shrinks geometrically, so the end grows evenly
  float e = mix(progress, progress * progress * (3.0 - 2.0 * progress), 0.7);
  float d = pow(far, 1.0 - e);
  float t = far - d; // distance flown
  float k = r * d < R ? d / far : R / (R + t * r); // image scale at that point
  float a = twist * min(t * r / R, t / d); // spiral, continuous at the end wall
  vec4 walls = getFromColor(0.5 + rotate(c * k, a) / aspect);
  walls.rgb *= 0.4 + 0.6 * sqrt(k); // darker where the walls are close
  float open = smoothstep(0.0, 0.6, progress);
  vec2 q = 0.5 + (uv - 0.5) * d / max(open, 1e-4);
  vec2 inside = step(0.0, q) * step(q, vec2(1.0));
  return mix(walls, getToColor(q), inside.x * inside.y * step(r * d, R));
}

// Author: mernking (gitlab.com/Godswork)
// License: MIT
// Description: A crossfade with drifting tracking lines and tearing, like a TV losing its signal
// Tags: retro, glitch, scanlines

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec4 transition(vec2 uv) {

    float p = progress;
    float strength = sin(p * 3.14159265);

    vec2 tv = uv;

    vec4 fromColor = getFromColor(tv);
    vec4 toColor   = getToColor(tv);

    vec4 color = mix(fromColor, toColor, p);

    float lineY = floor(tv.y * 120.0);

    float noise = hash(vec2(lineY, p * 20.0));

    float line = step(0.92, noise);

    float drift =
        sin(tv.y * 30.0 + p * 10.0)
        * 0.02
        * strength;

    vec4 shiftedFrom = getFromColor(tv + vec2(drift, 0.0));
    vec4 shiftedTo   = getToColor(tv + vec2(drift, 0.0));

    vec4 lineColor = mix(shiftedFrom, shiftedTo, p);

    color = mix(color, lineColor, line * strength);

    float scan =
        sin(tv.y * 900.0) * 0.03;

    color.rgb -= scan * strength;

    return color;
}

// Author: gre
// License: MIT
// Description: The outgoing image rolls faster and faster, like an old TV losing its vertical hold, then the roll slows down and locks on the incoming image
// Tags: retro, vertical, scanlines

// @range(1, 8) Number of frames that roll by
uniform int rolls; // = 3
// @range(0, 0.5) Height of the bar between the frames
uniform float barHeight; // = 0.12
// @color Color of the bar between the frames
uniform vec4 barColor; // = vec4(0.0, 0.0, 0.0, 1.0)

// The rolling picture at a vertical position y, in frames of height 1 + barHeight
vec4 picture(vec2 uv, float y, float m) {
  float period = 1.0 + barHeight;
  y = mod(y, period);
  if (y > 1.0) return barColor;
  vec2 q = vec2(uv.x, y);
  return mix(getFromColor(q), getToColor(q), m);
}

vec4 transition(vec2 uv) {
  float period = 1.0 + barHeight;
  // smooth start and stop: the picture locks again after a whole number of frames
  float s = progress * progress * (3.0 - 2.0 * progress);
  float offset = period * fract(float(rolls) * s);
  float speed = 4.0 * progress * (1.0 - progress); // 0 at both ends, 1 in the middle
  float m = smoothstep(0.42, 0.58, progress); // the channel changes at full speed
  vec2 p = uv + vec2(0.004 * speed * sin(uv.y * 9.0 + progress * 30.0), 0.0);
  vec4 c = vec4(0.0);
  for (int i = 0; i < 5; i++) {
    c += picture(p, p.y + offset - 0.0015 * float(rolls) * speed * float(i), m);
  }
  c /= 5.0;
  float scan = 0.5 + 0.5 * sin(uv.y * 400.0);
  float flicker = 0.08 * (0.5 + 0.5 * sin(progress * 97.0));
  c.rgb *= 1.0 - speed * (0.08 * scan + flicker);
  return c;
}

// Author: Brandon Anzaldi
// License: MIT
// Description: Cuts to full-screen TV static, then to the incoming image
// Tags: static, noise, retro
// @param Part of the transition, at each end, that shows the images instead of static
uniform float offset; // = 0.05

// http://byteblacksmith.com/improvements-to-the-canonical-one-liner-glsl-rand-for-opengl-es-2-0/
highp float noise(vec2 co)
{
    highp float a = 12.9898;
    highp float b = 78.233;
    highp float c = 43758.5453;
    highp float dt= dot(co.xy * progress, vec2(a, b));
    highp float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

vec4 transition(vec2 p) {
  if (progress < offset) {
    return getFromColor(p);
  } else if (progress > (1.0 - offset)) {
    return getToColor(p);
  } else {
    return vec4(vec3(noise(p)), max(getFromColor(p).a, getToColor(p).a)); // static where the images are
  }
}

// Author: gre
// License: MIT
// Description: The outgoing image collapses into a glowing line and a dot, like an old TV turned off, then the incoming image powers on from the dot
// Tags: retro, vertical, flash
// Preview: 0.1

// @color Color of the switched-off screen
uniform vec4 color; // = vec4(0.0, 0.0, 0.0, 1.0)
// @range(0, 2) Strength of the glow around the line and the dot
uniform float glow; // = 1.0

vec4 getColor(vec2 uv, bool isFrom) {
  return isFrom ? getFromColor(uv) : getToColor(uv);
}

// The screen at a time t of its power-off: 0 is the full image, 1 is off
vec4 screen(vec2 uv, float t, bool isFrom) {
  float collapse = smoothstep(0.0, 0.4, t); // the image squeezes into a line
  float shrink = smoothstep(0.3, 0.65, t); // the line shrinks into a dot
  float fade = 0.4 * smoothstep(0.75, 1.0, t); // the dot dims
  float radius = 0.01 * (1.0 - fade);
  // half size of the picture, in height units (x is scaled by ratio)
  vec2 size = vec2(mix(0.5 * ratio, radius, shrink), mix(0.5, radius, collapse));
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  vec2 q = clamp(0.5 + 0.5 * p / size, 0.0, 1.0);
  vec4 c = getColor(q, isFrom);
  float white = smoothstep(0.4, 1.0, collapse);
  vec4 light = vec4(mix(min(c.rgb * (1.0 + 2.0 * collapse), 1.0), vec3(1.0), white), c.a);
  // soft edges, outside the picture so that t = 0 is the exact image
  vec2 d = abs(p) - size;
  float dist = length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
  float inside = clamp(1.0 - dist / 0.004, 0.0, 1.0);
  vec4 mid = getColor(vec2(0.5), isFrom);
  vec4 halo = vec4(mix(mix(mid.rgb, vec3(1.0), 0.7), vec3(1.0, 0.92, 0.8), shrink), mid.a);
  float h = 1.0 - exp(-2.0 * glow * white * exp(-max(dist, 0.0) / (0.02 + 0.04 * shrink)));
  vec4 col = mix(color, halo, h * (1.0 - fade));
  return mix(col, light, inside * (1.0 - fade));
}

vec4 transition(vec2 uv) {
  if (progress < 0.5) {
    return screen(uv, 2.0 * progress, true);
  }
  return screen(uv, 2.0 - 2.0 * progress, false);
}

// Author: gre
// License: MIT
// Description: The grains of the outgoing image join in pairs, and the pairs in pairs, each time growing into a bigger dragon-shaped patch of flat color with the same ragged outline at every size, until a few huge interlocked dragons fill the frame; they are repainted along their own curl and split back down into the incoming image
// Tags: fractal, dragon, blocks, flat-color, math
// Preview: 0.5

// @range(40, 200) Grains along the height of the frame
uniform float cells; // = 120.0
// @range(0, 1) How vivid the flat colors are
uniform float vividness; // = 0.6

vec4 vivid(vec4 c, float k) {
  float g = dot(c.rgb, vec3(0.333));
  return vec4(clamp(g + (c.rgb - g) * (1.0 + vividness * k), 0.0, 1.0), c.a);
}

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

vec4 dragon(vec2 uv) {
  vec2 a = vec2(ratio, 1.0);
  vec2 z = floor((uv - 0.5) * a * cells);
  float u = min(progress, 1.0 - progress);
  // the digits of z in base 1 + i, whose powers are in pw
  vec2 pw = vec2(1.0, 0.0);
  vec2 mid = vec2(0.5);
  vec2 q = uv;
  float low = 0.0;
  float size = 1.0;
  for (int l = 0; l < 11; l++) {
    float d = mod(z.x + z.y, 2.0);
    z = vec2(z.x - d + z.y, z.y - z.x + d) * 0.5;
    low += d * size;
    size *= 2.0;
    mid += 0.5 * pw;
    pw = vec2(pw.x - pw.y, pw.x + pw.y);
    vec2 base = vec2(z.x * pw.x - z.y * pw.y, z.x * pw.y + z.y * pw.x);
    if (u > 0.014 + 0.034 * float(l) + (0.03 + 0.006 * float(l)) * low / size) q = fold((base + mid) / cells / a + 0.5);
  }
  bool late = progress > 0.44 + 0.12 * (low + 0.5) / size;
  vec4 c = vivid(late ? getToColor(q) : getFromColor(q), smoothstep(0.0, 0.35, u));
  return vec4(c.rgb * c.a, c.a);
}

vec4 transition(vec2 uv) {
  vec2 e = 0.0011 / vec2(ratio, 1.0) * smoothstep(0.0, 0.1, min(progress, 1.0 - progress));
  vec4 s = dragon(uv + e * vec2(0.5, 1.0)) + dragon(uv + e * vec2(-1.0, 0.5)) + dragon(uv - e * vec2(0.5, 1.0)) + dragon(uv - e * vec2(-1.0, 0.5));
  return vec4(s.rgb / max(s.a, 1e-5), 0.25 * s.a);
}

// Author: gre
// License: MIT
// Description: Seen from above, an umbrella made of the incoming picture pops open over the outgoing one: a furled star of pleats spins as its ribs spread and stretch the fabric into taut shaded panels with a scalloped hem and a soft shadow, then the canopy rises toward the camera and flattens out to fill the frame
// Tags: umbrella, open, 3d, object, playful

// @range(5, 12) Number of ribs
uniform int ribs; // = 8
// @range(0, 1) Strength of the shading of the fabric and of the shadow
uniform float shading; // = 0.7
// @range(0, 3) Turns in radians while it opens
uniform float spin; // = 1.6
// @color Ferrule and tips of the ribs
uniform vec4 metal; // = vec4(0.8, 0.78, 0.74, 1.0)

const float PI = 3.141592653589793;

vec2 rot(vec2 v, float a) {
  float c = cos(a), s = sin(a);
  return vec2(c * v.x - s * v.y, s * v.x + c * v.y);
}

// point in the frame of its panel: xy along the panel's bisector and across it, z the panel's angle
vec3 panelAt(vec2 q, float n) {
  float th = abs(q.x) + abs(q.y) < 1e-5 ? 0.0 : atan(q.y, q.x);
  float a = floor(th * n / (2.0 * PI) + 0.5) * 2.0 * PI / n;
  return vec3(rot(q, -a), a);
}

// -1 to 1 across a panel, rib to rib: a ratio, exact on the ribs whatever the precision of atan
float across(vec2 l, float n) {
  return clamp(l.y / (max(l.x, 1e-4) * tan(PI / n)), -1.0, 1.0);
}

// distance inside the hem: taut it is the chord between two rib tips, slack it dips toward the center
float hemGap(vec2 l, float u, float R, float sag, float n) {
  float chord = R * cos(PI / n);
  float tilt = 2.0 * chord * sag * u / max(l.x * tan(PI / n), 0.3 * chord * tan(PI / n) + 1e-4);
  return (chord * (1.0 - sag * (1.0 - u * u)) - l.x) / sqrt(1.0 + tilt * tilt);
}

vec4 transition(vec2 uv) {
  vec2 asp = vec2(ratio, 1.0);
  vec2 q = (uv - 0.5) * asp;
  float n = max(float(ribs), 5.0);

  float o = clamp(progress / 0.46, 0.0, 1.0);
  o *= sqrt(o);
  // eases past the open radius and settles back
  float pop = 1.0 + (o - 1.0) * (o - 1.0) * (2.4 * (o - 1.0) + 1.4);
  float v = clamp((progress - 0.34) / 0.66, 0.0, 1.0);
  float rise = v * v * (3.0 - 2.0 * v);
  float g = smoothstep(0.3, 1.0, v);
  float dome = 1.0 - g;
  float size = min(ratio, 1.0);
  float k = 0.42 * size;
  float rEnd = 0.54 * length(asp) / cos(PI / n);
  float R = mix(k * pop, rEnd, rise * rise);
  float sag = mix(mix(0.75, 0.09, smoothstep(0.15, 0.9, pop)), 0.0, g);
  float turn = spin * ((1.0 - o) * (1.0 - o) - 0.12 * v * sin(2.0 * PI * v) * dome);

  vec2 qc = rot(q, turn);
  vec3 panel = panelAt(qc, n);
  vec2 l = panel.xy;
  float u = across(l, n);
  float X = R * cos(PI / n) * (1.0 - sag * (1.0 - u * u));
  float e = hemGap(l, u, R, sag, n);
  // under a pixel of fabric there is no canopy yet
  float cov = smoothstep(-0.002, 0.002, e) * smoothstep(0.0, 0.01, R);

  float height = (0.4 + rise) * dome;
  vec3 sp = panelAt(rot(q - vec2(0.04, -0.06) * height * size, turn), n);
  float se = hemGap(sp.xy, across(sp.xy, n), R, sag, n);
  float soft = (0.015 + 0.05 * height) * size;
  float shadow = 0.55 * shading * dome * smoothstep(0.0, 0.15 * size, R) * smoothstep(-soft, soft, se);

  float rho = clamp(l.x / max(X, 1e-3), 0.0, 1.0);
  float bulge = 1.0 - 0.16 * (1.0 - rho * rho);
  // soft max with 1: the picture never grows past its final size
  float over = 1.1 * k / max(R, 1e-3) - 1.0;
  over = 0.5 * (over + sqrt(over * over + 0.01));
  vec2 tuv = 0.5 + qc * mix((1.0 + over) * bulge, 1.0, g) / asp;
  tuv = 1.0 - abs(1.0 - mod(tuv, 2.0));
  vec4 fabric = getToColor(tuv);

  float w = smoothstep(0.0, 0.05 * size, R) * dome;
  float crease = cos(17.0 * u) * (1.0 - rho) * (1.0 - rho) * 0.3 + cos(9.0 * u) * rho * rho * 0.06;
  vec2 grad = w * vec2(-0.15 - 0.75 * rho * rho, (0.35 + 1.6 * sag) * u * (0.3 + 0.7 * rho) + crease);
  vec3 nrm = normalize(vec3(-rot(grad, panel.z - turn), 1.0));
  vec3 L = normalize(vec3(-0.45, 0.6, 0.75));
  float lit = mix(1.0, max(dot(nrm, L), 0.0) / L.z, 0.8 * shading);
  vec3 H = normalize(L + vec3(0.0, 0.0, 1.0));
  float sheen = pow(max(dot(nrm, H), 0.0), 40.0) - pow(H.z, 40.0);
  float px = l.x * sin(PI / n);
  float rib = (1.0 - abs(u)) * px;
  float seam = (1.0 - smoothstep(0.001, 0.004, rib)) * smoothstep(0.0, 0.03, px);
  float ridge = (1.0 - smoothstep(0.004, 0.02, rib)) * smoothstep(0.002, 0.006, rib) * smoothstep(0.0, 0.06, px);
  float stitch = 1.0 - smoothstep(0.001, 0.0025, abs(e - 0.012));
  vec3 col = fabric.rgb * lit * (1.0 - shading * w * (0.45 * seam + 0.18 * stitch));
  // the rib under the fabric pushes up a soft ridge, and light shows through the thin hem
  col += shading * w * (0.18 * max(sheen, 0.0) + 0.07 * ridge + 0.07 * (1.0 - smoothstep(0.0, 0.012, e)));

  vec4 from = getFromColor(uv);
  vec4 c = vec4(from.rgb * from.a * (1.0 - shadow), from.a);

  vec2 tip = l - R * vec2(cos(PI / n), (l.y < 0.0 ? -1.0 : 1.0) * sin(PI / n));
  float tipR = 0.009 * size * w;
  float ball = (1.0 - smoothstep(tipR - 0.002, tipR, length(tip))) * smoothstep(0.2, 0.6, w);
  float shine = 0.7 + 0.5 * max(dot(rot(tip, panel.z - turn) / max(tipR, 1e-3), L.xy), 0.0);
  c = mix(c, vec4(metal.rgb * shine, 1.0), ball * metal.a);

  c = mix(c, vec4(col * fabric.a, fabric.a), cov);

  float r = length(q) / (0.022 * size * w + 1e-4);
  float cone = 0.75 + 0.45 * dot(q / max(length(q), 1e-4), L.xy) * min(r, 1.0) + 0.35 * (1.0 - smoothstep(0.25, 0.4, r));
  float cap = (1.0 - smoothstep(0.88, 1.0, r)) * smoothstep(0.0, 0.2, w);
  c = mix(c, vec4(metal.rgb * cone, 1.0), cap * metal.a * cov);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The incoming image is tossed in folded up as an open card box, its middle the floor and its borders the walls, lands with a small bounce after its shadow, then its walls fall open flat one pair after the other, each with a bounce, until the unfolded sheet covers the frame
// Tags: 3d, box, unfold, paper, shadow

// @range(0.1, 0.35) Height of the walls, as a part of the frame's shorter side: the borders of the incoming image that fold up
uniform float depth; // = 0.22
// @range(0, 1) Strength of the perspective
uniform float perspective; // = 0.6
// @range(0, 1) How much the faces darken away from the light, and the shadows they cast
uniform float shading; // = 0.6
// @color Color of the back of the card
uniform vec4 paper; // = vec4(0.93, 0.91, 0.86, 1.0)

const float PI = 3.141592653589793;
const float EDGE = 0.0016;
const float YAW0 = 0.45;
const vec3 LIGHT = vec3(-0.35045, 0.45058, 0.82107);

float wallAngle(float u) {
  float k = u / 0.72;
  return u < 0.72 ? 0.5 * PI * (1.0 - k * k) : 0.12 * sin(PI * (u - 0.72) / 0.28);
}

// sides of quad i: bottom and top walls (1, 2), left and right walls (3, 4), corner tabs (5 to 8)
vec2 sideSign(int i) {
  if (i == 0) return vec2(-1.0);
  if (i == 1) return vec2(0.0, -1.0);
  if (i == 2) return vec2(0.0, 1.0);
  if (i == 3) return vec2(-1.0, 0.0);
  if (i == 4) return vec2(1.0, 0.0);
  return vec2(i == 5 || i == 7 ? -1.0 : 1.0, i < 7 ? -1.0 : 1.0);
}

// hinge corner of quad i on the flat sheet, and the image direction of its two edges (u, v)
vec2 quadOrigin(int i, float W, float c) {
  vec2 sg = sideSign(i);
  return vec2(sg.x > 0.0 ? W - c : c, sg.y > 0.0 ? 1.0 - c : c);
}

vec4 quadAxes(int i) {
  vec2 sg = sideSign(i);
  if (i == 0 || i == 1 || i == 2) return vec4(1.0, 0.0, 0.0, i == 0 ? 1.0 : sg.y);
  if (i == 3 || i == 4) return vec4(0.0, 1.0, sg.x, 0.0);
  return vec4(sg.x, 0.0, 0.0, sg.y);
}

vec2 quadSize(int i, float W, float c) {
  if (i == 0) return vec2(W - 2.0 * c, 1.0 - 2.0 * c);
  if (i == 1 || i == 2) return vec2(W - 2.0 * c, c);
  if (i == 3 || i == 4) return vec2(1.0 - 2.0 * c, c);
  return vec2(c);
}

// edges that are free cuts (s = 0, s = len.x, t = 0, t = len.y), the others are hinges or folds
vec4 quadCut(int i) {
  if (i == 0) return vec4(0.0);
  if (i == 1 || i == 2) return vec4(0.0, 0.0, 0.0, 1.0);
  if (i == 3 || i == 4) return vec4(1.0, 1.0, 0.0, 1.0);
  return vec4(0.0, 1.0, 1.0, 1.0);
}

// edge directions U, V of quad i in box space (columns 0, 1), and its origin (column 2);
// wt holds cos and sin of the bottom/top and side wall angles, tt those of the tabs
mat3 quadFrame(int i, float W, float c, vec4 wt, vec2 tt) {
  vec2 sg = sideSign(i);
  vec3 O = vec3(quadOrigin(i, W, c), 0.0);
  vec3 U = vec3(1.0, 0.0, 0.0), V = vec3(0.0, 1.0, 0.0);
  if (i == 1 || i == 2) {
    V = vec3(0.0, sg.y * wt.x, wt.y);
  } else if (i == 3 || i == 4) {
    U = vec3(0.0, 1.0, 0.0);
    V = vec3(sg.x * wt.z, 0.0, wt.w);
  } else if (i >= 5) {
    // the tabs hang on the bottom and top walls and fold against the outside of the side walls
    V = vec3(0.0, sg.y * wt.x, wt.y);
    U = vec3(sg.x * tt.x, 0.0, 0.0) + tt.y * vec3(0.0, -sg.y * wt.y, wt.x);
  }
  return mat3(U, V, O);
}

vec3 rotate(vec3 v, vec2 rot) {
  return vec3(v.x * rot.x - v.y * rot.y, v.x * rot.y + v.y * rot.x, v.z);
}

// color of quad i at the hit (s, t, coverage, ray dot normal)
vec4 shadeFace(int i, vec4 hit, float W, float c, vec4 wt, vec2 tt, vec2 rot, float amount) {
  if (i < 0) return vec4(0.0);
  mat3 F = quadFrame(i, W, c, wt, tt);
  vec4 ax = quadAxes(i);
  vec2 len = quadSize(i, W, c);
  vec2 st = hit.xy;
  bool front = hit.w * (ax.x * ax.w - ax.y * ax.z) < 0.0;
  vec3 n = rotate(cross(F[0], F[1]), rot) * (front ? 1.0 : -1.0) * (ax.x * ax.w - ax.y * ax.z);
  vec4 col = getToColor(clamp((quadOrigin(i, W, c) + st.x * ax.xy + st.y * ax.zw) / vec2(W, 1.0), 0.0, 1.0));
  float lit = min((0.45 + 0.55 * max(dot(n, LIGHT), 0.0)) / (0.45 + 0.55 * LIGHT.z), 1.0);
  float up = i == 0 ? 0.0 : clamp(F[1].z, 0.0, 1.0);
  if (front) {
    // the image side of a raised wall faces into the box: darker toward the crease with the floor
    lit *= 1.0 - up * (0.35 + 0.4 * (1.0 - st.y / len.y));
    if (i == 0) {
      vec4 ao = exp(-vec4(st.x, len.x - st.x, st.y, len.y - st.y) / (0.25 * c)) * wt.wwyy;
      lit *= 1.0 - 0.45 * max(max(ao.x, ao.y), max(ao.z, ao.w));
    }
    col.rgb = mix(col.rgb, paper.rgb * 0.8, 0.25 * up);
  } else {
    col = vec4(paper.rgb, paper.a * col.a);
  }
  // a lit band along the free top edge of a raised wall reads as the card's thickness
  float rim = up * quadCut(i).w * (1.0 - smoothstep(0.006, 0.014, len.y - st.y));
  col.rgb = mix(col.rgb * mix(1.0, lit, shading * amount), paper.rgb * 1.05, rim * amount);
  return col;
}

vec4 transition(vec2 uv) {
  float W = ratio;
  float c = clamp(depth, 0.1, 0.35) * min(W, 1.0);
  float D = 1.0 / (0.25 + 0.75 * clamp(perspective, 0.0, 1.0));
  float f = clamp(progress / 0.36, 0.0, 1.0);
  float fe = 1.0 - (1.0 - f) * (1.0 - f);
  float h = 0.22 * (1.0 - f * f) + 0.03 * sin(PI * clamp((progress - 0.36) / 0.09, 0.0, 1.0));
  // starts just clear of the frame with its initial yaw, whatever the ratio
  float y0 = 0.52 + 0.5 * W * sin(YAW0) + 0.5 * cos(YAW0);
  vec3 off = vec3(0.0, y0 * (1.0 - fe), h);
  float yaw = YAW0 * (1.0 - fe) * (1.0 - fe);
  vec2 rot = vec2(cos(yaw), sin(yaw));
  float tb = wallAngle(clamp((progress - 0.42) / 0.34, 0.0, 1.0));
  float ts = wallAngle(clamp((progress - 0.6) / 0.4, 0.0, 1.0));
  vec4 wt = vec4(cos(tb), sin(tb), cos(ts), sin(ts));
  vec2 tt = vec2(cos(0.97 * tb), sin(0.97 * tb));
  float amount = clamp(10.0 * (tb + ts + h), 0.0, 1.0);
  float aa = EDGE * amount + 1e-4;
  vec3 C = vec3(0.5 * W, 0.5, 0.0);
  vec3 E = vec3(0.5 * W, 0.5, D);
  vec3 dir = vec3(uv.x * W, uv.y, 0.0) - E;

  // the two nearest faces along the ray, the front one is composited over the back one
  float t1 = 1e4, t2 = 1e4;
  vec4 h1 = vec4(0.0), h2 = vec4(0.0);
  int i1 = -1, i2 = -1;
  for (int i = 0; i < 9; i++) {
    mat3 F = quadFrame(i, W, c, wt, tt);
    vec3 U = rotate(F[0], rot), V = rotate(F[1], rot);
    vec3 n = cross(U, V);
    float den = dot(dir, n);
    if (abs(den) < 1e-6) continue;
    vec3 O = C + rotate(F[2] - C, rot) + off;
    float t = dot(O - E, n) / den;
    if (t <= 0.0 || t >= t2) continue;
    vec3 q = E + t * dir - O;
    vec2 st = vec2(dot(q, U), dot(q, V));
    vec2 len = quadSize(i, W, c);
    vec4 d = vec4(st.x, len.x - st.x, st.y, len.y - st.y);
    vec4 fr = quadCut(i);
    // hinges overlap slightly and cut edges antialias outward, so flat seams never crack
    d = mix(d + 1e-4, d, fr);
    if (min(min(d.x, d.y), min(d.z, d.w)) <= -aa) continue;
    vec4 e = mix(vec4(1.0), clamp(d / aa + 1.0, 0.0, 1.0), fr);
    vec4 hit = vec4(st, e.x * e.y * e.z * e.w, den);
    if (t < t1) { t2 = t1; h2 = h1; i2 = i1; t1 = t; h1 = hit; i1 = i; }
    else { t2 = t; h2 = hit; i2 = i; }
  }

  vec4 c1 = shadeFace(i1, h1, W, c, wt, tt, rot, amount);
  vec4 c2 = shadeFace(i2, h2, W, c, wt, tt, rot, amount);
  vec3 P1 = E + t1 * dir, P2 = E + t2 * dir;

  vec4 ground = getFromColor(uv);
  vec3 G = E + dir;
  float shG = 0.0, sh1 = 0.0, sh2 = 0.0;
  for (int i = 0; i < 9; i++) {
    mat3 F = quadFrame(i, W, c, wt, tt);
    vec3 U = rotate(F[0], rot), V = rotate(F[1], rot);
    vec3 O = C + rotate(F[2] - C, rot) + off;
    vec2 len = quadSize(i, W, c);
    vec3 n = cross(U, V);
    float den = dot(LIGHT, n);
    if (abs(den) < 1e-6) continue;
    for (int k = 0; k < 3; k++) {
      if ((k == 1 && i1 < 0) || (k == 2 && i2 < 0)) continue;
      vec3 P = k == 0 ? G : (k == 1 ? P1 : P2);
      float s = dot(O - P, n) / den;
      if (s < 2e-3) continue;
      vec3 q = P + s * LIGHT - O;
      vec2 st = vec2(dot(q, U), dot(q, V));
      float soft = 0.004 + 0.12 * s;
      float inside = min(min(st.x, len.x - st.x), min(st.y, len.y - st.y));
      float a = smoothstep(-soft, soft, inside) / (1.0 + 1.5 * s);
      if (k == 0) shG = max(shG, a); else if (k == 1) sh1 = max(sh1, a); else sh2 = max(sh2, a);
    }
  }
  float sk = 0.9 * shading * amount * min(8.0 * progress, 1.0);
  ground.rgb *= 1.0 - sk * shG;
  c1.rgb *= 1.0 - sk * sh1;
  c2.rgb *= 1.0 - sk * sh2;
  return mix(mix(ground, c2, h2.z), c1, h1.z);
}

// Author: gre
// License: MIT
// Description: The incoming picture turns up tiny inside the outgoing one, wearing its colors so that no edge shows; it hops closer, crouches, hops again and leaps into the whole frame, then drops the disguise as its true colors spread from the middle
// Tags: playful, hop, blend, color, zoom, reveal

// @param Size of the incoming picture when it first shows up
// @range(0.2, 0.6)
uniform float size; // = 0.34
// @param Height of its hops
// @range(0, 1)
uniform float bounce; // = 0.5

const int TAPS = 14;
const vec2 STEP = vec2(0.9009689, 0.4338837);

vec4 pm(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec2 inside(vec2 q) {
  return 1.0 - abs(1.0 - mod(q / vec2(ratio, 1.0) + 0.5, 2.0));
}

float hop(float a, float b) {
  float t = clamp((progress - a) / (b - a), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

vec4 transition(vec2 uv) {
  vec2 asp = vec2(ratio, 1.0);
  float m = min(ratio, 1.0);
  float h1 = hop(0.14, 0.23), h2 = hop(0.31, 0.4), h3 = hop(0.48, 0.64);
  float s = size * exp2(-log2(size) * (0.12 * h1 + 0.24 * h2 + 0.64 * h3));
  vec2 c = vec2(0.25, -0.08) * asp;
  c = mix(c, vec2(-0.23, -0.1) * asp, h1);
  c = mix(c, vec2(0.12, -0.04) * asp, h2) * (1.0 - h3);
  // it crouches before each hop
  float down = hop(0.1, 0.13) * (1.0 - hop(0.13, 0.15)) + hop(0.26, 0.29) * (1.0 - hop(0.29, 0.32)) + 1.5 * hop(0.42, 0.46) * (1.0 - hop(0.46, 0.5));
  c.y += bounce * m * (0.6 * h1 * (1.0 - h1) + 0.7 * h2 * (1.0 - h2) + 0.35 * h3 * (1.0 - h3) - 0.06 * s * down);
  float grow = hop(0.52, 0.68);
  float r = s * (0.48 * m * hop(0.0, 0.09) + (0.53 * length(asp) - 0.48 * m) * grow);
  vec2 d = (uv - 0.5) * asp - c;
  vec4 a = getFromColor(uv);
  vec2 w = d / max(r, 1e-4);
  float rho = length(w);
  if (rho >= 1.0) return a;
  a = pm(a);
  vec2 k = vec2(1.0, 1.0 / (1.0 - 0.16 * down)) / s;
  // Poisson kernel over fixed rim points: each picture's rim spread harmonically, without dither
  vec4 F = vec4(0.0), T = vec4(0.0);
  float total = 0.0, sq = 0.0;
  vec2 z = vec2(1.0, 0.0);
  for (int i = 0; i < TAPS; i++) {
    vec2 g = z - w;
    float q = 1.0 / (dot(g, g) + 0.02);
    vec4 t = pm(getToColor(inside(r * z * k)));
    F += q * pm(getFromColor(inside(c + r * z)));
    T += q * t;
    sq += q * dot(t, t);
    total += q;
    z = vec2(z.x * STEP.x - z.y * STEP.y, z.x * STEP.y + z.y * STEP.x);
  }
  F /= total;
  T /= total;
  vec4 b = pm(getToColor(inside(d * k)));
  float spread = max(sq / total - dot(T, T), 0.0);
  // what looks like the rim of the incoming picture is its background: the outgoing picture shows there
  vec4 e = b - T;
  float subject = smoothstep(0.3, 1.1, dot(e, e) / (0.012 + 0.7 * spread));
  subject = mix(subject, 1.0, smoothstep(0.04, 0.11, spread));
  subject = mix(subject, 1.0, smoothstep(0.15, 0.9, grow)) * (1.0 - smoothstep(mix(0.8, 0.95, grow), 1.0, rho));
  float worn = smoothstep(0.0, 0.7, rho + 0.7 - 1.7 * hop(0.6, 1.0)) * (1.0 - hop(0.75, 1.0));
  vec4 col = clamp(mix(a, b + (F - T) * worn, subject), 0.0, 1.0);
  return col.a > 0.0 ? vec4(min(col.rgb / col.a, 1.0), col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: Waves run along the contours of the outgoing image as if every tone were swaying on its own beat; the contours bend to the shapes of the incoming image, which takes over crest by crest as the waves calm down
// Tags: wave, distortion, liquid, tones
// Preview: 0.5

// @range(0, 0.3) How wide the tones sway, in frame heights
uniform float swing; // = 0.1
// @range(5, 40) How many waves lie between black and white
uniform float waves; // = 18.0

const int TAPS = 12;

vec2 fold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

// a quadratic B-spline over a coarse lattice: smooth tones for 9 reads an image
float tone(vec2 uv, bool incoming) {
  vec2 n = 6.0 * vec2(ratio, 1.0) / min(ratio, 1.0);
  vec2 p = uv * n;
  vec2 c = floor(p) + 0.5;
  float s = 0.0;
  for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
      vec2 o = c + vec2(float(i), float(j));
      vec2 a = abs(p - o);
      vec2 w = mix(0.75 - a * a, 0.5 * (1.5 - a) * (1.5 - a), step(0.5, a));
      vec2 q = fold(o / n);
      vec4 t = incoming ? getToColor(q) : getFromColor(q);
      s += dot(t.rgb, vec3(0.299, 0.587, 0.114)) * t.a * w.x * w.y;
    }
  return s;
}

vec4 transition(vec2 uv) {
  vec2 asp = vec2(ratio, 1.0);
  float f = mix(tone(uv, false), tone(uv, true), smoothstep(0.1, 0.9, progress));
  // the slope across the frame keeps a plain sky from swaying and switching as one piece
  float ph = waves * f - 20.0 * progress + dot((uv - 0.5) * asp, vec2(4.0, 2.5));
  float amp = swing * smoothstep(0.0, 0.5, progress) * (1.0 - smoothstep(0.5, 1.0, progress));
  vec2 q = uv + amp * vec2(cos(ph), sin(ph)) / asp;
  float level = 2.2 * smoothstep(0.0, 1.0, progress) - 1.1 + 0.55 * cos(ph);
  vec4 sum = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    float n = (float(i) + 0.5) / float(TAPS);
    float an = 2.399963 * float(i);
    vec2 r = fold(q + 0.04 * amp * sqrt(n) * vec2(cos(an), sin(an)) / asp);
    vec4 c = level + 0.03 * (n - 0.5) < 0.0 ? getFromColor(r) : getToColor(r);
    sum += vec4(c.rgb * c.a, c.a);
  }
  return vec4(sum.rgb / max(sum.a, 1e-5), sum.a / float(TAPS));
}

// License: MIT
// Author: pthrasher
// Description: A circle with a wavy edge burns out from the center to reveal the incoming image
// Tags: circle, burn, wipe
// adapted by gre from https://gist.github.com/pthrasher/8e6226b215548ba12734

// @param Softness of the edge
uniform float smoothness; // = 0.03
// @param Center of the circle
uniform vec2 center; // = vec2(0.5)
// @color Color of the burning edge
uniform vec4 color; // = vec4(0.0, 0.0, 0.0, 1.0)

const float M_PI = 3.14159265358979323846;

float quadraticInOut(float t) {
  float p = 2.0 * t * t;
  return t < 0.5 ? p : -p + (4.0 * t) - 1.0;
}

float getGradient(float r, float dist) {
  float d = r - dist;
  return mix(
    smoothstep(-smoothness, 0.0, r - dist * (1.0 + smoothness)),
    -1.0 - step(0.005, d),
    step(-0.005, d) * step(d, 0.01)
  );
}

float getWave(vec2 p){
  vec2 _p = p - center;
  float rads = atan(_p.y, _p.x);
  float degs = degrees(rads) + 180.0;
  vec2 range = vec2(0.0, M_PI * 30.0);
  vec2 domain = vec2(0.0, 360.0);
  float ratio = (M_PI * 30.0) / 360.0;
  degs = degs * ratio;
  float x = progress;
  float magnitude = mix(0.02, 0.09, smoothstep(0.0, 1.0, x));
  float offset = mix(40.0, 30.0, smoothstep(0.0, 1.0, x));
  float ease_degs = quadraticInOut(sin(degs));
  float deg_wave_pos = (ease_degs * magnitude) * sin(x * offset);
  // The soft edge reaches `smoothness` beyond the radius and the burn band 0.005 inside it:
  // start the radius below both so nothing but the outgoing image shows at progress 0
  // (unchanged from progress 0.1 on).
  return x - max(smoothness, 0.01) * (1.0 - smoothstep(0.0, 0.1, x)) + deg_wave_pos;
}

vec4 transition(vec2 p) {
  float dist = distance(center, p);
  float m = getGradient(getWave(p), dist);
  vec4 cfrom = getFromColor(p);
  vec4 cto = getToColor(p);
  return mix(mix(cfrom, cto, m), mix(cfrom, color, 0.75), step(m, -2.0));
}

// Author: gre
// License: MIT
// Description: The outgoing image is a stack of horizontal bands with the incoming image stacked on top of it, out of frame: bands are yanked out sideways one at a time in a shuffled order, and each time everything above drops into the gap with a small bounce, so the incoming image comes down into the frame in beats
// Tags: stack, bands, gravity, bounce, rhythm

// @range(2, 12, 1) Number of bands in the outgoing image
uniform int bands; // = 6
// @range(0, 1) Height of the bounce after each drop
uniform float bounce; // = 0.5
// @color Color of the slot left empty by a pulled band
uniform vec4 slot; // = vec4(0.1, 0.095, 0.09, 1.0)

const float PULL = 0.11;
const float FALL = 0.1;
// the stack starts to fall once the pulled band has nearly cleared its slot
const float LAG = 0.85;
const float IMPACT = 0.62;
// past 1 so the smeared tail has left the frame too
const float REACH = 1.3;
const float EDGE = 0.0015;
const int TAPS = 16;

float hash(float n) {
  vec2 p = fract(vec2(n) * vec2(0.1031, 0.1030));
  p += dot(p, p.yx + 33.33);
  return fract((p.x + p.y) * p.x);
}

float count() {
  return clamp(float(bands), 2.0, 12.0);
}

float rank(float i, float n) {
  float r = 0.0, hi = hash(i + 7.0);
  for (int j = 0; j < 12; j++) {
    if (float(j) >= n) break;
    float h = hash(float(j) + 7.0);
    if (h < hi || (h == hi && float(j) < i)) r += 1.0;
  }
  return r;
}

float startTime(float r, float n) {
  return 0.02 + r * (0.96 - LAG * PULL - FALL) / (n - 1.0);
}

float pullPhase(float t0) {
  return clamp((progress - t0) / PULL, 0.0, 1.0);
}

float pullOffset(float u, float r) {
  return (mod(r, 2.0) < 0.5 ? 1.0 : -1.0) * REACH * u * u;
}

float hump(float s) {
  return 4.0 * s * (1.0 - s);
}

float dropOf(float t0) {
  float t = clamp((progress - t0 - LAG * PULL) / FALL, 0.0, 1.0);
  if (t < IMPACT) return (t / IMPACT) * (t / IMPACT);
  // two rebounds, the second a third as high and shorter
  float s = (t - IMPACT) / (1.0 - IMPACT);
  float h = s < 0.6 ? hump(s / 0.6) : 0.3 * hump((s - 0.6) / 0.4);
  return 1.0 - 0.2 * clamp(bounce, 0.0, 1.0) * h;
}

float box(float v, float a, float b, float soft) {
  return smoothstep(a - soft, a + soft, v) * (1.0 - smoothstep(b - soft, b + soft, v));
}

vec4 transition(vec2 uv) {
  float n = count(), H = 1.0 / n;
  vec4 c = vec4(0.0);
  float covered = 0.0;
  float above = 1.0, below = 1.0;
  vec4 front = vec4(0.0);
  float frontA = 0.0, shadow = 1.0;
  float D = 0.0, floorY = 0.0;
  for (int k = 0; k < 24; k++) {
    float j = float(k);
    if (j >= 2.0 * n) break;
    float b = (j - D) * H;
    float y = uv.y - b;
    float u = 0.0, r = 0.0, t0 = 0.0;
    if (j < n) {
      r = rank(j, n);
      t0 = startTime(r, n);
      u = pullPhase(t0);
    }
    if (u > 0.0) {
      float x = pullOffset(u, r);
      float lift = smoothstep(0.0, 0.35, u);
      float off = 0.22 * H * lift;
      float grow = 1.0 + 0.08 * lift;
      shadow *= 1.0 - 0.55 * lift * box(uv.x - x - sign(x) * off * 0.4, 0.0, 1.0, off)
        * box(uv.y + off - b - 0.5 * H, -0.5 * H * grow, 0.5 * H * grow, off);
      // a lifted band is closer to the eye, so it looks a bit taller
      float ly = (y - 0.5 * H) / grow + 0.5 * H;
      float ya = clamp(min(ly, H - ly) / (EDGE * lift + 1e-5) + 0.5, 0.0, 1.0);
      // smear over the distance travelled in about half a frame
      float v = sign(x) * max(min(0.012 * 2.0 * REACH * u / PULL, 0.1), EDGE);
      float s0 = uv.x - x;
      float lo = min(s0, s0 + v), hi = max(s0, s0 + v);
      float a = ya * max(min(hi, 1.0) - max(lo, 0.0), 0.0) / abs(v);
      if (a > 0.0) {
        ly = clamp(ly, 0.0, H);
        vec4 sum = vec4(0.0);
        for (int m = 0; m < TAPS; m++) {
          vec4 t = getFromColor(vec2(mix(max(lo, 0.0), min(hi, 1.0), (float(m) + 0.5) / float(TAPS)), j * H + ly));
          sum += vec4(t.rgb * t.a, t.a);
        }
        vec4 band = vec4(sum.rgb / max(sum.a, 1e-6), sum.a / float(TAPS));
        band.rgb *= 1.0 - 0.3 * lift * (1.0 - smoothstep(0.0, 0.2 * H, min(ly, H - ly)));
        front = mix(front, band, frontA > 0.0 ? a : 1.0);
        frontA = a + frontA * (1.0 - a);
      }
    } else {
      // only edges facing an open gap are softened, and only inside it, so closed seams stay exact
      float e = max(min(EDGE, 0.5 * (b - floorY)), 0.0) + 1e-6;
      float m = clamp(y / e + 1.0, 0.0, 1.0) * step(y, H);
      if (m > 0.0) {
        vec4 img = j < n
          ? getFromColor(vec2(uv.x, j * H + max(y, 0.0)))
          : getToColor(vec2(uv.x, (j - n) * H + max(y, 0.0)));
        c = mix(c, img, covered > 0.0 ? m : 1.0);
        covered = max(covered, m);
      }
      if (y < 0.0) above = min(above, -y);
      if (y > H) below = min(below, y - H);
      floorY = b + H;
    }
    if (j < n) D += dropOf(t0);
  }
  vec4 gap = slot;
  gap.rgb *= (1.0 - 0.65 * exp(-above / (0.2 * H))) * (1.0 - 0.35 * exp(-below / (0.1 * H)));
  c = mix(gap, c, covered);
  c.rgb *= shadow;
  return mix(c, front, frontA);
}

// Author: gre
// License: MIT
// Description: The outgoing picture is a liquid that whirls stir one after another, stretching it into curls, ribbons and fine marbled filaments; the filaments take the colors of the incoming picture and the stirring undoes itself, curl by curl, until the incoming picture is whole
// Tags: liquid, marbling, swirl, paint, distort

// @range(0, 12) How far each whirl turns the liquid, in radians
uniform float stir; // = 7.0
// @range(0.15, 0.45) Radius of the whirls, as a part of the frame's short side in a square frame
uniform float size; // = 0.28

const int TAPS = 12;
const int WHIRLS = 6;

vec2 mirrorUv(vec2 u) {
  return 1.0 - abs(1.0 - mod(u, 2.0));
}

vec4 pm(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

float dye(vec2 x) {
  return 0.5 + 0.25 * sin(9.0 * x.x + 2.0 * sin(5.0 * x.y)) + 0.25 * sin(8.0 * x.y - 2.0 * sin(6.0 * x.x));
}

vec4 transition(vec2 uv) {
  vec2 s = vec2(ratio, 1.0) / min(ratio, 1.0);
  float r2 = size * size * max(s.x, s.y);
  float th = 1.12 - 1.24 * smoothstep(0.32, 0.68, progress);
  float env = smoothstep(0.0, 0.2, progress) * (1.0 - smoothstep(0.85, 1.0, progress));
  vec2 pos[TAPS];
  for (int i = 0; i < TAPS; i++) {
    float fi = float(i);
    pos[i] = (uv - 0.5) * s + vec2(fract(fi * 0.618 + 0.3) - 0.5, (fi + 0.5) / float(TAPS) - 0.5) * 0.0035 * env;
  }

  // where the liquid came from: the whirls undone, last one first
  for (int j = 0; j < WHIRLS; j++) {
    float k = float(WHIRLS - 1 - j);
    // they peak one after another, so that some still wind while others unwind
    float peak = 0.37 + 0.05 * k;
    float t = smoothstep(0.02 * k, peak, progress) * (1.0 - smoothstep(peak, 0.9 + 0.02 * k, progress));
    float g0 = stir * t * (mod(k, 2.0) * 2.0 - 1.0);
    float a = 2.4 * k + 0.6;
    vec2 c = 0.34 * s * vec2(cos(a), sin(a));
    for (int i = 0; i < TAPS; i++) {
      vec2 d = pos[i] - c;
      float g = g0 * exp(-dot(d, d) / r2);
      float cg = cos(g) - 1.0, sg = sin(g);
      pos[i] += vec2(cg * d.x - sg * d.y, sg * d.x + cg * d.y);
    }
  }

  vec4 sum = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    vec2 u = mirrorUv(pos[i] / s + 0.5);
    sum += mix(pm(getFromColor(u)), pm(getToColor(u)), smoothstep(-0.1, 0.1, dye(pos[i]) - th));
  }
  return sum.a > 0.0 ? vec4(sum.rgb / sum.a, sum.a / float(TAPS)) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image goes up in smoke: from one side, the picture itself turns to vapour that rises over what is still intact, curls into wisps and pales as it thins out, revealing the incoming image underneath
// Tags: smoke, organic, noise, directional, reveal

// @param Direction the vapour rises toward (the image starts turning to vapour on the opposite side)
uniform vec2 direction; // = vec2(0.0, 1.0)
// @range(0.1, 0.6) How high the vapour rises above the image before it is gone, in frame heights
uniform float rise; // = 0.4
// @range(0, 1) How much the vapour swirls and curls as it rises
uniform float swirl; // = 0.6
// @color Color the vapour pales to as it thins out
uniform vec4 color; // = vec4(0.92, 0.92, 0.94, 1.0)

// raggedness of the line where the image turns to vapour, and the width over which it dissolves
const float RAGGED = 0.09;
const float BAND = 0.12;
const float LIFE = 0.16;
const int TAPS = 6;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
    mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 p) {
  return 0.55 * vnoise(p) + 0.3 * vnoise(p * 2.03 + 5.1) + 0.15 * vnoise(p * 4.1 + 9.7);
}

// a swirling flow without sources or sinks: the curl of a noise field
vec2 curl(vec2 p) {
  float e = 0.1;
  float n = vnoise(p);
  float nx = vnoise(p + vec2(e, 0.0));
  float ny = vnoise(p + vec2(0.0, e));
  return vec2(ny - n, n - nx) / e;
}

// where the line is at time t, as a part of its way across: quicker through the margins
// outside the frame, slower across it
float sweep(float t) {
  return t + 0.6 * t * (1.0 - t) * (1.0 - 2.0 * t);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(0.0, 1.0);
  vec2 side = vec2(-dir.y, dir.x);
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  float along = dot(q, dir);
  float across = dot(q, side);
  float ext = 0.5 * (abs(dir.x) * ratio + abs(dir.y));

  float ragged = RAGGED * (2.0 * fbm(q * 2.5 + 1.3) - 1.0);
  float start = -ext - RAGGED;
  float travel = 2.0 * ext + 2.0 * RAGGED + BAND;
  float front = start + travel * sweep(progress) + ragged;

  float gone = smoothstep(0.0, BAND, front - along);
  vec4 base = mix(getFromColor(uv), getToColor(uv), gone);

  // the vapour above the line: the higher it is, the longer ago it left the image
  float height = max(rise, 0.05) * (0.7 + 0.6 * vnoise(vec2(across * 3.0 + 2.7, 0.5)));
  float age = (along - front) / height;
  float released = progress - age * LIFE;
  if (age <= 0.0 || age >= 1.0 || released <= 0.0) return base;

  // where it came from: the line, back when it was released
  float origin = start + travel * sweep(released) + ragged;
  vec2 org = q - dir * (along - origin);

  vec2 sw = curl(org * 3.0 + dir * progress * 1.5) * (swirl * 0.08 * sqrt(age));
  vec2 src = org - sw;

  vec2 spreadOut = (side * 0.07 + dir * 0.02) * sqrt(age);
  vec4 c = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    float t = float(i) / float(TAPS - 1) - 0.5;
    vec4 img = getFromColor(mirror((src + spreadOut * t) / vec2(ratio, 1.0) + 0.5));
    c += vec4(img.rgb * img.a, img.a);
  }
  c = c.a > 0.0 ? vec4(c.rgb / c.a, c.a / float(TAPS)) : vec4(0.0);

  vec2 wq = (q - 0.6 * sw - dir * (progress * 2.5)) * 4.0;
  float w = fbm(vec2(dot(wq, side), dot(wq, dir) * 0.6) + 2.0);
  float density = smoothstep(1.2 * age - 0.2, 1.2 * age + 0.1, w);
  density *= 1.0 - smoothstep(0.3, 1.0, age);
  // (only the image turns to vapour, not what lies beyond its edge)
  density *= smoothstep(-ext, -ext + 0.05, origin);

  float pale = smoothstep(0.0, 0.5, age);
  float l = dot(c.rgb, vec3(0.299, 0.587, 0.114));
  c = mix(c, vec4(mix(vec3(l), color.rgb, 0.7), c.a * color.a), pale * 0.85);
  c.rgb = min(c.rgb + 0.12 * pale * density * (1.0 - density), vec3(1.0));
  float a = density * c.a;
  float outA = a + base.a * (1.0 - a);
  if (outA <= 0.0) return vec4(0.0);
  return vec4((c.rgb * a + base.rgb * base.a * (1.0 - a)) / outA, outA);
}

