// Author: gre
// License: MIT
// Description: Tape-tracking bands of white snow roll down the frame, tearing the lines around them, with smeared color, wobbling lines, a jittering strip at the bottom and a dropout flash, as the incoming image is recorded over the outgoing one under the densest band
// Tags: retro, glitch, noise, tape, scanlines

// @range(1, 4, 1) Number of noise bands rolling down (the first one carries the cut)
uniform int bands; // = 3
// @range(0, 1) Amount of snow and tearing in the bands
uniform float noise; // = 0.6
// @range(0, 1) How far the color smears to the right of the picture
uniform float bleed; // = 0.5
// @range(0, 1) How much the lines wobble sideways
uniform float wobble; // = 0.5

const float LINES = 220.0; // tape lines over the frame height
const float FRAMES = 40.0; // the noise changes this many times over the transition
const float BAND = 0.11;
const float STRIP = 0.06;
const int TAPS = 6;

float hash12(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// the tape image on the outgoing (or, once re-recorded, incoming) side, premultiplied
vec4 tape(vec2 p, bool fresh) {
  p = mirror(p);
  vec4 c = fresh ? getToColor(p) : getFromColor(p);
  return vec4(c.rgb * c.a, c.a);
}

float luma(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

// how dense a band centered at y = c of half height w is on line y, with ragged edges
float bandDensity(float y, float c, float w, float jitter) {
  float d = abs(y - c) / w + 0.35 * jitter;
  return 1.0 - smoothstep(0.0, 1.0, d);
}

vec4 transition(vec2 uv) {
  // the effects build up quickly and settle at the end: exactly 0 at both ends
  float h = clamp(2.5 * (1.0 - abs(2.0 * progress - 1.0)), 0.0, 1.0);
  float env = h * h * (3.0 - 2.0 * h);
  float f = clamp(1.0 - abs(progress - 0.5) / 0.04, 0.0, 1.0);
  float flash = f * f * (3.0 - 2.0 * f);

  float frame = floor(progress * FRAMES);
  float line = floor(uv.y * LINES);
  float jitter = hash12(vec2(line, frame + 7.0)) - 0.5;

  // the main band rolls from above the frame to below it; the incoming image is above it
  float c0 = mix(1.0 + 1.2 * BAND, -1.2 * BAND, progress);
  bool fresh = uv.y > c0 + 0.8 * BAND * jitter;
  float dens = bandDensity(uv.y, c0, BAND, jitter);
  float tear = 1.0 - smoothstep(0.0, 1.0, abs(uv.y - c0) / (2.5 * BAND));
  for (int i = 1; i < 4; i++) {
    if (i < bands) {
      float k = float(i);
      float w = BAND * (0.35 + 0.2 * hash12(vec2(k, 3.0)));
      float speed = 1.3 + 0.9 * k;
      float cy = -w + (1.0 + 2.0 * w) * fract(hash12(vec2(k, 5.0)) - speed * progress);
      dens = max(dens, 0.6 * bandDensity(uv.y, cy, w, jitter));
      tear = max(tear, 0.5 * (1.0 - smoothstep(0.0, 1.0, abs(uv.y - cy) / (2.5 * w))));
    }
  }
  dens *= env;
  tear *= env;

  float rowTear = hash12(vec2(floor(uv.y * LINES * 0.5), frame + 31.0)) - 0.5;
  float dx = wobble * env * (0.006 * sin(uv.y * 7.0 + progress * 23.0) + 0.004 * jitter);
  dx += (0.3 + 0.7 * noise) * tear * 0.18 * rowTear;
  float strip = env * (1.0 - smoothstep(0.0, STRIP, uv.y));
  dx += strip * (0.03 + 0.06 * (1.0 - uv.y / STRIP)) * (0.6 + 0.8 * hash12(vec2(frame, 41.0)));
  vec2 q = vec2(uv.x + dx, uv.y);

  vec4 c = tape(q, fresh);
  if (c.a <= 0.0) return vec4(0.0);
  float len = bleed * (0.02 + 0.05 * dens) * env;
  vec4 avg = c;
  if (len > 0.0) {
    avg = vec4(0.0);
    for (int i = 0; i < TAPS; i++) {
      float u = (float(i) + 0.5) / float(TAPS);
      avg += tape(q - vec2(len * (0.4 + u), 0.0), fresh);
    }
    avg /= float(TAPS);
  }
  vec3 chroma = (avg.rgb - luma(avg.rgb)) / max(avg.a, 1e-5);
  vec3 rgb = luma(c.rgb) + chroma * c.a; // premultiplied by c.a
  rgb = mix(rgb, vec3(luma(rgb)), 0.6 * dens);

  // snow: short white streaks on the tape lines, starting at a random offset on each line so they never line up
  vec2 cell = vec2(floor(uv.x * LINES * 0.3 * ratio + 40.0 * jitter), line);
  float n = hash12(cell + frame * vec2(37.0, 17.0));
  float amount = clamp(noise * max(1.3 * dens, 0.8 * strip) + 0.35 * flash, 0.0, 1.0);
  float snow = amount > 0.0 ? smoothstep(1.0 - amount, 1.0 - 0.6 * amount, n) : 0.0;
  snow *= 0.55 + 0.45 * hash12(cell.yx + frame);
  float g = hash12(vec2(floor(uv.x * LINES * ratio), line) + frame * vec2(13.0, 29.0));
  snow = max(snow, amount > 0.0 ? 0.7 * smoothstep(1.0 - 0.4 * amount, 1.0, g) : 0.0);
  float dark = g < 0.1 * amount ? min(10.0 * amount, 1.0) : 0.0;
  float group = floor(uv.y * LINES / 3.0);
  float drop = step(1.0 - 0.15 * flash, hash12(vec2(group, floor(uv.x * 6.0 + 5.0 * hash12(vec2(group, frame))) + frame * 7.0)));
  rgb *= 1.0 - 0.5 * dark;
  snow *= min(10.0 * amount, 1.0);
  rgb += (clamp(snow + drop + 0.12 * flash, 0.0, 1.0)) * (c.a - rgb);

  return vec4(clamp(rgb / c.a, 0.0, 1.0), c.a);
}

// Author: gre
// License: MIT
// Description: The incoming image is pushed into the outgoing one like air into oil squeezed between two glass plates: a bubble grows into a few rounded fingers that keep splitting in two at their tips, shoving the old picture aside into thin glossy threads, until the fingers swell and close the last gaps
// Tags: liquid, branching, organic, radial, physical

// @param Where the incoming image is pushed in
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(3, 8, 1) Number of fingers leaving the first bubble
uniform int fingers; // = 5

const float TAU = 6.2831853;
const float AA = 0.0025;
const float R0 = 0.07;
const vec3 LIGHT = vec3(-0.4511, 0.5514, 0.7018);
const vec3 HALFWAY = vec3(-0.2445, 0.2989, 0.9224);

float vfHash(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float vfCap(float r, float lim, float w) {
  float x = clamp((lim - r) / max(w, 1e-4), 0.0, 1.0);
  return sqrt(x * (2.0 - x));
}

vec2 vfMirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// s = 2^(l + 1), passed exactly: exp2 is approximate on some targets
float vfSplit(float c, float l, float s) {
  return R0 * s * (0.8 + 0.4 * vfHash(c + 97.0 * l + 11.7));
}

// a finger of level l in cell c of n, at offset a (in cells) from the cell's middle
float vfFinger(float l, float n, float c, float a, float r, float n0, float Rt, float fill) {
  float g = 1.0;
  float ck = c;
  float lk = l;
  // a finger reaches no further than its ancestors, so no branch floats free
  for (int k = 0; k < 5; k++) {
    if (lk < 0.0) break;
    g = min(g, 0.68 + 0.32 * vfHash(ck + 97.0 * lk + 3.1));
    ck = floor(ck * 0.5);
    lk -= 1.0;
  }
  float split = vfSplit(c, l, 2.0 * n / n0);
  float rs = l < 0.5 ? 0.0 : vfSplit(floor(c * 0.5), l - 1.0, n / n0) * (1.0 - 0.3 * TAU * 2.0 / n);
  float cell = TAU * r / n;
  // children leave from their parent's middle at its full width, then settle into their own cell
  float fork = l < 0.5 ? 1.0 : smoothstep(rs, rs + 0.6 * (split - rs), r);
  float ac = (mod(c, 2.0) < 0.5 ? 0.5 : -0.5) * (1.0 - fork);
  float tip = Rt * mix(g, 1.0, fill);
  float w = mix(mix(0.2, 0.3, smoothstep(0.0, 0.3, tip - r)), 0.56, fill) * (2.0 - fork) * cell + 3.0 * AA * fill;
  float end = l < 3.5 ? min(tip, split + w) : tip;
  return max(abs(a - ac) * cell - w * vfCap(r, end, w), max(r - end, rs - r));
}

// distance-like field to the air, negative inside the fingers
float vfField(vec2 q, float Rt, float fill) {
  float r = length(q);
  float th = atan(q.y, dot(q, q) > 0.0 ? q.x : 1.0) / TAU + 0.5;
  th += (0.012 * sin(r * 11.0 + TAU * th * 3.0) + 0.007 * sin(r * 23.0 - TAU * th * 7.0)) / (0.3 + r);

  float n0 = float(fingers);
  float dist = r - min(Rt, R0);
  float n = n0;
  for (int l = 0; l < 5; l++) {
    float fl = float(l);
    float x = th * n;
    float c = floor(x);
    float a = x - c - 0.5;
    float side = a < 0.0 ? -1.0 : 1.0;
    // the neighbour on the near side too, so the field stays continuous across cell borders
    dist = min(dist, vfFinger(fl, n, mod(c, n), a, r, n0, Rt, fill));
    dist = min(dist, vfFinger(fl, n, mod(c + side, n), a - side, r, n0, Rt, fill));
    n *= 2.0;
  }
  return dist;
}

vec4 transition(vec2 uv) {
  vec2 asp = vec2(ratio, 1.0);
  vec2 q = (uv - center) * asp;
  vec2 dir = q / max(length(q), 1e-4);
  float rmax = length(max(center, 1.0 - center) * asp);

  float t = progress;
  float Rt = t * (rmax + 0.1) / 0.55;
  float fill = clamp((t - 0.45) / 0.55, 0.0, 1.0);
  float grow = smoothstep(0.0, 0.08, Rt) * (1.0 - fill * fill);

  const vec2 EPS = vec2(0.002, 0.0);
  float d = vfField(q, Rt, fill);
  vec2 grad = vec2(vfField(q + EPS, Rt, fill) - d, vfField(q + EPS.yx, Rt, fill) - d) / EPS.x;
  vec2 gdir = grad / max(length(grad), 1e-4);

  float slope = 0.4 * exp(-max(d, 0.0) / 0.01) * grow;
  vec3 nrm = normalize(vec3(-slope * gdir, 1.0));
  float diffuse = max(1.0 + 0.9 * (dot(nrm, LIGHT) - LIGHT.z), 0.0);
  float spec = max(pow(max(dot(nrm, HALFWAY), 0.0), 40.0) - pow(HALFWAY.z, 40.0), 0.0);

  // pushed radially, not away from the nearest finger, which would tear the oil along its mid-lines
  vec2 suv = uv - dir * 0.03 * exp(-max(d, 0.0) / 0.05) * grow / asp;
  vec4 oil = getFromColor(vfMirror(suv));
  oil.rgb = oil.rgb * diffuse + 0.4 * spec * oil.a;

  vec4 air = getToColor(uv);
  air.rgb *= 1.0 - 0.35 * grow * exp(min(d, 0.0) / 0.006);

  return mix(air, oil, smoothstep(-2.0 * AA, 0.0, d));
}

// Author: gre
// License: MIT
// Description: The outgoing image breaks into hundreds of small squares that a tornado carries away along a spiral around the center, from the eye outward, uncovering the incoming image
// Tags: tiles, spiral, rotation, shatter

// @range(4, 40, 1) Number of rows of squares
uniform int grid; // = 24
// Center of the tornado
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(-4, 4) Turns each square makes around the center as it flies away (negative turns clockwise)
uniform float spin; // = 1.0
// @range(0, 1) How randomly the squares leave: 0 from the center outward, 1 in any order
uniform float randomness; // = 0.2

// the squares leave in GROUPS waves, each one flying for DURATION of the transition
const int GROUPS = 24;
const float DURATION = 0.25;
const float AA = 0.0015;
const float TAU = 6.2831853;

float hash(vec2 n) {
  return fract(sin(dot(n, vec2(12.9898, 78.233))) * 43758.5453);
}

int groupOf(vec2 n, float h, vec2 c, float maxR) {
  float r = min(length((n + 0.5) * h - c) / (0.85 * maxR), 1.0);
  float key = clamp(mix(r * sqrt(r), hash(n), clamp(randomness, 0.0, 1.0)), 0.0, 0.9999);
  return int(floor(key * float(GROUPS)));
}

// local time of a wave's flight, 0 before it leaves, 1 once it has vanished
float flight(int g) {
  float delay = float(g) / float(GROUPS) * (1.0 - DURATION);
  return clamp((progress - delay) / DURATION, 0.0, 1.0);
}

vec4 premultiplied(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 transition(vec2 uv) {
  vec2 aspect = vec2(ratio, 1.0);
  vec2 p = uv * aspect;
  vec2 c = center * aspect;
  float maxR = max(max(length(c), length(c - vec2(ratio, 0.0))), max(length(c - vec2(0.0, 1.0)), length(c - aspect)));
  float h = 1.0 / float(grid < 1 ? 1 : grid);
  float reach = 0.7 * maxR;

  vec2 n0 = floor(p / h);
  // (it shows once the square above it has started to move away, so their edges never let it through at rest)
  float k = smoothstep(0.0, 0.05, flight(groupOf(n0, h, c, maxR)));
  vec4 col = k <= 0.0 ? premultiplied(getFromColor(uv)) : k >= 1.0 ? premultiplied(getToColor(uv)) : mix(premultiplied(getFromColor(uv)), premultiplied(getToColor(uv)), k);

  // the flying squares, painted from the last wave to leave (lowest) to the first (highest)
  for (int k = 0; k < GROUPS; k++) {
    int g = GROUPS - 1 - k;
    float s = flight(g);
    if (s <= 0.0 || s >= 1.0) continue;
    float e = s * s;
    // like in a tornado, the squares near the eye (the first to leave) spin much faster than
    // the outer ones; all of them orbit before they are flung out
    float angle = spin * TAU * e * 2.0 / (1.0 + 6.0 * float(g) / float(GROUPS));
    float push = reach * e * s;
    float size = (1.0 + 0.35 * sin(3.1415927 * s)) * (1.0 - s * s * s);
    float ca = cos(angle);
    float sa = sin(angle);
    mat2 rot = mat2(ca, sa, -sa, ca);
    // undo the wave's spiral to guess which square lands here, then test its neighbors exactly
    vec2 u = (p - c) * rot;
    float ru = length(u);
    vec2 guess = c + (ru > 0.0 ? u / ru : vec2(0.0)) * max(ru - push, 0.0);
    vec2 ng = floor(guess / h);
    for (int j = -1; j <= 1; j++) {
      for (int i = -1; i <= 1; i++) {
        vec2 n = ng + vec2(float(i), float(j));
        if (groupOf(n, h, c, maxR) != g) continue;
        vec2 home = (n + 0.5) * h;
        vec2 rel = home - c;
        float rr = length(rel);
        vec2 dir = rr > 0.0 ? rel / rr : vec2(0.0);
        vec2 pos = c + rot * (dir * (rr + push));
        float tumble = angle + (hash(n + 17.0) - 0.5) * 3.0 * e * sign(spin);
        float ct = cos(tumble);
        float st = sin(tumble);
        vec2 d = ((p - pos) * mat2(ct, st, -st, ct)) / max(size, 1e-4);
        float edge = 0.5 * h - max(abs(d.x), abs(d.y));
        float cov = clamp(edge * size / (2.0 * AA) + 0.5, 0.0, 1.0);
        vec2 src = home + d;
        if (cov <= 0.0 || src.x < 0.0 || src.y < 0.0 || src.x > ratio || src.y > 1.0) continue;
        vec4 piece = premultiplied(getFromColor(src / aspect)) * cov;
        col = piece + col * (1.0 - piece.a);
      }
    }
  }
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The camera jumps to light speed: star streaks shoot out from the center and stretch longer and longer while the outgoing image is pulled into a radial smear, then after a flash the incoming image emerges from the center as the streaks shrink back
// Tags: zoom, radial, light, motion-blur, space

// @param Point the camera flies toward, from (0, 0) at the bottom left to (1, 1) at the top right
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(20, 400) Number of star streaks around the center
uniform float streaks; // = 160.0
// @color Color of the streaks and of the flash, added as light
uniform vec4 streakColor; // = vec4(0.78, 0.88, 1.0, 1.0)
// @range(0, 1) Length of the streaks and of the radial smear
uniform float strength; // = 0.6
// @range(0, 1) Brightness of the flash at the peak of the jump
uniform float flash; // = 0.5

const float PI = 3.141592653589793;
const int TAPS = 12;

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// one layer of stars: one per angular cell, flying outward and stretched along its ray
float stars(float a, float r, float n, float layer, float travel, float speed, float reach) {
  float cell = floor(a * n);
  float h1 = hash(vec2(cell, layer));
  float h2 = hash(vec2(cell, layer + 17.0));
  float h3 = hash(vec2(cell, layer + 31.0));
  float life = fract(h1 + travel * (0.6 + 0.8 * h2));
  float head = reach * (0.05 + 1.05 * pow(life, 1.4));
  float tail = head * (1.0 - min(0.9, speed * (0.15 + 0.5 * h3)));
  float along = clamp((r - tail) / max(head - tail, 1e-4), 0.0, 1.0);
  float inside = step(tail, r) * (1.0 - smoothstep(head - 0.006, head, r));
  float profile = inside * along * along;
  // thin across the ray, a bit wider away from the center, with a faint halo,
  // faded out before the edges of the cell so that no seam shows between cells
  float f = fract(a * n);
  float cellWidth = 2.0 * PI * r / n;
  float offset = 0.3 + 0.4 * h3;
  float across = (f - offset) * cellWidth;
  float width = min(0.0014 + 0.002 * r / reach, 0.15 * cellWidth);
  float x = across * across / (width * width);
  float line = (exp(-x) + 0.25 * exp(-x / 9.0)) * smoothstep(0.0, 0.2, min(f, 1.0 - f));
  float fade = smoothstep(0.0, 0.2, life) * (1.0 - smoothstep(0.9, 1.0, life));
  return profile * line * fade * (0.4 + 0.6 * h2) * step(0.25, hash(vec2(cell, layer + 43.0)));
}

// an image pulled into a radial smear toward the center: scaled by k, blurred over a fraction b
vec4 smear(vec2 uv, float k, float b, float jitter, bool incoming) {
  if (b <= 0.0 && k >= 1.0) {
    vec4 c = incoming ? getToColor(uv) : getFromColor(uv);
    return vec4(c.rgb * c.a, c.a);
  }
  vec4 sum = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    float s = k * (1.0 - b * (float(i) + jitter) / float(TAPS));
    vec2 q = center + (uv - center) * s;
    vec4 c = incoming ? getToColor(q) : getFromColor(q);
    sum += vec4(c.rgb * c.a, c.a);
  }
  return sum / float(TAPS);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 aspect = vec2(ratio, 1.0);
  vec2 d = (uv - center) * aspect;
  float r = length(d);
  // (nudged off zero, where atan is undefined)
  float a = atan(d.y, d.x + 1e-6) / (2.0 * PI) + 0.5;
  vec2 far = max(center, 1.0 - center) * aspect;
  float reach = length(far);

  float speed = sin(PI * p);
  speed *= speed;
  float travel = 3.0 * (p - sin(2.0 * PI * p) / (2.0 * PI));
  float jitter = hash(floor(uv * aspect * 997.0));

  float goOut = smoothstep(0.0, 0.55, p);
  float goIn = 1.0 - smoothstep(0.45, 1.0, p);
  float soft = 0.35 * reach;
  float edge = mix(-soft, reach + soft, smoothstep(0.42, 0.78, p));
  float m = 1.0 - smoothstep(edge - soft, edge, r);
  vec4 before = vec4(0.0);
  vec4 after = vec4(0.0);
  if (m < 1.0) before = smear(uv, 1.0 - 0.3 * strength * goOut * goOut, 0.6 * strength * goOut, jitter, false);
  if (m > 0.0) after = smear(uv, 1.0 - 0.3 * strength * goIn * goIn, 0.6 * strength * goIn, jitter, true);
  vec4 c = mix(before, after, m);
  float dark = p < 0.5 ? speed : speed * speed * speed;
  c.rgb *= 1.0 - 0.65 * (0.5 + 0.5 * strength) * dark;

  float n = max(floor(streaks), 1.0);
  float len = speed * (0.5 + 1.5 * strength);
  float s = stars(a, r, n, 1.0, travel, len, reach);
  s += stars(fract(a + 0.37), r, max(floor(n * 0.71), 1.0), 2.0, travel * 1.3, len, reach);
  float core = r / (0.35 * reach);
  float peak = (p - 0.5) * 9.0;
  float glow = flash * exp(-peak * peak) * speed * (0.35 + 0.9 * exp(-core * core));
  vec3 light = streakColor.rgb * streakColor.a * (2.2 * s * speed + glow);
  // light is added to the image, but adds no opacity
  return c.a > 0.0 ? vec4(clamp(c.rgb / c.a + light, 0.0, 1.0), c.a) : vec4(0.0);
}

// Author: Paweł Płóciennik
// License: MIT
// Description: A drop falls into the image like into still water: round ripples spread out from where it hits, bending the image with glints on their slopes, the incoming image shows up inside the leading ripple, and the water calms down
// Tags: ripple, water, refraction, circle
// @range(10, 80) Frequency of the ripples: higher makes them closer together
uniform float amplitude; // = 30
// @range(0, 80) Speed of the ripples as they run outward through the spreading rings
uniform float speed; // = 30
// @param Where the drop falls, in texture coordinates
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(0, 0.08) How far the ripples bend the image, in frame heights
uniform float refraction; // = 0.015
// @range(0, 1) Brightness of the glints on the ripples
uniform float highlight; // = 0.5

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// height of the water, from -1 to 1, at a distance s inside the front
float wave(float s, float k, float lambda, float t) {
  float env = smoothstep(-0.3 * lambda, 0.6 * lambda, s) * exp(-s / (3.5 * lambda));
  // the ripples run out through the train, faster than the train itself spreads
  return env * sin(k * s + speed * t);
}

vec4 transition(vec2 uv) {
  float k = 2.0 * max(amplitude, 1.0);
  float lambda = 6.2831853 / k;
  // measured in square pixels, so the ripples are round
  vec2 q = (uv - center) * vec2(ratio, 1.0);
  float r = length(q);
  vec2 dir = r > 0.0 ? q / r : vec2(0.0);
  vec2 far = max(center, 1.0 - center) * vec2(ratio, 1.0);
  float R = length(far);

  float edge = 0.35 * lambda;
  float soft = 0.1 * lambda;
  // the front spreads out, slowing down a little, from just before the drop hits until
  // its revealed area is past the farthest corner
  float t = progress;
  float e = mix(t, 1.0 - (1.0 - t) * (1.0 - t), 0.4);
  float front = mix(-0.3 * lambda, R + edge + soft + 0.01, e);
  float s = front - r;

  float calm = 1.0 - smoothstep(0.55, 1.0, t);
  calm *= calm;
  // slope of the water along the radius, normalized to at most about 1
  // (one-sided at the very center)
  float d = 0.02 * lambda;
  float r0 = max(r - d, 0.0);
  float slope = calm * (wave(front - r - d, k, lambda, t) - wave(front - r0, k, lambda, t)) / ((r + d - r0) * k);
  vec2 offset = dir * slope * refraction / vec2(ratio, 1.0);

  vec4 ca = getFromColor(mirror(uv - offset));
  vec4 cb = getToColor(mirror(uv - offset));
  float m = smoothstep(edge - soft, edge + soft, s);
  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(ca.rgb * ca.a, ca.a), vec4(cb.rgb * cb.a, cb.a), m);

  float h = calm * wave(s, k, lambda, t);
  float lit = -dot(dir, normalize(vec2(-0.6, 0.8))) * slope;
  float glint = highlight * (0.2 * h + 0.6 * smoothstep(0.2, 0.9, lit) - 0.3 * smoothstep(0.2, 0.9, -lit));
  c.rgb = clamp(c.rgb + glint * c.a, 0.0, c.a);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: Seen from under water, the surface mirrors the outgoing picture everywhere except in a trembling round window where the light gets through, and there the whole incoming picture is crammed; waves tear the rim of the window into drifting islands as it widens until the surface is all open and calm
// Tags: light, water, refraction, reflection, optical

// @range(0, 2) Height of the waves
uniform float waves; // = 1.0
// @range(0, 0.1) Rainbow fringe of the window
uniform float dispersion; // = 0.035
// @range(0, 1) Tint of the water
uniform float tint; // = 0.6

vec4 pm(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec2 slope(vec2 q, float t) {
  vec2 g = vec2(0.0);
  q += 0.06 * vec2(sin(7.0 * q.y + t * 3.0), sin(6.0 * q.x - t * 4.0));
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float a = 2.39996 * fi + 1.0;
    float k = 6.0 + 4.2 * fi;
    vec2 n = vec2(cos(a), sin(a));
    g += n * cos(k * dot(n, q) + t * (9.0 + 2.5 * fi) + 1.9 * fi) / (1.0 + 0.35 * fi);
  }
  return g;
}

// refraction index 1 / sc
vec2 through(vec3 d, vec3 n, float sc, float fov) {
  float c = dot(d, n);
  vec3 t = (d - n * c) / max(sc, 0.02);
  float k = sqrt(max(1.0 - dot(t, t), 0.0));
  t += n * k;
  return t.xy / max(t.z, 0.35) / fov;
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 q = (uv - 0.5) * asp;
  float env = pow(max(sin(3.14159265 * p), 0.0), 1.5);
  // the frame covers the same angle whatever its shape
  float fov = 2.1 / length(asp);
  float amp = 0.075 * waves * env * (1.0 - 0.5 * p);
  vec2 g = slope(q, p);
  vec3 d = normalize(vec3(q * fov, 1.0));
  vec3 n = normalize(vec3(-g * amp, 1.0));
  float c = dot(d, n);
  float si = sqrt(max(1.0 - c * c, 0.0));
  // sine of the critical angle, 1 when the water bends light no more
  float lim = p * (1.45 - 0.45 * p);
  vec3 R = reflect(d, n);
  vec2 qa = R.xy / max(-R.z, 0.3) / fov;
  vec4 A = pm(getFromColor(mirror(qa / asp + 0.5)));
  // the whole sky stays in the window
  float rc = 2.0 * (1.0 - pow(p, 5.0));
  vec4 B = vec4(0.0);
  vec3 m = vec3(0.0);
  for (int i = 0; i < 3; i++) {
    float f = (float(i) - 1.0) * dispersion * env * (1.0 - 0.6 * p);
    float l = max(lim * (1.0 - f), 1e-3);
    vec2 qb = through(d, n, l, fov);
    vec2 box = qb / asp * rc;
    box *= box;
    qb /= pow(1.0 + dot(box, box), 0.25);
    vec4 b = pm(getToColor(mirror(qb / asp + 0.5)));
    float w = smoothstep(-0.012, 0.012, l - si - 0.0135 * (1.0 - p));
    if (i == 0) { B.r = b.r; m.r = w; }
    if (i == 1) { B.g = b.g; B.a = b.a; m.g = w; }
    if (i == 2) { B.b = b.b; m.b = w; }
  }
  vec3 rgb = mix(A.rgb, B.rgb, m);
  float al = mix(A.a, B.a, m.g);
  float rim = 1.0 - smoothstep(0.0, 0.07, abs(lim - si));
  rgb += 0.3 * env * rim * m.g * al * vec3(0.9, 1.0, 1.0);
  // slopes towards the light shine through the water, the others darken
  float facet = waves * env * (1.0 - m.g);
  rgb *= 1.0 + facet * clamp(0.16 * dot(g, vec2(-0.5, 0.8)), -0.3, 0.45);
  rgb += 0.35 * facet * al * smoothstep(1.4, 2.6, dot(g, vec2(-0.5, 0.8))) * vec3(0.8, 1.0, 1.0);
  rgb = mix(rgb, rgb * vec3(0.42, 0.86, 1.0) + vec3(0.0, 0.03, 0.05) * al, tint * env * (1.0 - m.g));
  return al > 0.0 ? vec4(min(rgb / al, 1.0), al) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image is washed off into wet paper, then the incoming one is painted in watercolor: pale washes spread first, blooming where the paint is still wet and drying with darker edges and grainy pigment, then deeper glazes go on, darkest tones first, until the picture is complete
// Tags: watercolor, paint, paper, organic, dissolve

// @range(0, 1) How dark the edges of the washes dry, where the pigment gathers
uniform float edges; // = 0.6
// @range(0, 1) Amount of blooms: lighter flowers of paint with frilly dark edges, where water runs back into a wet wash
uniform float blooms; // = 0.5
// @range(0, 1) How much the pigment settles into the grain of the paper
uniform float granulation; // = 0.5
// @color Color of the paper
uniform vec4 paper; // = vec4(0.98, 0.96, 0.92, 1.0)

float wcHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  // (kept in 0..1 before the last product, so that its rounding is the same on every target)
  p3 = fract(p3 + dot(p3, p3.yzx + 33.33));
  return fract((p3.x + p3.y) * p3.z * 37.0);
}

float wcNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(wcHash(i), wcHash(i + vec2(1.0, 0.0)), f.x),
    mix(wcHash(i + vec2(0.0, 1.0)), wcHash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// 0..1, spread evenly over the range (the sum of the octaves is about normal, around 0.5)
float wcFbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * wcNoise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p + 5.7;
    a *= 0.5;
  }
  float z = (v / 0.9375 - 0.5) / 0.11;
  return 0.5 + 0.5 * z / sqrt(1.0 + z * z);
}

vec2 wcFold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

// a front spreading over the thresholds of a wash: below -margin at the start, above 1 + margin at the end
float wcFront(float start, float dur, float margin) {
  float s = clamp((progress - start) / dur, 0.0, 1.0);
  s = mix(s, s * s * (3.0 - 2.0 * s), 0.5);
  return s * (1.0 + 2.0 * margin) - margin;
}

// dried edge of a wash at depth d inside it: a dark line right at the edge, fading inward over w
float wcRim(float d, float w) {
  float r = 1.0 - smoothstep(0.0, w, d);
  return smoothstep(-0.006, 0.004, d) * r * r;
}

float wcLuma(vec3 c) {
  return dot(c, vec3(0.299, 0.587, 0.114));
}

vec4 transition(vec2 uv) {
  // the last glaze has covered everything (see d3 below)
  if (progress >= 0.98) return getToColor(uv);
  vec2 q = vec2(uv.x * ratio, uv.y);
  vec2 px = vec2(1.0 / ratio, 1.0);
  vec4 from = getFromColor(uv);

  // paper texture, turned so that the cells of the noise do not line up with the frame
  vec2 gq = mat2(0.8, 0.6, -0.6, 0.8) * q;
  float grain = 0.55 * wcNoise(gq * 120.0) + 0.45 * wcNoise(gq * 50.0 + 3.1);
  float tooth = 0.03 * (grain - 0.5);
  vec2 w = vec2(wcNoise(q * 2.5 + 1.3), wcNoise(q * 2.5 + 8.1)) - 0.5;

  vec4 run = vec4(from.rgb * from.a, from.a);
  for (int i = 0; i < 4; i++) {
    float a = float(i) * 1.570796 + 0.8;
    vec4 f = getFromColor(wcFold(uv + 0.007 * vec2(cos(a), sin(a)) * px));
    run += vec4(f.rgb * f.a, f.a);
  }
  vec3 fromRun = run.a > 0.0 ? run.rgb / run.a : from.rgb;
  float d0 = wcFront(0.0, 0.4, 0.1) - wcFbm(q * 2.8 + 0.9 * w + 11.0);
  float lift = smoothstep(-0.03, 0.06, d0);
  vec3 stain = mix(paper.rgb, paper.rgb * fromRun, 0.12);
  vec3 c = mix(from.rgb, mix(fromRun, stain, smoothstep(0.0, 0.1, d0)), lift);
  c *= 1.0 - 0.18 * wcRim(d0, 0.05) * (1.0 - wcLuma(fromRun)) * lift;
  c *= (1.0 - 0.06 * lift * (1.0 - smoothstep(0.05, 0.4, d0)) * (1.0 - smoothstep(0.35, 0.6, progress))) * (1.0 - 0.05 * (grain - 0.5) * lift);
  float alpha = mix(from.a, paper.a, lift);
  // no wash has started yet (see d1 below)
  if (progress <= 0.07) return vec4(c, alpha);

  // washes carry no detail: they take the colors of the incoming image, blurred (broadly for the
  // first one, less for the second) and a little off its shapes, as painted by hand.
  // Their pigment is as dense as the incoming image is opaque
  vec2 hand = uv + 0.012 * w * px;
  vec4 broad = vec4(0.0);
  vec4 fine = vec4(0.0);
  for (int i = 0; i < 8; i++) {
    float a = float(i) * 0.785398 + 0.3;
    vec4 b = getToColor(wcFold(hand + 0.035 * vec2(cos(a), sin(a)) * px));
    vec4 f = getToColor(wcFold(hand + 0.012 * vec2(-sin(a), cos(a)) * px));
    broad += vec4(b.rgb * b.a, b.a);
    fine += vec4(f.rgb * f.a, f.a);
  }
  vec3 broadC = broad.rgb / max(broad.a, 1e-3);
  vec3 fineC = fine.rgb / max(fine.a, 1e-3);
  broad.a /= 8.0;
  fine.a /= 8.0;
  float pool = wcNoise(q * 4.0 + w * 2.0 + 31.0);

  float d1 = wcFront(0.07, 0.43, 0.12) - wcFbm(q * 3.0 + 1.2 * w + 2.0);
  float cov1 = smoothstep(-0.05, 0.03, d1) * lift;
  float k1 = 0.55 * broad.a;
  vec3 g1 = mix(vec3(1.0), broadC, (0.4 + 0.3 * pool) * broad.a);
  vec2 bq = q / 0.3;
  vec2 bc = floor(bq);
  float frill = 0.5 * wcNoise(q * 14.0) + 0.3 * wcNoise(q * 33.0 + 4.0) + 0.2 * wcNoise(q * 80.0 + 9.0);
  float inBloom = 0.0;
  float bloomRim = 0.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 cell = bc + vec2(float(i), float(j));
      if (wcHash(cell + vec2(17.0, 53.0)) < blooms) {
        vec2 ctr = cell + 0.3 + 0.4 * vec2(wcHash(cell + vec2(3.0, 71.0)), wcHash(cell + vec2(89.0, 9.0)));
        float g = clamp((d1 - 0.08 - 0.2 * wcHash(cell + vec2(5.0, 37.0))) / 0.3, 0.0, 1.0);
        g = 1.0 - (1.0 - g) * (1.0 - g) * (1.0 - g);
        // at most 0.32 * 1.55 < 0.5 cells: a bloom never reaches past the cells next to its own
        float r = g * (0.18 + 0.14 * wcHash(cell + vec2(61.0, 7.0))) * (0.45 + 1.1 * frill);
        float d = r - length(bq - ctr);
        float inside = smoothstep(-0.015, 0.015, d);
        inBloom = max(inBloom, inside * smoothstep(0.0, 0.25, r));
        bloomRim = max(bloomRim, inside * (1.0 - smoothstep(0.0, 0.05, d)) * smoothstep(0.0, 0.1, r));
      }
    }
  }
  g1 = mix(g1, mix(vec3(1.0), g1, 0.55), inBloom);
  g1 *= mix(vec3(1.0), g1 * g1 * 0.9, bloomRim);
  g1 *= mix(vec3(1.0), g1, edges * 0.8 * wcRim(d1, 0.06));

  float t2 = clamp(mix(wcFbm(q * 3.2 - 1.0 * w + 7.0), mix(1.0, wcLuma(fineC), fine.a), 0.55) + tooth, 0.0, 1.0);
  float d2 = wcFront(0.25, 0.42, 0.1) - t2;
  float cov2 = smoothstep(-0.006, 0.004, d2) * cov1;
  vec3 g2 = clamp(mix(vec3(1.0), fineC, (0.75 + 0.2 * (1.0 - pool)) * fine.a) / mix(vec3(1.0), broadC, 0.55 * broad.a), 0.0, 1.0);
  g2 *= mix(vec3(1.0), g2 * g2 * 0.92, edges * wcRim(d2, 0.07));

  vec3 wash = mix(vec3(1.0), g1, cov1) * mix(vec3(1.0), g2, cov2);
  float settle = clamp((grain - 0.5) * 2.0 + 0.5 * (wcNoise(q * 18.0 + 9.0) - 0.5), -0.4, 1.0);
  wash = min(wash * (1.0 - granulation * 0.45 * settle * (1.0 - wcLuma(wash))), 1.0);
  // on paper that is not opaque, the pigment brings its own opacity
  float a1 = alpha + (1.0 - alpha) * clamp(cov1 * k1 + cov2 * 0.35 * fine.a, 0.0, 1.0);
  c = mix(c * wash, wash, (a1 - alpha) / max(a1, 1e-3));
  alpha = a1;

  vec4 to = getToColor(uv);
  float t3 = clamp(mix(wcFbm(q * 3.6 + 0.8 * w + 19.0), mix(1.0, wcLuma(fineC), fine.a), 0.45) + tooth, 0.0, 1.0);
  float d3 = wcFront(0.45, 0.53, 0.1) - t3;
  float cov3 = smoothstep(-0.006, 0.004, d3);
  vec3 last = to.rgb * mix(vec3(1.0), to.rgb * 0.9, edges * 0.7 * wcRim(d3, 0.05));
  return vec4(mix(c, last, cov3), mix(alpha, to.a, cov3));
}

// Author: gre
// License: MIT
// Description: Blocks of the incoming image pour down from above the frame column after column, like a waterfall: in each column they fall one behind the other, land with a small bounce and stack up from the bottom, casting soft shadows on the outgoing image until the stack fills the frame
// Tags: blocks, grid, fall, cascade, stack, gravity, shadow

// @range(2, 40, 1) Number of columns (the blocks stay about square, with at most 48 rows)
uniform int columns; // = 10
// @range(0, 0.8) Share of the transition over which the columns start one after another (0 pours them all together)
uniform float stagger; // = 0.45
// @range(0, 1) How high the blocks bounce as they land
uniform float bounce; // = 0.5
// @range(0, 1) Darkness of the shadows and of the edges of the falling blocks
uniform float shadow; // = 0.5
// @param The columns pour from right to left instead of left to right
uniform bool reverse; // = false

const int MAX_ROWS = 48;
// time between two blocks of a column, as a part of the time it takes a block to fall its own height
const float SPACING = 1.15;
// time the edges and shadow of a block take to fade after its bounce, as a part of the frame's fall
const float SETTLE = 0.15;
// speed the blocks are thrown in with, as a part of the speed they reach after a fall of the frame's height
const float THROW = 0.25;
const float GROW = 0.06;
const float EDGE = 0.0015;

float boxDist(vec2 p, vec2 b) {
  vec2 d = abs(p) - b;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - abs(v));
}

vec4 transition(vec2 uv) {
  float nc = clamp(float(columns), 1.0, 40.0);
  float nr = clamp(floor(nc / ratio + 0.5), 1.0, float(MAX_ROWS));
  vec2 cell = vec2(ratio / nc, 1.0 / nr);
  vec2 x = uv * vec2(ratio, 1.0);
  float here = clamp(floor(uv.x * nc), 0.0, nc - 1.0);

  // the blocks start just above the frame, their grown size and anti-aliased edge included
  float top = 1.0 + 0.5 * GROW * cell.y + 2.0 * EDGE;
  // timing: g = 2 / u^2 is the gravity and 2 w / u the speed the blocks are thrown down with, so that a fall
  // of height h takes u (sqrt(w^2 + h) - w); d is the time between two blocks of a column, e the speed a block
  // bounces back with, as a part of its landing speed. The top block of the last column settles last, right
  // at the end
  float st = nc > 1.0 ? clamp(stagger, 0.0, 0.8) : 0.0;
  float w = THROW;
  float e = 0.2 * clamp(bounce, 0.0, 1.0);
  float hTop = sqrt(w * w + top - (nr - 1.0) * cell.y);
  float dn = SPACING * (sqrt(w * w + cell.y) - w);
  float u = (1.0 - st) / (dn * (nr - 1.0) + hTop - w + 2.0 * e * hTop + SETTLE);
  float d = dn * u;
  float k = clamp(shadow, 0.0, 1.0);

  // the two highest blocks seen here (height, coverage, image point) and the shadow cast here
  float z1 = -1.0, z2 = -1.0, m1 = 0.0, m2 = 0.0, a1 = 0.0, a2 = 0.0, shade = 0.0;
  vec2 s1 = vec2(0.0), s2 = vec2(0.0);
  vec2 light = vec2(0.35, -0.5) * min(cell.x, cell.y);
  for (int i = 0; i < 3; i++) {
    float c = here + float(i) - 1.0;
    if (c < 0.0 || c >= nc) continue;
    float order = reverse ? nc - 1.0 - c : c;
    float t0 = nc > 1.0 ? st * order / (nc - 1.0) : 0.0;
    // the top of the block below, which the next block cannot go through
    float floorY = 0.0;
    for (int j = 0; j < MAX_ROWS; j++) {
      float r = float(j);
      if (r >= nr) break;
      float slot = r * cell.y;
      float s = progress - t0 - r * d;
      // this block and the ones above it have not set off yet: they are all still above the frame
      if (s <= 0.0) break;
      float rh = sqrt(w * w + top - slot);
      float land = u * (rh - w);
      float y = top;
      float air = 1.0;
      if (s > land) {
        // it bounces back up with e times its landing speed, 2 rh / u
        float b = s - land;
        y = slot + max(0.0, b * (2.0 * e * rh - b / u) / u);
        air = 1.0 - smoothstep(0.0, (2.0 * e * rh + SETTLE) * u, b);
      } else {
        y = top - s * (2.0 * w + s / u) / u;
      }
      y = max(y, floorY);
      floorY = y + cell.y;
      float z, cov, a;
      vec2 src;
      if (air <= 0.0 && y - slot < 0.02 * cell.y) {
        // at rest in its slot: it fills its cell exactly
        if (c != here || x.y < slot || x.y >= slot + cell.y || z2 >= 0.0) continue;
        z = 0.0; cov = 1.0; a = 0.0; src = uv;
      } else {
        float inFrame = clamp((1.0 - y) / cell.y, 0.0, 1.0);
        vec2 center = vec2((c + 0.5) * cell.x, y + 0.5 * cell.y);
        float sc = 1.0 + GROW * air;
        vec2 q = (x - center) / sc;
        float blur = 0.002 + 0.3 * air * cell.y;
        float sd = boxDist(x - center - light * air, 0.5 * cell * sc);
        shade = max(shade, (1.0 - smoothstep(-blur, blur, sd)) * air * inFrame);
        float dist = boxDist(q, 0.5 * cell) * sc;
        // anti-aliased while it falls; it sharpens as it settles, to tile with the blocks around it
        float aa = EDGE * min(8.0 * air, 1.0);
        cov = aa > 0.0 ? clamp(0.5 - dist / aa, 0.0, 1.0) : step(dist, 0.0);
        z = air + 0.001 * r;
        if (cov <= 0.0 || z <= z2) continue;
        src = (vec2(c, r) * cell + q + 0.5 * cell) / vec2(ratio, 1.0);
        vec2 lq = q / (0.5 * cell);
        float bev = 1.0 - smoothstep(0.0, 0.12, -dist / min(cell.x, cell.y));
        a = air * bev * 0.5 * (lq.y - lq.x);
      }
      if (z > z1) {
        z2 = z1; m2 = m1; a2 = a1; s2 = s1;
        z1 = z; m1 = cov; a1 = a; s1 = src;
      } else {
        z2 = z; m2 = cov; a2 = a; s2 = src;
      }
    }
  }

  // the shadows fall on the outgoing image and on the blocks at rest, not on the moving ones
  vec4 col = getFromColor(uv);
  col.rgb *= 1.0 - 0.6 * k * shade;
  if (m2 > 0.0 && m1 < 1.0) {
    vec4 b = getToColor(mirror(s2));
    b.rgb = clamp(b.rgb * (1.0 + 0.6 * k * a2) * (1.0 - 0.6 * k * shade * step(z2, 0.0)), 0.0, 1.0);
    col = mix(col, b, m2);
  }
  if (m1 > 0.0) {
    vec4 b = getToColor(mirror(s1));
    b.rgb = clamp(b.rgb * (1.0 + 0.6 * k * a1) * (1.0 - 0.6 * k * shade * step(z1, 0.0)), 0.0, 1.0);
    col = mix(col, b, m1);
  }
  return col;
}

// Author: gre
// License: MIT
// Description: A breaking wave crashes across the frame, its lip curling over in front of its face and throwing foam and spray ahead, its shadow darkening the outgoing image; the incoming image is left behind it, tinted and bent by the water, clearing as the wave passes
// Tags: water, wave, ocean, foam, directional, reveal

// @param Direction the wave travels toward
uniform vec2 direction; // = vec2(1.0, 0.0)
// @range(0.1, 0.45) Size of the curling lip, in wave heights: how far it overhangs ahead of the face
uniform float curl; // = 0.3
// @range(0, 1) Amount of foam on the crest and spray thrown ahead of it
uniform float foam; // = 0.6
// @range(0, 0.1) How much the water bends the incoming image behind the wave
uniform float refraction; // = 0.04
// @color Color of the water tinting the incoming image behind the wave (its alpha is its strength)
uniform vec4 water; // = vec4(0.05, 0.36, 0.46, 0.75)
// @color Color of the foam and spray (its alpha is its strength)
uniform vec4 foamColor; // = vec4(1.0, 1.0, 1.0, 1.0)

const float PI = 3.141592653589793;
// half width of the antialiased edges, in wave heights
const float AA = 0.002;
// how far the base of the face trails behind its top, in wave heights
const float TRAIL = 0.35;
// how far behind the face the water still tints the incoming image, in wave heights
const float BAND = 0.4;
// how far ahead of the lip the spray reaches, in wave heights
const float REACH = 0.25;

float hash12(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

float vnoise(vec2 v) {
  vec2 i = floor(v);
  vec2 f = fract(v);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
    mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// folds coordinates back into the frame, so a displaced image never shows its clamped edges
vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

float droplets(vec2 q, float cell, float density, float seed) {
  vec2 g = q / cell;
  vec2 id = floor(g);
  if (hash12(id + seed) >= density) return 0.0;
  float r = 0.1 + 0.2 * hash12(id + seed + 4.7);
  vec2 c = id + 0.5 + (0.45 - r) * (vec2(hash12(id + seed + 1.3), hash12(id + seed + 8.1)) * 2.0 - 1.0);
  float px = AA / cell;
  return 1.0 - smoothstep(r - px, r + px, length(g - c));
}

vec4 transition(vec2 uv) {
  float t = progress;

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  // the crest points up the frame, or to the left when the wave travels straight up or down
  vec2 up = vec2(-dir.y, dir.x);
  if (up.y < 0.0 || (up.y == 0.0 && up.x > 0.0)) up = -up;
  float e = 0.5 * (abs(dir.x) * ratio + abs(dir.y));
  float w = 0.5 * (abs(up.x) * ratio + abs(up.y));
  // in wave heights: u along the travel, v from the trough (0) to the crest (1)
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0) / (2.0 * w);
  vec2 q = vec2(dot(p, dir), dot(p, up) + 0.5);
  float E = e / (2.0 * w);

  float R = max(curl, 0.01);
  // radius of the hollow at the back of the curl, where it meets the face
  float Rb = 0.5 * R;
  float tipAngle = PI * (0.08 - 0.5 * smoothstep(0.0, 0.85, t));
  // the wave sweeps from fully ahead of the frame, spray included, to fully past it, tinted water included
  float travel = mix(t, t * t * (3.0 - 2.0 * t), 0.25);
  vec2 C = vec2(mix(-E - R - REACH, E + Rb + TRAIL + BAND, travel), 1.02 - R);

  vec2 d = q - C;
  // atan is undefined at the very center
  if (d.x == 0.0) d.x = 1e-6;
  float r = length(d);
  float ang = atan(d.y, d.x);
  // the inner surface of the curl spirals in from the tip of the lip (zero thickness) to the back of the hollow
  float k = clamp((ang - tipAngle) / (PI - tipAngle), 0.0, 1.0);
  float rIn = R - (R - Rb) * (1.0 - (1.0 - k) * (1.0 - k));
  bool curled = ang >= tipAngle;
  // the face below the curl: vertical where it meets the hollow, its base trailing behind
  float s = 1.0 - clamp(q.y / C.y, 0.0, 1.0);
  float face = C.x - Rb - TRAIL * s * s;
  float behind = face - q.x; // > 0 behind the face

  float wet;
  if (curled) {
    wet = smoothstep(-AA, AA, r - rIn) * (ang > 0.5 * PI ? 1.0 : 1.0 - smoothstep(-AA, AA, r - R));
  } else {
    wet = smoothstep(-AA, AA, behind);
  }
  float lip = curled ? 1.0 - smoothstep(0.5 * PI - 0.3, 0.5 * PI + 0.5, ang) : 0.0;

  float n = vnoise(q * vec2(14.0, 10.0) + vec2(-9.0 * t, 3.0 * t));

  vec4 a = getFromColor(uv);
  float gap = max(min(r - R, -behind), 0.0);
  float shade = 0.55 * exp(-gap / 0.1) * (1.0 - smoothstep(0.0, REACH, gap)) * smoothstep(0.0, 0.6, q.y) * (1.0 - smoothstep(C.y + 0.2 * R, C.y + 1.1 * R, q.y));
  shade += 0.25 * (1.0 - smoothstep(0.0, R, r));
  a.rgb *= 1.0 - shade;
  float fwd = max(r - R, 0.0);
  float zone = smoothstep(tipAngle - 0.4, tipAngle + 0.2, ang) * (1.0 - smoothstep(0.0, REACH, fwd)) * step(0.0, r - R);
  vec2 sq = (d - t * vec2(0.5, -0.25)) * vec2(0.55, 1.0);
  float thin = exp(-fwd / 0.12);
  float spray = droplets(sq, 0.02, foam * thin, 1.0) + 0.6 * droplets(sq * 1.6 + 3.1, 0.02, foam * thin, 7.0);
  float mist = foam * n * n * exp(-fwd / 0.06) * (1.0 - smoothstep(0.0, REACH, fwd)) * smoothstep(-AA, AA, r - R) * smoothstep(tipAngle, tipAngle + 0.3, ang);
  a.rgb = mix(a.rgb, foamColor.rgb, foamColor.a * clamp(spray * zone + mist, 0.0, 1.0));

  float band = max(1.0 - smoothstep(0.05, BAND, behind), lip);
  float bend = refraction * band * band;
  vec2 off = bend * (dir * sin(17.0 * q.y + 2.0 * sin(9.0 * q.x) - 6.0 * t) + up * cos(13.0 * q.x - 5.0 * t));
  vec4 b = getToColor(mirror(uv + off * 2.0 * w / vec2(ratio, 1.0)));
  float luma = dot(b.rgb, vec3(0.299, 0.587, 0.114));
  vec3 tinted = water.rgb * (0.4 + 0.9 * luma) * (1.0 + 0.6 * q.y);
  tinted += 0.18 * lip * (1.0 - k) * vec3(0.5, 1.0, 0.9);
  tinted *= 1.0 - 0.35 * lip * (1.0 - smoothstep(0.0, 0.06, r - rIn));
  tinted += 0.35 * (curled ? k * (1.0 - smoothstep(0.0, 0.015, r - rIn)) : 1.0 - smoothstep(0.0, 0.015, behind)) * vec3(0.7, 0.95, 1.0);
  b.rgb = mix(b.rgb, tinted, water.a * band);

  float crest = curled ? (1.0 - smoothstep(0.01, 0.02 + 0.12 * n, abs(R - r))) * smoothstep(tipAngle, tipAngle + 0.4, ang) * (1.0 - smoothstep(0.5 * PI + 0.2, 0.5 * PI + 0.8, ang)) : 0.0;
  float churn = (1.0 - smoothstep(0.0, 0.15 + 0.1 * n, q.y)) * (1.0 - smoothstep(0.0, 0.3, abs(behind))) * smoothstep(0.3, 0.7, n);
  b.rgb = mix(b.rgb, foamColor.rgb, foamColor.a * clamp(foam * 1.5 * (crest + churn), 0.0, 1.0));

  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), wet);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: Two hands sweep away from each other around the center, opening a widening wedge that reveals the incoming image
// Tags: wipe, radial, clock, wedge

#define PI 3.141592653589793

// @range(-180, 180) Direction the wedge opens from, in degrees clockwise from 12 o'clock
uniform float angle; // = 0.0
// @range(0, 0.2) Softness of the hands' edges
uniform float smoothness; // = 0.01
// @param Point the hands turn around
uniform vec2 center; // = vec2(0.5)

vec4 transition (vec2 uv) {
  // Measured in square pixels, so the angles are not stretched
  vec2 q = (uv - center) * vec2(ratio, 1.0);
  float a = radians(angle);
  // Local frame: y along the starting direction, x across it (the wedge is symmetric)
  vec2 p = vec2(abs(q.x * cos(a) - q.y * sin(a)), q.x * sin(a) + q.y * cos(a));
  float spread = PI * progress;
  // (float PI rounds above pi, so sin(spread) would turn slightly negative at the end)
  vec2 hand = vec2(max(sin(spread), 0.0), cos(spread));
  // Signed distance to the wedge: the nearest hand, negative inside
  float l = length(p);
  float d = length(p - hand * clamp(dot(p, hand), 0.0, l)) * sign(hand.y * p.x - hand.x * p.y);
  // The soft edge keeps an even width and slides from outside to inside the hands,
  // so nothing is revealed at the start and everything is at the end
  float s = max(smoothness, 0.001);
  float m = 1.0 - smoothstep(0.0, s, d + s * (1.0 - progress));
  return mix(getFromColor(uv), getToColor(uv), m);
}

// Author: gre
// License: MIT
// Description: A fast camera pan that streaks both images with motion blur, the incoming one arriving from the opposite side
// Tags: slide, motion-blur, directional

// @param Direction in which the images move
uniform vec2 direction; // = vec2(-1.0, 0.0)
// @range(0, 1) Length of the motion blur at full speed
uniform float blur; // = 0.4

const int SAMPLES = 24;

// The panned strip: the outgoing image, then the incoming one behind it
vec4 strip(vec2 q, vec2 d) {
  vec2 qt = q + d;
  // which side of the seam between the two images (works for diagonals too)
  if (dot(q - 0.5, -d) < 0.5 * dot(d, d)) {
    return getFromColor(clamp(q, 0.0, 1.0));
  }
  return getToColor(clamp(qt, 0.0, 1.0));
}

float rand(vec2 co) {
  return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

vec4 transition(vec2 uv) {
  vec2 d = sign(direction);
  float p = progress;
  float h = 1.0 - abs(2.0 * p - 1.0); // 0 at both ends, 1 in the middle
  // mostly cubic, with a bit of linear so that it starts moving at once
  float e = 0.5 * h * (0.1 + 0.9 * h * h);
  float pos = p < 0.5 ? e : 1.0 - e;
  float len = blur * h * (0.1 + 2.7 * h * h) / 2.8; // follows the speed

  vec2 q = uv - d * pos;
  // average along the motion, jittered to hide the sample steps
  float jitter = rand(uv);
  vec3 color = vec3(0.0);
  float alpha = 0.0;
  for (int i = 0; i < SAMPLES; i++) {
    float t = (float(i) + jitter) / float(SAMPLES) - 0.5;
    vec4 c = strip(q + d * t * len, d);
    color += c.rgb * c.a;
    alpha += c.a;
  }
  return vec4(color / max(alpha, 1e-5), alpha / float(SAMPLES));
}

// Author: gre
// License: MIT
// Description: The camera rolls faster and faster around the center of the frame, streaking the outgoing image in a spin blur, then the incoming one takes over mid-spin and slows to a stop
// Tags: rotate, motion-blur, spin

// @range(-3, 3) Total rotation, in turns, split between the two images (negative turns clockwise)
uniform float turns; // = 1.0
// @range(0, 1) Length of the motion blur along the spin
uniform float blur; // = 0.5
// @range(0, 1) How much the color channels split apart as the spin speeds up
uniform float chroma; // = 0.6
// @range(0, 1) How much the camera zooms in at the fastest point
uniform float zoom; // = 0.25

const float PI = 3.141592653589793;
const int SAMPLES = 24;

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 mirror(vec2 v) {
  vec2 m = mod(v, 2.0);
  return mix(m, 2.0 - m, step(1.0, m));
}

// the camera's roll angle at time t: the outgoing image speeds up until the middle,
// then the incoming one, already turning, slows down to rest
float rollAngle(float t) {
  float halfTurn = PI * turns;
  if (t < 0.5) {
    float x = 2.0 * t;
    return halfTurn * x * x * x;
  }
  float x = 2.0 - 2.0 * t;
  return -halfTurn * x * x * x;
}

vec4 transition(vec2 uv) {
  float p = progress;
  float h = 1.0 - abs(2.0 * p - 1.0); // 0 at both ends, 1 at the cut
  float shutter = blur * 0.1 * h;
  float scale = 1.0 + zoom * h * h * h;
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  float jitter = hash(uv * vec2(ratio, 1.0) * 731.0);
  vec3 color = vec3(0.0);
  vec3 weight = vec3(0.0);
  float alpha = 0.0;
  for (int i = 0; i < SAMPLES; i++) {
    float s = (float(i) + jitter) / float(SAMPLES) - 0.5;
    float t = clamp(p + s * shutter, 0.0, 1.0);
    float a = rollAngle(t);
    float c = cos(a), sn = sin(a);
    vec2 r = vec2(c * q.x + sn * q.y, -sn * q.x + c * q.y) / scale;
    vec2 suv = mirror(r / vec2(ratio, 1.0) + 0.5);
    vec4 col = t < 0.5 ? getFromColor(suv) : getToColor(suv);
    // red trails behind and blue leads along the arc: the channels split with the speed
    vec3 w = max(vec3(1.0 - 4.0 * chroma * s, 1.0, 1.0 + 4.0 * chroma * s), 0.0);
    color += col.rgb * col.a * w;
    weight += col.a * w;
    alpha += col.a;
  }
  return vec4(color / max(weight, vec3(1e-5)), alpha / float(SAMPLES));
}

// Author: gre
// License: MIT
// Description: The camera tilts fast from the outgoing image to the incoming one, set edge to edge at an angle above it, streaking both in perspective with a vertical motion blur
// Tags: 3d, rotate, motion-blur, vertical

// @param Tilt the camera down to an incoming image below instead of above
uniform bool down; // = false
// @range(0, 1) Length of the motion blur along the tilt
uniform float blur; // = 0.5
// @range(0, 1) How much the color channels split apart as the tilt speeds up
uniform float chroma; // = 0.5
// @range(0, 1) Strength of the perspective (field of view of the camera)
uniform float perspective; // = 0.7

const float PI = 3.141592653589793;
const int SAMPLES = 24;

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// fold the coordinates back into the image, only a safety at the far edges
vec2 mirror(vec2 v) {
  vec2 m = mod(v, 2.0);
  return mix(m, 2.0 - m, step(1.0, m));
}

// how far the camera has tilted at time t, from 0 to 1: slow start, whip in the middle, slow landing
float tilt(float t) {
  float h = 1.0 - abs(2.0 * t - 1.0);
  float e = 0.5 * h * h * h * h;
  return t < 0.5 ? e : 1.0 - e;
}

vec4 transition(vec2 uv) {
  float p = progress;
  float h = 1.0 - abs(2.0 * p - 1.0); // 0 at both ends, 1 in the middle
  float shutter = blur * 0.25 * h * h;
  // the images are two faces of a drum around the camera, each filling the frame from the
  // middle: they meet edge to edge at the angle of the field of view, which the camera turns by
  float halfFov = mix(15.0, 45.0, perspective) * PI / 180.0;
  float dist = 0.5 / tan(halfFov);
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  if (down) q.y = -q.y;
  float jitter = hash(uv * vec2(ratio, 1.0) * 731.0);
  vec3 color = vec3(0.0);
  vec3 weight = vec3(0.0);
  float alpha = 0.0;
  for (int i = 0; i < SAMPLES; i++) {
    float s = (float(i) + jitter) / float(SAMPLES) - 0.5;
    float t = clamp(p + s * shutter, 0.0, 1.0);
    float a = 2.0 * halfFov * tilt(t);
    // zoom in just enough that the faces always cover the frame, wherever their edge is
    vec2 r = q * cos(halfFov) / cos(halfFov - a);
    float c0 = cos(a), s0 = sin(a);
    vec2 d0 = vec2(r.y * c0 + dist * s0, dist * c0 - r.y * s0);
    float b = a - 2.0 * halfFov;
    float c1 = cos(b), s1 = sin(b);
    vec2 d1 = vec2(r.y * c1 + dist * s1, dist * c1 - r.y * s1);
    // the ray leaves the drum through the nearest face
    bool incoming = d1.y > d0.y;
    vec2 d = incoming ? d1 : d0;
    vec2 hit = dist / d.y * vec2(r.x, d.x);
    if (down) hit.y = -hit.y;
    vec2 suv = mirror(hit / vec2(ratio, 1.0) + 0.5);
    vec4 col = incoming ? getToColor(suv) : getFromColor(suv);
    // red trails behind and blue leads along the motion: the channels split with the speed
    vec3 w = max(vec3(1.0 - 4.0 * chroma * s, 1.0, 1.0 + 4.0 * chroma * s), 0.0);
    color += col.rgb * col.a * w;
    weight += col.a * w;
    alpha += col.a;
  }
  return vec4(color / max(weight, vec3(1e-5)), alpha / float(SAMPLES));
}

// Author: gre
// License: MIT
// Description: Squares open one inside another out of the middle of the frame, each turned a little more than the last and showing one of the two images in turn, as small and as turned as the square itself, so their corners wind into spiral arms; they keep growing until the last one straightens up into the whole incoming image
// Tags: squares, spiral, nested, rotate, zoom, geometric

// @range(1, 11, 2) Number of squares, an odd number
uniform float squares; // = 7.0
// @range(-0.6, 0.6) How much each square turns from the one around it, in radians
uniform float twist; // = 0.3
// @range(0, 1) Strength of the shadow that each square casts on the one around it
uniform float shadow; // = 0.5

const int MAXN = 11;
// half side of a square that is born
const float SEED = 0.07;
// size of a square, relative to the frame's half diagonal, around which it straightens up, and the softness of that
const float FULL = 0.5;
const float SOFT = 0.65;

vec2 mirrored(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 premultiplied(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

// spot: where in the image, odd: whether the square shows the outgoing one
vec4 picture(vec3 spot) {
  vec2 st = mirrored(spot.xy / vec2(ratio, 1.0) + 0.5);
  return premultiplied(spot.z > 0.5 ? getFromColor(st) : getToColor(st));
}

vec4 transition(vec2 uv) {
  float n = 2.0 * floor(clamp(squares, 1.0, 11.0) * 0.5) + 1.0;
  vec2 P = (uv - 0.5) * vec2(ratio, 1.0);
  float R = 0.5 * length(vec2(ratio, 1.0)) + 0.02;
  // ratio of a square to the one it is inscribed in, when turned by bend
  float bend = clamp(twist, -0.75, 0.75);
  float gap = log(cos(bend) + abs(sin(bend))) + 0.1;
  float t = progress * (1.5 - 0.5 * progress);
  float z = (gap * (n - 1.0) + log(1.0 + R / SEED)) * t;
  vec3 top = vec3(P, 1.0);
  vec3 under = top;
  float cover = 1.0;
  float shade = 1.0;
  bool parent = true;
  for (int i = 0; i < MAXN; i++) {
    float k = float(i);
    float h = SEED * (exp(max(z - gap * k, 0.0)) - 1.0);
    if (k >= n || h <= 1e-4) break;
    float u = log(h / (FULL * R));
    // smooth minimum of u and 0, exactly 0 once the square spans the frame
    float v = u < -SOFT ? u : u < SOFT ? -(SOFT - u) * (SOFT - u) / (4.0 * SOFT) : 0.0;
    float a = bend / gap * v;
    vec2 q = vec2(cos(a) * P.x + sin(a) * P.y, cos(a) * P.y - sin(a) * P.x);
    float d = h - max(abs(q.x), abs(q.y));
    float m = clamp(d / 0.0025, 0.0, 1.0);
    if (m > 0.0) {
      under = top;
      // a tiny square only shows a part of the picture, which would alias if it were all in there
      top = vec3(q * exp(-max(v, -2.2)), mod(k, 2.0));
      cover = m;
      shade = 1.0;
    }
    if (parent || m > 0.0) shade *= 1.0 - 0.45 * shadow * exp(min(d, 0.0) / (0.22 * h)) * (1.0 - m);
    parent = m > 0.0;
  }
  vec4 col = mix(picture(under), picture(top), cover);
  col.rgb *= shade;
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A whirlwind crosses the frame from left to right: it winds the outgoing image into a spiral around its eye and draws it inward as it passes, and leaves the incoming image in its wake, which unwinds and straightens out behind it
// Tags: swirl, wind, vortex, directional, distort

// @range(0.5, 3) Turns the picture makes around the eye
uniform float turns; // = 1.6
// @range(0.15, 0.6) Radius of the whirlwind, as a fraction of the frame's shorter side
uniform float size; // = 0.32

const float PI = 3.141592653589793;
const int TAPS = 16;
// the front leans back at the top like a trailing funnel
const float LEAN = 0.35;
// nominal pixel footprint for the radial anti-aliasing (no resolution uniform)
const float PX = 0.004;

vec2 mirrored(vec2 v) {
  vec2 m = mod(v, 2.0);
  return mix(m, 2.0 - m, step(1.0, m));
}

vec4 transition(vec2 uv) {
  float t = progress, R = ratio;
  vec2 Q = vec2(uv.x * R, uv.y);
  float S = size * min(R, 1.0);
  // just far enough out that the front starts and ends off screen
  float reach = 0.5 * LEAN + 0.01;
  // the eye hurries near the edges, where little is seen, and lingers mid-frame
  float x = t + 0.3 * sin(2.0 * PI * t) / (2.0 * PI);
  vec2 c = vec2(mix(-reach, R + reach, x), 0.5 + 0.08 * sin(t * 6.0));
  // spins only once the eye is well inside: near an edge the twist would pull mirrored pixels from beyond it, showing a fold
  float ramp = min(2.0 * S, 0.7 * R);
  float g = smoothstep(0.0, ramp, c.x) * smoothstep(0.0, ramp, R - c.x);
  vec2 d = Q - c;
  float s2 = S * S;
  float k = s2 / (dot(d, d) + s2);
  float k3 = k * k * k;
  float kp = k3 * g;
  float A = 2.0 * PI * turns;
  float th = A * kp;
  float inflow = 1.0 + 0.5 * kp;
  // motion blur along the spin plus |dth/dr| * PX (dth/dr = 6 A g r k^4 / S^2), which hides the ring aliasing in the core
  float spread = min(0.15 * th * k + PX * 6.0 * A * g * length(d) * k3 * k / s2, 1.0);
  vec4 col = vec4(0.0);
  float wsum = 0.0;
  for (int i = 0; i < TAPS; i++) {
    float u = float(i) / float(TAPS - 1) - 0.5;
    float a = th + spread * u;
    float w = 1.0 - abs(u);
    float ca = cos(a), sa = sin(a);
    vec2 s = c + mat2(ca, -sa, sa, ca) * d * inflow;
    float f = s.x - c.x + LEAN * (s.y - 0.5);
    vec2 su = mirrored(vec2(s.x / R, s.y));
    vec4 v = mix(getToColor(su), getFromColor(su), smoothstep(-0.004, 0.004, f));
    // averaged premultiplied so transparent texels don't darken the blur
    col += w * vec4(v.rgb * v.a, v.a);
    wsum += w;
  }
  col /= wsum;
  return vec4(col.rgb / max(col.a, 1e-5) * (1.0 - 0.3 * kp * k), col.a);
}

// Author: gre
// License: MIT
// Description: Straight cuts are scored across the outgoing image one after another, and each time the piece beyond the cut lifts and slides away along it, whittling the image down to a small polygon that slides off last and uncovers the incoming image
// Tags: cut, slice, slide, shadow

// @range(2, 6, 1) Number of cuts before the last piece slides away
uniform int cuts; // = 5
// @color Color of the score line drawn along each cut (alpha sets the intensity)
uniform vec4 score; // = vec4(1.0, 0.97, 0.9, 0.85)
// @color Color of the shadow the lifted pieces cast on the incoming image
uniform vec4 shadow; // = vec4(0.0, 0.0, 0.0, 0.45)

const float AA = 0.0018;
const float SCORE_TIME = 0.075;
const float LIFT = 0.025;
const float GAP = 0.012;
const vec2 SHADOW_OFFSET = vec2(0.014, -0.022);
const float SHADOW_BLUR = 0.03;

// golden-angle steps spread the cut directions evenly whatever their number
vec2 normalOf(float k) {
  float a = k * 2.39996 + 0.7;
  return vec2(cos(a), sin(a));
}

// offsets shrink so every cut still crosses what is left
float offsetOf(float k, float n, float r) {
  return 0.42 * r * (0.35 + 0.65 * (1.0 - k / n)) * (0.8 + 0.2 * fract(k * 0.618));
}

float boxDistance(vec2 q) {
  vec2 d = abs(q) - 0.5 * vec2(ratio, 1.0);
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// signed distance to piece k (q relative to the center), negative inside; piece nc is the last polygon
float pieceDistance(vec2 q, int k, int nc, float n, float r) {
  float sd = boxDistance(q);
  for (int m = 0; m < 6; m++) {
    if (m >= k) break;
    float fm = float(m);
    sd = max(sd, dot(q, normalOf(fm)) - offsetOf(fm, n, r));
  }
  if (k < nc) sd = max(sd, offsetOf(float(k), n, r) - dot(q, normalOf(float(k))));
  return sd;
}

vec2 slideDir(float k, vec2 nk) {
  return vec2(-nk.y, nk.x) * (mod(k, 2.0) < 0.5 ? 1.0 : -1.0);
}

float startOf(float k, float n) {
  return 0.08 + k * 0.92 / (n + 2.2);
}

float slideOf(float k, float n) {
  return clamp((progress - startOf(k, n)) * (n + 2.2) / (0.92 * 2.2), 0.0, 1.0);
}

vec4 transition(vec2 uv) {
  vec2 P = (uv - 0.5) * vec2(ratio, 1.0);
  int nc = int(clamp(float(cuts), 2.0, 6.0));
  float n = float(nc);
  float r = min(ratio, 1.0) + 0.25 * abs(ratio - 1.0);
  // just enough to clear the frame with the shadow, so the slide never runs off-screen for long
  float travel = length(vec2(ratio, 1.0)) + 0.1;

  vec4 c = getToColor(uv);
  for (int k = 6; k >= 0; k--) {
    if (k > nc) continue;
    float fk = float(k);
    bool last = k == nc;
    vec2 nk = normalOf(last ? fk - 1.0 : fk);
    vec2 dk = slideDir(fk, nk);
    float g = slideOf(fk, n);
    if (g >= 1.0) continue;
    float lift = smoothstep(0.0, 0.35, g);
    vec2 shift = dk * travel * g * g * g + (last ? vec2(0.0) : nk * GAP * lift);
    float scale = 1.0 + LIFT * lift * (1.0 - g);
    vec2 Q = (P - shift) / scale;
    vec2 S = (P - shift - SHADOW_OFFSET * lift) / scale;
    if (lift > 0.0) {
      float blur = SHADOW_BLUR * (0.3 + lift);
      float sh = lift * (1.0 - smoothstep(-blur, blur, pieceDistance(S, k, nc, n, r)));
      c.rgb = mix(c.rgb, shadow.rgb, shadow.a * sh);
    }

    // overhang by AA: while pieces still touch, overlapping edges sample the same pixel
    float cover = clamp(0.5 - (pieceDistance(Q, k, nc, n, r) - AA) / AA, 0.0, 1.0);
    if (cover <= 0.0) continue;
    vec4 col = getFromColor(clamp(Q / vec2(ratio, 1.0) + 0.5, 0.0, 1.0));
    for (int m = 0; m < 6; m++) {
      if (m > k || m >= nc) break;
      float fm = float(m);
      vec2 nm = normalOf(fm);
      vec2 dm = slideDir(fm, nm);
      float run = clamp((progress - startOf(fm, n) + SCORE_TIME) / SCORE_TIME, 0.0, 1.0);
      float head = mix(-1.0, 1.0, run) * (0.5 * dot(abs(dm), vec2(ratio, 1.0)) + 0.02);
      float behind = head - dot(Q, dm);
      float drawn = clamp(0.5 + behind / AA, 0.0, 1.0) * (1.0 - smoothstep(0.0, 0.25, slideOf(fm, n)));
      float e = abs(dot(Q, nm) - offsetOf(fm, n, r));
      float line = exp(-e / 0.0016) + 0.3 * exp(-e / 0.008);
      float tip = exp(-length(vec2(behind, e)) / 0.012) * min(run * 20.0, 1.0) * (1.0 - run);
      col.rgb = mix(col.rgb, score.rgb, clamp(score.a * drawn * (line * (0.6 + 0.4 * exp(-max(behind, 0.0) * 3.0)) + tip), 0.0, 1.0));
    }
    c = mix(c, col, cover);
  }
  return c;
}

// Author: gre
// License: MIT
// Description: A ragged left-to-right wipe, as if the image was blown away by the wind
// Tags: wipe, horizontal, noise

// @range(0, 1) Width of the ragged edge
uniform float size; // = 0.2
// @param Wipe from right to left instead
uniform bool reversed; // = false

float rand (vec2 co) {
  return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
