  vec4 c = other ? getToColor(st) : getFromColor(st);

  float off = (L - b) / (0.03 + 0.1 * b);
  float edge = smoothstep(0.0, 0.12, b) * smoothstep(0.0, 0.3, l0);
  c.rgb *= 1.0 - 0.35 * edge * exp(-abs(off) * 0.6) * (through ? 1.0 : 0.6);
  c.rgb = min(c.rgb + ring * edge * (0.25 + 0.75 * c.rgb) * exp(-off * off * 5.0), 1.0);
  return vec4(c.rgb * c.a, c.a);
}

vec4 transition(vec2 uv) {
  float p = progress;
  // still moving at the end: the last of the bending fades like the square of what is left
  float A = PI * p * p * (2.0 - p);
  vec2 asp = vec2(ratio, 1.0);
  float field = 0.3 * length(asp);
  vec2 d = (uv - 0.5) * asp;
  // kept off the axis, where the deflection of a closed mouth is 0 / 0
  float rs = max(length(d), 1e-4);
  vec2 dir = length(d) > 1e-5 ? normalize(d) : vec2(1.0, 0.0);
  // radial samples around the rim, where the images wind up endlessly
  float rim = 2.0 * field * tan(0.5 * min(A, 1.6));
  float dr = 0.0014 * exp(-abs(rs - rim) / (0.02 + 0.06 * rim)) * smoothstep(0.0, 0.15, A) * (1.0 - smoothstep(1.4, 1.6, A));
  vec4 c = trace(rs, dir, A, field);
  if (dr > 1e-4) {
    c += trace(max(abs(rs - dr), 1e-4), rs < dr ? -dir : dir, A, field) + trace(rs + dr, dir, A, field);
    c /= 3.0;
  }
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing picture is a tray of stuck tiles that is wrenched: its two ends twist against each other in 3D while cracks run out along the joints, it snaps back flat, and the loosened tiles tip out one after another and fall out of the frame, uncovering the incoming picture
// Tags: 3d, tiles, twist, crack, gravity, shadow
// Preview: 0.7

// @range(2, 8, 1) Number of rows of tiles
uniform int rows; // = 4
// @range(0, 1) How far the two ends of the tray turn against each other
uniform float twist; // = 0.75
// @range(0, 1) How much the tiles darken as they turn from the light, and the shadows they cast
uniform float shading; // = 0.6

const float PI = 3.14159265;
const float EYE = 1.8;
const float TWIST_END = 0.48;
const float POP_SPREAD = 0.24;
const float FLIGHT = 0.28;
const float THICK = 0.03;
const float EDGE = 0.0015;
const vec3 L = vec3(-0.3, 0.45, 0.84);

vec4 hash4(vec2 p) {
  vec4 q = fract(vec4(p.xyxy) * vec4(0.1031, 0.1030, 0.0973, 0.1099));
  q += dot(q, q.wzxy + 33.33);
  return fract((q.xxyz + q.yzzw) * q.zywx);
}

// wind up, then a released snap that rings out to exactly zero
float wrench(float s) {
  if (s < 0.75) return smoothstep(0.0, 0.75, s);
  float r = (s - 0.75) / 0.25;
  return (1.0 - r) * (1.0 - r) * cos(2.5 * PI * r);
