float popU(vec2 g, vec2 grid, vec2 size) {
  float order = clamp((0.55 * hash4(g).x + 0.45 * arrival(g + 0.5, vec2(-7.0), grid, size) - 0.2) / 0.62, 0.0, 1.0);
  return clamp((progress - TWIST_END - POP_SPREAD * order) / FLIGHT, 0.0, 1.0);
